-- Canonical encoding is Lua data syntax, not an evaluator or foreign format.
local function canonical(value, seen)
  local kind = type(value)
  if kind == "boolean" then return value and "true" or "false" end
  if kind == "number" then
    assert(math.type(value) == "integer", "canonical data needs exact integers")
    return tostring(value)
  end
  if kind == "string" then
    local result = {'"'}
    for i = 1, #value do
      local byte = value:byte(i)
      if byte == 34 then result[#result+1] = '\\"'
      elseif byte == 92 then result[#result+1] = '\\\\'
      elseif byte < 32 or byte == 127 then
        result[#result+1] = string.format("\\%03d", byte)
      else result[#result+1] = string.char(byte) end
    end
    result[#result+1] = '"'
    return table.concat(result)
  end
  assert(kind == "table", "canonical data forbids functions, nil, and userdata")
  seen = seen or {}
  assert(not seen[value], "canonical data forbids cyclic tables")
  seen[value] = true
  local count, array, keys = 0, true, {}
  for key in pairs(value) do
    count = count + 1
    if type(key) ~= "number" or math.type(key) ~= "integer" or key < 1 then
      array = false
    end
    keys[#keys+1] = key
  end
  if array then
    for index = 1, count do
      if rawget(value,index) == nil then array = false; break end
    end
  end
  local fields = {}
  if array then
    for index=1,count do fields[index]=canonical(value[index],seen) end
  else
    for _,key in ipairs(keys) do
      assert(type(key)=="string", "canonical maps need only string keys")
    end
    table.sort(keys)
    for _,key in ipairs(keys) do
      fields[#fields+1] = "["..canonical(key,seen).."]="..canonical(value[key],seen)
    end
  end
  seen[value]=nil
  return "{"..table.concat(fields,",").."}"
end
