    a,b=as_rat(a),as_rat(b)
    local g1,g2=gcd(b.d,a.n%b.d),gcd(a.d,b.n%a.d)
    return rational(mul(a.n//g1,b.n//g2),mul(a.d//g2,b.d//g1))
