  local OPERATORS={add={2},mul={2},sub={2,2},rational={2,2},floor_div={2,2},clip={3,3},min={2},max={2},xor={2},["and"]={2},["or"]={2},["not"]={1,1},eq={2,2},lt={2,2},le={2,2},gt={2,2},ge={2,2},indicator={1,1},["if"]={3,3}}
