    for _,t in ipairs(types) do require_ok(t=="integer" or t=="rational",name.." requires numeric arguments"); any_rational=any_rational or t=="rational" end
    if name=="lt" or name=="le" or name=="gt" or name=="ge" then return "boolean" end
    if name=="rational" or name=="floor_div" then
      require_ok(types[1]=="integer" and types[2]=="integer",name.." requires integer arguments")
      require_ok(integer(args[2]) and args[2]>0,name.." needs a certified positive literal denominator")
      return name=="rational" and "rational" or "integer"
    end
    if name=="clip" then require_ok(integer(args[1]) and integer(args[2]) and args[1]<=args[2], "clip needs ordered integer limits") end
    return any_rational and "rational" or "integer"
  end
  local function evaluate(ast,env)
    if integer(ast) or type(ast)=="boolean" then return ast end
    require_ok(type(ast)=="table", "Evaluator rejects strings and floating point literals")
    if fields(ast,{ref=true}) then
      local value=env[ast.ref]
      require_ok(value~=nil, "Missing environment reference: "..tostring(ast.ref))
      require_ok(type(value)=="boolean" or integer(value) or is_rat(value), "Invalid environment value")
      return value
    end
    require_ok(fields(ast,{op=true,args=true}) and OPERATORS[ast.op]~=nil and array(ast.args), "Malformed evaluator AST")
    local name,args=ast.op,ast.args; local arity=OPERATORS[name]
    require_ok(#args>=arity[1] and (arity[2]==nil or #args==arity[2]),"Invalid evaluator arity")
    if name=="if" then
      local condition=evaluate(args[1],env); require_ok(type(condition)=="boolean", "if condition must be boolean")
