    end
    local values={}; for i,a in ipairs(args) do values[i]=evaluate(a,env) end
    if name=="add" or name=="mul" then
      local answer=name=="add" and 0 or 1
      for _,v in ipairs(values) do answer=(name=="add" and num_add or num_mul)(answer,v) end
      return answer
    end
    if name=="sub" then return num_sub(values[1],values[2]) end
    if name=="rational" then return rational(values[1],values[2]) end
    if name=="floor_div" then int(values[1]); int(values[2]); require_ok(values[2]>0,"floor_div needs a positive denominator"); return values[1]//values[2] end
    if name=="clip" then
      require_ok(compare(values[1],values[2])<=0,"clip limits are reversed")
      if compare(values[3],values[1])<0 then return values[1] elseif compare(values[3],values[2])>0 then return values[2] else return values[3] end
    end
    if name=="min" or name=="max" then
      local answer=values[1]
      for i=2,#values do local c=compare(values[i],answer); if (name=="min" and c<0) or (name=="max" and c>0) then answer=values[i] end end
      return answer
    end
    if name=="eq" then
      require_ok((type(values[1])=="boolean" and type(values[2])=="boolean") or ((integer(values[1]) or is_rat(values[1])) and (integer(values[2]) or is_rat(values[2]))), "eq needs compatible primitive types")
      return equal(values[1],values[2])
    end
    if name=="lt" then return compare(values[1],values[2])<0 end
    if name=="le" then return compare(values[1],values[2])<=0 end
    if name=="gt" then return compare(values[1],values[2])>0 end
    if name=="ge" then return compare(values[1],values[2])>=0 end
    if name=="and" or name=="or" or name=="not" or name=="indicator" then
