    require_ok(pow(2,forecasts.bits_per_report)>forecasts.quantization_denominator,"Forecast alphabet does not fit")
    require_ok(spec.evaluation.prediction_event_count==mul(forecasts.reports,clock.scored_steps),"Prediction denominator mismatch")
    require_ok(spec.evaluation.utility_denominator==mul(topology.width,clock.scored_steps),"Utility denominator mismatch")
    local ids=spec.event_id_layout
