    require_ok(clock.total_steps<pow(2,ids.physical_step_bits) and nodes<pow(2,ids.source_bits),"Event indices do not fit")
    require_ok(add(clock.total_microticks,mul(2,clock.microticks_per_step))<pow(2,ids.physical_step_bits),"Auditor acceptance/response microtime does not fit identifier field")
    require_ok(ids.time_field_meaning_by_kind.auditor=="request acceptance microtick r, not coarse step k","Auditor invocation identity must distinguish same-step requests")
    local codes={}; for _,v in pairs(ids.kind_codes) do codes[#codes+1]=v end
    require_ok(unique(codes),"Event kinds collide")
    for _,v in ipairs(codes) do require_ok(integer(v) and v>=0 and v<pow(2,ids.event_kind_bits),"Event kind does not fit identifier") end
    record("layout_clock_archive_and_score_arithmetic",1,"Record=512 bits; forecast=320 bits; archive=4 MiB; exact horizon and event counts.")

    local prior=spec.rational_prior; local cardinalities={}; local node_support=1
    for _,v in pairs(prior.per_node) do local c=distribution_size(v); cardinalities[#cardinalities+1]=c; node_support=mul(node_support,c) end
    local delay=prior.per_link_delay; local link_support=distribution_size(delay)
    local pair_support=distribution_size(prior.changed_pair)
    local shift_support=distribution_size(prior.change_scored_index)
    local blindness_support=distribution_size(prior.auditor_lifetime_blindness)
    distribution_size(spec.initial_physical_state.load)
    for _,draw in pairs(spec.fresh_draws) do if type(draw)=="table" and (draw.p or draw.family=="uniform" or draw.family=="categorical") then distribution_size(draw) end end
    local expected_shifts={}; local max_shift=0
    for i,t in ipairs(prior.change_scored_index.values) do expected_shifts[i]=add(clock.preparation_steps,t); max_shift=math.max(max_shift,expected_shifts[i]) end
    require_ok(equal(prior.change_absolute_indices,expected_shifts) and max_shift<clock.total_steps,"Shift time units disagree")
    local max_delay=math.max(table.unpack(delay.values))
    require_ok(bounds.per_link_transit_capacity>=max_delay+1,"Transit buffer insufficient")
    require_ok(bounds.node_queue_transient_capacity>=bounds.node_queue_capacity+2,"Arrival staging insufficient")
    require_ok(bounds.normal_command_history_steps>=math.max(table.unpack(prior.per_node.lambda.values))+1,"Command delay history insufficient")
    require_ok(bounds.auditor_request_slots==1 and bounds.live_readable_sensor_slots==1 and bounds.pending_sensor_generation_slots==1,"Declared asynchronous slot capacities differ")
    record("finite_priors_and_buffer_derivations",#cardinalities+8,"Exact prior masses; transit cap from maximum delay; queue staging from indegree; command-history cap from delay.")

    require_ok(machine.word_bits==64 and machine.register_words==16,"Reference hardware differs")
    local encoded_input=spec.public_contract.initial_input_encoding
