    require_ok(type(M.canonical)=="function","Canonical native Lua serializer is not supplied")
    local canonical_source=M.canonical(spec)
    local canonical_bytes=#canonical_source
    if spec==SPEC then require_ok(type(M.spec_source)=="string" and M.spec_source==canonical_source,"Canonical native Lua source bytes disagree with the active specification") end
    require_ok(encoded_input.canonical_native_lua_bytes==canonical_bytes,"Canonical public-input storage size disagrees")
    require_ok(mul(canonical_bytes,8)<=machine.maximum_initial_image_bits,"Public contract alone exceeds initial-image capacity")
    local components=machine.memory_components
    require_ok(components.archive_bits==history.bits and components.register_bits==mul(machine.register_words,machine.word_bits) and components.writable_extra_bits==machine.writable_extra_bits,"Memory-component accounting differs")
    require_ok(machine.total_budget_includes_watchdog_reserve==true,"Watchdog reserve must belong to total B")
    local watchdog=spec.interfaces.watchdog
    require_ok(watchdog.work_reserved_before_controller_allocation==mul(watchdog.work,clock.total_steps),"Watchdog reserve mismatch")
    require_ok(watchdog.work_reserved_before_controller_allocation<machine.total_work_budget,"No discretionary work remains")
    require_ok(machine.instruction_work>0 and machine.instruction_duration>0,"Instruction costs must be positive")
    for name,interface in pairs(spec.interfaces) do
      if type(interface)=="table" and interface.work~=nil then
        require_ok(integer(interface.work) and integer(interface.duration) and interface.work>0 and interface.duration>0,"Invalid positive interface cost: "..name)
        require_ok(add(interface.duration,watchdog.duration)<clock.microticks_per_step,"Interface cannot fit within a command interval: "..name)
      end
    end
    require_ok(spec.interfaces.common.processor_stalls_during_interface_transfer==true,"Sequential interface profile changed")
    require_ok(machine.writable_extra_bits%8==0 and machine.maximum_initial_image_bits%8==0,"Memory capacity is not byte aligned")
    probability(spec.evaluation.failure_tolerance)
    require_ok(equal(spec.risk_certification_accounting.actual_global_failure_target,spec.evaluation.failure_tolerance),"Certificate target differs from actual failure target")
    record("resource_and_interface_capacity",10,"Positive costs and stalls; watchdog reserve inside B; public input has "..canonical_bytes.." canonical native Lua bytes counted inside L0; individual operation timing. This does not certify any complete controller trace or peak allocation.")

    local variables=spec.expression_language.variables
    local declared={}; for name in pairs(spec.expression_language.operators) do declared[name]=true end
    local expected={}; for name in pairs(OPERATORS) do expected[name]=true end
    require_ok(equal(declared,expected),"AST operator registry differs from validator")
    for name,arity in pairs(OPERATORS) do
      local documented=spec.expression_language.operators[name]
      require_ok((arity[2]~=nil and equal(documented,{arity=arity[2]})) or (arity[2]==nil and equal(documented,{arity_min=arity[1]})),"AST documented arity differs from validator: "..name)
    end
    for name,domain in pairs(variables) do
      require_ok(domain.type=="integer" or domain.type=="boolean","Invalid variable type: "..name)
      if domain.type=="integer" then
        if domain.values then
          require_ok(array(domain.values) and #domain.values>0 and unique(domain.values),"Invalid finite variable domain: "..name)
          for _,v in ipairs(domain.values) do require_ok(integer(v),"Noninteger domain member: "..name) end
        else require_ok(integer(domain.minimum) and integer(domain.maximum) and domain.minimum<=domain.maximum,"Invalid bounded integer domain: "..name) end
      end
    end
    local thermal_names={"T_old_i","T_old_left","T_old_right","thermal_base","T_new_i","global_max_temperature"}
    for i=0,nodes-1 do thermal_names[#thermal_names+1]="T_new_"..i end
    for _,name in ipairs(thermal_names) do require_ok(equal({variables[name].minimum,variables[name].maximum},bounds.temperature_domain),"Thermal parent/state domains disagree") end
    require_ok(equal({variables.h_old_i.minimum,variables.h_old_i.maximum},bounds.degradation_domain),"Degradation domains disagree")
    require_ok(equal({variables.energy_old.minimum,variables.energy_old.maximum},bounds.energy_domain),"Energy domains disagree")
    require_ok(variables.q_plus_i.minimum==0 and variables.q_plus_i.maximum==bounds.node_queue_capacity,"Queue parent domain disagrees")
    require_ok(variables.requested_demand.minimum==0 and variables.requested_demand.maximum==2*nodes,"Demand domain disagrees")
    require_ok(variables.k.minimum==0 and variables.k.maximum==clock.total_steps-1,"AST step domain disagrees")
    require_ok(equal(variables.change_scored_index.values,prior.change_scored_index.values),"AST shift prior differs")
    for _,pair in ipairs({{"rho_i","rho"},{"gamma_i","gamma"},{"eta_i","eta"},{"temperature_bias","temperature_bias"},{"occupancy_bias","occupancy_bias"}}) do require_ok(equal(variables[pair[1]].values,prior.per_node[pair[2]].values),"AST parameter prior differs: "..pair[1]) end
    require_ok(equal(variables.sensor_error.values,spec.fresh_draws.sensor_noise.values),"AST sensor noise support differs")
    require_ok(variables.forecast_numerator.maximum==forecasts.quantization_denominator and variables.completed_jobs.maximum==spec.evaluation.utility_denominator,"Scoring domains disagree")
    require_ok(variables.brier_sum_numerator.maximum==mul(spec.evaluation.prediction_event_count,pow(forecasts.quantization_denominator,2)),"Brier accumulator domain disagrees")
    local laws=spec.algebraic_laws; local law_count=0
    for name,law in pairs(laws) do
      require_ok(infer_type(law.expression,variables)==law.result_type,"Law result type mismatch: "..name)
      require_ok(array(law.bounds) and #law.bounds==2 and compare(law.bounds[1],law.bounds[2])<=0,"Malformed law range: "..name)
      law_count=law_count+1
    end
    record("typed_ast_validation",law_count,"All references, arities, result types and literal positive division denominators checked; no strings evaluated.")
    local function value(name,env)
      local law=laws[name]; local answer=evaluate(law.expression,env)
      local for_bounds=answer
      if type(answer)=="boolean" then for_bounds=answer and 1 or 0 end
      require_ok(compare(law.bounds[1],for_bounds)<=0 and compare(for_bounds,law.bounds[2])<=0,"Law outside declared bounds: "..name)
      local expected_type=law.result_type
      require_ok((expected_type=="boolean" and type(answer)=="boolean") or (expected_type=="integer" and integer(answer)) or (expected_type=="rational" and is_rat(answer)),"Runtime type differs: "..name)
      return answer
    end
    local probability_cases=0
    for _,name in ipairs({"source_arrival_probability","service_success_probability","thermal_noise_probability","load_next_one_probability","fault_next_one_probability"}) do
      local names=keys(references(laws[name].expression)); local domains={}
      for i,n in ipairs(names) do domains[i]=values_for(variables[n]) end
      product(domains,function(...)
        local args={...}; local env={}; for i,n in ipairs(names) do env[n]=args[i] end
        local p=value(name,env)
        require_ok(compare(p,0)>=0 and compare(p,1)<=0 and equal(num_add(p,num_sub(1,p)),1),"Conditional Bernoulli mass invalid: "..name)
        probability_cases=probability_cases+1
      end)
    end
    record("exhaustive_conditional_probability_domains",probability_cases,"All complete finite parents of five probability laws; exact reduced-rational normalization.")

    local shifts=0
    product({values_for(variables.k),values_for(variables.change_scored_index),BOOLEAN},function(k,tau,member)
      local actual=value("structural_shift",{k=k,change_scored_index=tau,node_in_changed_pair=member})
      require_ok(not actual or k>=clock.preparation_steps+tau,"Structural shift activates before its declared physical time")
      require_ok(actual==(member and k>=clock.preparation_steps+tau),"Scored and absolute shift clocks disagree")
      shifts=shifts+1
    end)
    local orientation=laws.orientation.expression; local shift_ast=laws.structural_shift.expression
    local expected_orientation=expr("xor",ref("b_i"),expr("xor",expr("mul",ref("z_i"),expr("indicator",expr("ge",ref("q_plus_i"),ref("rho_i")))),expr("indicator",shift_ast)))
    require_ok(equal(orientation,expected_orientation),"Orientation must compose declared occupancy and structural-shift factors")
    require_ok(equal(laws.processing_channel.expression,expr("if",expr("eq",orientation,0),ref("a1_i"),ref("a2_i"))),"Processing channel must compose only declared orientation")
    require_ok(equal(laws.cooling_channel.expression,expr("if",expr("eq",orientation,0),ref("a2_i"),ref("a1_i"))),"Cooling channel must compose only declared orientation")
    local cases=0
    product({BINARY,BINARY,range(0,16),{4,8},BOOLEAN,BINARY,BINARY},function(b,z,q,rho,shifted,a1,a2)
      local env={b_i=b,z_i=z,q_plus_i=q,rho_i=rho,k=shifted and 2560 or 1024,change_scored_index=1536,node_in_changed_pair=true,a1_i=a1,a2_i=a2}
      local orientation_value=value("orientation",env)
      local p,c=value("processing_channel",env),value("cooling_channel",env)
      require_ok(p+c==a1+a2 and (a1~=a2 or (p==a1 and c==a2)),"Channel permutation breaks demand or diagonal equivalence")
      require_ok((orientation_value==0 and p==a1 and c==a2) or (orientation_value==1 and p==a2 and c==a1),"Swap does not follow declared orientation")
      cases=cases+1
    end)
    record("shift_and_factored_orientation_domains",shifts+cases,"All physical shift times; all occupancy thresholds and boolean correction/channel factors. Structural factor composition is checked before reduction.")

    local base_ast=laws.thermal_diffusion_base.expression
    local factored_ast=laws.temperature_update_from_base.expression
    require_ok(equal(replace(factored_ast,ref("thermal_base"),base_ast),laws.temperature_update.expression),"Full thermal law differs from declared factorization")
    local reachable_bases={}; local thermal_cases=0
    product({range(0,63),range(0,63),range(0,63)},function(center,left,right)
      local base=value("thermal_diffusion_base",{T_old_i=center,T_old_left=left,T_old_right=right})
      require_ok(base<=math.max(center,left,right),"Diffusion exceeds old neighborhood maximum")
      reachable_bases[base]=true; thermal_cases=thermal_cases+1
    end)
    for i=0,63 do require_ok(reachable_bases[i]==true,"Thermal factor domain is not exact") end
    require_ok(#keys(reachable_bases)==64,"Thermal factor domain exceeds the declared domain")
    local heat_cases,stop_cases=0,0
    product({range(0,63),{2,3,4},BINARY,BINARY,{3,4,5},BINARY,BINARY},function(base,gamma,g,p,eta,c,xi)
      local env={thermal_base=base,gamma_i=gamma,g_old=g,p_i=p,eta_i=eta,c_i=c,xi_i=xi,T_old_i=base,T_old_left=base,T_old_right=base}
      local updated=value("temperature_update_from_base",env)
      require_ok(updated==value("temperature_update",env),"Thermal factorization changes a result")
      if p==0 and c==0 then require_ok(updated<=base,"STOP increases the thermal diffusion base"); stop_cases=stop_cases+1 end
      heat_cases=heat_cases+1
    end)
    record("exhaustive_thermal_update_and_stop",thermal_cases+heat_cases,"All 64^3 old-neighbor triples and "..heat_cases.." distinct heat-parent cases; "..stop_cases.." STOP cases. Checked factorization covers the full parent product.")

    local degradation_cases=0
    product({range(0,63),range(0,2),BINARY,BINARY,BINARY},function(temp,h,g,p,c)
      local env={T_old_i=temp,h_old_i=h,g_old=g,p_i=p,c_i=c}
      local up,down=value("degradation_up_threshold",env),value("degradation_down_threshold",env)
      require_ok(up<=down,"Degradation exceptional ranges overlap")
      local counts={}
      for noise=0,63 do
        env.degradation_U=noise; local updated=value("degradation_update",env)
        require_ok(math.abs(updated-h)<=1,"Degradation moves more than one level")
        counts[updated]=(counts[updated] or 0)+1; degradation_cases=degradation_cases+1
      end
      local mass=rational(0,1)
      for _,count in pairs(counts) do mass=num_add(mass,rational(count,64)) end
      require_ok(equal(mass,1),"Degradation transition mass is not one")
    end)
    record("exhaustive_degradation_transition",degradation_cases,"Every old temperature, degradation, load, channel pair and uniform-noise outcome; disjoint exceptional ranges and exact transition mass.")

    local sensor_cases=0
    product({range(0,63),range(-2,2),BINARY,{-1,0,1}},function(temp,bias,fault,noise)
      value("sensor_temperature",{T_new_i=temp,temperature_bias=bias,F_new=fault,sensor_error=noise}); sensor_cases=sensor_cases+1
    end)
    product({range(0,16),{-1,0,1},BINARY,{-1,0,1}},function(q,bias,fault,noise)
      value("sensor_occupancy",{q_plus_i=q,occupancy_bias=bias,F_new=fault,sensor_error=noise}); sensor_cases=sensor_cases+1
    end)
    record("exhaustive_sensor_encoding_domains",sensor_cases,"All true sensor parents, fixed biases, shared-fault values and fresh noise values; encoded ranges fit their declared fields.")

    local auditor_cases=0
    product({BINARY,BINARY,range(0,16),{4,8},BOOLEAN,BINARY,BINARY},function(b,z,q,rho,shifted,blind,noise)
      local env={b_i=b,z_i=z,q_plus_i=q,rho_i=rho,k=shifted and 2560 or 1024,change_scored_index=1536,node_in_changed_pair=true,A=blind,E=noise}
      local answer=value("auditor_response",env); local target=blind==1 and b or value("orientation",env)
      require_ok(answer==(target ~ noise),"Auditor violates lifetime-blindness or fresh-flip law")
      auditor_cases=auditor_cases+1
    end)
    record("exhaustive_factored_auditor_domains",auditor_cases,"Every occupancy and persistent/fresh binary factor; blindness suppresses the entire correction. This is not a theorem about a deployed verifier's error rate.")

    local energy_cases=0
    product({range(0,64),range(0,32)},function(old,demand)
      local env={energy_old=old,requested_demand=demand}
      local replenished,rejected,new=value("energy_replenished",env),value("energy_rejected",env),value("energy_next",env)
      local expected_new; if rejected then expected_new=replenished else expected_new=replenished-demand end
      require_ok(new==expected_new,"Energy accounting fails conservation after rejection")
      require_ok(rejected==(demand>replenished),"Energy rejection boundary differs")
      energy_cases=energy_cases+1
    end)
    record("exhaustive_global_energy_domains",energy_cases,"Every energy level and feasible total binary-channel demand; recharge cap, rejection boundary and retained energy.")

    local max_ast=laws.global_max_temperature.expression; local node_refs={}
    for i=0,nodes-1 do node_refs[#node_refs+1]=ref("T_new_"..i) end
    require_ok(equal(max_ast,expr("max",table.unpack(node_refs))),"Global thermal maximum omits or duplicates a node")
    require_ok(equal(replace(laws.global_failure_from_max.expression,ref("global_max_temperature"),max_ast),laws.global_failure_update.expression),"Failure update differs from maximum factorization")
    local failure_cases=0
    product({BINARY,range(0,63)},function(old,maximum)
      local failed=value("global_failure_from_max",{D_old=old,global_max_temperature=maximum})
      require_ok(failed==((old==1 or maximum>=48) and 1 or 0),"Failure flag is not absorbing at the thermal threshold")
      for position=0,nodes-1 do
        local env={D_old=old}; for i=0,nodes-1 do env["T_new_"..i]=(i==position) and maximum or 0 end
        require_ok(value("global_failure_update",env)==failed,"A node's thermal failure is omitted")
        failure_cases=failure_cases+1
      end
    end)
    record("factored_global_failure_and_absorption",failure_cases,"All old-failure values and reachable thermal maxima; every node can independently trigger failure. Checked max-composition covers arbitrary temperature vectors.")

    local reward_cases=0; local full_gate=laws.safe_scored_completion_gate.expression
    for _,pair in ipairs({{"birth_eligible","birth_scored"},{"deadline_eligible","completion_on_time"},{"horizon_eligible","completion_within_horizon"}}) do full_gate=replace(full_gate,ref(pair[1]),laws[pair[2]].expression) end
    require_ok(equal(full_gate,laws.safe_scored_completion.expression),"Full completion law differs from declared eligibility-gate composition")
    product({BOOLEAN,BOOLEAN,BOOLEAN,BOOLEAN,BOOLEAN,BOOLEAN},function(success,birth,deadline,horizon,old,new)
      local gate=value("safe_scored_completion_gate",{terminal_success=success,birth_eligible=birth,deadline_eligible=deadline,horizon_eligible=horizon,D_old=old and 1 or 0,D_new=new and 1 or 0})
      require_ok(gate==(success and birth and deadline and horizon and not old and not new),"Completion gate admits failed, late or ineligible reward")
      reward_cases=reward_cases+1
    end)
    for k=0,clock.total_steps-1 do
      value("completion_boundary",{k=k})
      require_ok(value("completion_within_horizon",{k=k}),"Valid step ends beyond horizon")
      for age=0,12 do
        local birth=k-age
        if birth>=0 then
          local env={k=k,job_birth=birth,job_deadline=birth+12,terminal_success=true,D_old=0,D_new=0}
          local actual=value("safe_scored_completion",env)
          local expected_completion=value("birth_scored",env) and value("completion_on_time",env) and value("completion_within_horizon",env)
          require_ok(actual==expected_completion,"Full completion law differs from eligibility composition")
          require_ok(value("completion_on_time",env)==(age<=11),"Job deadline off-by-one error")
          reward_cases=reward_cases+1
        end
      end
    end
    record("exhaustive_completion_gate_and_deadline_classes",reward_cases,"Six-factor gate truth table, every active step, and every valid boundary-intersecting job age. Expired jobs are structurally removed; long-expired states are not admissible queue parents.")

    local score_cases=0; local denominator=pow(forecasts.quantization_denominator,2)
    product({range(0,forecasts.quantization_denominator),BINARY},function(numerator,outcome)
      local env={forecast_numerator=numerator,prediction_outcome=outcome}
      local square,loss=value("brier_squared_numerator",env),value("brier_event_loss",env)
      require_ok(equal(loss,rational(square,denominator)),"Brier loss differs from its exact grid numerator")
      if numerator==128 then require_ok(equal(loss,rational(1,4)),"Missing-report default has incorrect loss") end
      score_cases=score_cases+1
    end)
    for complete=0,spec.evaluation.utility_denominator do value("normalized_utility",{completed_jobs=complete}); score_cases=score_cases+1 end
    require_ok(equal(laws.normalized_brier_loss.expression,expr("rational",ref("brier_sum_numerator"),mul(spec.evaluation.prediction_event_count,denominator))),"Normalized Brier denominator is not the full fixed event set")
    for _,total in ipairs({0,variables.brier_sum_numerator.maximum}) do value("normalized_brier_loss",{brier_sum_numerator=total}); score_cases=score_cases+1 end
    record("exact_grid_prediction_and_normalization",score_cases,"Every grid forecast/outcome pair and utility count; missing-report loss; fixed-event Brier normalization is an exact nonnegative linear map checked at both endpoints.")

    local parameter_worlds="1"
    for _=1,nodes do parameter_worlds=decimal_multiply(parameter_worlds,node_support) end
    for _=1,topology.link_count do parameter_worlds=decimal_multiply(parameter_worlds,link_support) end
    for _,factor in ipairs({pair_support,shift_support,blindness_support}) do parameter_worlds=decimal_multiply(parameter_worlds,factor) end
    local risk_target=probability(spec.evaluation.failure_tolerance)
    require_ok(equal(risk_target,rational(1,1048576)),"The historical rare-risk sample count is tied to delta=2^-20")
    local finite_cases=0; for _,item in ipairs(checks) do finite_cases=add(finite_cases,item.cases) end
    return {
      valid=true,artifact_kind=spec.artifact_kind,benchmark_id=spec.benchmark_id,checks=checks,finite_cases_checked=finite_cases,
      persistent_parameter_realizations=parameter_worlds,
      rare_risk_zero_failure_episode_count=3141252,
      zero_failure_sampling_design={
        status="historical analytic required sample size only; no episodes were run; this integer is retained from the verified source calculation, not computed with floating point here",
        target_failure_probability={risk_target.n,risk_target.d},one_sided_confidence={95,100},formula="ceil(log(0.05)/log1p(-delta))",
        trial_unit="one complete independently initialized preparation-and-scoring episode",
        assumptions="IID full-episode failure indicators for one fixed precommitted controller and one declared evaluation distribution. Fresh independent latent realizations support Bayesian-distribution evaluation; a fixed parameter realization gives a conditional result only. No adaptive selection, censoring, distribution change, or multiple-controller search is covered without additional correction.",
        warning="A zero-failure empirical bound is not a controller safety proof, a per-world robust guarantee, or evidence that these simulations were performed."
