  end
  M.evaluate=evaluate
  M.infer_type=infer_type
  M.validate=validate
  M.rational=rational
  M.rational_equal=equal
  M.checked_integer={add=add,sub=sub,mul=mul}

  local function clone(value)
    if type(value)~="table" then return value end
    local out={}; for k,v in pairs(value) do out[k]=clone(v) end; return out
  end
  M.selftest=function()
    local tests=0
    local function rejected(label,f,expected_message)
      local ok,err=pcall(f)
      require_ok(not ok and tostring(err):find(expected_message,1,true),"Self-test did not reject "..label.." at its intended guard")
      tests=tests+1
    end
    require_ok(evaluate(expr("if",false,true,false),{})==false,"Lazy if must preserve a false result"); tests=tests+1
    require_ok(evaluate(expr("if",true,7,ref("unavailable")),{})==7,"Unselected if branch must not evaluate"); tests=tests+1
    require_ok(evaluate(expr("floor_div",-5,2),{})==-3,"Negative signed floor division differs"); tests=tests+1
    require_ok(equal(evaluate(expr("rational",6,8),{}),rational(3,4)),"Exact rational reduction differs"); tests=tests+1
    require_ok(equal(num_mul(rational(MAX,2),rational(2,MAX)),1),"Rational cross cancellation must precede products"); tests=tests+1
    rejected("bool arithmetic",function() evaluate(expr("add",true,1),{}) end,"Numeric argument cannot")
    rejected("float literal",function() evaluate(0.5,{}) end,"floating point literals")
    rejected("unknown AST reference",function() infer_type(ref("missing"),{}) end,"Unknown AST reference")
    rejected("zero denominator",function() infer_type(expr("rational",1,0),{}) end,"positive literal denominator")
    rejected("addition overflow",function() add(MAX,1) end,"addition overflow")
    rejected("subtraction overflow",function() sub(MIN,1) end,"subtraction overflow")
    rejected("multiplication overflow",function() mul(MAX,2) end,"multiplication overflow")
    rejected("double minimum overflow",function() mul(MIN,-1) end,"multiplication overflow")
    require_ok(mul(MIN,1)==MIN and mul(-3,-4)==12 and mul(MAX,-1)==-MAX,"Checked multiplication rejects valid boundary arithmetic"); tests=tests+1
    local mutations={
      {name="record packing",message="Record packing mismatch",change=function(s) s.record_layout.total_bits=513 end},
      {name="buffer capacity",message="Transit buffer insufficient",change=function(s) s.bounded_state.per_link_transit_capacity=2 end},
      {name="illegal probability",message="Law outside declared bounds: service_success_probability",change=function(s) s.algebraic_laws.service_success_probability.expression=expr("rational",2,1) end},
      {name="unknown law reference",message="Unknown AST reference",change=function(s) s.algebraic_laws.source_arrival_probability.expression=ref("hidden_free_state") end}
    }
    for _,mutation in ipairs(mutations) do
      local altered=clone(SPEC); mutation.change(altered)
      local encoding=altered.public_contract.initial_input_encoding
      for _=1,10 do
        local bytes=#M.canonical(altered)
        if encoding.canonical_native_lua_bytes==bytes then break end
        encoding.canonical_native_lua_bytes=bytes
      end
      rejected(mutation.name,function() validate(altered) end,mutation.message)
    end
    return {valid=true,tests_passed=tests,scope="Lua arithmetic, evaluator and four finite-specification rejection guards; not deployed-controller behavior"}
  end
end

-- All report serialization and command handling below are standard Lua.
local function help()
  io.write("One-file Lua architecture handoff. Lua 5.4, 64-bit integers.\n",
    "--prompt    Print the complete Claude Code Lua-only implementation prompt.\n",
    "--validate  Run exact finite-law specification validation.\n",
    "--selftest  Run meaningful rejection and numeric safeguard checks.\n",
    "--all       Run validation and selftests, then print a Lua-table report.\n",
    "--spec      Print the authoritative native Lua SPEC table.\n",
    "--evidence  Print archived validation evidence and representation lineage.\n",
    "--help      Show this guide.\n",
    "No other input file or package is required.\n")
end

local function cli(option)
  if option == nil or option == "--help" then help(); return 0 end
  if option == "--prompt" then io.write(CLAUDE_PROMPT); return 0 end
  if option == "--spec" then io.write("return ", M.canonical(M.spec), "\n"); return 0 end
  if option == "--evidence" then
    io.write("return ", M.canonical({lineage=M.lineage, historical=M.archived_validation_report}), "\n")
    return 0
  end
  local report
  if option == "--validate" then report = M.validate(M.spec)
  elseif option == "--selftest" then report = M.selftest()
  elseif option == "--all" then
    report = {validation=M.validate(M.spec), selftests=M.selftest(),
      scope="Finite mathematical law validation only; no intelligent controller or benchmark wins",
      lineage=M.lineage}
  else
    io.stderr:write("Unknown option: ", tostring(option), "\n")
    return 2
  end
  io.write("return ", M.canonical(report), "\n")
  return 0
end
M.cli = cli

local invocation = arg and arg[0] or ""
local is_main = invocation:gsub("\\", "/"):match("([^/]+)$") == "superintelligence-lua-only-complete.lua"
if is_main then
  local ok, status = pcall(cli, arg[1])
  if not ok then
    io.stderr:write("Validation/command failed: ", tostring(status), "\n")
    os.exit(1)
  end
  os.exit(status)
end
return M

end

-- ======================================================================== asi.spec  (asi/spec.lua)
package.preload["asi.spec"] = function(...)
--[============[
asi/spec.lua -- authoritative constants derived from the handoff SPEC table.

The handoff file is loaded ONCE as trusted local Lua data (the only dofile in the project;
no model / candidate / checkpoint / proof content is ever executed). Every constant used by
the simulator and machine is READ FROM the SPEC and independently re-asserted against the
numbers printed in the mathematical text, so a drifted SPEC or a drifted constant fails at
load time instead of silently changing the benchmark.

Topology / index conventions (documented once, used everywhere):
  node index        n = 4*layer + column, layer 0..3, column 0..3 (thermal ring is n mod 16)
  successors        (layer+1, column) for route bit 0 and (layer+1, (column+1) mod 4) for 1
  link index        l = 8*layer + 2*column + route   (layer 0..2 => 24 links 0..23)
  job id            (episode<<48) | (birth_step<<16) | (kind<<8) | source   (arrival kind = 1)
  event id (64 bit) (episode<<48) | (time_field<<16) | (kind<<8) | source
  record words      a 512-bit record is 8 big-endian words, bits MSB first
]============]
local U = require("asi.util")

local here = (debug.getinfo(1, "S").source:match("^@(.*)/asi/spec%.lua$")) or "."
local handoff_path = here .. "/handoff/superintelligence-lua-only-complete.lua"

local function load_handoff()
  -- single-file bundle (bundle.lua): the handoff text is embedded as the body of the module "asi.handoff_source"
  local chunk, err = package.preload["asi.handoff_source"], nil
  if not chunk then chunk, err = loadfile(handoff_path) end    -- trusted local handoff only
  if not chunk then error("cannot load handoff: " .. tostring(err), 0) end
  local saved = _G.arg
  _G.arg = {[0] = "asi-loader"}               -- keep the handoff from running its own CLI
  local ok, M = pcall(chunk)
  _G.arg = saved
  if not ok then error("handoff failed to load: " .. tostring(M), 0) end
  return M
end

local H = load_handoff()
local SPEC = H.spec
local S = {handoff = H, spec = SPEC, handoff_path = handoff_path}

local function expect(cond, msg) if not cond then error("spec constant drift: " .. msg, 0) end end

-- ------------------------------------------------------------------ clock & scoring
local clock = SPEC.clock
S.DELTA = clock.microticks_per_step
S.STEPS = clock.total_steps
S.PREP_STEPS = clock.preparation_steps
S.SCORED_STEPS = clock.scored_steps
S.TOTAL_TICKS = clock.total_microticks
S.FIRST_SCORED = clock.scored_processing_indices.first
S.LAST_SCORED = clock.scored_processing_indices.last
expect(S.DELTA == 8192 and S.STEPS == 5120 and S.PREP_STEPS == 1024 and S.SCORED_STEPS == 4096, "clock")
expect(S.TOTAL_TICKS == 41943040 and S.TOTAL_TICKS == S.STEPS * S.DELTA, "total ticks")
expect(S.FIRST_SCORED == 1024 and S.LAST_SCORED == 5119, "scored indices")

-- ------------------------------------------------------------------ topology
S.LAYERS, S.WIDTH = SPEC.topology.layers, SPEC.topology.width
S.NODES = S.LAYERS * S.WIDTH
S.LINKS = SPEC.topology.link_count
expect(S.NODES == 16 and S.LINKS == 24 and S.WIDTH == 4 and S.LAYERS == 4, "topology")
S.QCAP = SPEC.bounded_state.node_queue_capacity
S.QSTAGE = SPEC.bounded_state.node_queue_transient_capacity
S.TRANSIT_CAP = SPEC.bounded_state.per_link_transit_capacity
S.HIST_STEPS = SPEC.bounded_state.normal_command_history_steps
expect(S.QCAP == 16 and S.QSTAGE == 18 and S.TRANSIT_CAP == 3 and S.HIST_STEPS == 3, "bounded state")
S.DEADLINE_SPAN = 12          -- job deadline = birth + 12 (spec 7.3, bounded_state.job_deadline)
S.FAIL_TEMP = 48              -- absorbing failure at updated temperature >= 48 (spec 7.3 item 5)
S.HOT_TEMP = 40               -- thermal forecast indicator threshold 1{T >= 40}
S.TEMP_MAX = SPEC.bounded_state.temperature_domain[2]
S.ENERGY_MAX = SPEC.bounded_state.energy_domain[2]
S.ENERGY_REPLENISH = 12
S.INIT_TEMP, S.INIT_ENERGY = SPEC.initial_physical_state.temperatures, SPEC.initial_physical_state.energy
expect(S.TEMP_MAX == 63 and S.ENERGY_MAX == 64 and S.INIT_TEMP == 16 and S.INIT_ENERGY == 64, "state domains")

function S.node(layer, col) return 4 * layer + col end
function S.layer_of(n) return n // 4 end
function S.col_of(n) return n % 4 end
-- successor node and link index for a non-terminal node and route bit
function S.successor(n, route)
  local layer, col = n // 4, n % 4
  assert(layer < 3, "terminal nodes have no successors")
  local ncol = (route == 0) and col or ((col + 1) % 4)
  return 4 * (layer + 1) + ncol, 8 * layer + 2 * col + route
end
S.link_table = {}
for n = 0, 11 do
  for route = 0, 1 do
    local dst, l = S.successor(n, route)
    S.link_table[l] = {src = n, dst = dst, route = route}
  end
end
do local c = 0; for _ in pairs(S.link_table) do c = c + 1 end; expect(c == 24, "link table size") end

-- ------------------------------------------------------------------ priors (supports)
local prior = SPEC.rational_prior
S.PRIOR = prior
S.CHANGE_SCORED = prior.change_scored_index.values       -- {1536,2048,2560}
S.CHANGE_ABS = prior.change_absolute_indices             -- {2560,3072,3584}
expect(S.CHANGE_SCORED[1] == 1536 and S.CHANGE_ABS[3] == 3584, "shift support")

-- ------------------------------------------------------------------ interfaces
local I = SPEC.interfaces
S.COST = {
  sensor_read = I.sensor_read.work,          -- 72
  command_submit = I.command_submit.work,    -- 65
  auditor_invoke = I.auditor_invoke.work,    -- 128
  auditor_read = I.auditor_read.work,        -- 128
  auditor_cancel = I.auditor_cancel.work,    -- 128
  forecast_submit = I.forecast_submit.work,  -- 6
  page_setup = I.page_read.setup_work_duration,   -- 2048
  page_word = I.page_read.per_64_bit_word_work_duration, -- 1
  instruction = SPEC.machine.instruction_work,
  watchdog_per_step = I.watchdog.work,
}
expect(S.COST.sensor_read == 72 and S.COST.command_submit == 65 and S.COST.auditor_invoke == 128, "interface costs")
expect(S.COST.auditor_read == 128 and S.COST.auditor_cancel == 128 and S.COST.forecast_submit == 6, "interface costs 2")
expect(S.COST.page_setup == 2048 and S.COST.page_word == 1 and S.COST.instruction == 1, "interface costs 3")
S.PAGE_WORDS = I.page_read.full_page_words           -- 512
S.PAGES = SPEC.record_layout.history.pages           -- 1024
S.RECORD_BITS = SPEC.record_layout.total_bits        -- 512
S.RECORD_WORDS = S.RECORD_BITS // 64
S.RECORDS_PER_EPISODE = SPEC.record_layout.history.steps_per_episode
S.ARCHIVE_EPISODES = SPEC.record_layout.history.episodes
S.AUDITOR_DELAY_STEPS = 2
S.ACTIVE_EPISODE_ID = SPEC.event_id_layout.active_episode_id
S.KIND = SPEC.event_id_layout.kind_codes             -- sensor 0 arrival 1 auditor 2 forecast 3
expect(S.PAGE_WORDS == 512 and S.PAGES == 1024 and S.RECORD_BITS == 512 and S.ACTIVE_EPISODE_ID == 1024, "archive")
expect(S.KIND.sensor == 0 and S.KIND.arrival == 1 and S.KIND.auditor == 2 and S.KIND.forecast == 3, "kinds")

-- ------------------------------------------------------------------ machine / memory
local MC = SPEC.machine
S.WORK_BUDGET = MC.total_work_budget                 -- 2^25
S.WATCHDOG_RESERVE = I.watchdog.work_reserved_before_controller_allocation  -- 5120
S.DISCRETIONARY_WORK = S.WORK_BUDGET - S.WATCHDOG_RESERVE
S.MAX_IMAGE_BITS = MC.maximum_initial_image_bits     -- 2^20
S.REGISTERS = MC.register_words
S.WORD_BITS = MC.word_bits
