expect(S.ARCHIVE_BITS == 65536 * 512 and S.WRITABLE_BITS == 262144 and S.REGISTER_BITS == 1024, "memory comps")
function S.total_memory_bits(L0_bits) return S.ARCHIVE_BITS + L0_bits + S.REGISTER_BITS + S.WRITABLE_BITS end

-- ------------------------------------------------------------------ risk / scoring
S.RISK_NUM, S.RISK_DEN = SPEC.evaluation.failure_tolerance[1], SPEC.evaluation.failure_tolerance[2]
expect(S.RISK_NUM == 1 and S.RISK_DEN == 1048576, "risk target 2^-20")
S.UTILITY_DEN = SPEC.evaluation.utility_denominator        -- 16384
S.PRED_EVENTS = SPEC.evaluation.prediction_event_count     -- 81920
