-- ======================================================================== asi.laws  (asi/laws.lua)
package.preload["asi.laws"] = function(...)
--[============[
asi/laws.lua -- native integer implementations of the SPEC's typed algebraic laws.

These are the fast laws used by the simulator and by the guest-side models' reference
checks. They are NOT trusted on their own: asi/validate.lua differentially tests every law
here against the SPEC's typed AST (evaluated by two independent evaluators: the handoff's
and asi/astx.lua) over the complete finite parent domains.

Probabilities are returned as (numerator, denominator) integer pairs, never floats.
]============]
local L = {}

local function clip(lo, hi, x) if x < lo then return lo elseif x > hi then return hi end return x end
L.clip = clip

-- (N6) thermal factorisation: diffusion base uses OLD values of the node and its two ring neighbours
function L.thermal_base(T, Tl, Tr) return (4 * T + Tl + Tr) // 6 end
function L.temp_update(base, gamma, g, p, eta, c, xi)
  return clip(0, 63, base + (gamma + g) * p - eta * c - 1 + xi)
end
-- (N7) degradation; U uniform on 0..63; the two exceptional ranges are disjoint
function L.degradation_update(h, U, g, p, c, T_old)
  local hot = (T_old >= 40) and 1 or 0
  if U < 1 + g + p * hot then return math.min(2, h + 1)
  elseif U >= 64 - 2 * c then return math.max(0, h - 1)
  else return h end
end
function L.degradation_up_threshold(g, p, T_old) return 1 + g + p * ((T_old >= 40) and 1 or 0) end
function L.degradation_down_threshold(c) return 64 - 2 * c end

-- energy interface: returns replenished, rejected(bool), next
function L.energy(e_old, demand)
  local plus = math.min(64, e_old + 12)
  if demand > plus then return plus, true, plus end
  return plus, false, plus - demand
end

-- (N3) orientation sigma
function L.shifted(member, k, tau)         -- tau is the SCORED change index (1536/2048/2560)
  return member and k >= 1024 and (k - 1024) >= tau
end
function L.orientation(b, z, q_plus, rho, shifted)
  return b ~ ((z * ((q_plus >= rho) and 1 or 0)) ~ (shifted and 1 or 0))
end
-- (N4) physical outputs: returns p (processing), c (cooling)
function L.channels(sigma, a1, a2)
  if sigma == 0 then return a1, a2 end
  return a2, a1
end

-- (N5),(N8),(N9) conditional probabilities as {num,den}
function L.service_prob(h, g) return 15 - 2 * h - g, 16 end
function L.arrival_prob(g) return 1 + g, 4 end
function L.thermal_noise_prob(g) return 1 + g, 8 end
function L.load_next_prob(g) if g == 0 then return 1, 32 else return 7, 8 end end   -- P(g'=1)
function L.fault_next_prob(F, g) if F == 0 then return 1 + g, 256 else return 15, 16 end end -- P(F'=1)

-- (N10),(N11) sensor encodings
function L.sensor_temperature(T_new, bias, F_new, err) return clip(0, 31, T_new // 2 + bias - 3 * F_new + err) end
function L.sensor_occupancy(q_plus, bias, F_new, err) return clip(0, 8, q_plus // 2 + bias - F_new + err) end

-- (N12) auditor response bit
function L.auditor(b, z, q_plus, rho, A, member, k, tau, E)
  local sh = L.shifted(member, k, tau) and 1 or 0
  local inner = (z * ((q_plus >= rho) and 1 or 0)) ~ sh
  return b ~ ((1 - A) * inner) ~ E
end

-- scoring
function L.brier_num(r, outcome) local d = r - 256 * outcome; return d * d end   -- over 65536
function L.birth_scored(birth) return birth >= 1024 and birth < 5120 end
function L.completion_on_time(k, deadline) return k + 1 <= deadline end
function L.completion_within_horizon(k) return k + 1 <= 5120 end
function L.safe_scored_completion(terminal_success, birth, k, deadline, D_old, D_new)
  return terminal_success and L.birth_scored(birth) and L.completion_on_time(k, deadline)
    and L.completion_within_horizon(k) and D_old == 0 and D_new == 0
end
function L.global_failure(D_old, max_T) return (D_old == 1 or max_T >= 48) and 1 or 0 end

--[[@@END@@]]
return L
end

-- ======================================================================== asi.astx  (asi/astx.lua)
package.preload["asi.astx"] = function(...)
--[============[
asi/astx.lua -- independent typed-AST type checker and evaluator for the SPEC expression
language ("finite-expr-1").

This is a SECOND implementation (the handoff ships its own). The two are cross-checked in
asi/validate.lua. Rules (spec expression_language.semantics):
  * literals are integers or booleans; strings / floats are rejected, nothing is ever load()ed
  * integer arithmetic is exact (BigInt-backed); rational returns an exact reduced pair
  * floor_div floors toward negative infinity; xor takes binary integers; and/or/not booleans
  * if evaluates ONLY the selected branch; clip(lo,hi,x); min/max variadic
  * operator arities come from the registry below and are checked statically
]============]
local B = require("asi.bigint")
local Q = B.Q
local X = {}

local REG = {
  add = {2}, mul = {2}, sub = {2, 2}, rational = {2, 2}, floor_div = {2, 2}, clip = {3, 3},
  min = {2}, max = {2}, xor = {2}, ["and"] = {2}, ["or"] = {2}, ["not"] = {1, 1},
  eq = {2, 2}, lt = {2, 2}, le = {2, 2}, gt = {2, 2}, ge = {2, 2}, indicator = {1, 1}, ["if"] = {3, 3},
}
X.registry = REG

local function bad(msg) error("astx: " .. msg, 0) end
local function isint(v) return math.type(v) == "integer" end

-- static type inference: "integer" | "boolean" | "rational"
function X.infer(ast, vars)
  if type(ast) == "boolean" then return "boolean" end
  if isint(ast) then return "integer" end
  if type(ast) ~= "table" then bad("node is not an integer, boolean or table (prose is not code)") end
  if ast.ref ~= nil then
    local n = 0; for _ in pairs(ast) do n = n + 1 end
    if n ~= 1 or type(ast.ref) ~= "string" then bad("malformed reference node") end
    if not vars[ast.ref] then bad("unknown reference " .. ast.ref) end
    return vars[ast.ref].type
  end
  local op, args = ast.op, ast.args
  if type(op) ~= "string" or type(args) ~= "table" or REG[op] == nil then bad("unknown or malformed operator") end
  local lo, hi = REG[op][1], REG[op][2]
  if #args < lo or (hi and #args > hi) then bad("arity violation for " .. op) end
  local ts = {}
  for i, a in ipairs(args) do ts[i] = X.infer(a, vars) end
  local function all(t) for _, x in ipairs(ts) do if x ~= t then return false end end return true end
  local function numeric() for _, x in ipairs(ts) do if x == "boolean" then return false end end return true end
  if op == "and" or op == "or" or op == "not" then
    if not all("boolean") then bad(op .. " needs booleans") end
    return "boolean"
  elseif op == "indicator" then
    if ts[1] ~= "boolean" then bad("indicator needs a boolean") end
    return "integer"
  elseif op == "if" then
    if ts[1] ~= "boolean" or ts[2] ~= ts[3] then bad("if needs boolean condition and equal branch types") end
    return ts[2]
  elseif op == "xor" then
    if not all("integer") then bad("xor needs binary integers") end
    return "integer"
  elseif op == "eq" then
    if ts[1] ~= ts[2] and (ts[1] == "boolean" or ts[2] == "boolean") then bad("eq type mismatch") end
    return "boolean"
  end
  if not numeric() then bad(op .. " needs numeric arguments") end
  if op == "lt" or op == "le" or op == "gt" or op == "ge" then return "boolean" end
  if op == "rational" or op == "floor_div" then
    if ts[1] ~= "integer" or ts[2] ~= "integer" then bad(op .. " needs integers") end
    if not (isint(args[2]) and args[2] > 0) then bad(op .. " needs a positive literal denominator") end
    return op == "rational" and "rational" or "integer"
  end
  if op == "clip" then
    if not (isint(args[1]) and isint(args[2]) and args[1] <= args[2]) then bad("clip needs ordered literal limits") end
  end
  for _, x in ipairs(ts) do if x == "rational" then return "rational" end end
  return "integer"
end

local function num(v)       -- numeric value as rational
  if Q.is(v) then return v end
  if B.is(v) then return Q.from(v) end
  return Q.from(v)
end

local function intval(v)    -- exact integer view of a numeric value (BigInt)
  return B.from(v)
end

function X.eval(ast, env)
  if type(ast) == "boolean" then return ast end
  if isint(ast) then return ast end
  if type(ast) ~= "table" then bad("evaluator rejects non-integer literals") end
  if ast.ref ~= nil then
    local v = env[ast.ref]
    if v == nil then bad("missing environment value " .. tostring(ast.ref)) end
    return v
  end
  local op, args = ast.op, ast.args
  if op == "if" then
    local c = X.eval(args[1], env)
    if type(c) ~= "boolean" then bad("if condition must be boolean") end
    if c then return X.eval(args[2], env) end
    return X.eval(args[3], env)
  end
  local v = {}
  for i, a in ipairs(args) do v[i] = X.eval(a, env) end
  local function anyq() for _, x in ipairs(v) do if Q.is(x) then return true end end return false end
  local function norm(q)            -- keep integer-typed results as Lua ints when they fit
    if Q.is(q) and B.eq(q.d, 1) then return q.n end
    return q
  end
  if op == "add" or op == "mul" or op == "sub" then
    local acc
    if op == "sub" then acc = Q.sub(num(v[1]), num(v[2]))
    elseif op == "add" then acc = Q.from(0); for _, x in ipairs(v) do acc = Q.add(acc, num(x)) end
    else acc = Q.from(1); for _, x in ipairs(v) do acc = Q.mul(acc, num(x)) end end
    if anyq() then return acc end
    local r = acc.n
    return B.fits_int(r) and B.to_int(r) or r
  elseif op == "rational" then
    return Q.make(B.from(v[1]), B.from(v[2]))
  elseif op == "floor_div" then
    local q = B.divmod(B.from(v[1]), B.from(v[2]))
    return B.fits_int(q) and B.to_int(q) or q
  elseif op == "clip" then
    local lo, hi, x = num(v[1]), num(v[2]), num(v[3])
    local r
    if Q.lt(x, lo) then r = v[1] elseif Q.lt(hi, x) then r = v[2] else r = v[3] end
    return r
  elseif op == "min" or op == "max" then
    local best = v[1]
    for i = 2, #v do
      local c = Q.cmp(num(v[i]), num(best))
      if (op == "min" and c < 0) or (op == "max" and c > 0) then best = v[i] end
    end
    return best
  elseif op == "eq" then
    if type(v[1]) == "boolean" or type(v[2]) == "boolean" then return v[1] == v[2] end
    return Q.eq(num(v[1]), num(v[2]))
  elseif op == "lt" then return Q.lt(num(v[1]), num(v[2]))
  elseif op == "le" then return Q.le(num(v[1]), num(v[2]))
  elseif op == "gt" then return Q.lt(num(v[2]), num(v[1]))
  elseif op == "ge" then return Q.le(num(v[2]), num(v[1]))
  elseif op == "and" or op == "or" then
    local acc = (op == "and")
    for _, x in ipairs(v) do
      if type(x) ~= "boolean" then bad(op .. " needs booleans") end
      if op == "and" then acc = acc and x else acc = acc or x end
    end
    return acc
  elseif op == "not" then
    if type(v[1]) ~= "boolean" then bad("not needs a boolean") end
    return not v[1]
  elseif op == "indicator" then
    if type(v[1]) ~= "boolean" then bad("indicator needs a boolean") end
    return v[1] and 1 or 0
  elseif op == "xor" then
    local acc = 0
    for _, x in ipairs(v) do
      if not (isint(x) and (x == 0 or x == 1)) then bad("xor input outside {0,1}") end
      acc = acc ~ x
    end
    return acc
  end
  bad("unsupported operator " .. tostring(op))
end

-- comparable view of a result: booleans stay booleans, integers/rationals -> reduced "n/d"
function X.canon(v)
  if type(v) == "boolean" then return v end
  if B.is(v) then return B.tostring(v) .. "/1" end
  if Q.is(v) then return Q.tostring(v) end
  return tostring(v) .. "/1"
end

function X.refs(ast, out)
  out = out or {}
  if type(ast) == "table" then
    if ast.ref then out[ast.ref] = true else for _, a in ipairs(ast.args) do X.refs(a, out) end end
  end
  return out
end

--[[@@END@@]]
return X
end

-- ======================================================================== asi.validate  (asi/validate.lua)
package.preload["asi.validate"] = function(...)
--[============[
asi/validate.lua -- level 1 (specification consistency) validation.

Two layers, kept deliberately separate:
  (a) the PRESERVED handoff validator (spec.handoff.validate / selftest), run unchanged;
  (b) an INDEPENDENT check_spec(): own layout arithmetic, own exact prior masses (BigInt),
      own AST type check + evaluation (asi/astx.lua), and DIFFERENTIAL tests of the native
      laws (asi/laws.lua) against the SPEC ASTs over the complete finite parent domains,
      cross-checked against the handoff's evaluator on samples.

check_spec(spec, opts) raises "InvalidSpec: ..." on any violation so that malformed-input
rejection tests (asi/tests/t_validate.lua) can mutate a clone and demand rejection.
Passing establishes ONLY the local finite-law properties it lists; it is not a controller,
simulator conformance, a safety proof or a benchmark result.
]============]
local U = require("asi.util")
local B = require("asi.bigint")
local Q = B.Q
local X = require("asi.astx")
local L = require("asi.laws")
local V = {}

local function req(cond, msg) if not cond then error("InvalidSpec: " .. msg, 0) end end

-- cartesian product iterator over arrays of candidate values
local function product(domains, cb)
  local n, row = #domains, {}
  local function rec(i)
    if i > n then return cb(table.unpack(row, 1, n)) end
    for _, v in ipairs(domains[i]) do row[i] = v; rec(i + 1) end
  end
  rec(1)
end
local function range(a, b) local t = {}; for i = a, b do t[#t + 1] = i end; return t end
local BIN, BOOL = {0, 1}, {false, true}

local function rat_pair(n, d) return Q.make(n, d) end

-- ---------------------------------------------------------------- the checker
function V.check_spec(spec, opts)
  opts = opts or {}
  local H = opts.handoff
  local checks = {}
  local function record(name, cases, detail) checks[#checks + 1] = {check = name, cases = cases, detail = detail} end

  req(spec.schema_version == "3.0-lua" and spec.artifact_kind == "typed_finite_law_specification", "schema/kind")
  local clock, topo, bs = spec.clock, spec.topology, spec.bounded_state
  local layout, fl, ev = spec.record_layout, spec.forecast_layout, spec.evaluation

  -- ---- layout, clock, archive arithmetic (own computation)
  local nodes = topo.layers * topo.width
  req(nodes == 16, "node count")
  req(topo.link_count == 2 * topo.width * (topo.layers - 1), "link count must be 2*width*(layers-1)")
  req(clock.total_steps == clock.preparation_steps + clock.scored_steps, "clock horizons")
  req(clock.total_microticks == clock.total_steps * clock.microticks_per_step, "physical horizon")
  req(clock.scored_processing_indices.first == clock.preparation_steps and
      clock.scored_processing_indices.last == clock.total_steps - 1, "scored index range")
  local sum, w = 0, {}
  for _, f in ipairs(layout.fields) do req(w[f[1]] == nil, "duplicate record field " .. f[1]); w[f[1]] = f[2]; sum = sum + f[2] end
  req(sum == 512 and layout.total_bits == 512, "Record packing mismatch")
  req(w.event_id == 64 and w.episode_id == 16 and w.physical_step == 32, "record id fields")
  req(w.occupancy_measurements == 4 * nodes and w.temperature_measurements == 5 * nodes, "sensor field widths")
  req(w.latched_requested_channels_and_routes == 3 * nodes and w.source_arrivals == topo.width, "actuator/arrival widths")
  req(layout.history.records == layout.history.episodes * layout.history.steps_per_episode, "archive records")
  req(layout.history.bits == layout.history.records * 512 and layout.history.bits == layout.history.bytes * 8, "archive bits")
  req(layout.history.pages * spec.interfaces.page_read.full_page_words * 64 == layout.history.bits, "archive pages")
  local pr = spec.interfaces.page_read
  req(pr.full_page_work_duration == pr.setup_work_duration + pr.full_page_words * pr.per_64_bit_word_work_duration, "page cost")
  req(fl.reports == topo.width + nodes, "forecast report count")
  req(fl.reports * fl.bits_per_report + fl.event_id_bits + fl.timestamp_bits + fl.zero_padding_bits == fl.total_bits and
      fl.total_bits == 320, "Forecast packing mismatch")
  req(ev.prediction_event_count == fl.reports * clock.scored_steps, "prediction denominator")
  req(ev.utility_denominator == topo.width * clock.scored_steps, "utility denominator")
  local id = spec.event_id_layout
  req(id.episode_bits + id.physical_step_bits + id.event_kind_bits + id.source_bits == 64, "identifier widths")
  req(spec.interfaces.watchdog.work_reserved_before_controller_allocation == spec.interfaces.watchdog.work * clock.total_steps, "watchdog reserve")
  for name, itf in pairs(spec.interfaces) do
    if type(itf) == "table" and itf.work ~= nil then
      req(itf.work > 0 and itf.duration > 0, "non-positive interface cost " .. name)
      req(itf.duration + spec.interfaces.watchdog.duration < clock.microticks_per_step, "interface does not fit a step " .. name)
    end
  end
  req(bs.per_link_transit_capacity >= 2 + 1, "Transit buffer insufficient")
  req(bs.node_queue_transient_capacity >= bs.node_queue_capacity + 2, "Arrival staging insufficient")
  req(bs.normal_command_history_steps >= 2 + 1, "Command delay history insufficient")
  record("layout_clock_archive", 1, "record 512 bits, forecast 320 bits, archive 4 MiB, horizon and event counts recomputed independently")

  -- ---- exact prior masses and world-count (BigInt)
  local prior = spec.rational_prior
  local function support(dist)
    if dist.family == "bernoulli" then
      local p = rat_pair(dist.p[1], dist.p[2]); req(Q.sign(p) >= 0 and Q.le(p, 1), "bernoulli probability outside [0,1]")
      return (Q.sign(p) > 0 and Q.lt(p, 1)) and 2 or 1, Q.from(1)
    elseif dist.family == "uniform" then
      local n = #dist.values
      req(n > 0, "empty uniform support")
      local seen = {}
      for _, v in ipairs(dist.values) do req(not seen[v], "duplicate support value"); seen[v] = true end
      return n, Q.mul(Q.make(1, n), n)
    elseif dist.family == "categorical" then
      local m = Q.from(0)
      for _, pq in ipairs(dist.probabilities) do m = Q.add(m, Q.make(pq[1], pq[2])) end
      req(Q.eq(m, 1), "categorical mass must sum exactly to one")
      return #dist.values, m
    elseif dist.family == "uniform_unordered_pair" then
      local n = dist.population * (dist.population - 1) // 2
      req(n == dist.support_size, "pair support cardinality")
      return n, Q.from(1)
    end
    error("InvalidSpec: unknown distribution family " .. tostring(dist.family), 0)
  end
  local node_support, count = B.from(1), 0
  for _, d in pairs(prior.per_node) do local n, mass = support(d); req(Q.eq(mass, 1), "prior mass"); node_support = node_support * n; count = count + 1 end
  local link_support = support(prior.per_link_delay)
  local worlds = B.pow(node_support, nodes) * B.pow(B.from(link_support), topo.link_count)
  worlds = worlds * support(prior.changed_pair) * support(prior.change_scored_index) * support(prior.auditor_lifetime_blindness)
  req(count == 8, "eight per-node persistent parameters expected")
  req(B.tostring(worlds) == "29989054468492955302925100657671500094869675791561523200000000000000000" or opts.skip_world_count,
    "persistent parameter realizations differ from the published count")
  for i, t in ipairs(prior.change_scored_index.values) do
    req(prior.change_absolute_indices[i] == clock.preparation_steps + t, "Shift time units disagree")
  end
  record("exact_prior_masses_and_world_count", count + 5, "every support finite, mass exactly 1 (BigInt rationals); parameter realizations " .. B.tostring(worlds))

  -- ---- AST typing + differential evaluation
  local vars = spec.expression_language.variables
  local laws = spec.algebraic_laws
  local nlaws = 0
  for name, law in pairs(laws) do
    local ty = X.infer(law.expression, vars)
    req(ty == law.result_type, "Law result type mismatch: " .. name)
    req(law.bounds[1] <= law.bounds[2], "Malformed law range: " .. name)
    nlaws = nlaws + 1
  end
  record("typed_ast_validation", nlaws, "every law typed by asi/astx.lua; references declared; arities per registry; literal positive denominators")

  local function ev_law(name, env)
    local v = X.eval(laws[name].expression, env)
    local b = (type(v) == "boolean") and (v and 1 or 0) or v
    local lo, hi = laws[name].bounds[1], laws[name].bounds[2]
    local qv = Q.is(b) and b or Q.from(b)
    req(Q.le(lo, qv) and Q.le(qv, hi), "Law outside declared bounds: " .. name)
    return v
  end
  local function same(name, env, expected)
    local v = ev_law(name, env)
    local want = X.canon(expected)
    local got = X.canon(v)
    if got ~= want then
      local parts = {}
      for k, x in pairs(env) do parts[#parts + 1] = k .. "=" .. tostring(x) end
      table.sort(parts)
      error("InvalidSpec: law " .. name .. " disagrees with native law at " .. table.concat(parts, ",") ..
            " (spec " .. tostring(got) .. " native " .. tostring(want) .. ")", 0)
    end
  end

  local cases = 0
  -- probability laws on complete finite parents
  for g = 0, 1 do
    same("source_arrival_probability", {g_old = g}, rat_pair(L.arrival_prob(g)))
    same("thermal_noise_probability", {g_old = g}, rat_pair(L.thermal_noise_prob(g)))
    same("load_next_one_probability", {g_old = g}, rat_pair(L.load_next_prob(g)))
    for h = 0, 2 do same("service_success_probability", {h_old_i = h, g_old = g}, rat_pair(L.service_prob(h, g))); cases = cases + 1 end
    for F = 0, 1 do same("fault_next_one_probability", {F_old = F, g_old = g}, rat_pair(L.fault_next_prob(F, g))); cases = cases + 1 end
    cases = cases + 3
  end
  record("exhaustive_probability_domains", cases, "all finite parents of the five conditional Bernoulli laws equal the native laws and lie in [0,1]")

  -- thermal: diffusion base on ALL 64^3 triples (own evaluator), factored update on all 9216 heat-parent cases
  cases = 0
  local base_ast = laws.thermal_diffusion_base.expression
  local reachable = {}
  local stride = opts.thermal_stride or 1       -- 1 = exhaustive (--validate); >1 = quick sampling (--selftest)
  for c = 0, 63, stride do for l = 0, 63, stride do for r = 0, 63, stride do
    local v = X.eval(base_ast, {T_old_i = c, T_old_left = l, T_old_right = r})
    local nb = L.thermal_base(c, l, r)
    req(v == nb, "thermal base differs from native law")
    req(nb <= math.max(c, l, r) and nb >= math.min(c, l, r), "diffusion base outside old neighbourhood range")
    reachable[nb] = true; cases = cases + 1
  end end end
  if stride == 1 then for i = 0, 63 do req(reachable[i], "thermal base domain not exact (missing " .. i .. ")") end end
  local stop_cases, heat = 0, 0
  product({range(0, 63), {2, 3, 4}, BIN, BIN, {3, 4, 5}, BIN, BIN}, function(base, gamma, g, p, eta, c, xi)
    local env = {thermal_base = base, gamma_i = gamma, g_old = g, p_i = p, eta_i = eta, c_i = c, xi_i = xi}
    local want = L.temp_update(base, gamma, g, p, eta, c, xi)
    req(X.eval(laws.temperature_update_from_base.expression, env) == want, "Law disagrees: temperature_update_from_base")
    local full = {T_old_i = base, T_old_left = base, T_old_right = base, gamma_i = gamma, g_old = g, p_i = p, eta_i = eta, c_i = c, xi_i = xi}
    req(X.eval(laws.temperature_update.expression, full) == want, "Law disagrees: temperature_update")
    if p == 0 and c == 0 then req(want <= base, "STOP raised a node temperature above its diffusion base"); stop_cases = stop_cases + 1 end
    heat = heat + 1
  end)
  -- randomized full-law check over unequal neighbour triples
  local seed = 99
  local function rnd(n) seed = (seed * 6364136223846793005 + 1442695040888963407); return ((seed >> 33) % n) end
  local nrand = opts.fast and 1500 or 20000
  for _ = 1, nrand do
    local T, Tl, Tr = rnd(64), rnd(64), rnd(64)
    local gamma, g, p, eta, c, xi = 2 + rnd(3), rnd(2), rnd(2), 3 + rnd(3), rnd(2), rnd(2)
    local env = {T_old_i = T, T_old_left = Tl, T_old_right = Tr, gamma_i = gamma, g_old = g, p_i = p, eta_i = eta, c_i = c, xi_i = xi}
    req(X.eval(laws.temperature_update.expression, env) == L.temp_update(L.thermal_base(T, Tl, Tr), gamma, g, p, eta, c, xi), "Law disagrees: temperature_update (random)")
    if H then
      req(H.evaluate(laws.temperature_update.expression, env) == L.temp_update(L.thermal_base(T, Tl, Tr), gamma, g, p, eta, c, xi), "handoff evaluator disagrees: temperature_update")
    end
  end
  record("exhaustive_thermal_update_and_stop", cases + heat + nrand, "diffusion triples (stride " .. stride .. "), " .. heat .. " heat-parent cases (" .. stop_cases .. " STOP), " .. nrand .. " unequal-neighbour samples; base within neighbourhood range")

  -- STOP maximum-temperature invariance, independent of the AST: for every ring of the form (T_{i-1},T_i,T_{i+1}) in 0..47
  -- the STOP update never exceeds the neighbourhood maximum (so a ring maximum cannot increase)
  cases = 0
  local ss = opts.fast and 5 or 1
  for c = 0, 47, ss do for l = 0, 47, ss do for r = 0, 47, ss do
    local m = math.max(c, l, r)
    for xi = 0, 1 do req(L.temp_update(L.thermal_base(c, l, r), 4, 1, 0, 3, 0, xi) <= m, "STOP max invariance violated"); cases = cases + 1 end
  end end end
  record("stop_max_temperature_invariance", cases, "STOP (p=c=0): updated node <= max of its old neighbourhood for every old triple below 48 and both noise values")

  -- degradation: every old temperature, level, load, channel pair and noise outcome
  cases = 0
  product({opts.fast and {0, 1, 17, 39, 40, 41, 63} or range(0, 63), range(0, 2), BIN, BIN, BIN}, function(T, h, g, p, c)
    local env = {T_old_i = T, h_old_i = h, g_old = g, p_i = p, c_i = c}
    req(L.degradation_up_threshold(g, p, T) <= L.degradation_down_threshold(c), "Degradation exceptional ranges overlap")
    same("degradation_up_threshold", env, L.degradation_up_threshold(g, p, T))
    same("degradation_down_threshold", env, L.degradation_down_threshold(c))
    local mass = {}
    for U_ = 0, 63 do
      env.degradation_U = U_
      local nh = L.degradation_update(h, U_, g, p, c, T)
      req(X.eval(laws.degradation_update.expression, env) == nh, "Law disagrees: degradation_update")
      req(math.abs(nh - h) <= 1 and nh >= 0 and nh <= 2, "degradation left its domain or moved by more than one")
      mass[nh] = (mass[nh] or 0) + 1; cases = cases + 1
    end
    local tot = 0; for _, m in pairs(mass) do tot = tot + m end
    req(tot == 64, "degradation transition mass")
  end)
  record("exhaustive_degradation_transition", cases, "every temperature, level, load, channel pair and uniform noise outcome vs native law; ranges disjoint; mass 64/64")

  -- sensors
  cases = 0
  product({opts.fast and {0, 1, 2, 31, 62, 63} or range(0, 63), range(-2, 2), BIN, {-1, 0, 1}}, function(T, bias, F, e)
    same("sensor_temperature", {T_new_i = T, temperature_bias = bias, F_new = F, sensor_error = e}, L.sensor_temperature(T, bias, F, e)); cases = cases + 1
  end)
  product({range(0, 16), {-1, 0, 1}, BIN, {-1, 0, 1}}, function(q, bias, F, e)
    same("sensor_occupancy", {q_plus_i = q, occupancy_bias = bias, F_new = F, sensor_error = e}, L.sensor_occupancy(q, bias, F, e)); cases = cases + 1
  end)
  record("exhaustive_sensor_encoding_domains", cases, "all true sensor parents, biases, shared-fault values, noise values; clipped codes within their 5/4 bit fields")

  -- orientation / shift / auditor
  cases = 0
  local ks = {}
  for _, tau in ipairs(prior.change_scored_index.values) do
    for _, k in ipairs({0, 1, 1023, 1024, 1024 + tau - 1, 1024 + tau, 5119}) do ks[#ks + 1] = {k, tau} end
  end
  for _, kt in ipairs(ks) do for _, member in ipairs(BOOL) do
    local k, tau = kt[1], kt[2]
    local sh = L.shifted(member, k, tau)
    req(sh == (member and k >= 1024 + tau), "scored and absolute shift clocks disagree")
    same("structural_shift", {k = k, change_scored_index = tau, node_in_changed_pair = member}, sh); cases = cases + 1
  end end
  product({BIN, BIN, opts.fast and {0, 3, 4, 7, 8, 16} or range(0, 16), {4, 8}, BIN, BIN, BIN, BIN}, function(b, z, q, rho, A, E, a1, a2)
    for _, member in ipairs(BOOL) do for _, kt in ipairs({{1500, 1536}, {2560, 1536}}) do
      local k, tau = kt[1], kt[2]
      local env = {b_i = b, z_i = z, q_plus_i = q, rho_i = rho, A = A, E = E, a1_i = a1, a2_i = a2, k = k, change_scored_index = tau, node_in_changed_pair = member}
      local sh = L.shifted(member, k, tau)
      local sigma = L.orientation(b, z, q, rho, sh)
      same("orientation", env, sigma)
      local p, c = L.channels(sigma, a1, a2)
      same("processing_channel", env, p); same("cooling_channel", env, c)
      req(p + c == a1 + a2 and (a1 ~= a2 or (p == a1 and c == a2)), "orientation swap changes demand or breaks diagonal invariance")
      same("auditor_response", env, L.auditor(b, z, q, rho, A, member, k, tau, E))
      local target = (A == 1) and b or sigma
      req(L.auditor(b, z, q, rho, A, member, k, tau, E) == (target ~ E), "auditor lifetime blindness law")
      cases = cases + 1
    end end
  end)
  record("exhaustive_orientation_shift_auditor", cases, "every occupancy/persistent/fresh factor; swap conserves demand; diagonal channels orientation invariant; blindness suppresses the whole correction")

  -- energy
  cases = 0
  product({opts.fast and {0, 1, 20, 52, 63, 64} or range(0, 64), opts.fast and {0, 1, 11, 12, 13, 32} or range(0, 32)}, function(e, d)
    local env = {energy_old = e, requested_demand = d}
    local plus, rej, nxt = L.energy(e, d)
    same("energy_replenished", env, plus); same("energy_rejected", env, rej); same("energy_next", env, nxt)
    req(rej == (d > plus) and nxt == (rej and plus or plus - d) and nxt >= 0 and nxt <= 64, "energy conservation")
    cases = cases + 1
  end)
  record("exhaustive_global_energy_domains", cases, "every energy level and demand: recharge cap, rejection boundary, retained energy")

  -- absorbing failure, global max
  cases = 0
  product({BIN, range(0, 63)}, function(D, m)
    same("global_failure_from_max", {D_old = D, global_max_temperature = m}, L.global_failure(D, m))
    for pos = 0, nodes - 1 do
      local env = {D_old = D}
      for i = 0, nodes - 1 do env["T_new_" .. i] = (i == pos) and m or 0 end
      same("global_failure_update", env, L.global_failure(D, m))
      same("global_max_temperature", env, m)
      cases = cases + 1
    end
  end)
  record("absorbing_failure_and_global_max", cases, "failure flag absorbing; every node alone can trigger failure at 48")

  -- completion eligibility and scoring
  cases = 0
  product({BOOL, BOOL, BOOL, BOOL, BOOL, BOOL}, function(s, bi, di, hi, o, n)
    local env = {terminal_success = s, birth_eligible = bi, deadline_eligible = di, horizon_eligible = hi, D_old = o and 1 or 0, D_new = n and 1 or 0}
    same("safe_scored_completion_gate", env, s and bi and di and hi and not o and not n); cases = cases + 1
  end)
  for k = 0, clock.total_steps - 1, (opts.fast and 97 or 1) do
    same("completion_boundary", {k = k}, k + 1)
    same("completion_within_horizon", {k = k}, L.completion_within_horizon(k))
    for age = 0, 12 do
      local birth = k - age
      if birth >= 0 then
        local env = {k = k, job_birth = birth, job_deadline = birth + 12, terminal_success = true, D_old = 0, D_new = 0}
        same("birth_scored", env, L.birth_scored(birth))
        same("completion_on_time", env, L.completion_on_time(k, birth + 12))
        same("safe_scored_completion", env, L.safe_scored_completion(true, birth, k, birth + 12, 0, 0))
        req(L.completion_on_time(k, birth + 12) == (age <= 11), "job deadline off-by-one")
        cases = cases + 1
      end
    end
  end
  record("completion_gate_and_deadline_classes", cases, "six-factor gate truth table; every step and valid job age; on time exactly when k+1 <= deadline")

  cases = 0
  for r = 0, 256 do for o = 0, 1 do
    local sq = L.brier_num(r, o)
    same("brier_squared_numerator", {forecast_numerator = r, prediction_outcome = o}, sq)
    same("brier_event_loss", {forecast_numerator = r, prediction_outcome = o}, Q.make(sq, 65536))
    cases = cases + 1
  end end
  req(L.brier_num(128, 0) == 16384 and L.brier_num(128, 1) == 16384, "missing-report forecast 1/2 loses 1/4")
  for c = 0, ev.utility_denominator, 16 do same("normalized_utility", {completed_jobs = c}, Q.make(c, 16384)); cases = cases + 1 end
  for _, tot in ipairs({0, vars.brier_sum_numerator.maximum}) do
    same("normalized_brier_loss", {brier_sum_numerator = tot}, Q.make(tot, ev.prediction_event_count * 65536)); cases = cases + 1
  end
  record("exact_grid_prediction_and_normalization", cases, "every grid forecast/outcome pair, utility counts, normalized Brier endpoints")

  local total = 0; for _, c in ipairs(checks) do total = total + c.cases end
  return {valid = true, benchmark_id = spec.benchmark_id, checks = checks, finite_cases_checked = total}
end

-- ------------------------------------------------------------ preserved handoff path
function V.run_handoff(H)
  local report = H.validate(H.spec)
  local selftest = H.selftest()
  return report, selftest
end

--[[@@END@@]]
return V
end

-- ======================================================================== asi.world  (asi/world.lua)
package.preload["asi.world"] = function(...)
--[============[
asi/world.lua -- exact event-driven simulator of the 16-node / 24-link benchmark
("causal-service-network-16-v3"). EVALUATOR SIDE: nothing here is reachable by the controller
except through the charged interfaces defined below (the VM calls them with explicit
microtick start/end times).

TIME AND ATOMIC BOUNDARIES
  boundary k occurs at microtick k*Delta (Delta = 8192). World.advance(t) processes every
  boundary with k*Delta <= t, in order. At boundary k >= 1 the atomic phases are, in this
  exact order and with no controller instruction between them:
     (A) mature packet k-2 (if present) into the single readable latch (overwrites),
     (B) finalize step k-1 (thermal/degradation/failure/scoring/departures) and generate its
         packet k-1 into the single pending slot,
     (C) begin step k if k < horizon (arrivals, expiry, capacity, STOP / delayed commands,
         energy, orientation, service draws, physical-noise draws).
  Boundary 0 only begins step 0. Interface effects that complete exactly at a boundary see the
  state AFTER those phases. All thermal neighbours use OLD values (no sequential update).

INTERFACE ARGUMENT / ACCEPTANCE RULES (spec interfaces.common)
  arguments are snapshotted at the START microtick; effects happen at COMPLETION.
  command / forecast submission started in window j targets boundary j+1 and is accepted iff
  completion <= (j+1)*Delta - 1 (the final microtick of every window belongs to the watchdog);
  a late submission is charged and rejected, never rolled into a later boundary.

STATUS CODES returned by interface calls (the VM converts them to register values)
  0 OK, 1 LATE (charged, rejected), 2 NOT_READY, 3 INVALID, 4 BUSY, 5 EMPTY, 6 ERASED

WORD FORMATS (MSB-first, see asi/spec.lua)
  command word   : bit 48 = STOP flag, bits 47..0 = 16 node triples (a1<<2 | a2<<1 | route),
                   node 0 in the most significant triple; STOP requires payload 0; terminal
                   nodes (12..15) must have route bit 0; bits 49..63 must be zero.
  sensor packet  : 8 words, layout of spec.record_layout.fields.
  forecast frame : 5 words: id(64) | timestamp(32) | 20 x 9-bit reports | 44 zero bits;
                   id = (1024<<48)|(target_step<<16)|(3<<8); timestamp = target_step*Delta.
  auditor result : 2 words: event id, then (k<<8)|(node<<1)|bit.
]============]
local U = require("asi.util")
local R = require("asi.rng")
local S = require("asi.spec")
local L = require("asi.laws")

local World = {}
World.__index = World

local DELTA, NODES = S.DELTA, S.NODES
World.OK, World.LATE, World.NOT_READY, World.INVALID, World.BUSY, World.EMPTY, World.ERASED = 0, 1, 2, 3, 4, 5, 6
local OK, LATE, NOT_READY, INVALID, BUSY, EMPTY, ERASED = 0, 1, 2, 3, 4, 5, 6

-- ----------------------------------------------------------------- persistent parameters
-- Draw order (documented replay contract): for node 0..15: b,z,rho,gamma,eta,lambda,betaT,betaq;
-- then links 0..23 delay; then changed pair; then tau; then A. Streams: (seed,"theta").
function World.sample_theta(seed)
  local r = R.new(seed, "theta")
  local th = {b = {}, z = {}, rho = {}, gamma = {}, eta = {}, lambda = {}, betaT = {}, betaq = {}, dl = {}}
  for i = 0, NODES - 1 do
    th.b[i] = r:bit(1, 2); th.z[i] = r:bit(1, 4)
    th.rho[i] = r:pick({4, 8}); th.gamma[i] = r:pick({2, 3, 4}); th.eta[i] = r:pick({3, 4, 5})
    th.lambda[i] = r:pick({0, 1, 2}); th.betaT[i] = r:pick({-2, -1, 0, 1, 2}); th.betaq[i] = r:pick({-1, 0, 1})
  end
  for l = 0, S.LINKS - 1 do th.dl[l] = r:pick({0, 1, 2}) end
  local pair = r:subset(2, NODES)
  th.S = {[pair[1]] = true, [pair[2]] = true}; th.pair = pair
  th.tau = r:pick(S.CHANGE_SCORED)
  th.A = r:bit(1, 8)
  return th
end

-- deterministic "extreme" members of the prior support for robust evaluation
function World.extreme_theta(kind, seed)
  local th = World.sample_theta(seed or 1)
  local function all(field, v) for i = 0, NODES - 1 do th[field][i] = v end end
  if kind == "hot" then            -- fastest heating, weakest cooling, no command delay, long link delays
    all("gamma", 4); all("eta", 3); all("lambda", 0); for l = 0, S.LINKS - 1 do th.dl[l] = 2 end
  elseif kind == "delayed" then    -- maximal actuator delay with hot parameters
    all("gamma", 4); all("eta", 3); all("lambda", 2); for l = 0, S.LINKS - 1 do th.dl[l] = 0 end
  elseif kind == "cool" then
    all("gamma", 2); all("eta", 5); all("lambda", 1)
  elseif kind == "flip" then       -- every node reorients with occupancy at the smallest threshold
    all("z", 1); all("rho", 4); all("gamma", 4); all("eta", 3)
  elseif kind == "blind" then
    th.A = 1; all("z", 1); all("rho", 4)
  else error("unknown extreme world '" .. tostring(kind) .. "'") end
  return th
end

-- ------------------------------------------------------------------------ constructor
-- opts: episode_id, steps (horizon), historical (bool: raw logger, no delays, no structural
-- change, no scoring), structural_change (bool), archive (table of pages), label (stream label)
function World.new(theta, seed, opts)
  opts = opts or {}
  local w = setmetatable({}, World)
  w.theta = theta
  w.episode = opts.episode_id or S.ACTIVE_EPISODE_ID
  w.steps = opts.steps or S.STEPS
  w.historical = opts.historical or false
  w.structural = (opts.structural_change ~= false) and not w.historical
  w.label = opts.label or "active"
  -- independent streams so that EXOGENOUS processes (arrivals, load, fault, thermal noise, degradation noise)
  -- consume a fixed number of words per step and are IDENTICAL across controllers (common random numbers);
  -- only the service stream depends on the controller's powering decisions.
  w.phys = R.new(seed, "phys/" .. w.label)        -- initial load, arrivals, load/fault chains
  w.noise = R.new(seed, "noise/" .. w.label)      -- thermal noise xi and degradation noise U
  w.serv = R.new(seed, "serv/" .. w.label)        -- service successes (variable count)
  w.sens = R.new(seed, "sens/" .. w.label)
  w.audr = R.new(seed, "audr/" .. w.label)
  w.archive = opts.archive
  w.erased = {}
  -- state (node arrays are 0-based tables)
  w.queue, w.T, w.h, w.hist, w.qplus = {}, {}, {}, {}, {}
  for i = 0, NODES - 1 do
    w.queue[i] = {}; w.T[i] = S.INIT_TEMP; w.h[i] = 0; w.hist[i] = {[0] = 0, 0, 0}; w.qplus[i] = 0
  end
  w.transit = {}
  for l = 0, S.LINKS - 1 do w.transit[l] = {head = 1, tail = 0} end
  w.e = S.INIT_ENERGY
  w.g = w.phys:bernoulli(1, 5) and 1 or 0
  w.F = 0
  w.D = 0
  w.fail_step = nil
  w.next_boundary = 0
  w.now = 0
  w.latch = {}                 -- latch[target boundary] = {stop=, word=, trip={}}
  w.pending, w.readable = nil, nil
  w.aud = nil
  w.committed = {}             -- committed[target step] = report array (latest accepted)
  w.ctx = nil
  w.log = {}                   -- historical logger (raw packets at generation)
  w.hist_words = {}
  -- evaluator accumulators
  w.completed = 0              -- scored-birth safe on-time completions (utility numerator)
  w.bg_completions, w.terminal_completions = 0, 0
  w.brier_arrival, w.brier_thermal = 0, 0
  w.scored_events = 0
  w.forecasts_accepted, w.forecasts_rejected = 0, 0
  w.cmd_accepted, w.cmd_rejected = 0, 0
  w.stop_boundaries, w.reject_energy = 0, 0
  w.maxT_seen = S.INIT_TEMP
  w.per_step = opts.trace and {} or nil
  -- optional FIXED INTERVENTION PROTOCOL (evaluation only): protocol(k) -> latch table {stop=, word=, trip=} or nil (STOP).
  -- When set, the commands the controller submits are still accepted/charged/counted but the protocol is what is applied,
  -- so that predictors can be compared on the same intervention (controlled thermal prediction, cross-predictor claims).
  w.protocol = opts.protocol
  return w
end

-- ----------------------------------------------------------------------- helpers
local function job_before(a, b) if a.dl ~= b.dl then return a.dl < b.dl end return a.id < b.id end

local function insert_job(q, job)
  local pos = #q + 1
  for i = 1, #q do if job_before(job, q[i]) then pos = i; break end end
  table.insert(q, pos, job)
end

local function member(w, i) return w.theta.S[i] == true end

function World:requested_payload(trip)
  local v = 0
  for i = 0, NODES - 1 do v = (v << 3) | trip[i] end
  return v
end

-- --------------------------------------------------------------------- step begin
function World:begin_step(k)
  local th, rng = self.theta, self.phys
  local ctx = {k = k, arrivals = {}, succ = {}, xi = {}, Ud = {}, p = {}, c = {}, route = {}, applied = {}}
  -- (1) due link arrivals
  for l = 0, S.LINKS - 1 do
    local buf, lk = self.transit[l], S.link_table[l]
    while buf.head <= buf.tail and buf[buf.head].arr <= k do
      local e = buf[buf.head]; buf[buf.head] = nil; buf.head = buf.head + 1
      assert(e.arr == k, "link arrival skipped its boundary")
      insert_job(self.queue[lk.dst], e.job)
    end
  end
  -- source arrivals at the four first-layer nodes, probability (1+g)/4 conditional on g_k
  local ap, ad = L.arrival_prob(self.g)
  for j = 0, 3 do
    local a = rng:bernoulli(ap, ad)
    ctx.arrivals[j] = a and 1 or 0
    if a then
      insert_job(self.queue[j], {id = (self.episode << 48) | (k << 16) | (S.KIND.arrival << 8) | j, birth = k, dl = k + S.DEADLINE_SPAN})
    end
  end
  -- expiry (eligible only while k < deadline) then keep the sixteen earliest deadlines
  for i = 0, NODES - 1 do
    local q = self.queue[i]
    assert(#q <= S.QSTAGE, "arrival staging exceeded the derived capacity 18")
    local keep = {}
    for _, job in ipairs(q) do if job.dl > k then keep[#keep + 1] = job end end
    while #keep > S.QCAP do keep[#keep] = nil end
    self.queue[i] = keep
    self.qplus[i] = #keep
  end
  ctx.qplus = {}
  for i = 0, NODES - 1 do ctx.qplus[i] = self.qplus[i] end
  -- (2) mode, delayed commands, energy, orientation
  local latch = self.latch[k]; self.latch[k] = nil
  if self.protocol then latch = self.protocol(k) end
  local stop = (self.D == 1) or latch == nil or latch.stop
  ctx.mode_stop = stop and 1 or 0
  ctx.requested = (not stop) and latch.word & 0xffffffffffff or 0
  local trip = {}
  if stop then
    for i = 0, NODES - 1 do local hh = self.hist[i]; hh[0], hh[1], hh[2] = 0, 0, 0; trip[i] = 0 end
  else
    for i = 0, NODES - 1 do
      local hh = self.hist[i]
      hh[2], hh[1], hh[0] = hh[1], hh[0], latch.trip[i]
      trip[i] = hh[th.lambda[i]]
    end
  end
  ctx.rejected = 0
  local e_plus = math.min(S.ENERGY_MAX, self.e + S.ENERGY_REPLENISH)
  local demand = 0
  for i = 0, NODES - 1 do demand = demand + ((trip[i] >> 2) & 1) + ((trip[i] >> 1) & 1) end
  if (not stop) and demand > e_plus then       -- energy rejection: all outputs zero, buffers cleared
    ctx.rejected = 1
    for i = 0, NODES - 1 do local hh = self.hist[i]; hh[0], hh[1], hh[2] = 0, 0, 0; trip[i] = 0 end
    demand = 0
    self.reject_energy = self.reject_energy + 1
  end
  ctx.e_next = e_plus - demand
  ctx.demand = demand
  if stop then self.stop_boundaries = self.stop_boundaries + 1 end
  for i = 0, NODES - 1 do
    local a1, a2, r = (trip[i] >> 2) & 1, (trip[i] >> 1) & 1, trip[i] & 1
    local sh = self.structural and L.shifted(member(self, i), k, th.tau)
    local sigma = L.orientation(th.b[i], th.z[i], ctx.qplus[i], th.rho[i], sh)
    local p, c = L.channels(sigma, a1, a2)
    ctx.p[i], ctx.c[i], ctx.route[i], ctx.applied[i] = p, c, r, trip[i]
  end
  -- (3) service outcomes for powered, nonempty nodes (conditionally independent)
  for i = 0, NODES - 1 do
    local s = false
    if ctx.p[i] == 1 and #self.queue[i] > 0 then
      local n, d = L.service_prob(self.h[i], self.g)
      s = self.serv:bernoulli(n, d)
    end
    ctx.succ[i] = s
  end
  -- physical noises and next load / fault (conditional on OLD g, F)
  local nn, nd = L.thermal_noise_prob(self.g)
  for i = 0, NODES - 1 do ctx.xi[i] = self.noise:bit(nn, nd) end
  for i = 0, NODES - 1 do ctx.Ud[i] = self.noise:below(64) end
  local pn, pd = L.load_next_prob(self.g)
  ctx.g_next = rng:bit(pn, pd)
  local fn, fd = L.fault_next_prob(self.F, self.g)
  ctx.F_next = rng:bit(fn, fd)
  ctx.g_old = self.g
  self.ctx = ctx
  self.k_cur = k
end

-- ------------------------------------------------------------------ step finalisation
function World:finalize_step(k)
  local th, ctx = self.theta, self.ctx
  assert(ctx and ctx.k == k, "finalize without matching step")
  local T, h = self.T, self.h
  local g_old, D_old = self.g, self.D
  -- departures / completions (all simultaneous; successful heads leave their queues)
  local terminal, term_n = {}, 0
  for i = 0, NODES - 1 do
    if ctx.succ[i] then
      local job = table.remove(self.queue[i], 1)
      if i < 12 then
        local dst, l = S.successor(i, ctx.route[i])
        local buf = self.transit[l]
        buf.tail = buf.tail + 1
        buf[buf.tail] = {arr = k + 1 + th.dl[l], job = job}
        assert(buf.tail - buf.head + 1 <= S.TRANSIT_CAP, "link transit capacity exceeded")
      else
        term_n = term_n + 1; terminal[term_n] = job
      end
    end
  end
  -- thermal / degradation from OLD state only
  local Tn, hn = {}, {}
  for i = 0, NODES - 1 do
    local base = L.thermal_base(T[i], T[(i - 1) % NODES], T[(i + 1) % NODES])
    Tn[i] = L.temp_update(base, th.gamma[i], g_old, ctx.p[i], th.eta[i], ctx.c[i], ctx.xi[i])
    hn[i] = L.degradation_update(h[i], ctx.Ud[i], g_old, ctx.p[i], ctx.c[i], T[i])
  end
  local maxT = 0
  for i = 0, NODES - 1 do if Tn[i] > maxT then maxT = Tn[i] end end
  if maxT > self.maxT_seen then self.maxT_seen = maxT end
  local D_new = L.global_failure(D_old, maxT)
  if D_new == 1 and D_old == 0 then self.fail_step = k end
  -- scoring of terminal completions (provisional until the failure check)
  local safe = 0
  for n = 1, term_n do
    local job = terminal[n]
    self.terminal_completions = self.terminal_completions + 1
    if not L.birth_scored(job.birth) then self.bg_completions = self.bg_completions + 1 end
    if (not self.historical) and L.safe_scored_completion(true, job.birth, k, job.dl, D_old, D_new) then safe = safe + 1 end
  end
  self.completed = self.completed + safe
  -- install new physical state atomically
  for i = 0, NODES - 1 do T[i] = Tn[i]; h[i] = hn[i] end
  self.e = ctx.e_next
  self.g, self.F, self.D = ctx.g_next, ctx.F_next, D_new
  -- prediction scoring (fixed event set, continues after failure; missing report = 128/256)
  if (not self.historical) and k >= S.FIRST_SCORED and k <= S.LAST_SCORED then
    local rep = self.committed[k]
    for j = 0, 3 do
      local r = rep and rep[j + 1] or 128
      self.brier_arrival = self.brier_arrival + L.brier_num(r, ctx.arrivals[j])
    end
    for i = 0, NODES - 1 do
      local r = rep and rep[5 + i] or 128
      self.brier_thermal = self.brier_thermal + L.brier_num(r, (Tn[i] >= S.HOT_TEMP) and 1 or 0)
    end
    self.scored_events = self.scored_events + 20
    self.committed[k] = nil
  end
  -- generate packet k (raw, at generation time)
  local bw = U.BitWriter()
  local arrbits = 0
  for j = 0, 3 do arrbits = (arrbits << 1) | ctx.arrivals[j] end
  bw:put((self.episode << 48) | (k << 16) | (S.KIND.sensor << 8), 64)
  bw:put(self.episode, 16); bw:put(k, 32); bw:put(arrbits, 4)
  bw:put(ctx.requested, 48); bw:put(ctx.mode_stop, 1)
  bw:put(ctx.e_next, 7); bw:put(ctx.rejected, 1); bw:put(math.min(term_n, 7), 3); bw:put(D_new, 1)
  local occ, tmp = {}, {}
  for i = 0, NODES - 1 do
    local e = self.sens:categorical({1, 14, 1}) - 2
    occ[i] = L.sensor_occupancy(ctx.qplus[i], th.betaq[i], self.F, e)   -- self.F is already F_{k+1}
    e = self.sens:categorical({1, 14, 1}) - 2
    tmp[i] = L.sensor_temperature(Tn[i], th.betaT[i], self.F, e)
  end
  for i = 0, NODES - 1 do bw:put(occ[i], 4) end
  for i = 0, NODES - 1 do bw:put(tmp[i], 5) end
  local words = bw:pad_to(512)
  assert(#words == 8, "packet must be exactly 512 bits")
  local packet = {words = words, k = k}
  if self.historical then
    self.log[#self.log + 1] = words
  else
    self.pending = packet
  end
  if self.per_step then
    self.per_step[k + 1] = {T = U.clone(Tn), max = maxT, g = g_old, F = self.F, e = ctx.e_next, D = D_new, term = term_n, safe = safe,
                            mode = ctx.mode_stop, rej = ctx.rejected, q = U.clone(ctx.qplus)}
  end
  self.ctx = nil
end

-- ------------------------------------------------------------------------ boundaries
function World:boundary(k)
  assert(k == self.next_boundary, "boundary order violated")
  if k >= 1 then
    if self.pending and not self.historical then          -- (A) mature packet k-2
      assert(self.pending.k == k - 2, "pending packet index mismatch")
      self.readable = self.pending; self.pending = nil
    end
    self:finalize_step(k - 1)                              -- (B)
  end
  if k < self.steps then self:begin_step(k) end            -- (C)
  self.next_boundary = k + 1
end

-- process every boundary with k*Delta <= t
function World:advance(t)
  assert(t >= self.now, "world time moved backwards")
  while self.next_boundary <= self.steps and self.next_boundary * DELTA <= t do
    self:boundary(self.next_boundary)
  end
  self.now = t
end

-- =========================================================== charged interface effects
-- (the VM computes cost/duration; these calls apply the exact world-side semantics)

-- command word -> ok, stop, triples
local function parse_command(word)
  if word < 0 or (word >> 49) ~= 0 then return false end
  local stop = ((word >> 48) & 1) == 1
  local payload = word & 0xffffffffffff
  if stop and payload ~= 0 then return false end
  local trip = {}
  for i = 0, NODES - 1 do
    trip[i] = (payload >> (3 * (NODES - 1 - i))) & 7
    if i >= 12 and (trip[i] & 1) ~= 0 then return false end       -- terminal route bits are zero
  end
  return true, stop, trip
end
World.parse_command = parse_command

function World.pack_command(trip, stop)
  local v = 0
  for i = 0, NODES - 1 do v = (v << 3) | (trip[i] or 0) end
  if stop then v = v | (1 << 48) end
  return v
end

function World:sensor_read(t_start)
  self:advance(t_start)
  if not self.readable then return EMPTY end
  local out = {}
  for i = 1, 8 do out[i] = self.readable.words[i] end
  return OK, out, self.readable.k
end

function World:command_submit(t_start, t_end, word)
  self:advance(t_start)
  local ok, stop, trip = parse_command(word)
  local target = t_start // DELTA + 1
  self:advance(t_end)
  if not ok or target >= self.steps then self.cmd_rejected = self.cmd_rejected + 1; return INVALID end
  if t_end > target * DELTA - 1 then self.cmd_rejected = self.cmd_rejected + 1; return LATE end
  self.latch[target] = {stop = stop, word = word, trip = trip}
  self.cmd_accepted = self.cmd_accepted + 1
  return OK
end

function World.pack_forecast(target_step, reports)
  assert(#reports == 20)
  local bw = U.BitWriter()
  bw:put((S.ACTIVE_EPISODE_ID << 48) | (target_step << 16) | (S.KIND.forecast << 8), 64)
  bw:put((target_step * DELTA) & 0xffffffff, 32)
  for i = 1, 20 do bw:put(reports[i], 9) end
  return bw:pad_to(320)
end

function World:forecast_submit(t_start, t_end, words)
  self:advance(t_start)
  local target = t_start // DELTA + 1
  self:advance(t_end)
  local ok = #words == 5 and target < self.steps
  local reports = {}
  if ok then
    local rd = U.BitReader(words)
    local id, ts = rd:get(64), rd:get(32)
    ok = (id == ((S.ACTIVE_EPISODE_ID << 48) | (target << 16) | (S.KIND.forecast << 8))) and ts == ((target * DELTA) & 0xffffffff)
    for i = 1, 20 do reports[i] = rd:get(9); if reports[i] > S.PRED_GRID then ok = false end end
    if ok and rd:get(44) ~= 0 then ok = false end
  end
  if not ok then self.forecasts_rejected = self.forecasts_rejected + 1; return INVALID end
  if t_end > target * DELTA - 1 then self.forecasts_rejected = self.forecasts_rejected + 1; return LATE end
  self.committed[target] = reports
  self.forecasts_accepted = self.forecasts_accepted + 1
  return OK
end

function World:auditor_invoke(t_start, t_end, node)
  self:advance(t_start)
  if node < 0 or node >= NODES then return INVALID end
  if self.aud then return BUSY end
  self:advance(t_end)
  local k = t_end // DELTA
  if k >= self.steps then return INVALID end
  local th = self.theta
  local E = self.audr:bit(1, 16)
  local q = self.qplus[node]            -- arrival-processed snapshot q+_{node,k} of the step in progress at acceptance
  local bit = L.auditor(th.b[node], th.z[node], q, th.rho[node], th.A, self.structural and member(self, node) or false, k, th.tau, E)
  self.aud = {node = node, k = k, bit = bit, r = t_end, ready_at = t_end + S.AUDITOR_DELAY_STEPS * DELTA,
              id = (S.ACTIVE_EPISODE_ID << 48) | (t_end << 16) | (S.KIND.auditor << 8) | node}
  return OK
end

function World:auditor_read(t_start)
  self:advance(t_start)
  local a = self.aud
  if not a then return INVALID end
  if t_start < a.ready_at then return NOT_READY end
  self.aud = nil
  return OK, {a.id, (a.k << 8) | (a.node << 1) | a.bit}, a
end

function World:auditor_cancel(t_start)
  self:advance(t_start)
  if not self.aud then return INVALID end
  self.aud = nil
  return OK
end

-- pure status of a cold-storage request (no data revealed, no state changed)
function World:page_status(page, offset, count)
  if not self.archive or page < 0 or page >= S.PAGES then return INVALID end
  if offset < 0 or count < 1 or offset + count > S.PAGE_WORDS then return INVALID end
  if self.erased[page] then return ERASED end
  return OK
end
function World:erase_status(page)
  if not self.archive or page < 0 or page >= S.PAGES then return INVALID end
  if self.erased[page] then return ERASED end
  return OK
end

-- cold storage: returns status, words
function World:page_read(page, offset, count)
  local st = self:page_status(page, offset, count)
  if st ~= OK then return st end
  local src, out = self.archive[page], {}
  for i = 1, count do out[i] = src[offset + i] end
  return OK, out
end

function World:erase_page(page)
  if not self.archive or page < 0 or page >= S.PAGES then return INVALID end
  if self.erased[page] then return ERASED end
  self.erased[page] = true
  return OK
end

-- ============================================================================ results
function World:finish()
  self:advance(self.steps * DELTA)
end

function World:result()
  local n_arr, n_th = 4 * S.SCORED_STEPS, 16 * S.SCORED_STEPS
  return {
    utility_num = self.completed, utility_den = S.UTILITY_DEN,
    failed = self.D == 1, fail_step = self.fail_step,
    brier_arrival_num = self.brier_arrival, brier_thermal_num = self.brier_thermal,
    brier_total_num = self.brier_arrival + self.brier_thermal,
    brier_arrival_den = n_arr * 65536, brier_thermal_den = n_th * 65536,
    brier_total_den = S.PRED_EVENTS * 65536,
    scored_events = self.scored_events,
    terminal_completions = self.terminal_completions, bg_completions = self.bg_completions,
    forecasts_accepted = self.forecasts_accepted, forecasts_rejected = self.forecasts_rejected,
    commands_accepted = self.cmd_accepted, commands_rejected = self.cmd_rejected,
    stop_boundaries = self.stop_boundaries, energy_rejections = self.reject_energy,
    max_temperature = self.maxT_seen,
  }
end

-- state digest (determinism / twin-world tests)
function World:digest()
  local parts = {}
  for i = 0, NODES - 1 do
    parts[#parts + 1] = string.format("%d:%d:%d", self.T[i], self.h[i], #self.queue[i])
    for _, j in ipairs(self.queue[i]) do parts[#parts + 1] = tostring(j.id) end
  end
  parts[#parts + 1] = string.format("e%d g%d F%d D%d b%d c%d", self.e, self.g, self.F, self.D, self.next_boundary, self.completed)
  return U.sha256(table.concat(parts, ","))
end

--[[@@END@@]]
return World
end

-- ======================================================================== asi.archive  (asi/archive.lua)
package.preload["asi.archive"] = function(...)
--[============[
asi/archive.lua -- the 4 MiB historical archive: 1,024 episodes x 64 raw packets x 512 bits.

An episode is one page (page p = episode p): 64 records of 8 big-endian words = 512 words.
Episodes share the active system's persistent node/link parameters and auditor blindness,
have NO structural change, reset to the active initial state with a fresh load g ~ Ber(1/5)
and fresh physical noise, clear every delayed packet/command/transit buffer at reset, and are
logged RAW at packet generation (no sensor delay). Each step requests exactly twelve of the
thirty-two channels (uniformly) and fair non-terminal route bits; after a failure the hardware
STOP persists to the scheduled reset (zero payload, mode bit 1). Terminal route bits are 0.
Historical resets are declared experimental interventions (provenance field episode_id < 1024).
]============]
local U = require("asi.util")
local R = require("asi.rng")
local S = require("asi.spec")
local World = require("asi.world")

local A = {}

local NODES = S.NODES

-- one historical episode -> 512 words (64 records)
function A.generate_episode(theta, seed, ep)
  local w = World.new(theta, seed, {episode_id = ep, steps = S.RECORDS_PER_EPISODE, historical = true, label = "arch/" .. ep})
  local cmd = R.new(seed, "archcmd/" .. ep)
  for k = 0, S.RECORDS_PER_EPISODE - 1 do
    local chan = cmd:subset(12, 2 * NODES)            -- exactly twelve of the 32 channels set to one
    local on = {}
    for _, c in ipairs(chan) do on[c] = true end
    local trip = {}
    for i = 0, NODES - 1 do
      local a1, a2 = on[2 * i] and 1 or 0, on[2 * i + 1] and 1 or 0
      local route = (i < 12 and cmd:bernoulli(1, 2)) and 1 or 0
      trip[i] = (a1 << 2) | (a2 << 1) | route
    end
    -- the evaluator-side logger chooses the request for boundary k; a failed episode is forced to STOP by the hardware
    w.latch[k] = {stop = false, word = World.pack_command(trip, false), trip = trip}
    w:advance(k * S.DELTA)
  end
  w:advance(S.RECORDS_PER_EPISODE * S.DELTA)                -- boundary 64 finalises step 63
  assert(#w.log == S.RECORDS_PER_EPISODE, "an episode must log exactly 64 records")
  local words = {}
  for _, rec in ipairs(w.log) do for i = 1, 8 do words[#words + 1] = rec[i] end end
  assert(#words == S.PAGE_WORDS)
  return words, w
end

-- full archive: pages[0..n-1] (each a 1-based array of 512 words)
function A.generate(theta, seed, episodes)
  episodes = episodes or S.ARCHIVE_EPISODES
  local pages = {}
  for ep = 0, episodes - 1 do pages[ep] = (A.generate_episode(theta, seed, ep)) end
  -- pad with all-zero pages if fewer than 1024 episodes were requested (test archives)
  for ep = episodes, S.PAGES - 1 do
    local z = {}; for i = 1, S.PAGE_WORDS do z[i] = 0 end
    pages[ep] = z
  end
  return pages
end

-- decode one 512-bit record (array of 8 words) per spec.record_layout
function A.unpack_record(words)
  local rd = U.BitReader(words)
  local r = {}
  r.event_id = rd:get(64); r.episode = rd:get(16); r.step = rd:get(32)
  r.arrivals = {}
  local a = rd:get(4); for j = 0, 3 do r.arrivals[j] = (a >> (3 - j)) & 1 end
  r.cmd = {}
  for i = 0, NODES - 1 do r.cmd[i] = {a1 = rd:get(1), a2 = rd:get(1), route = rd:get(1)} end
  r.stop = rd:get(1); r.energy = rd:get(7); r.rejected = rd:get(1); r.completions = rd:get(3); r.failed = rd:get(1)
  r.occ, r.temp = {}, {}
  for i = 0, NODES - 1 do r.occ[i] = rd:get(4) end
  for i = 0, NODES - 1 do r.temp[i] = rd:get(5) end
  r.padding_zero = true
  for _ = 1, 191 // 64 do if rd:get(64) ~= 0 then r.padding_zero = false end end
  if rd:get(191 % 64) ~= 0 then r.padding_zero = false end
  return r
end

-- record index helper: record k of a page is words[8k+1 .. 8k+8]
function A.record(page_words, k)
  local out = {}
  for i = 1, 8 do out[i] = page_words[8 * k + i] end
  return out
end

--[[@@END@@]]
return A
end

-- ======================================================================== asi.isa  (asi/isa.lua)
package.preload["asi.isa"] = function(...)
--[============[
asi/isa.lua -- the published finite decoder / instruction table of machine VM-1.

Word: 64 bits. Registers: sixteen 64-bit registers r0..r15 (no hardwired register).
Instruction word (all instructions are exactly one 64-bit word):
     bits 63..56  opcode (8)
     bits 55..52  rd (4)       bits 51..48  ra (4)       bits 47..44  rb (4)
     bits 43..0   imm (44, two's complement; sign-extended)
Branch / jump immediates are RELATIVE to the address of the branching instruction.
Memory is word addressed; byte strings are big-endian inside words (first byte = MSB).

The decoder here IS the semantics table: opcode -> mnemonic, operand format, base cost class.
Core opcodes are fixed; environment-specific opcodes (charged interfaces) are appended from
opcode 48 upward by the environment adapter, so the full decoder of a given machine is
isa.build(env_ops). A table entry costs DECODER_ENTRY_BITS in L0.

Formats (operands used): rrr = rd,ra,rb   rri = rd,ra,imm   ri = rd,imm   rr = rd,ra
  ld = rd,[ra+imm]  st = [ra+imm],rb  ldb = rd,[ra+imm],rb  b2 = ra,rb,off  b1 = ra,off
  j = off  jal = rd,off  jr = ra  jalr = rd,ra (rd = pc+1; pc = r[ra])  r0 = none  clk/coin = rd,imm  idle = ra
Environment ops declare their own format and may use rd as a status destination.
]============]
local ISA = {}

ISA.IMM_BITS = 44
ISA.IMM_MAX = (1 << 43) - 1
ISA.IMM_MIN = -(1 << 43)
ISA.DECODER_ENTRY_BITS = 32

local CORE = {
  {"NOP", "r0"}, {"HALT", "r0"},
  {"MOV", "rr"}, {"MOVI", "ri"}, {"LDA", "ri"}, {"LD", "ld"}, {"ST", "st"},
  {"ADD", "rrr"}, {"SUB", "rrr"}, {"MUL", "rrr"}, {"AND", "rrr"}, {"OR", "rrr"}, {"XOR", "rrr"},
  {"SHL", "rrr"}, {"SHR", "rrr"}, {"SAR", "rrr"}, {"SLT", "rrr"}, {"SLTU", "rrr"}, {"MULHU", "rrr"},
  {"DIVS", "rrr"}, {"MODS", "rrr"}, {"DIVU", "rrr"}, {"MODU", "rrr"},
  {"ADDI", "rri"}, {"MULI", "rri"}, {"ANDI", "rri"}, {"ORI", "rri"}, {"XORI", "rri"},
  {"SHLI", "rri"}, {"SHRI", "rri"}, {"SARI", "rri"}, {"SLTI", "rri"}, {"SLTUI", "rri"},
  {"DIVSI", "rri"}, {"MODSI", "rri"},
  {"JMP", "j"}, {"BEQ", "b2"}, {"BNE", "b2"}, {"BLT", "b2"}, {"BGE", "b2"}, {"BLTU", "b2"}, {"BGEU", "b2"},
  {"BEQZ", "b1"}, {"BNEZ", "b1"}, {"JAL", "jal"}, {"JR", "jr"},
  {"LDB", "ldb"}, {"COIN", "coin"}, {"CLK", "clk"}, {"IDLE", "idle"}, {"JALR", "jalr"},
}
ISA.ENV_BASE = 64         -- environment-specific opcodes start here
ISA.core_count = #CORE

-- build(env_ops) -> machine description {name->code, code->{name,fmt}, count}
function ISA.build(env_ops)
  local m = {by_name = {}, by_code = {}, count = 0}
  for i, e in ipairs(CORE) do
    m.by_name[e[1]] = i; m.by_code[i] = {name = e[1], fmt = e[2]}; m.count = m.count + 1
  end
  assert(#CORE < ISA.ENV_BASE, "core opcode space exhausted")
  for i, e in ipairs(env_ops or {}) do
    local code = ISA.ENV_BASE + i - 1
    assert(code < 256, "too many environment opcodes")
    assert(m.by_name[e[1]] == nil, "duplicate mnemonic " .. e[1])
    m.by_name[e[1]] = code; m.by_code[code] = {name = e[1], fmt = e[2], env = true, index = i}; m.count = m.count + 1
  end
  return m
end

function ISA.decoder_bits(machine) return machine.count * ISA.DECODER_ENTRY_BITS end

local IMASK = (1 << 44) - 1
function ISA.encode(code, rd, ra, rb, imm)
  rd, ra, rb, imm = rd or 0, ra or 0, rb or 0, imm or 0
  assert(rd >= 0 and rd < 16 and ra >= 0 and ra < 16 and rb >= 0 and rb < 16, "register index out of range")
  assert(imm >= ISA.IMM_MIN and imm <= ISA.IMM_MAX, "immediate does not fit 44 bits: " .. tostring(imm))
  return (code << 56) | (rd << 52) | (ra << 48) | (rb << 44) | (imm & IMASK)
end

function ISA.decode(w)
  local imm = w & IMASK
  if imm >= (1 << 43) then imm = imm - (1 << 44) end
  return (w >> 56) & 0xff, (w >> 52) & 15, (w >> 48) & 15, (w >> 44) & 15, imm
end

function ISA.disasm(w, machine, addr)
  local code, rd, ra, rb, imm = ISA.decode(w)
  local e = machine.by_code[code]
  if not e then return string.format(".word 0x%016x", w) end
  local f = e.fmt
  local n = e.name
  if f == "rrr" then return string.format("%-6s r%d, r%d, r%d", n, rd, ra, rb)
  elseif f == "rri" then return string.format("%-6s r%d, r%d, %d", n, rd, ra, imm)
  elseif f == "ri" then return string.format("%-6s r%d, %d", n, rd, imm)
  elseif f == "rr" then return string.format("%-6s r%d, r%d", n, rd, ra)
  elseif f == "ld" then return string.format("%-6s r%d, [r%d%+d]", n, rd, ra, imm)
  elseif f == "st" then return string.format("%-6s [r%d%+d], r%d", n, ra, imm, rb)
  elseif f == "ldb" then return string.format("%-6s r%d, [r%d%+d], r%d", n, rd, ra, imm, rb)
  elseif f == "b2" then return string.format("%-6s r%d, r%d, %s", n, ra, rb, addr and string.format("@%d", addr + imm) or tostring(imm))
  elseif f == "b1" then return string.format("%-6s r%d, %s", n, ra, addr and string.format("@%d", addr + imm) or tostring(imm))
  elseif f == "j" then return string.format("%-6s %s", n, addr and string.format("@%d", addr + imm) or tostring(imm))
  elseif f == "jal" then return string.format("%-6s r%d, %s", n, rd, addr and string.format("@%d", addr + imm) or tostring(imm))
  elseif f == "jr" or f == "idle" then return string.format("%-6s r%d", n, ra)
  elseif f == "jalr" then return string.format("%-6s r%d, r%d", n, rd, ra)
  elseif f == "coin" or f == "clk" then return string.format("%-6s r%d, %d", n, rd, imm)
  elseif f == "r0" then return n
  else return string.format("%-6s rd=%d ra=%d rb=%d imm=%d", n, rd, ra, rb, imm) end
end

--[[@@END@@]]
return ISA
end

