  local fault, reason
  local ult = math.ult

  while true do
    if steps >= limit then reason = "limit"; break end
    if t >= wd_next then
      if t == wd_next then t = t + 1 end                -- the reserved watchdog tick belongs to hardware
      wd_next = (t // wd + 1) * wd - 1
    end
    if t >= horizon then reason = "horizon"; break end
    if work_left < iw then reason = "budget"; break end
    local op = Dop[pc]
    if op == nil then
      op = predecode(self, pc)
      if op == nil then fault = VM.FAULT.PC; break end
    end
    local rd, ra, rb, imm = Drd[pc], Dra[pc], Drb[pc], Dim[pc]
    steps = steps + 1
    local npc = pc + 1
    if op == OP_ADDI then r[rd] = r[ra] + imm
    elseif op == OP_LD then
      local a = r[ra] + imm
      local v
      if a >= RB and a < RE then v = ram[a - RB]
      elseif a >= 0 and a < IE then v = img[a]
      else
        self.ram_hi = ram_hi
        v = self:mread(a)
        if v == nil then fault = VM.FAULT.ACCESS; break end
      end
      r[rd] = v
    elseif op == OP_ST then
      local a = r[ra] + imm
      if a >= RB and a < RE then
        local i = a - RB
        ram[i] = r[rb]
        if i >= SF then if i < stack_lo then stack_lo = i end
        elseif i >= ram_hi then ram_hi = i + 1 end
        Dop[a] = nil
      else
        self.ram_hi, self.stack_lo = ram_hi, stack_lo
        if a >= 0 and a < IE then fault = VM.FAULT.WRITE_RO; break end
        if not self:mwrite(a, r[rb]) then fault = VM.FAULT.ACCESS; break end
        ram_hi, stack_lo = self.ram_hi, self.stack_lo
      end
    elseif op == OP_ADD then r[rd] = r[ra] + r[rb]
    elseif op == OP_BNE then if r[ra] ~= r[rb] then npc = pc + imm end
    elseif op == OP_BEQ then if r[ra] == r[rb] then npc = pc + imm end
    elseif op == OP_MOV then r[rd] = r[ra]
    elseif op == OP_MOVI then r[rd] = imm
    elseif op == OP_SUB then r[rd] = r[ra] - r[rb]
    elseif op == OP_JMP then npc = pc + imm
    elseif op == OP_BLT then if r[ra] < r[rb] then npc = pc + imm end
    elseif op == OP_BGE then if r[ra] >= r[rb] then npc = pc + imm end
    elseif op == OP_BEQZ then if r[ra] == 0 then npc = pc + imm end
    elseif op == OP_BNEZ then if r[ra] ~= 0 then npc = pc + imm end
    elseif op == OP_AND then r[rd] = r[ra] & r[rb]
    elseif op == OP_OR then r[rd] = r[ra] | r[rb]
    elseif op == OP_XOR then r[rd] = r[ra] ~ r[rb]
    elseif op == OP_ANDI then r[rd] = r[ra] & imm
    elseif op == OP_ORI then r[rd] = r[ra] | imm
    elseif op == OP_XORI then r[rd] = r[ra] ~ imm
    elseif op == OP_MUL then r[rd] = r[ra] * r[rb]
    elseif op == OP_MULI then r[rd] = r[ra] * imm
    elseif op == OP_SHLI then if imm >= 0 and imm < 64 then r[rd] = r[ra] << imm else r[rd] = 0 end
    elseif op == OP_SHRI then if imm >= 0 and imm < 64 then r[rd] = r[ra] >> imm else r[rd] = 0 end
    elseif op == OP_SARI then
      local x, n = r[ra], imm
      if n < 0 or n >= 64 then r[rd] = (x < 0) and -1 or 0
      else r[rd] = (x >> n) | ((x < 0) and ~(-1 >> n) or 0) end
    elseif op == OP_SHL then local n = r[rb]; if n >= 0 and n < 64 then r[rd] = r[ra] << n else r[rd] = 0 end
    elseif op == OP_SHR then local n = r[rb]; if n >= 0 and n < 64 then r[rd] = r[ra] >> n else r[rd] = 0 end
    elseif op == OP_SAR then
      local x, n = r[ra], r[rb]
      if n < 0 or n >= 64 then r[rd] = (x < 0) and -1 or 0
      else r[rd] = (x >> n) | ((x < 0) and ~(-1 >> n) or 0) end
    elseif op == OP_SLT then r[rd] = (r[ra] < r[rb]) and 1 or 0
    elseif op == OP_SLTU then r[rd] = ult(r[ra], r[rb]) and 1 or 0
    elseif op == OP_SLTI then r[rd] = (r[ra] < imm) and 1 or 0
    elseif op == OP_SLTUI then r[rd] = ult(r[ra], imm) and 1 or 0
    elseif op == OP_LDA then
      local v
      if imm >= RB and imm < RE then v = ram[imm - RB]
      elseif imm >= 0 and imm < IE then v = img[imm]
      else self.ram_hi = ram_hi; v = self:mread(imm); if v == nil then fault = VM.FAULT.ACCESS; break end end
      r[rd] = v
    elseif op == OP_JAL then r[rd] = pc + 1; npc = pc + imm
    elseif op == OP_JR then npc = r[ra]
    elseif op == OP_JALR then local target = r[ra]; r[rd] = pc + 1; npc = target
    elseif op == OP_BLTU then if ult(r[ra], r[rb]) then npc = pc + imm end
    elseif op == OP_BGEU then if not ult(r[ra], r[rb]) then npc = pc + imm end
    elseif op == OP_LDB then
      local base, idx = r[ra] + imm, r[rb]
      local a = base + (idx >> 3)
      local w
      if a >= RB and a < RE then w = ram[a - RB]
      elseif a >= 0 and a < IE then w = img[a]
      else self.ram_hi = ram_hi; w = self:mread(a); if w == nil then fault = VM.FAULT.ACCESS; break end end
      r[rd] = (w >> (56 - 8 * (idx & 7))) & 0xff
    elseif op == OP_DIVS then
      local d = r[rb]; if d == 0 then fault = VM.FAULT.DIV; break end
      r[rd] = r[ra] // d
    elseif op == OP_MODS then
      local d = r[rb]; if d == 0 then fault = VM.FAULT.DIV; break end
      r[rd] = r[ra] % d
    elseif op == OP_DIVSI then
      if imm == 0 then fault = VM.FAULT.DIV; break end
      r[rd] = r[ra] // imm
    elseif op == OP_MODSI then
      if imm == 0 then fault = VM.FAULT.DIV; break end
      r[rd] = r[ra] % imm
    elseif op == OP_DIVU then
      local d = r[rb]; if d == 0 then fault = VM.FAULT.DIV; break end
      r[rd] = (U.udivmod(r[ra], d))
    elseif op == OP_MODU then
      local d = r[rb]; if d == 0 then fault = VM.FAULT.DIV; break end
      local _, m = U.udivmod(r[ra], d); r[rd] = m
    elseif op == OP_MULHU then r[rd] = mulhu(r[ra], r[rb])
    elseif op == OP_NOP then -- nothing
    elseif op == OP_HALT then
      t = t + idur; work_left = work_left - iw
      pc = npc; reason = "halt"; break
    elseif op == OP_COIN then
      if imm < 1 or imm > 64 then fault = VM.FAULT.OP; break end
      r[rd] = self.coin:bits(imm); self.coin_draws = self.coin_draws + 1
    elseif op == OP_CLK then
      local v
      if imm == 0 then v = t % self.step_ticks
      elseif imm == 1 then v = t // self.step_ticks
      elseif imm == 2 then v = t
      elseif imm == 3 then v = work_left
      elseif imm == 4 then v = (self.budget - work_left) - self.work_iface
      elseif imm == 5 then v = self.work_iface
      elseif imm == 6 then v = ram_hi + (self.ram_words - stack_lo)
      elseif imm == 7 then v = self.ram_words
      else fault = VM.FAULT.OP; break end
      r[rd] = v
    elseif op == OP_IDLE then
      local target = r[ra]
      local d = target - t
      if d < idur then d = idur end
      t = t + d - idur            -- the common +idur below completes the wait
    elseif op >= ENV_BASE and env then
      self.t, self.work_left, self.ram_hi, self.stack_lo = t, work_left, ram_hi, stack_lo
      local info = self.machine.by_code[op]
      if info == nil then fault = VM.FAULT.OP; break end
      local quote, qf = env:quote(self, info.index, rd, ra, rb, imm, t)   -- side-effect free cost
      if quote == nil then fault = qf or VM.FAULT.ENV; break end
      if work_left < quote then reason = "budget"; break end              -- the whole interface must fit; else it never starts
      local w, d = env:exec(self, info.index, rd, ra, rb, imm, t)
      if w == nil then fault = d or VM.FAULT.ENV; break end
      assert(w == quote, "environment quote differs from charged work")
      ram_hi, stack_lo = self.ram_hi, self.stack_lo
      work_left = work_left - w + iw                          -- the common -iw below nets exactly w
      self.work_iface = self.work_iface + w
      self.iface_count = self.iface_count + 1
      t = t + d - idur
      if self.trace then
        self.trace[#self.trace + 1] = string.format("%s,%d,%d,%d,%d,%d", info.name, self.t, w, d, r[rd], pc)
      end
    else
      fault = VM.FAULT.OP; break
    end
    t = t + idur
    work_left = work_left - iw
    pc = npc
  end

  self.t, self.work_left, self.pc, self.ram_hi, self.stack_lo = t, work_left, pc, ram_hi, stack_lo
  self.instr_count = self.instr_count + steps
  if fault then
    self.halted, self.reason = true, "fault"
    self.fault = {code = fault, name = VM.FAULT_NAME[fault], pc = pc, t = t}
  elseif reason == "limit" then
    -- not halted: caller may continue
  else
    self.halted, self.reason = true, reason
  end
  return self.halted and self.reason or "limit"
end

function VM:trace_hash()
  return U.sha256(table.concat(self.trace or {}, "\n"))
end

--[[@@END@@]]
return VM
end

-- ======================================================================== asi.asm  (asi/asm.lua)
package.preload["asi.asm"] = function(...)
--[============[
asi/asm.lua -- assembler for VM-1 (implemented in Lua; the only "source language" of guest
programs is Lua code that calls this builder, as required by the Lua-only rule).

Usage
  local a = Asm.new(machine)
  a:label("loop"); a:ins("ADDI", 1, 1, 0, 1); a:ins("BNE", nil, 1, 2, "loop")
  a:lda(3, 123456789012345)         -- load a 64-bit constant from the pooled constants
  local addr = a:ram("buf", 16)     -- static RAM allocation, returns absolute word address
  local words, syms = a:assemble()  -- code, then constant pool, then data blocks
Operand notes
  registers are integers 0..15; imm may be an integer, a label name (relative for branches /
  jumps / JAL, absolute otherwise) or {sym=name, off=n}. Image layout: code | pool | data blocks.
]============]
local ISA = require("asi.isa")
local VM = require("asi.vm")

local Asm = {}
Asm.__index = Asm

function Asm.new(machine)
  return setmetatable({machine = machine, items = {}, labels = {}, pool = {}, pool_index = {},
                       data = {}, data_order = {}, ram_top = 0, ram_syms = {}, ncode = 0}, Asm)
end

function Asm:here() return self.ncode end

function Asm:label(name)
  assert(self.labels[name] == nil, "duplicate label " .. name)
  self.labels[name] = self.ncode
end

local REL = {j = true, b1 = true, b2 = true, jal = true}

-- generic emit; imm may be integer or symbol reference
function Asm:ins(mnemonic, rd, ra, rb, imm)
  local code = self.machine.by_name[mnemonic]
  assert(code, "unknown mnemonic " .. tostring(mnemonic))
  local fmt = self.machine.by_code[code].fmt
  self.items[#self.items + 1] = {code = code, rd = rd or 0, ra = ra or 0, rb = rb or 0, imm = imm or 0,
                                 rel = REL[fmt] or false, at = self.ncode}
  self.ncode = self.ncode + 1
  return self.ncode - 1
end

-- 64-bit constant from the pool
function Asm:lda(rd, value)
  local idx = self.pool_index[value]
  if idx == nil then
    self.pool[#self.pool + 1] = value
    idx = #self.pool
    self.pool_index[value] = idx
  end
  return self:ins("LDA", rd, 0, 0, {pool = idx})
end

function Asm:movi(rd, value)
  if value >= ISA.IMM_MIN and value <= ISA.IMM_MAX then return self:ins("MOVI", rd, 0, 0, value) end
  return self:lda(rd, value)
end

-- read-only data block in the image (appended after the pool)
function Asm:data_block(name, words)
  assert(self.data[name] == nil, "duplicate data block " .. name)
  self.data[name] = words; self.data_order[#self.data_order + 1] = name
end

-- static RAM allocation; returns absolute address
function Asm:ram(name, nwords)
  assert(self.ram_syms[name] == nil, "duplicate ram symbol " .. name)
  local addr = VM.RAM_BASE + self.ram_top
  self.ram_syms[name] = {addr = addr, words = nwords}
  self.ram_top = self.ram_top + nwords
  return addr
end

function Asm:assemble()
  local ncode = self.ncode
  local base_pool = ncode
  local sym = {}
  for k, v in pairs(self.labels) do sym[k] = v end
  local pos = base_pool + #self.pool
  for _, name in ipairs(self.data_order) do
    sym[name] = pos
    pos = pos + #self.data[name]
  end
  for name, r in pairs(self.ram_syms) do sym[name] = r.addr end
  local words = {}
  for _, it in ipairs(self.items) do
    local imm = it.imm
    if type(imm) == "table" then
      if imm.pool then imm = base_pool + imm.pool - 1
      else
        local target = sym[imm.sym]; assert(target, "undefined symbol " .. tostring(imm.sym))
        imm = target + (imm.off or 0)
        if it.rel then imm = imm - it.at end
      end
    elseif type(imm) == "string" then
      local target = sym[imm]; assert(target, "undefined label " .. imm)
      imm = it.rel and (target - it.at) or target
    end
    words[#words + 1] = ISA.encode(it.code, it.rd, it.ra, it.rb, imm)
  end
  for _, v in ipairs(self.pool) do words[#words + 1] = v end
  for _, name in ipairs(self.data_order) do
    for _, v in ipairs(self.data[name]) do words[#words + 1] = v end
  end
  return words, sym
end

function Asm:listing(words)
  local out = {}
  for i = 1, self.ncode do out[#out + 1] = string.format("%5d  %s", i - 1, ISA.disasm(words[i], self.machine, i - 1)) end
  return table.concat(out, "\n")
end

--[[@@END@@]]
return Asm
end

-- ======================================================================== asi.gl  (asi/gl.lua)
package.preload["asi.gl"] = function(...)
--[============[
asi/gl.lua -- GL, a Lua-embedded compiler from guest programs to VM-1 words.

Guest programs are written as ordinary Lua code that builds expression objects and
statements; there is no external DSL, no string evaluation and no foreign language. The
compiler lives entirely in Lua and emits instruction WORDS (numeric data) through asm.lua.

Language (all values are signed 64-bit words)
  expressions   Lua operators on expression objects:  + - * // (floor) % (floor) & | ~(xor) << >> (logical)
                unary - and bnot; methods :sar(n) :udiv(x) :umod(x) :mulhu(x)
                comparisons (value 0/1 or branch condition): :lt :le :gt :ge :eq :ne :ltu :leu :gtu :geu
                GL.and_(c1,c2,..) GL.or_(..) GL.not_(c)  (short circuit when used as conditions)
                f:ld(addr_expr [,off])   word load       f:ldb(base_addr, byte_index)  byte load
                f:call("fn", a, b, c, d) call (<= 4 args, result in r1)
                f:clk(kind)  f:coin(nbits)  f:sys("OPNAME", a, b)   (environment interface op; value = status)
  statements    f:set(v, e)  f:st(addr_expr, value [,off])  f:iff(c, then_fn [, else_fn])  f:while_(c, body)
                f:for_(v, lo, hi, body [,step])  f:break_() f:continue_() f:ret([e]) f:do_(e) f:idle(e) f:halt()
Calling convention: args in r1..r4, result r1, link r15, stack pointer r14 (stack grows down from the
top of RAM), locals in callee-saved r5..r11 (more are spilled to the frame), temporaries r1-r4,r12,r13,
r0 is the permanent ZERO register (main sets it; static addresses use [r0+imm]). Non-leaf functions save r15, live temporaries are saved around calls.
]============]
local ISA = require("asi.isa")
local VM = require("asi.vm")
local Asm = require("asi.asm")

local GL = {}
local E = {}
E.__index = E
local function node(t) return setmetatable(t, E) end
local function lift(x)
  if getmetatable(x) == E then return x end
  if math.type(x) == "integer" then return node({k = "const", v = x}) end
  error("GL: cannot use " .. tostring(x) .. " (" .. type(x) .. ") as an expression", 3)
end
GL.lift = lift
local function bin(op) return function(a, b) return node({k = "bin", op = op, a = lift(a), b = lift(b)}) end end
E.__add, E.__sub, E.__mul = bin("add"), bin("sub"), bin("mul")
E.__idiv, E.__mod = bin("divs"), bin("mods")
E.__band, E.__bor, E.__bxor = bin("band"), bin("bor"), bin("bxor")
E.__shl, E.__shr = bin("shl"), bin("shr")
E.__unm = function(a) return node({k = "un", op = "neg", a = lift(a)}) end
E.__bnot = function(a) return node({k = "un", op = "not", a = lift(a)}) end
E.sar, E.udiv, E.umod, E.mulhu = function(a, b) return bin("sar")(a, b) end, function(a, b) return bin("divu")(a, b) end,
  function(a, b) return bin("modu")(a, b) end, function(a, b) return bin("mulhu")(a, b) end
local function cmp(op) return function(a, b) return node({k = "cmp", op = op, a = lift(a), b = lift(b)}) end end
for _, op in ipairs({"lt", "le", "gt", "ge", "eq", "ne", "ltu", "leu", "gtu", "geu"}) do E[op] = cmp(op) end
function GL.and_(...) return node({k = "and", c = {...}}) end
function GL.or_(...) return node({k = "or", c = {...}}) end
function GL.not_(c) return node({k = "not", c = lift(c)}) end
GL.C = function(v) return lift(v) end

local BIN = {add = "ADD", sub = "SUB", mul = "MUL", band = "AND", bor = "OR", bxor = "XOR", shl = "SHL", shr = "SHR",
             sar = "SAR", divs = "DIVS", mods = "MODS", divu = "DIVU", modu = "MODU", mulhu = "MULHU"}
local IMMOP = {add = "ADDI", mul = "MULI", band = "ANDI", bor = "ORI", bxor = "XORI", shl = "SHLI", shr = "SHRI",
               sar = "SARI", divs = "DIVSI", mods = "MODSI"}
local COMM = {add = true, mul = true, band = true, bor = true, bxor = true}
local NEG = {eq = "ne", ne = "eq", lt = "ge", ge = "lt", gt = "le", le = "gt", ltu = "geu", geu = "ltu", gtu = "leu", leu = "gtu"}
local BR = {eq = {"BEQ", false}, ne = {"BNE", false}, lt = {"BLT", false}, ge = {"BGE", false}, gt = {"BLT", true},
            le = {"BGE", true}, ltu = {"BLTU", false}, geu = {"BGEU", false}, gtu = {"BLTU", true}, leu = {"BGEU", true}}

local SP, LINK, SCRATCH = 14, 15, 0
local TEMPS = {1, 2, 3, 4, 12, 13}
local LOCAL_REGS = {5, 6, 7, 8, 9, 10, 11}
local function fits(v) return math.type(v) == "integer" and v >= ISA.IMM_MIN and v <= ISA.IMM_MAX end

-- ------------------------------------------------------------------- program
local Program = {}
Program.__index = Program

function GL.program(machine, opts)
  opts = opts or {}
  local p = setmetatable({machine = machine, asm = Asm.new(machine), funcs = {}, nlabel = 0,
                          stack_words = opts.stack_words or 256, ram_words = opts.ram_words or 4096,
                          main_defined = false}, Program)
  p.asm:ins("JMP", 0, 0, 0, "main")          -- entry vector: address 0 jumps to main
  return p
end

function Program:static(name, nwords)
  local addr = self.asm:ram(name, nwords or 1)
  return node({k = "sym", name = name, off = 0}), addr
end
function Program:rodata(name, words)
  self.asm:data_block(name, words)
  return node({k = "sym", name = name, off = 0})
end
function Program:sym(name) return node({k = "sym", name = name, off = 0}) end
function Program:label_addr(name) return node({k = "sym", name = name, off = 0}) end

-- function builder ------------------------------------------------------------
local F = {}
F.__index = F

local function newF(prog, name)
  return setmetatable({prog = prog, name = name, buf = {}, free = {}, live = {}, nlocals = 0, regvars = 0,
                       nspill = 0, nonleaf = false, loops = {}, nl = 0}, F)
end

function F:newlabel() self.nl = self.nl + 1; return self.name .. ".L" .. self.nl end
function F:place(l) self.buf[#self.buf + 1] = {label = l} end
function F:emit(mn, rd, ra, rb, imm) self.buf[#self.buf + 1] = {mn, rd or 0, ra or 0, rb or 0, imm or 0} end
function F:raw(mn, rd, ra, rb, imm) self:emit(mn, rd, ra, rb, imm) end

-- temp pool
function F:reset_temps()
  self.free = {}
  for _, r in ipairs(TEMPS) do self.free[#self.free + 1] = r end
  self.allocated = {}
end
function F:alloc()
  local r = table.remove(self.free)
  if r == nil then error("GL: expression too complex in function " .. self.name .. " (out of temporaries); split it with a local", 3) end
  self.allocated[r] = true
  return r
end
function F:release(r)
  if r and self.allocated[r] then
    self.allocated[r] = nil
    table.insert(self.free, r)
  end
end

function F:var(name, init)
  local v = {name = name}
  if self.regvars < #LOCAL_REGS then
    self.regvars = self.regvars + 1
    v.reg = LOCAL_REGS[self.regvars]
  else
    self.nspill = self.nspill + 1
    v.slot = self.nspill - 1
  end
  local n = node({k = "var", var = v})
  if init ~= nil then self:set(n, init) end
  return n
end

-- immediates that may refer to frame slots are resolved at flush time
local function slot_imm(slot) return {slot = slot} end

function F:emit_const(r, v)
  if fits(v) then self:emit("MOVI", r, 0, 0, v) else self:emit("LDA", r, 0, 0, {const = v}) end
end

-- address folding: returns base_node (or nil), imm (integer or {sym=,off=})
local function addimm(a, b)
  if type(a) == "number" and type(b) == "number" then return a + b end
  if type(a) == "table" and type(b) == "number" then return {sym = a.sym, off = a.off + b} end
  if type(a) == "number" and type(b) == "table" then return {sym = b.sym, off = b.off + a} end
  return nil
end
local function fold_addr(n)
  if n.k == "const" then return nil, n.v end
  if n.k == "sym" then return nil, {sym = n.name, off = n.off} end
  if n.k == "bin" and n.op == "add" then
    local a, b = n.a, n.b
    local function constlike(x) return x.k == "const" or x.k == "sym" end
    local function cval(x) if x.k == "const" then return x.v end return {sym = x.name, off = x.off} end
    if constlike(a) and constlike(b) then
      local comb = addimm(cval(a), cval(b))
      if comb then return nil, comb end
      return n, 0
    elseif constlike(b) then
      local base, imm = fold_addr(a)
      local comb = addimm(imm, cval(b))
      if comb then return base, comb end
      return n, 0
    elseif constlike(a) then
      local base, imm = fold_addr(b)
      local comb = addimm(imm, cval(a))
      if comb then return base, comb end
      return n, 0
    end
  end
  return n, 0
end

function F:gen(n, want)
  local k = n.k
  if k == "const" then
    local r = want or self:alloc()
    self:emit_const(r, n.v)
    return r, want == nil
  elseif k == "sym" then
    local r = want or self:alloc()
    self:emit("MOVI", r, 0, 0, {sym = n.name, off = n.off})
    return r, want == nil
  elseif k == "var" then
    local v = n.var
    if v.reg then
      if want and want ~= v.reg then self:emit("MOV", want, v.reg); return want, false end
      return v.reg, false
    end
    local r = want or self:alloc()
    self:emit("LD", r, SP, 0, slot_imm(v.slot))
    return r, want == nil
  elseif k == "bin" then
    local a, b, op = n.a, n.b, n.op
    if COMM[op] and a.k == "const" and b.k ~= "const" then a, b = b, a end
    if b.k == "const" and fits(b.v) and (IMMOP[op] or (op == "sub" and fits(-b.v))) then
      local ra, oa = self:gen(a)
      local rd = want or (oa and ra) or self:alloc()
      if op == "sub" then self:emit("ADDI", rd, ra, 0, -b.v) else self:emit(IMMOP[op], rd, ra, 0, b.v) end
      if oa and rd ~= ra then self:release(ra) end
      return rd, want == nil
    end
    local ra, oa = self:gen(a)
    local rb, ob = self:gen(b)
    local rd = want or (oa and ra) or (ob and rb) or self:alloc()
    self:emit(BIN[op], rd, ra, rb)
    if oa and ra ~= rd then self:release(ra) end
    if ob and rb ~= rd then self:release(rb) end
    return rd, want == nil
  elseif k == "un" then
    local ra, oa = self:gen(n.a)
    local rd = want or (oa and ra) or self:alloc()
    if n.op == "neg" then self:emit("MULI", rd, ra, 0, -1) else self:emit("XORI", rd, ra, 0, -1) end
    if oa and rd ~= ra then self:release(ra) end
    return rd, want == nil
  elseif k == "ld" then
    local base, imm = fold_addr(n.addr)
    if n.off ~= 0 then
      if type(imm) == "number" then imm = imm + n.off elseif type(imm) == "table" then imm = {sym = imm.sym, off = imm.off + n.off} end
    end
    if base == nil then
      local r = want or self:alloc()
      self:emit("LDA", r, 0, 0, imm)
      return r, want == nil
    end
    local rb, ob = self:gen(base)
    local rd = want or (ob and rb) or self:alloc()
    self:emit("LD", rd, rb, 0, imm)
    if ob and rb ~= rd then self:release(rb) end
    return rd, want == nil
  elseif k == "ldb" then
    local rb, ob = self:gen(n.base)
    local ri, oi = self:gen(n.idx)
    local rd = want or (ob and rb) or (oi and ri) or self:alloc()
    self:emit("LDB", rd, rb, ri, 0)
    if ob and rb ~= rd then self:release(rb) end
    if oi and ri ~= rd then self:release(ri) end
    return rd, want == nil
  elseif k == "cmp" then
    local a, b, op = n.a, n.b, n.op
    local ra, oa = self:gen(a)
    local rb, ob = self:gen(b)
    local rd = want or (oa and ra) or (ob and rb) or self:alloc()
    if op == "lt" then self:emit("SLT", rd, ra, rb)
    elseif op == "gt" then self:emit("SLT", rd, rb, ra)
    elseif op == "ge" then self:emit("SLT", rd, ra, rb); self:emit("XORI", rd, rd, 0, 1)
    elseif op == "le" then self:emit("SLT", rd, rb, ra); self:emit("XORI", rd, rd, 0, 1)
    elseif op == "ltu" then self:emit("SLTU", rd, ra, rb)
    elseif op == "gtu" then self:emit("SLTU", rd, rb, ra)
    elseif op == "geu" then self:emit("SLTU", rd, ra, rb); self:emit("XORI", rd, rd, 0, 1)
    elseif op == "leu" then self:emit("SLTU", rd, rb, ra); self:emit("XORI", rd, rd, 0, 1)
    elseif op == "eq" then self:emit("SUB", rd, ra, rb); self:emit("SLTUI", rd, rd, 0, 1)
    elseif op == "ne" then self:emit("SUB", rd, ra, rb); self:emit("SLTUI", rd, rd, 0, 1); self:emit("XORI", rd, rd, 0, 1)
    else error("GL: bad comparison " .. op) end
    if oa and ra ~= rd then self:release(ra) end
    if ob and rb ~= rd then self:release(rb) end
    return rd, want == nil
  elseif k == "and" or k == "or" or k == "not" then
    -- boolean value of a condition: 1 / 0
    local rd = want or self:alloc()
    local lt, le = self:newlabel(), self:newlabel()
    self:cond_jump(n, lt, true)
    self:emit("MOVI", rd, 0, 0, 0); self:emit("JMP", 0, 0, 0, le)
    self:place(lt); self:emit("MOVI", rd, 0, 0, 1); self:place(le)
    return rd, want == nil
  elseif k == "clk" then
    local rd = want or self:alloc(); self:emit("CLK", rd, 0, 0, n.kind); return rd, want == nil
  elseif k == "coin" then
    local rd = want or self:alloc(); self:emit("COIN", rd, 0, 0, n.bits); return rd, want == nil
  elseif k == "sys" then
    local ra, oa, rb, ob = 0, false, 0, false
    if n.a then ra, oa = self:gen(n.a) end
    if n.b then rb, ob = self:gen(n.b) end
    local rd = want or (oa and ra) or (ob and rb) or self:alloc()
    self:emit(n.name, rd, ra, rb, 0)
    if oa and ra ~= rd then self:release(ra) end
    if ob and rb ~= rd then self:release(rb) end
    return rd, want == nil
  elseif k == "call" then
    return self:gen_call(n, want)
  end
  error("GL: unknown node kind " .. tostring(k))
end

function F:callr(target, ...)
  local args = {}
  for i, a in ipairs({...}) do args[i] = lift(a) end
  return node({k = "call", target = lift(target), args = args})
end

function F:gen_call(n, want)
  assert(#n.args <= 4, "GL: at most 4 call arguments")
  self.nonleaf = true
  local live = {}
  for _, r in ipairs(TEMPS) do if self.allocated[r] then live[#live + 1] = r end end
  -- Argument expressions may contain calls before this call enters a new machine frame.
  -- Their backups therefore need disjoint ranges in the current frame.
  local save_base = self.call_save_used or 0
  self.call_save_used = save_base + #live
  self.call_save_words = math.max(self.call_save_words or 0, self.call_save_used)
  for i, r in ipairs(live) do self:emit("ST", 0, SP, r, {tsave = save_base + i - 1}) end
  -- all temporaries are free while the arguments are built (live ones are saved)
  local saved_alloc = self.allocated
  self:reset_temps()
  local reserved = {}
  for i, a in ipairs(n.args) do
    local argreg = i                                   -- r1..r4
    -- make argreg unavailable to subexpressions, then compute into it
    local pos
    for j, r in ipairs(self.free) do if r == argreg then pos = j end end
    if pos then table.remove(self.free, pos) end
    local r, owned = self:gen(a, argreg)
    self.allocated[argreg] = true                      -- only the completed argument is live across later calls
    reserved[#reserved + 1] = argreg
  end
  if n.target then
    -- indirect call: the target address goes to r13 after the arguments are in place (r13 is never an argument register)
    local t = n.target
    self.free = {13}                                   -- only r13 may be used while computing the target
    -- Keep completed arguments live if computing the target itself invokes another function.
    self:gen(t, 13)
    self:emit("JALR", LINK, 13, 0, 0)
  else
    self:emit("JAL", LINK, 0, 0, n.fname)
  end
  -- result is in r1; choose a destination that is not one of the registers we must restore
  local isLive = {}
  for _, r in ipairs(live) do isLive[r] = true end
  self:reset_temps()
  local dest = want
  if dest == nil then
    for _, r in ipairs(TEMPS) do if not isLive[r] then dest = r; break end end
    if dest == nil then error("GL: no register available for a call result in " .. self.name) end
  end
  if dest ~= 1 then self:emit("MOV", dest, 1) end
  for i, r in ipairs(live) do
    if r ~= dest then self:emit("LD", r, SP, 0, {tsave = save_base + i - 1}) end
  end
  self.call_save_used = save_base
  -- rebuild allocation state: live temporaries again allocated
  self:reset_temps()
  for _, r in ipairs(live) do
    for j, f in ipairs(self.free) do if f == r then table.remove(self.free, j); break end end
    self.allocated[r] = true
  end
  if want then return want, false end
  for j, f in ipairs(self.free) do if f == dest then table.remove(self.free, j); break end end
  self.allocated[dest] = true
  return dest, true
end

-- conditional jump: jump to label when cond evaluates to `sense`
function F:cond_jump(c, label, sense)
  local k = c.k
  if k == "cmp" then
    local op = sense and c.op or NEG[c.op]
    local a, b = c.a, c.b
    if b.k == "const" and b.v == 0 and (op == "eq" or op == "ne") then
      local ra, oa = self:gen(a)
      self:emit(op == "eq" and "BEQZ" or "BNEZ", 0, ra, 0, label)
      if oa then self:release(ra) end
      return
    end
    local ra, oa = self:gen(a)
    local rb, ob = self:gen(b)
    local mn, swap = BR[op][1], BR[op][2]
    if swap then self:emit(mn, 0, rb, ra, label) else self:emit(mn, 0, ra, rb, label) end
    if oa then self:release(ra) end
    if ob then self:release(rb) end
  elseif k == "and" then
    if sense then
      local skip = self:newlabel()
      for i = 1, #c.c - 1 do self:cond_jump(lift(c.c[i]), skip, false) end
      self:cond_jump(lift(c.c[#c.c]), label, true)
      self:place(skip)
    else
      for i = 1, #c.c do self:cond_jump(lift(c.c[i]), label, false) end
    end
  elseif k == "or" then
    if sense then
      for i = 1, #c.c do self:cond_jump(lift(c.c[i]), label, true) end
    else
      local skip = self:newlabel()
      for i = 1, #c.c - 1 do self:cond_jump(lift(c.c[i]), skip, true) end
      self:cond_jump(lift(c.c[#c.c]), label, false)
      self:place(skip)
    end
  elseif k == "not" then
    self:cond_jump(c.c, label, not sense)
  else
    local r, o = self:gen(c)
    self:emit(sense and "BNEZ" or "BEQZ", 0, r, 0, label)
    if o then self:release(r) end
  end
end

-- statements ----------------------------------------------------------------------
function F:stmt_end() self:reset_temps() end

function F:set(v, e)
  assert(v.k == "var", "GL: set needs a variable")
  e = lift(e)
  local var = v.var
  if var.reg then
    local r, o = self:gen(e, var.reg)
  else
    local r, o = self:gen(e)
    self:emit("ST", 0, SP, r, slot_imm(var.slot))
  end
  self:stmt_end()
end
function F:inc(v, n) self:set(v, v + (n or 1)) end

function F:ld(addr, off) return node({k = "ld", addr = lift(addr), off = off or 0}) end
function F:ldb(base, idx) return node({k = "ldb", base = lift(base), idx = lift(idx)}) end
function F:clk(kind) return node({k = "clk", kind = kind}) end
function F:coin(bits) return node({k = "coin", bits = bits}) end
function F:sys(name, a, b)
  assert(self.prog.machine.by_name[name], "GL: unknown environment op " .. name)
  return node({k = "sys", name = name, a = a and lift(a), b = b and lift(b)})
end
function F:call(fname, ...)
  local args = {}
  for i, a in ipairs({...}) do args[i] = lift(a) end
  return node({k = "call", fname = fname, args = args})
end

function F:st(addr, value, off)
  local base, imm = fold_addr(lift(addr))
  if off and off ~= 0 then
    if type(imm) == "number" then imm = imm + off elseif type(imm) == "table" then imm = {sym = imm.sym, off = imm.off + off} end
  end
  value = lift(value)
  local rv, ov = self:gen(value)
  if base == nil then
    self:emit("ST", 0, SCRATCH, rv, imm)           -- r0 is the permanent zero register (set by main)
  else
    local rb, ob = self:gen(base)
    self:emit("ST", 0, rb, rv, imm)
    if ob then self:release(rb) end
  end
  if ov then self:release(rv) end
  self:stmt_end()
end

function F:run(fname, ...) self:do_(self:call(fname, ...)) end

function F:do_(e)
  local r, o = self:gen(lift(e))
  if o then self:release(r) end
  self:stmt_end()
end

function F:iff(c, then_fn, else_fn)
  c = lift(c)
  local lelse, lend = self:newlabel(), self:newlabel()
  self:cond_jump(c, lelse, false)
  self:stmt_end()
  then_fn()
  if else_fn then self:emit("JMP", 0, 0, 0, lend) end
  self:place(lelse)
  if else_fn then else_fn(); self:place(lend) end
end

function F:while_(c, body)
  c = lift(c)
  local ltop, lend = self:newlabel(), self:newlabel()
  self:place(ltop)
  self:cond_jump(c, lend, false)
  self:stmt_end()
  self.loops[#self.loops + 1] = {brk = lend, cont = ltop}
  body()
  table.remove(self.loops)
  self:emit("JMP", 0, 0, 0, ltop)
  self:place(lend)
end

function F:for_(v, lo, hi, body, step)
  self:set(v, lo)
  local ltop, lcont, lend = self:newlabel(), self:newlabel(), self:newlabel()
  self:place(ltop)
  self:cond_jump(v:lt(hi), lend, false)
  self:stmt_end()
  self.loops[#self.loops + 1] = {brk = lend, cont = lcont}
  body()
  table.remove(self.loops)
  self:place(lcont)
  self:set(v, v + (step or 1))
  self:emit("JMP", 0, 0, 0, ltop)
  self:place(lend)
end

function F:break_() self:emit("JMP", 0, 0, 0, self.loops[#self.loops].brk) end
function F:continue_() self:emit("JMP", 0, 0, 0, self.loops[#self.loops].cont) end

function F:ret(e)
  if e ~= nil then
    local r, o = self:gen(lift(e), 1)
    self:stmt_end()
  end
  self:emit("JMP", 0, 0, 0, self.name .. ".ret")
end

function F:idle(e)
  local r, o = self:gen(lift(e))
  self:emit("IDLE", 0, r, 0, 0)
  if o then self:release(r) end
  self:stmt_end()
end
function F:halt() self:emit("HALT") end

-- flush function code with prologue/epilogue into the assembler
local function flush(f, params)
  local asm = f.prog.asm
  local nsaved = f.regvars
  local lead = f.nonleaf and 1 or 0
  local spill_base = lead + nsaved
  local tsave_base = spill_base + f.nspill
  local frame = tsave_base + (f.nonleaf and math.max(#TEMPS, f.call_save_words or 0) or 0)
  local function resolve(imm)
    if type(imm) == "table" then
      if imm.slot then return spill_base + imm.slot end
      if imm.tsave then return tsave_base + imm.tsave end
      if imm.const then return imm end
      return imm
    end
    return imm
  end
  asm:label(f.name)
  if frame > 0 then asm:ins("ADDI", SP, SP, 0, -frame) end
  if f.nonleaf then asm:ins("ST", 0, SP, LINK, 0) end
  for i = 1, nsaved do asm:ins("ST", 0, SP, LOCAL_REGS[i], lead + i - 1) end
  -- parameters arrive in r1..r4
  for i, pvar in ipairs(params) do
    local v = pvar.var
    if v.reg then asm:ins("MOV", v.reg, i, 0, 0) else asm:ins("ST", 0, SP, i, spill_base + v.slot) end
  end
  for _, it in ipairs(f.buf) do
    if it.label then asm:label(it.label)
    else
      local imm = it[5]
      if type(imm) == "table" and imm.const then
        local rd = it[2]
        asm:lda(rd, imm.const)
      else
        asm:ins(it[1], it[2], it[3], it[4], resolve(imm))
      end
    end
  end
  asm:label(f.name .. ".ret")
  for i = 1, nsaved do asm:ins("LD", LOCAL_REGS[i], SP, 0, lead + i - 1) end
  if f.nonleaf then asm:ins("LD", LINK, SP, 0, 0) end
  if frame > 0 then asm:ins("ADDI", SP, SP, 0, frame) end
  asm:ins("JR", 0, LINK, 0, 0)
end

-- define a function; body(f, p1, p2, ...) builds statements
function Program:func(name, params, body)
  assert(self.funcs[name] == nil, "GL: duplicate function " .. name)
  self.funcs[name] = true
  local f = newF(self, name)
  f:reset_temps()
  local pvars = {}
  for i, pname in ipairs(params) do pvars[i] = f:var(pname) end
  body(f, table.unpack(pvars))
  flush(f, pvars)
end

-- program entry: sets the stack pointer, then runs body; never returns
function Program:main(body)
  local f = newF(self, "main")
  f:reset_temps()
  f:emit("MOVI", SCRATCH, 0, 0, 0)                 -- r0 == 0 for the whole run (absolute addressing base)
  f:emit("MOVI", SP, 0, 0, 0)                      -- patched below: top of RAM minus main's own frame
  local sp_item = f.buf[#f.buf]
  body(f)
  f:emit("HALT")
  local asm = self.asm
  -- main's frame (spill slots + temp save area) sits at the top of RAM; main has no saved registers
  local extra = f.nspill + (f.nonleaf and math.max(#TEMPS, f.call_save_words or 0) or 0)
  sp_item[5] = VM.RAM_BASE + self.ram_words - extra
  local function resolve(imm)
    if type(imm) == "table" then
      if imm.slot then return imm.slot end
      if imm.tsave then return f.nspill + imm.tsave end
    end
    return imm
  end
  asm:label("main")
  for _, it in ipairs(f.buf) do
    if it.label then asm:label(it.label)
    else
      local imm = it[5]
      if type(imm) == "table" and imm.const then asm:lda(it[2], imm.const)
      else asm:ins(it[1], it[2], it[3], it[4], resolve(imm)) end
    end
  end
  asm:label("main.ret")
  asm:ins("HALT")
end

function Program:build()
  local words, sym = self.asm:assemble()
  assert(self.asm.ram_top <= self.ram_words - self.stack_words, "GL: static RAM exceeds RAM minus the stack reservation ("
    .. self.asm.ram_top .. " > " .. (self.ram_words - self.stack_words) .. ")")
  return words, sym
end

--[[@@END@@]]
return GL
end

-- ======================================================================== asi.netenv  (asi/netenv.lua)
package.preload["asi.netenv"] = function(...)
--[============[
asi/netenv.lua -- environment adapter binding VM-1 to the network world.

Paid interface instructions (cost = work units = microticks, invoking instruction included;
the processor stalls, the world does not pause; arguments snapshotted at the START tick):

  SENSE    rd, ra      read latest readable packet into 8 words at mem[r[ra]]   72
  SUBMIT   rd, ra      command word r[ra] for the next boundary                  65
  FORECAST rd, ra      5-word prediction frame at mem[r[ra]]                      6
  AUDINV   rd, ra      invoke auditor on node r[ra]                              128
  AUDREAD  rd, ra      retrieve the ready auditor result into 2 words at mem[r[ra]] 128
  AUDCANC  rd, ra      cancel the pending/ready auditor request                  128
  PAGE     rd, ra, rb  cold page transfer: r[ra] = (count<<32)|(offset<<16)|page, dest r[rb]
                       cost 2048 + count when valid, 2048 (setup only) when rejected
  ERASE    rd, ra      paid erase of page r[ra]; the page becomes ordinary RAM  2560 (2048 if rejected)

rd always receives the status code (0 OK, 1 LATE, 2 NOT_READY, 3 INVALID, 4 BUSY, 5 EMPTY,
6 ERASED). A destination range that is not writable memory is an ACCESS FAULT (no data revealed).
]============]
local S = require("asi.spec")
local VM = require("asi.vm")

local NetEnv = {}
NetEnv.__index = NetEnv

NetEnv.ops = {
  {"SENSE", "rr"}, {"SUBMIT", "rr"}, {"FORECAST", "rr"}, {"AUDINV", "rr"},
  {"AUDREAD", "rr"}, {"AUDCANC", "rr"}, {"PAGE", "rrr"}, {"ERASE", "rr"},
}
local I = {SENSE = 1, SUBMIT = 2, FORECAST = 3, AUDINV = 4, AUDREAD = 5, AUDCANC = 6, PAGE = 7, ERASE = 8}
NetEnv.index = I

function NetEnv.profile()
  return {inst_work = 1, inst_dur = 1, ram_words = S.WRITABLE_BITS // 64, horizon = S.TOTAL_TICKS,
          watchdog_period = S.DELTA, step_ticks = S.DELTA, work_budget = S.DISCRETIONARY_WORK}
end

function NetEnv.new(world) return setmetatable({world = world}, NetEnv) end

local function writable(vm, a, n)
  for i = 0, n - 1 do
    local x = a + i
    local ok = (x >= VM.RAM_BASE and x < VM.RAM_BASE + vm.ram_words)
    if not ok and x >= VM.COLD_BASE and x < VM.COLD_BASE + VM.COLD_WORDS then ok = vm.erased[(x - VM.COLD_BASE) >> 9] ~= nil end
    if not ok then return false end
  end
  return true
end

-- side-effect free price of an interface instruction (used to refuse it before it starts)
function NetEnv:quote(vm, idx, rd, ra, rb, imm, t)
  local r, C = vm.r, S.COST
  if idx == I.SENSE then return C.sensor_read
  elseif idx == I.SUBMIT then return C.command_submit
  elseif idx == I.FORECAST then return C.forecast_submit
  elseif idx == I.AUDINV then return C.auditor_invoke
  elseif idx == I.AUDREAD then return C.auditor_read
  elseif idx == I.AUDCANC then return C.auditor_cancel
  elseif idx == I.PAGE then
    local desc = r[ra]
    local st = self.world:page_status(desc & 0xffff, (desc >> 16) & 0xffff, (desc >> 32) & 0xffffffff)
    if st == 0 then return C.page_setup + ((desc >> 32) & 0xffffffff) * C.page_word end
    return C.page_setup
  elseif idx == I.ERASE then
    if self.world:erase_status(r[ra]) == 0 then return C.page_setup + S.PAGE_WORDS * C.page_word end
    return C.page_setup
  end
  return nil, VM.FAULT.OP
end

function NetEnv:exec(vm, idx, rd, ra, rb, imm, t)
  local w, r, C = self.world, vm.r, S.COST
  if idx == I.SENSE then
    local dest = r[ra]
    if not writable(vm, dest, 8) then return nil, VM.FAULT.ACCESS end
    local st, words = w:sensor_read(t)
    if st == 0 then for i = 1, 8 do vm:mwrite(dest + i - 1, words[i]) end end
    r[rd] = st
    return C.sensor_read, C.sensor_read
  elseif idx == I.SUBMIT then
    r[rd] = w:command_submit(t, t + C.command_submit, r[ra])
    return C.command_submit, C.command_submit
  elseif idx == I.FORECAST then
    local words = {}
    for i = 0, 4 do
      local v = vm:mread(r[ra] + i)
      if v == nil then return nil, VM.FAULT.ACCESS end
      words[i + 1] = v
    end
    r[rd] = w:forecast_submit(t, t + C.forecast_submit, words)
    return C.forecast_submit, C.forecast_submit
  elseif idx == I.AUDINV then
    r[rd] = w:auditor_invoke(t, t + C.auditor_invoke, r[ra])
    return C.auditor_invoke, C.auditor_invoke
  elseif idx == I.AUDREAD then
    local dest = r[ra]
    if not writable(vm, dest, 2) then return nil, VM.FAULT.ACCESS end
    local st, words = w:auditor_read(t)
    if st == 0 then vm:mwrite(dest, words[1]); vm:mwrite(dest + 1, words[2]) end
    r[rd] = st
    return C.auditor_read, C.auditor_read
  elseif idx == I.AUDCANC then
    r[rd] = w:auditor_cancel(t)
