  elseif idx == I.PAGE then
    local desc, dest = r[ra], r[rb]
    local page, offset, count = desc & 0xffff, (desc >> 16) & 0xffff, (desc >> 32) & 0xffffffff
    local st, words = w:page_read(page, offset, count)
    local cost = C.page_setup
    if st == 0 then
      if not writable(vm, dest, count) then return nil, VM.FAULT.ACCESS end
      for i = 1, count do vm:mwrite(dest + i - 1, words[i]) end
      cost = C.page_setup + count * C.page_word
    end
    r[rd] = st
    return cost, cost
  elseif idx == I.ERASE then
    local st = w:erase_page(r[ra])
    local cost = C.page_setup
    if st == 0 then vm:reclassify_page(r[ra]); cost = C.page_setup + S.PAGE_WORDS * C.page_word end
    r[rd] = st
