-- ======================================================================== asi.run  (asi/run.lua)
package.preload["asi.run"] = function(...)
--[============[
asi/run.lua -- episode runner: binds a controller image (VM-1 words) to a world and archive.

An episode is one complete independently initialised preparation-and-scoring run:
   theta (world index) -> archive (1,024 historical episodes) -> active world -> VM run.
Evaluator work (world, archive generation) is separate from controller work and can never
produce controller advice: the controller sees only what its paid interface instructions return.

L0 accounting (spec 7.7): the initial image is counted as
    64 * (image words)  +  decoder table bits  +  fixed firmware bits  (declared constant)
and must not exceed 2^20 bits. The total memory bound is
    M = 65,536*512 + L0 + 16*64 + 262,144 bits  (N14);
peak memory of a run is L0 + RAM high-water + registers + the archive (always resident).
]============]
local U = require("asi.util")
local S = require("asi.spec")
local ISA = require("asi.isa")
local VM = require("asi.vm")
local World = require("asi.world")
local Arch = require("asi.archive")
local NetEnv = require("asi.netenv")

local Run = {}
Run.MACHINE = ISA.build(NetEnv.ops)
Run.FIRMWARE_BITS = 1024      -- declared: reserved watchdog implementation and reset vector (belongs to L0)

function Run.image_bits(words, machine)
  return #words * 64 + ISA.decoder_bits(machine or Run.MACHINE) + Run.FIRMWARE_BITS
end

function Run.check_image(words, machine)
  local bits = Run.image_bits(words, machine)
  return bits <= S.MAX_IMAGE_BITS, bits
end

-- opts: image words, theta | theta_seed, world_seed, archive | archive_episodes, coin_seed, trace,
--       max_instr, structural_change
function Run.episode(opts)
  local theta = opts.theta or World.sample_theta(opts.theta_seed or 1)
  local archive = opts.archive
  if archive == nil and not opts.no_archive then
    archive = Arch.generate(theta, opts.world_seed or 1, opts.archive_episodes)
  end
  local world = World.new(theta, opts.world_seed or 1, {archive = archive, trace = opts.world_trace,
                                                        structural_change = opts.structural_change, protocol = opts.protocol})
  local env = NetEnv.new(world)
  local ok, l0 = Run.check_image(opts.image)
  if not ok then error(string.format("initial image does not fit: L0 = %d bits > %d", l0, S.MAX_IMAGE_BITS)) end
  local prof = NetEnv.profile()
  if opts.work_budget then prof.work_budget = opts.work_budget end
  prof.stack_words = opts.stack_words or 0
  local vm = VM.new({image = {words = opts.image, entry = 0, bits = l0}, machine = Run.MACHINE, env = env, profile = prof,
                     coin_seed = opts.coin_seed or 1, trace = opts.trace})
  local why = vm:run(opts.max_instr)
  world:finish()
  local res = world:result()
  res.controller = {
    reason = why, fault = vm.fault, instructions = vm.instr_count, interface_ops = vm.iface_count,
    work_used = vm.budget - vm.work_left, work_iface = vm.work_iface, work_proc = (vm.budget - vm.work_left) - vm.work_iface,
    final_tick = vm.t, ram_high_water_words = vm:peak_ram_words(), l0_bits = l0, peak_bits = vm:peak_bits(),
    total_memory_bits = S.total_memory_bits(l0), coin_draws = vm.coin_draws, image_hash = vm.image_hash,
  }
  res.controller.peak_total_bits = S.ARCHIVE_BITS + res.controller.peak_bits    -- archive is always resident
  res.controller.within_memory = res.controller.peak_total_bits <= res.controller.total_memory_bits
  return res, world, vm
end

--[[@@END@@]]
return Run
end

-- ======================================================================== asi.guest.rt  (asi/guest/rt.lua)
package.preload["asi.guest.rt"] = function(...)
--[============[
asi/guest/rt.lua -- guest-side compile-time helpers shared by every controller image.

These are Lua functions that EMIT VM-1 code through GL (they run on the host at build time;
the emitted words are what the metered machine executes). Nothing here runs inside the VM.
]============]
local S = require("asi.spec")

local RT = {}

-- packet bit layout (512 bits, MSB first) derived from the SPEC record layout
RT.OFF = {}
do
  local off = 0
  for _, fld in ipairs(S.spec.record_layout.fields) do
    RT.OFF[fld[1]] = {off = off, len = fld[2]}
    off = off + fld[2]
  end
  assert(off == 512, "record layout must sum to 512 bits")
end

-- expression extracting `len` bits at big-endian bit offset `off` of the word array at `base`
function RT.field(f, base, off, len)
  local wi, bo = off // 64, off % 64
  assert(len >= 1 and len <= 63)
  if bo + len <= 64 then
    local e = f:ld(base + wi) >> (64 - bo - len)
    if bo + len < 64 or bo > 0 then e = e & ((1 << len) - 1) end
    return e
  end
  local hi, lo = 64 - bo, len - (64 - bo)
  return ((f:ld(base + wi) & ((1 << hi) - 1)) << lo) | (f:ld(base + wi + 1) >> (64 - lo))
end

-- terms (expression list) that place 9-bit reports into a 320-bit frame word w (w = 1..4)
-- reports are static words REP+i; stream position of report i = 96 + 9*i
function RT.frame_word_terms(f, REP, w)
  local terms = {}
  for i = 0, 19 do
    local s = 96 + 9 * i
    local e = s + 8
    local ws, we = s // 64, e // 64
    if ws == w and we == w then
      terms[#terms + 1] = f:ld(REP + i) << (63 - (s % 64) - 8)
    elseif ws == w and we > w then
      local inword = 64 - (s % 64)                 -- bits of this report in word w
      terms[#terms + 1] = f:ld(REP + i) >> (9 - inword)
    elseif we == w and ws < w then
      local inword = (e % 64) + 1                  -- bits of this report in word w
      terms[#terms + 1] = (f:ld(REP + i) & ((1 << inword) - 1)) << (64 - inword)
    end
  end
  return terms
end

--[[@@END@@]]
return RT
end

-- ======================================================================== asi.guest.boot  (asi/guest/boot.lua)
package.preload["asi.guest.boot"] = function(...)
--[============[
asi/guest/boot.lua -- charged load / parse / verification of the public contract (guest code).

The public contract is the canonical native-Lua literal of the SPEC (35,493 bytes) stored read-only
inside L0. Every byte examined here is a charged LDB. The scan is a real parser of a SUBSET of the
literal: it finds known key patterns in the canonical (alphabetically sorted) encoding in increasing
position order and parses the signed decimal integers that follow. It extracts the constants the
safety argument depends on:
    gamma_max   largest heating coefficient gamma  (rational_prior.per_node.gamma values)
    eta_min     smallest cooling coefficient eta   (rational_prior.per_node.eta values)
    bias_lo     smallest temperature bias          (rational_prior.per_node.temperature_bias values)
    fail_temp   absorbing failure threshold        (law global_failure_from_max: max T >= 48)
    hot_temp    forecast indicator threshold       (law degradation_up_threshold: T_old >= 40)
    delta       microticks per step                (clock.microticks_per_step)
The image's shield constants were SPECIALISED from the same SPEC at build time; boot verifies the
parsed values against them. A mismatch (a different public contract) latches SAFE_MODE: the controller
then only ever dispatches STOP (certified safe by the STOP invariant) and says so in its status word.
Parsing structural information does not reveal hidden realisations: the contract holds only the family.
]============]
local GL = require("asi.gl")
local U = require("asi.util")

local Boot = {}

function Boot.install(X)
  local P, cfg, N = X.P, X.cfg, X.N
  local S = require("asi.spec")
  local PUBW = S.public_words
  local PUB = P:rodata("PUB", PUBW)
  local PUBLEN = S.public_bytes
  local function pat(name, text) return P:rodata(name, U.bytes_to_words(text)), #text end

  local CUR = P:static("CUR", 1)
  local PARSED = P:static("PARSED", 8)        -- [0]gamma_max [1]eta_min [2]bias_lo [3]fail [4]hot [5]delta [6]ok [7]cost marker
  local SAFE = P:static("SAFE", 1)
  X.PARSED, X.SAFE, X.PUB = PARSED, SAFE, PUB

  -- scan forward from CUR for pattern (rodata byte string of length plen); returns position after it or -1
  P:func("scan", {"pat", "plen"}, function(f, pattern, plen)
    local pos, last, k = f:var("pos", f:ld(CUR)), f:var("last", PUBLEN - plen), f:var("k")
    local c0 = f:var("c0", f:ldb(pattern, 0))
    f:while_(pos:le(last), function()
      f:iff(f:ldb(PUB, pos):eq(c0), function()
        f:set(k, 1)
        f:while_(GL.and_(k:lt(plen), f:ldb(PUB, pos + k):eq(f:ldb(pattern, k))), function() f:set(k, k + 1) end)
        f:iff(k:eq(plen), function() f:st(CUR, pos + plen); f:ret(pos + plen) end)
      end)
      f:set(pos, pos + 1)
    end)
    f:ret(-1)
  end)

  -- parse a signed decimal integer at byte position pos; the value is returned, CUR is set past it
  P:func("parse_int", {"pos"}, function(f, pos)
    local neg, v, c = f:var("neg", 0), f:var("v", 0), f:var("c")
    f:set(c, f:ldb(PUB, pos))
    f:iff(c:eq(45), function() f:set(neg, 1); f:set(pos, pos + 1); f:set(c, f:ldb(PUB, pos)) end)
    f:while_(GL.and_(c:ge(48), c:le(57)), function()
      f:set(v, v * 10 + c - 48)
      f:set(pos, pos + 1)
      f:set(c, f:ldb(PUB, pos))
    end)
    f:st(CUR, pos)
    f:iff(neg:ne(0), function() f:set(v, 0 - v) end)
    f:ret(v)
  end)

  -- first value, then min or max of a "{a,b,c}" list starting at pos (pos at the first digit / sign)
  P:func("parse_list", {"pos", "want_max"}, function(f, pos, want_max)
    local best, v, c, first = f:var("best", 0), f:var("v"), f:var("c"), f:var("first", 1)
    f:while_(f:ldb(PUB, pos):ne(125), function()          -- until '}'
      f:set(v, f:call("parse_int", pos))
      f:set(pos, f:ld(CUR))
      f:iff(GL.or_(first:ne(0), GL.and_(want_max:ne(0), v:gt(best)), GL.and_(want_max:eq(0), v:lt(best))), function() f:set(best, v) end)
      f:set(first, 0)
      f:iff(f:ldb(PUB, pos):eq(44), function() f:set(pos, pos + 1) end)
    end)
    f:ret(best)
  end)

  local P_CLOCK, L_CLOCK = pat("PAT_CLOCK", '["microticks_per_step"]=')
  local P_ETA, L_ETA = pat("PAT_ETA", '["eta"]={["family"]="uniform",["values"]={')
  local P_GAMMA, L_GAMMA = pat("PAT_GAMMA", '["gamma"]={["family"]="uniform",["values"]={')
  local P_BIAS, L_BIAS = pat("PAT_BIAS", '["temperature_bias"]={["family"]="uniform",["values"]={')
  local P_FAIL, L_FAIL = pat("PAT_FAIL", '["ref"]="global_max_temperature"},')
  local P_HOT, L_HOT = pat("PAT_HOT", '["ref"]="T_old_i"},')

  P:func("boot_parse", {}, function(f)
    local pos = f:var("pos")
    -- scan 1: absorbing failure threshold (algebraic_laws come first in sorted order)
    f:st(CUR, 0)
    f:set(pos, f:call("scan", P_FAIL, L_FAIL))
    f:iff(pos:ge(0), function() f:st(PARSED + 3, f:call("parse_int", pos)) end, function() f:st(PARSED + 3, -1) end)
    f:st(CUR, 0)
    f:set(pos, f:call("scan", P_HOT, L_HOT))
    f:iff(pos:ge(0), function() f:st(PARSED + 4, f:call("parse_int", pos)) end, function() f:st(PARSED + 4, -1) end)
    -- scan 2: clock
    f:st(CUR, 0)
    f:set(pos, f:call("scan", P_CLOCK, L_CLOCK))
    f:iff(pos:ge(0), function() f:st(PARSED + 5, f:call("parse_int", pos)) end, function() f:st(PARSED + 5, -1) end)
    -- scan 3: prior supports in their sorted order eta < gamma < temperature_bias, one forward pass
    f:st(CUR, 0)
    f:set(pos, f:call("scan", P_ETA, L_ETA))
    f:iff(pos:ge(0), function() f:st(PARSED + 1, f:call("parse_list", pos, 0)) end, function() f:st(PARSED + 1, -1) end)
    f:set(pos, f:call("scan", P_GAMMA, L_GAMMA))
    f:iff(pos:ge(0), function() f:st(PARSED + 0, f:call("parse_list", pos, 1)) end, function() f:st(PARSED + 0, -99) end)
    f:set(pos, f:call("scan", P_BIAS, L_BIAS))
    f:iff(pos:ge(0), function() f:st(PARSED + 2, f:call("parse_list", pos, 0)) end, function() f:st(PARSED + 2, 99) end)
    -- verify against the constants the shield was specialised with
    f:st(SAFE, 0)
    f:iff(GL.or_(f:ld(PARSED + 0):ne(cfg.gamma_max), f:ld(PARSED + 1):ne(cfg.eta_min), f:ld(PARSED + 2):ne(cfg.bias_lo),
                 f:ld(PARSED + 3):ne(cfg.fail_temp), f:ld(PARSED + 4):ne(40), f:ld(PARSED + 5):ne(8192)), function()
      f:st(SAFE, 1)
    end)
    f:st(PARSED + 6, 1 - f:ld(SAFE))
  end)
end

--[[@@END@@]]
return Boot
end

