    f:st(PAR + 6, cfg.cap_energy)
    f:st(PAR + 7, cfg.assignment_strategy or 0)
    f:st(PAR + 8, cfg.downstream_urgency or 0)
    f:st(PARV, 1)
  end)

  -- Context fragment composed with either kernel implementation. Preserve
  -- the style and promote only eligible downstream jobs; never invent work.
  P:func("priority_context", {"par"}, function(f, par)
    local b, d, cls = f:var("b", f:ld(par + 8)), f:var("d"), f:var("cls")
    f:iff(b:eq(0), function() f:ret(0) end)
    for i = 4, N - 1 do
      f:set(d, f:ld(DS + i))
      f:iff(d:ne(0), function()
        f:set(cls, (d >> 2) + b * (i // 4))
        f:iff(cls:gt(3), function() f:set(cls, 3) end)
        f:st(DS + i, (cls << 2) | (d & 3))
      end)
    end
  end)

  P:func("plan_quant", {}, function(f)
    local q, t = f:var("q"), f:var("t")
    for i = 0, N - 1 do
      f:set(q, f:ld(QSEL + i) >> 5)
      f:iff(q:gt(31), function() f:set(q, 31) end)
      f:st(QB + i, q)
      f:set(t, f:ld(THAT + i))
      f:iff(t:lt(0), function() f:set(t, 0) end)
      f:set(t, t >> 2)
      f:iff(t:gt(9), function() f:set(t, 9) end)
      f:st(TB + i, t)
    end
  end)

  -- generic (table-driven) kernel: DS[i] from QB[i], TB[i], ORIOK[i] and the parameter table at `par`
  P:func("kernel_generic", {"par"}, function(f, par)
    local ds, cls = f:var("ds"), f:var("cls")
    for i = 0, N - 1 do
      f:set(ds, 0)
      f:iff(GL.and_(f:ld(TB + i):le(f:ld(par + 3)), f:ld(QB + i):ge(f:ld(par + 2))), function()
        f:set(cls, 1)
        f:iff(f:ld(QB + i):ge(f:ld(par + 1)), function() f:set(cls, 2) end)
        f:iff(f:ld(QB + i):ge(f:ld(par + 0)), function() f:set(cls, 3) end)
        f:set(ds, (cls << 2) + 2)
        f:iff(GL.and_(f:ld(ORIOK + i):ne(0), f:ld(QB + i):lt(f:ld(par + 5)), f:ld(TB + i):le(f:ld(par + 4))), function()
          f:set(ds, (cls << 2) + 1)
        end)
      end)
      f:st(DS + i, ds)
    end
  end)

  -- assignment by priority class under the per-step energy cap (single channel costs 1, diagonal 2)
  P:func("plan_assign", {}, function(f)
    local s, cost, i, c, d = f:var("s"), f:var("cost"), f:var("i"), f:var("c"), f:var("d")
    local rank, order = f:var("rank"), f:var("order", (f:ld(PAR + 7) << 6) | ((f:ld(QPT) & 3) << 4))
    f:for_(c, 0, 3, function()
      local function visit(rank)
        f:set(i, f:ld(ORDER + order + rank))
        f:set(d, f:ld(DS + i))
        f:iff(GL.and_((d >> 2):eq(3 - c), f:ld(X.DES + i):eq(0)), function()
          f:set(s, f:ld(SSEL + i))
          f:set(cost, 2)
          f:iff((d & 3):eq(1), function() f:set(cost, 1) end)
          f:iff((f:ld(CNT + s) + cost):le(f:ld(PAR + 6)), function()
            f:st(CNT + s, f:ld(CNT + s) + cost)
            f:iff(cost:eq(1), function()
              f:iff(f:ld(ORI + i):eq(0), function() f:st(X.DES + i, 4) end, function() f:st(X.DES + i, 2) end)
            end, function() f:st(X.DES + i, 6) end)
          end)
        end)
      end
      if cfg.fast_assign ~= false then
        for node = 0, N - 1 do visit(GL.lift(node)) end
      else
        f:for_(rank, 0, N, function() visit(rank) end)
      end
    end)
  end)

  -- A finite strategy language: source order, downstream order, rotating lanes,
  -- or downstream stages with rotating lanes. Both real and synthetic dispatch use it.
  P:func("assignment_node", {"rank", "mode", "t"}, function(f, rank, mode, t)
    f:ret(f:ld(ORDER + (mode << 6) + ((t & 3) << 4) + rank))
  end)

  -- ---------------------------------------------------------------- one planning window
  -- Fills DES for boundary j+1. pg3 = predicted P(g=1) three steps ahead (x2^16).
  P:func("plan_window", {"j", "pg3"}, function(f, j, pg3)
    local a = f:var("a")
    -- expected arrivals per source (x256)
    f:set(a, 64 + ((pg3 * 64) >> 16))
    f:st(GEXP, a)
    -- clear ring slots that now enter the window
    for i = 0, N - 1 do f:st(PW + (((j + 3) & 7) << 4) + i, 0) end
    f:st(CNT + ((j + 3) & 7), 0)
    -- persistent belief to step j+1 using expected arrivals for the new step (kept current in every phase);
    -- after a long gap (boot, overrun) the belief is cold anyway: restart it instead of replaying hundreds of steps
    f:iff((j + 1 - f:ld(QPT)):gt(6), function()
      for i = 0, N - 1 do f:st(QP + i, 0) end
      for i = 0, 4 * N - 1 do f:st(FLP + i, 0) end
      f:st(QPT, j)
    end)
    f:while_(f:ld(QPT):lt(j + 1), function()
      local t = f:var("t", f:ld(QPT))
      f:run("powvec", t)
      for i = 0, 3 do f:st(SRCV + i, f:ld(GEXP)) end
      f:st(EXPH + ((t + 1) & 7), f:ld(GEXP))
      f:run("mstep", QP, FLP, t, DUMMYACC)
      f:st(QPT, t + 1)
    end)
    -- identification phase: pulses only
    f:iff(j:lt(PLAN_FROM), function()
      f:run("ident_plan", j)
    end, function()
      if cfg.rollout then
        -- tentative rollouts to steps j+2 and j+3 with the commands decided so far
        f:run("copy_model", QP, FLP, QT1, FLT)
        f:run("powvec", j + 1)
        for i = 0, 3 do f:st(SRCV + i, f:ld(GEXP)) end
        f:run("mstep", QT1, FLT, j + 1, DUMMYACC)
        for i = 0, N - 1 do f:st(QT2 + i, f:ld(QT1 + i)) end
        f:run("powvec", j + 2)
        f:run("mstep", QT2, FLT, j + 2, DUMMYACC)
      end
      -- belief of each node at the step its command will apply
      local lam = f:var("lam")
      local lq, ls
      if cfg.cheap_landing and not cfg.rollout then
        lq, ls = f:var("lq"), f:var("ls")
        -- The arrival-rate and posterior temporaries are dead here. Reuse
        -- their registers for the history and pending-flow ring bases.
        f:set(a, ((j - 1) & 7) << 4)
        f:set(pg3, ((j + 2) & 3) << 4)
      end
      for i = 0, N - 1 do
        f:set(lam, f:ld(LAM + i))
        f:st(SSEL + i, (j + 1 + lam) & 7)
        if cfg.rollout then
          f:iff(lam:eq(0), function() f:st(QSEL + i, f:ld(QP + i)) end, function()
            f:iff(lam:eq(1), function() f:st(QSEL + i, f:ld(QT1 + i)) end, function() f:st(QSEL + i, f:ld(QT2 + i)) end)
          end)
        else
          if cfg.cheap_landing then
            f:set(lq, f:ld(QP + i))
            -- Long-delay nodes need the extra horizon most. Predict only
            -- their existing service and pending arrivals, leaving the
            -- persistent model untouched and retaining background slack.
            f:iff(lam:eq(2), function()
              for h = 1, 2 do
                f:set(ls, 0)
                f:iff(f:ld(PW + ((a + ((h + 1 - lam) << 4)) & 127) + i):ne(0), function()
                  f:set(ls, lq)
                  f:iff(ls:gt(256), function() f:set(ls, 256) end)
                  f:set(ls, (ls * SUCC) >> 8)
                end)
                f:set(lq, lq - ls + f:ld(FLP + ((pg3 + ((h - 1) << 4)) & 63) + i))
                if i < 4 then f:set(lq, lq + f:ld(GEXP)) end
                f:set(lq, lq - ((lq * 21) >> 8))
                f:iff(lq:gt(4096), function() f:set(lq, 4096) end)
              end
            end)
            f:st(QSEL + i, lq)
          else
            f:st(QSEL + i, f:ld(QP + i))
          end
        end
        f:st(X.DES + i, 0)
      end
      -- decision kernel: quantise, then the installed package (if current) or the generic kernel, then assignment
      f:run("plan_quant")
      f:iff(GL.and_(f:ld(PKGACT):ne(0), f:ld(PKGVER):eq(f:ld(PARV))), function()
        f:do_(f:callr(f:ld(PKGE)))
        f:st(PKGUSES, f:ld(PKGUSES) + 1)
      end, function()
        f:run("kernel_generic", PAR)
      end)
      f:run("priority_context", PAR)
      f:run("plan_assign")
    end)
  end)

  -- record which nodes were actually requested (after the shield) for boundary b
  P:func("pw_commit", {"b"}, function(f, b)
    local o = f:var("o", (b & 7) << 4)
    for i = 0, N - 1 do f:st(PW + o + i, ((f:ld(X.FIN + i) >> 1) | (f:ld(X.FIN + i) >> 2)) & 1) end
  end)

  -- correct the persistent belief with the ACTUAL arrivals of packet step kp (observed two windows late)
  P:func("arrival_correct", {"kp", "arr"}, function(f, kp, arr)
    local d = f:var("d")
    for i = 0, 3 do
      f:set(d, (((arr >> (3 - i)) & 1) << 8) - f:ld(EXPH + (kp & 7)))
      f:set(d, d + f:ld(QP + i))
      f:iff(d:lt(0), function() f:set(d, 0) end)
      f:st(QP + i, d)
    end
  end)
end

--[[@@END@@]]
return Plan
end

-- ======================================================================== asi.guest.bias  (asi/guest/bias.lua)
package.preload["asi.guest.bias"] = function(...)
--[============[
asi/guest/bias.lua -- certified sensor-bias envelope from archive evidence (guest code).

WHAT IS CERTIFIED
  The shield's sensor bound is U <= 2Y - 2*bias_lo + 9. bias_lo = -2 is the public-support default
  (no statistics, zero error). This module may RAISE bias_lo_i using archive evidence, at a cost
  alpha that is reserved in the risk ledger:  r0 <= Delta - eta - alpha - eps_contract.

EVIDENCE (fresh, real, independent given the persistent world index)
  Record 0 of every historical episode starts from the exactly known reset state (T = 16 at all
  nodes). If its latched request for node i is (a1,a2) = (0,0), the applied command at step 0 is
  zero whatever lambda_i and the orientation are, so T_{i,1} = 15 + xi, hence
        Y_i = clip(7 + xi + b + eps - 3F, 0, 31)
  with b the node's temperature bias, eps ~ (1/16,7/8,1/16) on (-1,0,1), and (G0, xi, F) the initial
  load g0 ~ Ber(1/5), xi ~ Ber((1+g0)/8), F1 ~ Ber((1+g0)/256). Episodes are independent, so the
  per-node reading across episodes is an i.i.d. sample of P_b(y) = N_b(y)/163840 (exact integers).
  Each episode record is read at most once (provenance), and a page whose record fields do not name
  its own episode / step 0 is rejected as non-evidence (zero pages in test archives).

TEST
  For hypothesis H_b0 (bias = b0) and any alternative b > b0, LR_b(t) = prod_s P_b(y_s)/P_b0(y_s) is a
  nonnegative martingale under H_b0 (mean exactly 1). By Ville's inequality
  P(sup_t LR_b >= c) <= 1/c, so rejecting H_b0 when some alternative has LR_b >= n_alt * 2^31 has total
  size <= 2^-31 per (node, hypothesis) identifier. Identifiers are the fixed-length prefix-free codes
  (node:4 bits, hypothesis:3 bits); their allocations sum to at most 80 * 2^-31 < alpha = 2^-24.
  Likelihoods are accumulated in the log2 domain, in fixed point 2^-16, with DIRECTED ROUNDING:
  lower sums use lower enclosures, upper sums use upper enclosures, so a rejection is certified.
  An observation impossible under H_b0 (P = 0) rejects it with zero error.
  The log2 enclosures are computed by interval squaring on the guest (charged work), not read from a table.
]============]
local GL = require("asi.gl")
local RT = require("asi.guest.rt")

local Bias = {}
Bias.ALPHA_LOG2 = -24            -- total false-rejection budget alpha = 2^-24
Bias.ID_LOG2 = -31               -- per (node, hypothesis) allocation 2^-31
Bias.NALT_LOG2 = 2               -- at most 4 alternatives: threshold constant 2^2
Bias.FRAC = 16                   -- fixed-point fractional bits of the log2 domain
Bias.BIG = 1 << 40               -- stands for -infinity (impossible observation)

function Bias.install(X)
  local P, cfg, N = X.P, X.cfg, X.N
  local FR = Bias.FRAC
  local THR = (31 + Bias.NALT_LOG2) << FR
  local BIG = Bias.BIG

  local LOGLO, LOGHI = P:static("LOGLO", 160), P:static("LOGHI", 160)
  local LLO, LHI = P:static("LLO", 5 * N), P:static("LHI", 5 * N)
  local BLO = P:static("BLO", N)               -- certified bias lower bound per node
  local BCNT = P:static("BCNT", N)             -- samples used per node
  local ENVV = P:static("ENVV", 1)             -- envelope version (increments when any bound improves)
  local NEXTEP = P:static("NEXTEP", 1)         -- next archive episode to read (provenance: read once)
  local EPUSED = P:static("EPUSED", 1)         -- episodes accepted as evidence
  local EPBAD = P:static("EPBAD", 1)           -- pages rejected as non-evidence
  local REC = P:static("REC", 8)
  local LST = P:static("LST", 1)               -- learning stage: 0 = read the next page, 1 = add the record held in REC, 2 = run the tests
  local LEST = P:static("LEST", 1)             -- estimated ticks of the NEXT stage (guards the scheduler)
  local LSMAX = P:static("LSMAX", 3)           -- measured max work of stage 0 / 1 / 2
  local NTAB = P:static("NTAB", 160)           -- exact counts N_b(y) (out of 163840)
  local L2LO, L2HI = P:static("L2LO", 1), P:static("L2HI", 1)
  local DLOG = P:static("DLOG", 2)             -- log2(163840) enclosure
  X.BLO, X.ENVV, X.BCNT, X.EPUSED, X.EPBAD, X.NEXTEP, X.LEST, X.LSMAX, X.LST = BLO, ENVV, BCNT, EPUSED, EPBAD, NEXTEP, LEST, LSMAX, LST
  X.LOGLO, X.LOGHI, X.LLO, X.LHI = LOGLO, LOGHI, LLO, LHI

  -- enclosure of log2(n) for an integer 1 <= n < 2^40, in units of 2^-16 (results in L2LO, L2HI)
  P:func("log2_enc", {"n"}, function(f, n)
    local k, t = f:var("k", 0), f:var("t", n)
    local xlo, xhi = f:var("xlo"), f:var("xhi")
    local lo, i = f:var("lo"), f:var("i")
    f:while_(t:gt(1), function() f:set(t, t >> 1); f:set(k, k + 1) end)
    f:set(xlo, n << (60 - k))                     -- value in [2^60, 2^61): exact
    f:set(xhi, xlo)
    f:set(lo, k << FR)
    f:set(t, 0)                                   -- t = 1 once a digit could not be decided
    f:for_(i, 1, FR + 1, function()
      -- square both bounds: floor / ceil of x*x / 2^60
      local h, l = f:var("h"), f:var("l")
      f:set(h, xlo:mulhu(xlo)); f:set(l, xlo * xlo)
      f:set(xlo, (h << 4) | (l >> 60))
      f:set(h, xhi:mulhu(xhi)); f:set(l, xhi * xhi)
      f:set(xhi, (h << 4) | (l >> 60))
      f:iff((l & ((1 << 60) - 1)):ne(0), function() f:set(xhi, xhi + 1) end)
      f:iff(xlo:ge(1 << 61), function()
        f:set(lo, lo + (1 << (FR - i))); f:set(xlo, xlo >> 1); f:set(xhi, (xhi + 1) >> 1)
      end, function()
        f:iff(xhi:lt(1 << 61), function() end, function()
          f:set(t, i); f:break_()                  -- straddles 2: stop refining
        end)
      end)
    end)
    f:st(L2LO, lo)
    -- remaining uncertainty: undecided digits (width 2^(FR - i + 1)) or one unit
    f:iff(t:eq(0), function() f:st(L2HI, lo + 1) end, function() f:st(L2HI, lo + (GL.lift(1 << (FR + 1)) >> t)) end)
  end)

  -- exact initial-state sample law of the temperature reading under bias b (index bi = b + 2), as integer counts
  -- out of 5*8*256*16 = 163840, then directed-rounding log2 enclosures of N/163840
  P:func("build_tables", {}, function(f)
    local bi, g, xi, fl, e = f:var("bi"), f:var("g"), f:var("xi"), f:var("fl"), f:var("e")
    local w, y = f:var("w"), f:var("y")
    f:run("log2_enc", 163840)
    f:st(DLOG, f:ld(L2LO)); f:st(DLOG + 1, f:ld(L2HI))
    f:for_(bi, 0, 5, function()
      f:for_(y, 0, 32, function() f:st(NTAB + (bi << 5) + y, 0) end)
      f:for_(g, 0, 2, function()
        f:for_(xi, 0, 2, function()
          f:for_(fl, 0, 2, function()
            f:for_(e, 0, 3, function()
              f:set(w, 4 - 3 * g)                                          -- P(g0) * 5: 4 for g0=0, 1 for g0=1
              f:set(w, w * (xi * (1 + g) + (1 - xi) * (7 - g)))            -- P(xi|g0) * 8
              f:set(w, w * (fl * (1 + g) + (1 - fl) * (255 - g)))          -- P(F|g0) * 256
              f:set(w, w * (1 + 13 * (e & 1)))                             -- P(eps) * 16 : (1,14,1)
              -- reading = clip(7 + xi + (bi-2) + (e-1) - 3*fl, 0, 31)
              f:set(y, 7 + xi + bi - 2 + e - 1 - 3 * fl)
              f:iff(y:lt(0), function() f:set(y, 0) end)
              f:iff(y:gt(31), function() f:set(y, 31) end)
              f:st(NTAB + (bi << 5) + y, f:ld(NTAB + (bi << 5) + y) + w)
            end)
          end)
        end)
      end)
      f:for_(y, 0, 32, function()
        local n = f:var("n", f:ld(NTAB + (bi << 5) + y))
        f:iff(n:eq(0), function()
          f:st(LOGLO + (bi << 5) + y, -BIG); f:st(LOGHI + (bi << 5) + y, -BIG)
        end, function()
          f:run("log2_enc", n)
          f:st(LOGLO + (bi << 5) + y, f:ld(L2LO) - f:ld(DLOG + 1))
          f:st(LOGHI + (bi << 5) + y, f:ld(L2HI) - f:ld(DLOG))
        end)
      end)
    end)
    for i = 0, N - 1 do f:st(BLO + i, cfg.bias_lo) end
    f:st(LEST, cfg.est_learn_read)
  end)

  -- add one archive record (8 words in REC) to the per-node likelihood sums
  -- runtime bit-field extractor: len bits at big-endian bit position pos of the word array at base (len <= 57)
  P:func("bits_dyn", {"base", "pos", "len"}, function(f, base, pos, len)
    local bo, hi, lo = f:var("bo", pos & 63), f:var("hi"), f:var("lo")
    f:set(base, base + (pos >> 6))
    f:iff((bo + len):le(64), function()
      f:ret((f:ld(base) >> (64 - bo - len)) & ((GL.lift(1) << len) - 1))
    end)
    f:set(hi, 64 - bo); f:set(lo, len - hi)
    f:ret(((f:ld(base) & ((GL.lift(1) << hi) - 1)) << lo) | (f:ld(base + 1) >> (64 - lo)))
  end)

  P:func("bias_record", {}, function(f)
    local O = RT.OFF
    local y, b = f:var("y"), f:var("b")
    -- These schema offsets are fixed. Decode them directly rather than paying
    -- two dynamic extractor calls per node; retain every likelihood update.
    for i = 0, N - 1 do
      f:iff(RT.field(f, REC, O.latched_requested_channels_and_routes.off + i * 3, 2):eq(0), function()
        f:set(y, RT.field(f, REC, O.temperature_measurements.off + i * 5, 5))
        f:st(BCNT + i, f:ld(BCNT + i) + 1)
        f:for_(b, 0, 5, function()
          f:st(LLO + i * 5 + b, f:ld(LLO + i * 5 + b) + f:ld(LOGLO + (b << 5) + y))
          f:st(LHI + i * 5 + b, f:ld(LHI + i * 5 + b) + f:ld(LOGHI + (b << 5) + y))
        end)
      end)
    end
  end)

  -- sequential rejection from below: raise BLO_i while H_b0 is rejected by some alternative b > b0
  P:func("bias_decide", {}, function(f)
    local i, b0, b, rej, base = f:var("i"), f:var("b0"), f:var("b"), f:var("rej"), f:var("base")
    f:for_(i, 0, N, function()
      f:set(base, i * 5)
      f:set(b0, f:ld(BLO + i) + 2)
      f:set(rej, 1)
      f:while_(GL.and_(b0:lt(4), rej:ne(0)), function()
        f:set(rej, 0)
        f:for_(b, b0 + 1, 5, function()
          f:iff((f:ld(LLO + base + b) - f:ld(LHI + base + b0)):ge(THR), function() f:set(rej, 1) end)
        end)
        f:iff(rej:ne(0), function()
          f:set(b0, b0 + 1)
          f:st(BLO + i, b0 - 2)
          f:st(ENVV, f:ld(ENVV) + 1)
        end)
      end)
    end)
  end)

  -- read and use archive episode e (record 0 only); returns 1 if accepted as evidence
  P:func("learn_page", {"e"}, function(f, e)
    local O = RT.OFF
    local st = f:var("st")
    f:set(st, f:sys("PAGE", GL.lift(8 << 32) | e, REC))
    f:iff(st:ne(0), function() f:ret(0) end)
    -- integrity: the record must name its own episode and step 0 (zero pages are not evidence)
    f:iff(GL.and_(RT.field(f, REC, O.episode_id.off, 16):eq(e), RT.field(f, REC, O.physical_step.off, 32):eq(0),
                  f:ld(REC):eq(GL.lift(0) | (e << 48))), function()
      f:ret(1)                                      -- accepted: the record stays in REC for the processing stage
    end)
    f:st(EPBAD, f:ld(EPBAD) + 1)
    f:ret(0)
  end)

  -- learning in two bounded stages (each fits a window next to the control work):
  --   stage 0 reads one fresh episode page (charged page read) and validates it as evidence;
  --   stage 1 adds the record to the likelihood sums, runs the sequential tests and re-checks the risk ledger.
  P:func("learn_slice", {}, function(f)
    local w0, e, d = f:var("w0", f:clk(4)), f:var("e"), f:var("d")
    f:iff(f:ld(LST):eq(0), function()
      f:set(e, f:ld(NEXTEP))
      f:iff(e:lt(cfg.learn_episodes), function()
        f:st(NEXTEP, e + 1)
        f:iff(f:call("learn_page", e):ne(0), function()
          local req = f:var("req", RT.field(f, REC, RT.OFF.latched_requested_channels_and_routes.off, 48))
          local n = f:var("eligible", 0)
          for i = 0, N - 1 do
            f:iff(((req >> (3 * (N - 1 - i) + 1)) & 3):eq(0), function() f:set(n, n + 1) end)
          end
          f:st(LST, 1)
          -- The fixed decoder's most expensive path fits est_learn_rec.
          -- Every excluded node saves at least 169 metered instructions;
          -- the default retains a margin for the slice wrapper and calls.
          f:st(LEST, cfg.est_learn_rec - (N - n) * 169)
        end)
      end)
      f:set(d, f:clk(4) - w0)
