-- ======================================================================== asi.guest.audit  (asi/guest/audit.lua)
package.preload["asi.guest.audit"] = function(...)
--[============[
asi/guest/audit.lua -- orientation estimation and shift monitoring with the delayed auditor.

The auditor answers Z = b_i xor (1-A)(z_i*[q>=rho_i] xor shift_i) xor E_j with E_j ~ Ber(1/16) fresh per
call and a lifetime blind-spot A ~ Ber(1/8) shared by all calls. It is a DELAYED, NOISY, CORRELATED
channel, not a proof of orientation:
  * at small occupancy (q < rho) and before the structural change, Z = b_i xor E, so a majority of
    five polls recovers b_i except for the 1/16-per-poll flips;
  * if A = 1 it carries no information about z or the structural change at all;
  * a poll can be stale by the time it is read (it is evaluated at ACCEPTANCE, read >= 2 steps later).
Every poll is a charged invocation (128) + retrieval (128); there is one request slot, so queries are
sequential (invoke, wait three windows, read, repeat) and cancellation is never needed in normal operation.

Policy use (heuristic, never a safety argument): ORI_i = majority bit when the margin |vote| >= 3 (then
single-channel commands become possible for that node); afterwards polling continues round-robin and
three net disagreements flip ORI_i (recovery after a structural change when A = 0; invisible when A = 1,
which is a stated limitation and is measured in the harness).
]============]
local GL = require("asi.gl")

local Audit = {}

function Audit.install(X)
  local P, cfg, N, stat_inc = X.P, X.cfg, X.N, X.stat_inc
  local ORI, ORIOK = X.ORI, X.ORIOK
  local AUDST = P:static("AUDST", 1)       -- 0 idle, 1 request pending
  local AUDN = P:static("AUDN", 1)         -- next node to poll
  local AUDJ = P:static("AUDJ", 1)         -- window of the pending invocation
  local AUDR = P:static("AUDR", 1)         -- completed polling rounds
  local VOTE = P:static("VOTE", N)
  local DIS = P:static("DIS", N)
  local AUDBUF = P:static("AUDBUF", 2)
  local AST = P:static("AST", 8)           -- counters: [0]invoked [1]read [2]notready [3]flips [4]rejected
  X.VOTE, X.AST, X.AUDR = VOTE, AST, AUDR
  local FROM, ROUNDS, MARGIN, FLIPAT = cfg.audit_from, cfg.audit_rounds, cfg.audit_margin, cfg.audit_flip

  P:func("aud_process", {"node", "z"}, function(f, node, z)
    local v = f:var("v")
    f:iff(f:ld(AUDR):lt(ROUNDS), function()
      -- initial voting rounds
      f:set(v, f:ld(VOTE + node))
      f:iff(z:ne(0), function() f:set(v, v + 1) end, function() f:set(v, v - 1) end)
      f:st(VOTE + node, v)
    end, function()
      -- monitoring: disagreement counter against the current estimate
      f:iff(f:ld(ORIOK + node):ne(0), function()
        f:set(v, f:ld(DIS + node))
        f:iff(z:ne(f:ld(ORI + node)), function() f:set(v, v + 1) end, function()
          f:iff(v:gt(0), function() f:set(v, v - 1) end)
        end)
        f:iff(v:ge(FLIPAT), function()
          f:st(ORI + node, 1 - f:ld(ORI + node))
          f:st(AST + 3, f:ld(AST + 3) + 1)
          f:set(v, 0)
        end)
        f:st(DIS + node, v)
      end)
    end)
  end)

  -- finish the voting phase: set ORI/ORIOK from the vote margins
  P:func("aud_finish_votes", {}, function(f)
    local v = f:var("v")
    if cfg.policy == "fluid" then
      if cfg.pkg then f:run("pkg_invalidate") else f:st(X.PARV, f:ld(X.PARV) + 1) end -- also invalidate paired tuner premises
    end
    for i = 0, N - 1 do
      f:set(v, f:ld(VOTE + i))
      f:iff(v:ge(MARGIN), function() f:st(ORI + i, 1); f:st(ORIOK + i, 1) end, function()
        f:iff(v:le(-MARGIN), function() f:st(ORI + i, 0); f:st(ORIOK + i, 1) end)
      end)
    end
  end)

  P:func("aud_step", {"j"}, function(f, j)
    local st = f:var("st")
    f:iff(f:ld(AUDST):eq(0), function()
      f:iff(GL.and_(j:ge(FROM), (j & 3):eq(0)), function()
        f:set(st, f:sys("AUDINV", f:ld(AUDN)))
        f:iff(st:eq(0), function()
          f:st(AUDJ, j); f:st(AUDST, 1); f:st(AST + 0, f:ld(AST + 0) + 1)
        end, function()
          f:st(AST + 4, f:ld(AST + 4) + 1)
          f:iff(st:eq(4), function() f:do_(f:sys("AUDCANC", 0)) end)   -- a stale request occupies the single slot: cancel it
        end)
      end)
    end, function()
      f:iff(j:ge(f:ld(AUDJ) + 3), function()
        f:set(st, f:sys("AUDREAD", AUDBUF))
        f:iff(st:eq(0), function()
          f:st(AST + 1, f:ld(AST + 1) + 1)
          f:run("aud_process", (f:ld(AUDBUF + 1) >> 1) & 15, f:ld(AUDBUF + 1) & 1)
          f:st(AUDST, 0)
          f:st(AUDN, (f:ld(AUDN) + 1) & 15)
          f:iff(f:ld(AUDN):eq(0), function()
            f:st(AUDR, f:ld(AUDR) + 1)
            f:iff(f:ld(AUDR):eq(ROUNDS), function() f:run("aud_finish_votes") end)
          end)
        end, function()
          f:iff(st:eq(2), function() f:st(AST + 2, f:ld(AST + 2) + 1) end, function()
            f:st(AST + 4, f:ld(AST + 4) + 1); f:st(AUDST, 0)       -- anything else: drop the request and retry
          end)
        end)
      end)
    end)
  end)
end

--[[@@END@@]]
return Audit
end

-- ======================================================================== asi.guest.pkg  (asi/guest/pkg.lua)
