Pkg.REC = {emitted = 0, static_ok = 1, static_rej = 2, equiv_ok = 3, equiv_rej = 4, installed = 5, rejected_cost = 6,
           invalidated = 7, cases = 8, gen_cost = 9, pkg_cost = 10, last_len = 11, last_hash = 12, rejected_stale = 13,
           domain_min_saving = 14, domain_mean_saving = 15}

