    {T("BEQZ", 0, 2, 0), 0, 11},         {T("LD", 1, 0, 0), 1, 0},           {T("SLTI", 2, 1, 0), 4, par(2, 0)},
    {T("BNEZ", 0, 2, 0), 0, 8},          {T("MOVI", 3, 0, 0), 0, 6},         {T("SLTI", 2, 1, 0), 4, par(1, 0)},
    {T("BNEZ", 0, 2, 0), 0, 5},          {T("MOVI", 3, 0, 0), 0, 10},        {T("SLTI", 2, 1, 0), 4, par(0, 0)},
    {T("BNEZ", 0, 2, 0), 0, 2},          {T("MOVI", 3, 0, 0), 0, 14},        {T("ST", 0, 0, 3), 3, 0},
