    if LOOKUP then
      -- Accept one exact block language. Every 64-bit input is mapped into its dedicated table.
      local base, p, row, expected, ok = f:var("base", CODEA), f:var("p", f:ld(SCP)),
                                        f:var("row"), f:var("expected"), f:var("ok", f:ld(SCOK))
      f:iff(slot:ne(0), function() f:set(base, CODEB) end)
      f:while_(GL.and_(count:gt(0), p:lt(8 * N), ok:ne(0)), function()
        f:set(row, p & 7)
        for r = 0, 7 do
          f:iff(row:eq(r), function()
            local imm = ROWSA[r + 1][3]
            if r == 0 then imm = QB + (p >> 3)
            elseif r == 2 then imm = TB + (p >> 3)
            elseif r == 6 then imm = LUT0
            elseif r == 7 then imm = DS + (p >> 3) end
            f:set(expected, GL.lift(ROWSA[r + 1][1]) | (GL.lift(imm) & MASK))
          end)
        end
        f:iff(GL.and_(row:eq(6), f:ld(base + p):eq(GL.lift(ROWSA[7][1]) | (LUT1 & MASK))),
          function() f:set(expected, f:ld(base + p)) end)
        f:iff(f:ld(base + p):ne(expected), function() f:set(ok, 0) end)
        f:set(p, p + 1); f:set(count, count - 1)
      end)
      f:st(SCP, p); f:st(SCOK, ok)
      f:iff(ok:eq(0), function() f:ret(0) end)
      f:iff(p:lt(8 * N), function() f:ret(1) end)
      f:iff(f:ld(base + 8 * N):ne(RET_WORD), function() f:ret(0) end)
      f:ret(2)
      return
    end
    local base, len = f:var("base"), f:var("len", f:ld(PKGLEN))
    local p, w, op, blk, bend, ok = f:var("p", f:ld(SCP)), f:var("w"), f:var("op"), f:var("blk", f:ld(SCBLK)), f:var("bend", f:ld(SCBEND)), f:var("ok", f:ld(SCOK))
    local rd, ra, imm = f:var("rd"), f:var("ra"), f:var("imm")
    f:set(base, CODEA)
    f:iff(slot:ne(0), function() f:set(base, CODEB) end)
    f:while_(GL.and_(count:gt(0), p:lt(len - 1), ok:ne(0)), function()
      f:iff(p:ge(bend), function()                                 -- entering the next block
        f:set(blk, blk + 1)
        f:set(bend, f:ld(BS + blk + 1))
      end)
      f:set(w, f:ld(base + p))
      f:set(op, w >> 56)
      -- every block must END with its DS store
      f:iff(GL.and_(p:eq(bend - 1), op:ne(M.by_name.ST)), function() f:set(ok, 0) end)
      f:set(rd, (w >> 52) & 15); f:set(ra, (w >> 48) & 15)
      f:set(imm, w & MASK)
      f:iff(imm:ge(1 << 43), function() f:set(imm, imm - (1 << 44)) end)
      f:iff(op:eq(M.by_name.LD), function()
        -- load: absolute (base r0), destination r1..r4, own node's QB/TB only
        f:iff(GL.or_(ra:ne(0), rd:lt(1), rd:gt(4), GL.not_(GL.or_(imm:eq(QB + blk), imm:eq(TB + blk)))), function() f:set(ok, 0) end)
      end, function()
      f:iff(op:eq(M.by_name.ST), function()
        f:iff(GL.or_(ra:ne(0), imm:ne(DS + blk), ((w >> 44) & 15):lt(1), ((w >> 44) & 15):gt(4), p:ne(bend - 1)), function() f:set(ok, 0) end)
      end, function()
      f:iff(GL.or_(op:eq(M.by_name.MOVI), op:eq(M.by_name.SLTI), op:eq(M.by_name.ADDI)), function()
        f:iff(GL.or_(rd:lt(1), rd:gt(4)), function() f:set(ok, 0) end)
        f:iff(GL.and_(op:ne(M.by_name.MOVI), GL.or_(ra:lt(1), ra:gt(4))), function() f:set(ok, 0) end)
      end, function()
      f:iff(GL.or_(op:eq(M.by_name.BEQZ), op:eq(M.by_name.BNEZ)), function()
        -- forward only, target inside the block (at most the block's final instruction)
        f:iff(GL.or_(ra:lt(1), ra:gt(4), imm:le(0), (p + imm):gt(bend - 1)), function() f:set(ok, 0) end)
      end, function()
        f:set(ok, 0)                                              -- anything else: not in the language
      end) end) end) end)
      f:set(p, p + 1); f:set(count, count - 1)
    end)
    f:st(SCP, p); f:st(SCBLK, blk); f:st(SCBEND, bend); f:st(SCOK, ok)
    f:iff(ok:eq(0), function() f:ret(0) end)
    f:iff(p:lt(len - 1), function() f:ret(1) end)
    -- the final instruction must be JR r15
    f:set(w, f:ld(base + len - 1))
    f:iff(GL.or_((w >> 56):ne(M.by_name.JR), ((w >> 48) & 15):ne(15)), function() f:ret(0) end)
    f:ret(2)
  end)

  -- ---------------------------------------------------------------- semantic checker (bounded slice)
  -- run up to `count` of the 320 domain points starting at EQI; returns 1 = continue/ok, 0 = mismatch, 2 = complete
  P:func("pkg_equiv_step", {"slot", "count"}, function(f, slot, count)
    local e, qb, tb, i, ok = f:var("e", f:ld(EQI)), f:var("qb"), f:var("tb"), f:var("i"), f:var("ok", 1)
    local entry = f:var("entry")
    local saving = f:var("saving")
    f:set(entry, CODEA)
    f:iff(slot:ne(0), function() f:set(entry, CODEB) end)
    f:while_(GL.and_(count:gt(0), e:lt(32 * 10), ok:ne(0)), function()
      f:set(qb, e // 10); f:set(tb, e % 10)
      for k = 0, N - 1 do f:st(QB + k, qb); f:st(TB + k, tb) end
      f:set(qb, f:clk(4))                                       -- comparison uses paid execution on the same input
      f:run("kernel_generic", PAR)
      f:set(tb, f:clk(4) - qb)
      for k = 0, N - 1 do f:st(DSG + k, f:ld(DS + k)); f:st(DS + k, 255) end
      f:set(qb, f:clk(4))
      f:do_(f:callr(entry))
      f:set(saving, tb - (f:clk(4) - qb))
      f:iff(saving:lt(f:ld(PKGMIN)), function() f:st(PKGMIN, saving) end)
      f:st(PKGSUM, f:ld(PKGSUM) + saving)
      for k = 0, N - 1 do f:iff(f:ld(DS + k):ne(f:ld(DSG + k)), function() f:set(ok, 0) end) end
      f:set(e, e + 1); f:set(count, count - 1)
      f:st(PREC + Pkg.REC.cases, f:ld(PREC + Pkg.REC.cases) + 1)
    end)
    f:st(EQI, e)
    f:iff(ok:eq(0), function() f:ret(0) end)
    f:iff(e:ge(32 * 10), function() f:ret(2) end)
    f:ret(1)
  end)

  -- ---------------------------------------------------------------- installer / invalidation
  P:func("pkg_install", {"slot"}, function(f, slot)
    local base = f:var("base", CODEA)
    f:iff(slot:ne(0), function() f:set(base, CODEB) end)
    f:st(PKGE, base)
    f:st(PKGVER, f:ld(PKGPV))
    f:st(PKGLIVE, slot)
    f:st(PKGACT, 1)
    f:st(PREC + Pkg.REC.last_len, f:ld(PKGLEN)); f:st(PREC + Pkg.REC.last_hash, f:ld(PKGHASH))
    rec(f, Pkg.REC.installed)
  end)

  -- parameter or orientation change: any package is stale
  P:func("pkg_invalidate", {}, function(f)
    f:iff(f:ld(PKGACT):ne(0), function() rec(f, Pkg.REC.invalidated) end)
    f:st(PKGACT, 0)
    f:st(PARV, f:ld(PARV) + 1)
  end)

  -- measure per-call processor work of the generic kernel and of the package on a representative input
  P:func("pkg_measure", {"slot"}, function(f, slot)
    local w0, w1, w2, entry = f:var("w0"), f:var("w1"), f:var("w2"), f:var("entry", CODEA)
    f:iff(slot:ne(0), function() f:set(entry, CODEB) end)
    for k = 0, N - 1 do f:st(QB + k, f:ld(QBR + k)); f:st(TB + k, f:ld(TBR + k)) end
    f:set(w0, f:clk(4))
    f:run("kernel_generic", PAR)
    f:set(w1, f:clk(4))
    f:do_(f:callr(entry))
    f:set(w2, f:clk(4))
    f:st(PREC + Pkg.REC.gen_cost, w1 - w0)
    f:st(PREC + Pkg.REC.pkg_cost, w2 - w1)
  end)

  -- one bounded slice of the production pipeline; returns 1 if it did work
  -- stage costs are metered with CLK and accumulated in PKGCOST; the install decision uses them
  P:func("pkg_slice", {"j"}, function(f, j)
    local st, w0, r = f:var("st", f:ld(PKGST)), f:var("w0", f:clk(4)), f:var("r")
    local slot = f:var("slot", f:ld(PKGSLOT))
    f:iff(GL.and_(st:ne(0), f:ld(PKGPV):ne(f:ld(PARV))), function()
      rec(f, Pkg.REC.rejected_stale); f:st(PKGST, 0); f:ret(0)     -- stop spending on invalidated premises immediately
    end)
    f:iff(st:eq(0), function()
      f:iff(f:ld(PKGREJV):ne(f:ld(PARV)), function()
        f:st(PKGREJV, f:ld(PARV)); f:st(PKGREJ, 0)
      end)
      if cfg.tune then
        -- Avoid repeatedly specializing a policy whose paired search is still changing its premises.
        local ready = P:sym("TREC")
        local settle = (cfg.tune_last_start or 2000)
                       + 4 * math.max(cfg.tune_horizon, cfg.tune_verify_horizon or cfg.tune_horizon) + 8
        f:iff(GL.and_(f:ld(ready):lt(cfg.tune_max_evals), j:lt(settle)), function() f:ret(0) end)
      end
      -- request a package when none is current and enough windows remain to repay a production
      f:iff(GL.and_(f:ld(PKGVER):ne(f:ld(PARV)), j:lt(cfg.pkg_last_start), f:ld(PKGREJ):lt(cfg.pkg_max_rejects),
                    f:ld(PREC + Pkg.REC.emitted):lt(cfg.pkg_max_emits)), function()
        f:st(PKGSLOT, 1 - f:ld(PKGLIVE))                           -- build into the slot that is not live
        f:st(PKGPV, f:ld(PARV))
        if LOOKUP then
          f:st(PKGST, 6); f:st(LUTI, 0); f:st(LUTV, 0)
        else f:st(PKGST, 1) end
        f:st(PKGCOST, 0); f:st(EQI, 0); f:st(EMI, 0)
        f:st(PKGMIN, 1 << 60); f:st(PKGSUM, 0)
      end)
      f:ret(0)
    end)
    if LOOKUP then
      f:iff(st:eq(6), function()
        f:iff(f:call("pkg_lut_step", cfg.pkg_lut_points or 8):ne(0), function() f:st(PKGST, 1) end)
      end)
    end
    f:iff(st:eq(1), function()
      f:run("pkg_emit", slot, f:ld(EMI), cfg.pkg_emit_nodes)
      f:st(EMI, f:ld(EMI) + cfg.pkg_emit_nodes)
      f:iff(f:ld(EMI):ge(N), function() f:st(PKGST, 5) end)
    end)
    f:iff(st:eq(5), function()
      f:iff(f:call("pkg_hash_step", slot, cfg.pkg_hash_words):ne(0), function() f:st(PKGST, 2); f:run("pkg_static_begin", slot) end)
    end)
    f:iff(st:eq(2), function()
      f:set(r, f:call("pkg_static_step", slot, cfg.pkg_static_words))
      f:iff(r:eq(0), function() rec(f, Pkg.REC.static_rej); f:st(PKGST, 0) end)
      f:iff(r:eq(2), function() rec(f, Pkg.REC.static_ok); f:st(PKGST, 3) end)
    end)
    f:iff(st:eq(3), function()
      f:set(r, f:call("pkg_equiv_step", slot, cfg.pkg_equiv_per_slice))
      f:iff(r:eq(0), function() rec(f, Pkg.REC.equiv_rej); f:st(PKGST, 0) end)
      f:iff(r:eq(2), function() rec(f, Pkg.REC.equiv_ok); f:st(PKGST, 4) end)
    end)
    f:iff(st:eq(4), function()
      -- decide: stale? cheaper? repays its metered cost over the remaining windows?
      f:run("pkg_measure", slot)
      local saving = f:var("saving")
      f:st(PREC + Pkg.REC.domain_min_saving, f:ld(PKGMIN))
      f:st(PREC + Pkg.REC.domain_mean_saving, f:ld(PKGSUM) // (32 * 10))
      f:set(saving, f:ld(PREC + Pkg.REC.gen_cost) - f:ld(PREC + Pkg.REC.pkg_cost))
      f:set(saving, saving - 8)                                  -- reserve the installed branch's dispatch bookkeeping
      f:iff(f:ld(PKGPV):ne(f:ld(PARV)), function()
        rec(f, Pkg.REC.rejected_stale); f:st(PKGST, 0)               -- parameters moved while checking: proof is for an old version
      end, function()
        f:iff(GL.and_(saving:gt(0), f:ld(PREC + Pkg.REC.domain_mean_saving):gt(0),
                      (saving * (cfg.pkg_horizon - j)):gt(f:ld(PKGCOST) + f:clk(4) - w0 + cfg.pkg_margin)), function()
          f:run("pkg_install", slot)
        end, function() rec(f, Pkg.REC.rejected_cost); f:st(PKGREJ, f:ld(PKGREJ) + 1) end)
        f:st(PKGST, 0)
      end)
    end)
    f:st(PKGCOST, f:ld(PKGCOST) + f:clk(4) - w0)
    f:ret(1)
  end)
end

--[[@@END@@]]
return Pkg
end

-- ======================================================================== asi.guest.tune  (asi/guest/tune.lua)
package.preload["asi.guest.tune"] = function(...)
--[============[
asi/guest/tune.lua -- candidate production, synthetic evaluation and selection (template A loop).

CANDIDATES are parameter vectors of the planner (priority thresholds T1>T2>T3, single-channel backlog limit
QDB, per-step energy cap CAPE). Producers (resident code, charged):
  * LOCAL  : one-coordinate perturbations of the incumbent (a heuristic producer);
  * ENUM   : the lexicographic enumerator over the finite grid
             T3 in {1..4} x (T2-T3) in {1..3} x (T1-T2) in {1..3} x CAPE in {10,12,14}   (108 codes).
             It is COMPLETE over this grid when the resource schedule grants 108 evaluations; with the
             declared slice budget it is only a paid fallback and need not finish (reported, never hidden).
EVALUATOR (candidate interpreter): a bounded-slice SYNTHETIC rollout of the fluid belief model for H steps
starting from the current belief, applying the candidate's kernel and assignment each step, scoring the
expected terminal service mass. It is a model-conditional estimate: synthetic samples are not evidence, the
score is never used as a safety argument, and every instruction of it is metered.
SELECTOR (resident): accept a candidate when its synthetic score exceeds the incumbent's by the declared
margin; acceptance rewrites PAR (cheap, no code), bumps the parameter version and thereby invalidates any
installed package, which the package pipeline then re-produces and re-proves (charged). Safety never
depends on the choice: every dispatched command passes the shield.
Slices retain preparation and execution separately; foreground scratch is never treated as retained synthetic state.
The finite structural/local/enumeration race uses at most tune_max_evals candidate pairs and tune_max_validations
extended checks. Only candidates passing the extended paired comparison may replace the incumbent.
]============]
local GL = require("asi.gl")

local Tune = {}

function Tune.install(X)
  local P, cfg, N, stat_inc = X.P, X.cfg, X.N, X.stat_inc
  local QB, TB, DS, PAR, PARV = X.QB, X.TB, X.DS, X.PAR, X.PARV
  local QP, FLP, GEXP, SRCV, POWV, ORIOK = X.QP, X.FLP, X.GEXP, X.SRCV, X.POWV, X.ORIOK
  local H = cfg.tune_horizon

  local SIMQ, SIMFL = P:static("SIMQ", N), P:static("SIMFL", 4 * N)
  local SIMDS, SIMPHASE = P:static("SIMDS", N), P:static("SIMPHASE", 1)
  local SIMT, SIMTN, SIMPOW = P:static("SIMT", N), P:static("SIMTN", N), P:static("SIMPOW", N)
  local SCAND = P:static("SCAND", 16)
  local SIMTERM = P:static("SIMTERM", 1)
  local SIMI = P:static("SIMI", 1)         -- rollout steps done for the candidate under evaluation
  local TST = P:static("TST", 1)           -- 0 idle, 1 evaluating incumbent, 2 evaluating candidate
  local INCSC = P:static("INCSC", 1)
  local CSC = P:static("CSC", 1)
  local TNEXT = P:static("TNEXT", 1)       -- candidate counter
  local TENUM = P:static("TENUM", 1)       -- enumerator position
  local TREC = P:static("TREC", 16)        -- [0..8] counters; [9]duplicates [10]stale [11]structural [12]gain [13]work [14]validations [15]qualified rejects
  local BASEQ, BASEFL = P:static("BASEQ", N), P:static("BASEFL", 4 * N)
  local BASET = P:static("BASET", N)
  local BASEPAR = P:static("BASEPAR", 16)
  local BTIME, BRATE, BVER = P:static("BTIME", 1), P:static("BRATE", 1), P:static("BVER", 1)
  local TWORK = P:static("TWORK", 1)
  local THORIZON, TVERIFY = P:static("THORIZON", 1), P:static("TVERIFY", 1)
  local SEEN, SEENV = P:static("TSEEN", 32), P:static("TSEENV", 32)
  X.TREC, X.SCAND, X.INCSC, X.TST = TREC, SCAND, INCSC, TST
  local DUMMY = X.DUMMYACC

  -- ----------------------------------------------------------- producers
  -- fill SCAND from the incumbent PAR by perturbation n (0..9); returns 1 if the vector is valid (ordering, ranges)
  P:func("cand_local", {"n"}, function(f, n)
    for k = 0, 8 do f:st(SCAND + k, f:ld(PAR + k)) end
    local k, d = f:var("k"), f:var("d")
    f:set(k, n >> 1)                                           -- coordinate pair
    f:set(d, 1 - ((n & 1) << 1))                                -- +1 / -1
    f:iff(k:le(2), function() f:st(SCAND + k, f:ld(PAR + k) + d) end)
    f:iff(k:eq(3), function() f:st(SCAND + 5, f:ld(PAR + 5) + d * 4) end)
    f:iff(k:eq(4), function() f:st(SCAND + 6, f:ld(PAR + 6) + d) end)
    f:ret(f:call("cand_valid"))
  end)

  -- fill SCAND from enumerator code g (0..107): lexicographic mixed radix (4,3,3,3)
  P:func("cand_enum", {"g"}, function(f, g)
    local t3, d2, d1, ce = f:var("t3"), f:var("d2"), f:var("d1"), f:var("ce")
    f:set(ce, g % 3); f:set(g, g // 3)
    f:set(d1, g % 3); f:set(g, g // 3)
    f:set(d2, g % 3); f:set(g, g // 3)
    f:set(t3, g % 4)
    for k = 0, 8 do f:st(SCAND + k, f:ld(PAR + k)) end
    f:st(SCAND + 2, t3 + 1)
    f:st(SCAND + 1, t3 + 1 + d2 + 1)
    f:st(SCAND + 0, t3 + 1 + d2 + 1 + d1 + 1)
    f:st(SCAND + 6, 10 + ce * 2)
    f:ret(f:call("cand_valid"))
  end)

  -- Compositional producer: change the assignment strategy together with one
  -- threshold scale or energy allocation. The old 108-code fallback remains.
  P:func("cand_structure", {"n"}, function(f, n)
    for k = 0, 8 do f:st(SCAND + k, f:ld(PAR + k)) end
    f:st(SCAND + 7, (f:ld(PAR + 7) + 1 + (n % 3)) % 4)
    f:iff(n:eq(1), function()
      f:st(SCAND + 7, f:ld(PAR + 7)); f:st(SCAND + 5, 12)
    end)
    f:iff(n:eq(2), function()
      f:st(SCAND + 7, f:ld(PAR + 7)); f:st(SCAND + 8, 1 - f:ld(PAR + 8))
    end)
    f:iff(n:ge(3), function() f:st(SCAND + 8, 1 - f:ld(PAR + 8)) end)
    local d = f:var("d", 0)
    f:iff((n // 3 % 3):eq(1), function() f:set(d, -1) end)
    f:iff((n // 3 % 3):eq(2), function() f:set(d, 1) end)
    for k = 0, 2 do f:st(SCAND + k, f:ld(PAR + k) + d) end
    f:ret(f:call("cand_valid"))
  end)

  P:func("cand_valid", {}, function(f)
    f:iff(GL.or_(f:ld(SCAND + 2):lt(1), f:ld(SCAND + 1):le(f:ld(SCAND + 2)), f:ld(SCAND):le(f:ld(SCAND + 1)),
                 f:ld(SCAND):gt(31), f:ld(SCAND + 5):lt(4), f:ld(SCAND + 5):gt(31), f:ld(SCAND + 6):lt(2), f:ld(SCAND + 6):gt(14),
                 f:ld(SCAND + 7):lt(0), f:ld(SCAND + 7):gt(3), f:ld(SCAND + 8):lt(0), f:ld(SCAND + 8):gt(1)),
      function() f:ret(0) end)
    f:ret(1)
  end)

  -- Exact packed vector identity, retained in a bounded 32-entry circular
  -- archive. Scores are never reused across different states or versions.
  P:func("cand_novel", {}, function(f)
    local h, i = f:var("h", 0), f:var("i")
    for k = 0, 8 do f:set(h, (h << 5) | f:ld(SCAND + k)) end
    f:for_(i, 0, 32, function()
      f:iff(GL.and_(f:ld(SEENV + i):eq(f:ld(PARV)), f:ld(SEEN + i):eq(h)), function() f:ret(0) end)
    end)
    f:set(i, f:ld(TNEXT) & 31)
    f:st(SEEN + i, h); f:st(SEENV + i, f:ld(PARV))
    f:ret(1)
  end)

  P:func("sim_snapshot", {}, function(f)
    f:run("copy_model", QP, FLP, BASEQ, BASEFL)
    for k = 0, 8 do f:st(BASEPAR + k, f:ld(PAR + k)) end
    local t = f:var("t")
    for i = 0, N - 1 do
      f:set(t, f:ld(X.THAT + i))
      f:iff(t:lt(0), function() f:set(t, 0) end)
      f:set(t, t >> 2)
      f:iff(t:gt(9), function() f:set(t, 9) end)
      f:st(BASET + i, t)
    end
    f:st(BTIME, f:ld(X.QPT)); f:st(BRATE, f:ld(GEXP)); f:st(BVER, f:ld(PARV))
    f:st(TWORK, 0)
  end)

  -- ----------------------------------------------------------- bounded rollout (candidate interpreter)
  P:func("sim_begin", {}, function(f)
    f:run("copy_model", BASEQ, BASEFL, SIMQ, SIMFL)
    for i = 0, N - 1 do f:st(SIMT + i, f:ld(BASET + i) << 2); f:st(SIMPOW + i, 0) end
    f:st(SIMTERM, 0); f:st(SIMI, 0); f:st(SIMPHASE, 0)
  end)

  -- one synthetic step with the parameter table at `par` (kernel + capped assignment + fluid step)
  P:func("sim_step", {"par"}, function(f, par)
    local q, cost, cnt, cap = f:var("q"), f:var("cost"), f:var("cnt", 0), f:var("cap", f:ld(par + 6))
    local i, c, rank = f:var("i"), f:var("c"), f:var("rank")
    f:iff(f:ld(SIMPHASE):eq(0), function()
      if cfg.tune_thermal then
        -- A conditional model, never a safety bound: diffuse OLD temperatures
        -- and distinguish single-channel heating from diagonal cooling.
        f:iff(f:ld(SIMI):gt(0), function()
          for k = 0, N - 1 do
            f:set(q, (f:ld(SIMT + k) * 4 + f:ld(SIMT + (k - 1) % N) + f:ld(SIMT + (k + 1) % N)) // 6 - 1)
            f:set(cost, f:ld(SIMPOW + k))
            f:iff(cost:eq(1), function() f:set(q, q + 4) end)
            f:iff(cost:eq(2), function() f:set(q, q - 1) end)
            f:iff(q:lt(0), function() f:set(q, 0) end)
            f:iff(q:gt(63), function() f:set(q, 63) end)
            f:st(SIMTN + k, q)
          end
          for k = 0, N - 1 do f:st(SIMT + k, f:ld(SIMTN + k)) end
        end)
      end
      f:for_(i, 0, N, function()
        f:set(q, f:ld(SIMQ + i) >> 5)
        f:iff(q:gt(31), function() f:set(q, 31) end)
        f:st(QB + i, q)
        f:set(q, f:ld(SIMT + i) >> 2)
        f:iff(q:gt(9), function() f:set(q, 9) end)
        f:st(TB + i, q)
      end)
      f:run("kernel_generic", par)
      f:run("priority_context", par)
      for k = 0, N - 1 do f:st(SIMDS + k, f:ld(DS + k)) end
      f:st(SIMPHASE, 1); f:ret(0)
    end)
    -- Foreground work may overwrite DS/POWV between these two slices.
    -- Restore retained synthetic decisions before completing the model step.
    for k = 0, N - 1 do f:st(DS + k, f:ld(SIMDS + k)); f:st(POWV + k, 0) end
    -- The quantisation temporary is now free; reuse it for the packed
    -- assignment order instead of spilling an eighth live local.
    f:set(q, (f:ld(par + 7) << 6) | (((f:ld(BTIME) + f:ld(SIMI)) & 3) << 4))
    f:for_(c, 0, 3, function()
      f:for_(rank, 0, N, function()
        f:set(i, f:ld(X.ORDER + q + rank))
        f:iff((f:ld(DS + i) >> 2):eq(3 - c), function()
          f:set(cost, 2)
          f:iff((f:ld(DS + i) & 3):eq(1), function() f:set(cost, 1) end)
          f:iff((cnt + cost):le(cap), function() f:set(cnt, cnt + cost); f:st(POWV + i, cost) end)
        end)
      end)
    end)
    for k = 0, 3 do f:st(SRCV + k, f:ld(BRATE)) end
    f:run("mstep", SIMQ, SIMFL, f:ld(BTIME) + f:ld(SIMI), SIMTERM)
    for k = 0, N - 1 do f:st(SIMPOW + k, f:ld(POWV + k)) end
    f:st(SIMI, f:ld(SIMI) + 1)
    f:st(SIMPHASE, 0); f:ret(1)
  end)

  -- ----------------------------------------------------------- scheduler slice + selector
  P:func("tune_slice", {"j"}, function(f, j)
    local st, k, n = f:var("st", f:ld(TST)), f:var("k"), f:var("n")
    local w0 = f:var("w0", f:clk(4))
    f:iff(st:eq(0), function()
      f:iff(f:ld(TREC + 0):ge(cfg.tune_max_evals), function() f:ret(0) end)
      f:iff(j:ge(cfg.tune_last_start), function() f:ret(0) end)
      f:set(n, f:ld(TNEXT)); f:st(TNEXT, n + 1)
      f:iff((n % 3):eq(0), function()
        f:set(k, f:call("cand_structure", n // 3)); f:st(TREC + 11, f:ld(TREC + 11) + 1)
      end, function()
        f:iff((n % 3):eq(1), function()
          f:set(k, f:call("cand_local", (n // 3) % 10)); f:st(TREC + 4, f:ld(TREC + 4) + 1)
        end, function()
          f:set(k, f:call("cand_enum", f:ld(TENUM) % 108)); f:st(TENUM, f:ld(TENUM) + 1)
          f:st(TREC + 3, f:ld(TREC + 3) + 1)
        end)
      end)
      f:iff(k:eq(0), function() f:st(TREC + 5, f:ld(TREC + 5) + 1); f:ret(0) end)
      f:iff(f:call("cand_novel"):eq(0), function() f:st(TREC + 9, f:ld(TREC + 9) + 1); f:ret(0) end)
      f:run("sim_snapshot"); f:st(TST, 1); f:run("sim_begin")
      f:st(THORIZON, H); f:st(TVERIFY, 0)
      f:st(TWORK, f:clk(4) - w0)
      f:ret(1)
    end)
    f:iff(f:ld(BVER):ne(f:ld(PARV)), function()
      f:st(TREC + 10, f:ld(TREC + 10) + 1); f:st(TST, 0); f:ret(1)
    end)
    -- run SIM_STEPS rollout steps of whatever is under evaluation
    f:set(k, 0)
    f:while_(GL.and_(k:lt(cfg.tune_steps_per_window), f:ld(SIMI):lt(f:ld(THORIZON))), function()
      f:iff(st:eq(1), function() f:run("sim_step", BASEPAR) end, function() f:run("sim_step", SCAND) end)
      f:iff(f:ld(SIMPHASE):eq(0), function() f:st(TREC + 6, f:ld(TREC + 6) + 1) end)
      f:set(k, k + 1)
    end)
    f:iff(f:ld(SIMI):ge(f:ld(THORIZON)), function()
      f:iff(st:eq(1), function()
        f:st(INCSC, f:ld(SIMTERM)); f:st(TREC + 8, f:ld(SIMTERM))
        f:st(TST, 2); f:run("sim_begin")
      end, function()
        -- Race cheaply, then validate promising changes over a longer horizon
        -- from the SAME frozen snapshot. A bounded number of extended races
        -- prevents model search from consuming the acting reserve.
        f:iff(GL.and_(f:ld(TVERIFY):eq(0),
                      (f:ld(SIMTERM) * 1024):gt(f:ld(INCSC) * (1024 + cfg.tune_margin))), function()
          f:iff(f:ld(TREC + 14):lt(cfg.tune_max_validations), function()
            f:st(TREC + 14, f:ld(TREC + 14) + 1)
            f:st(TVERIFY, 1); f:st(THORIZON, cfg.tune_verify_horizon)
            f:st(TST, 1); f:run("sim_begin")
            f:st(TWORK, f:ld(TWORK) + f:clk(4) - w0); f:ret(1)
          end, function()
            -- Exhausted validation credit: retain the validated incumbent.
            f:st(TVERIFY, 2)
          end)
        end)
        f:st(TREC + 0, f:ld(TREC + 0) + 1)
        f:st(TREC + 13, f:ld(TREC + 13) + f:ld(TWORK) + f:clk(4) - w0)
        f:st(CSC, f:ld(SIMTERM)); f:st(TREC + 7, f:ld(SIMTERM))
        -- selector: strictly better by the margin (parts per 1024)
        f:iff(GL.and_(f:ld(TVERIFY):eq(1), (f:ld(SIMTERM) * 1024):gt(f:ld(INCSC) * (1024 + cfg.tune_margin))), function()
          for q = 0, 8 do f:st(PAR + q, f:ld(SCAND + q)) end
          f:st(TREC + 12, f:ld(TREC + 12) + f:ld(SIMTERM) - f:ld(INCSC))
          f:st(INCSC, f:ld(SIMTERM)); f:st(TREC + 8, f:ld(SIMTERM))
          f:st(TREC + 1, f:ld(TREC + 1) + 1)
          if cfg.pkg then f:run("pkg_invalidate") else f:st(PARV, f:ld(PARV) + 1) end
        end, function()
          f:st(TREC + 2, f:ld(TREC + 2) + 1)
          f:iff(f:ld(TVERIFY):ne(0), function() f:st(TREC + 15, f:ld(TREC + 15) + 1) end)
        end)
        f:st(TST, 0)
      end)
    end)
    f:st(TWORK, f:ld(TWORK) + f:clk(4) - w0)
    f:ret(1)
  end)
end

--[[@@END@@]]
return Tune
end

-- ======================================================================== asi.guest.ledger  (asi/guest/ledger.lua)
package.preload["asi.guest.ledger"] = function(...)
--[============[
asi/guest/ledger.lua -- global risk ledger and timing evidence (guest code).

LEDGER  r0 <= Delta - eta - alpha - eps_contract   (equation B), all terms in units of 2^-40 (exact integers).
  Delta          2^-20 (the promised global failure limit, a CONSTANT of the task: 2^20 units)
  eta            initial coverage failure: 0 - the envelope is the PUBLIC SUPPORT of the parameters plus
                 worst-case bounds over every noise path; the controller never relies on a fitted model
                 for safety (the benchmark laws themselves are the trusted boundary)
  alpha_used     sum of the allocations of the (node, hypothesis) test identifiers actually examined:
                 n_ids * 2^-31 = n_ids * 2^9 units, with n_ids <= 80 so alpha_used <= 80*2^-31 < 2^-24
  eps_contract   pathwise contract error: 0 - installed packages are proved EXACTLY equivalent to the
                 resident kernel (eps_u = eps_d = eps_l = 0) and the shield gates every dispatch, so
                 neither a changed parameter nor a package can change the failure bound
  reserve        Delta - eta - alpha_used - eps_contract; r0 may be at most this; a NEGATIVE reserve makes the
                 certification route infeasible and latches INFEASIBLE (the controller then only dispatches
                 STOP, which the STOP invariant certifies)
STOPPED-LEDGER STEP (Q). With r_i = r0 constant and the shield invariant, a segment's first-failure
  probability is exactly 0 on the covered event, so E[1_F + 1_S r'] = r0 <= r0 + 0: (Q) holds with eps_i = 0.
  The bound is therefore Pr(D_N) <= r0 + eps_bar + eta + alpha = r0 + alpha_used... with r0 = 0 the
  guaranteed bound is alpha_used <= Delta - reserve; this is reported, not weakened.
TIMING EVIDENCE. The dispatch guard is that SUBMIT completes at or before (k+1)*Delta - 1; the controller
  records the maximum tick-in-window at which its submission completed (MAXSUB) and the maximum processor
  work used by one window (MAXWIN), measured on the metered machine.
]============]

local Ledger = {}

Ledger.UNIT_LOG2 = -40          -- all ledger terms are integer multiples of 2^-40
Ledger.DELTA_UNITS = 1 << 20    -- 2^-20 = 2^20 units
Ledger.ID_UNITS = 1 << 9        -- 2^-31 = 2^9 units per examined identifier

function Ledger.install(X)
  local P, cfg, N = X.P, X.cfg, X.N
  local BLO, BCNT = X.BLO, X.BCNT
  local LEDG = P:static("LEDG", 16)          -- [0]Delta [1]eta [2]alpha_used [3]eps [4]reserve [5]feasible [6]n_ids [7]envv
                                             -- [8]MAXSUB [9]MAXWIN [10]gate_downgrades [11]stop_all [12]version of computation
  local INFEAS = P:static("INFEAS", 1)
  X.LEDG, X.INFEAS = LEDG, INFEAS

  P:func("ledger_compute", {}, function(f)
    local n, i, c, b = f:var("n", 0), f:var("i"), f:var("c"), f:var("b")
    -- identifiers examined: hypotheses -2..BLO_i for node i, never beyond 1 (H_2 is not testable)
    f:for_(i, 0, N, function()
      f:set(b, f:ld(BLO + i) + 3)
      f:iff(b:gt(4), function() f:set(b, 4) end)
      f:iff(f:ld(BCNT + i):eq(0), function() f:set(b, 0) end)             -- no evidence was ever used for this node: no test examined
      f:set(n, n + b)
    end)
    local delta = cfg.delta_units or Ledger.DELTA_UNITS      -- the task's Delta; a smaller value is a TEST mutation only
    f:st(LEDG + 0, delta)
    f:st(LEDG + 1, 0)
    f:st(LEDG + 2, n * Ledger.ID_UNITS)
    f:st(LEDG + 3, 0)
    f:st(LEDG + 4, delta - 0 - n * Ledger.ID_UNITS - 0)
    f:st(LEDG + 5, 1)
    f:iff(f:ld(LEDG + 4):lt(0), function() f:st(LEDG + 5, 0); f:st(INFEAS, 1) end)
    f:st(LEDG + 6, n)
    f:st(LEDG + 7, f:ld(X.ENVV))
    f:st(LEDG + 10, f:ld(X.STAT + X.STATI.down))
    f:st(LEDG + 11, f:ld(X.STAT + X.STATI.stop_all))
    f:st(LEDG + 12, f:ld(X.PARV))
  end)
end

--[[@@END@@]]
return Ledger
end

-- ======================================================================== asi.guest.ctrl  (asi/guest/ctrl.lua)
package.preload["asi.guest.ctrl"] = function(...)
--[============[
asi/guest/ctrl.lua -- controller image builder (guest program, compiled to VM-1 words).

STAGE 1 CONTENTS (resident incumbent + reserved STOP fallback)
  sense      one paid SENSE per window, bit-field decode of the 512-bit packet
  load       exact-structure HMM filter of the hidden common load g from the observed arrival bits
  shield     SOUND worst-case thermal upper bounds U_i >= T_i (initial state exact; public-support
             parameters gamma<=4, eta>=3, xi<=1, g<=1; sensor bound U <= 2Y-2*bias_lo+9 allowing
             fault and noise). A command is dispatched only if the worst-case bound after the step in
             which it can first apply stays <= 47; otherwise it is downgraded node by node, and a
             global STOP (always safe: STOP cannot raise a maximum) replaces it if needed.
  submit     one paid SUBMIT per window (deadline: completion <= (k+1)*Delta - 1)
  forecast   one paid FORECAST per scored window: arrival probability from the load filter and
             thermal probability 0 whenever the sound bound says the event is impossible
  schedule   idle until the next window start; the world, not the processor, owns time

SHIELD INVARIANT (proved in asi/guest/NOTES (comment below) and attacked by tests):
  I(b): for every node i, T_{i,b} <= UH_i[b] <= 47 at boundary b.
  A command for boundary j+1 may first heat step j+1 (lambda=0); older pipelined commands may also
  apply (lambda 1,2): the heat bound of step s is max(inc(u(s)),inc(u(s-1)),inc(u(s-2))) with
  inc(a1,a2) = (gamma_max+g_max)*max(a1,a2) - eta_min*min(a1,a2) - 1 + xi_max, i.e. 5*max - 3*min.
  Orientation (hidden, state dependent, structural change) only permutes (p,c) and is covered by the
  max/min; delay lambda is covered by the three-command window; energy rejection / STOP only remove heat.
  Hence T_{b+1,i} <= floor((4U_i+U_{i-1}+U_{i+1})/6) + heat <= UH_i[b+1] by monotonicity, and the gate
  keeps UH[b+1] <= 47 < 48. The argument holds for every parameter realisation in the public support
  and every noise path, so its failure probability is exactly zero under the stated laws.
]============]
local ISA = require("asi.isa")
local NetEnv = require("asi.netenv")
local GL = require("asi.gl")
local VM = require("asi.vm")
local S = require("asi.spec")
local RT = require("asi.guest.rt")

local Ctrl = {}
local DELTA, N = S.DELTA, 16
Ctrl.MACHINE = ISA.build(NetEnv.ops)

local function cfg_default()
  return {
    shield = true,          -- keep the gate on (turning it off is only for adversarial tests)
    policy = "fluid",     -- the full controller; stub policies (stop, diag_all, diag_sources, p_only) are baselines / adversaries
    forecast = true,
    bias_lo = -2,           -- public-support lower bound of the temperature bias
    gamma_max = 4, eta_min = 3, fail_temp = 48,
    forecast_from = 1023,   -- first window whose forecast target is scored (target = j+1 >= 1024)
    ident_start = 8, ident_round_gap = 100, plan_from = 300,
    cap = 6, thresholds = {160, 96, 48}, succ = 184, cap_energy = 12, q_diag = 768,
    tune = true, tune_thermal = false, tune_from = 620, tune_last_start = 2000, tune_horizon = 12, tune_verify_horizon = 24,
    tune_max_validations = 4, tune_steps_per_window = 1, tune_max_evals = 16, tune_margin = 20,
    pkg = true, pkg_from = 1400, pkg_last_start = 3600, pkg_equiv_per_slice = 1, pkg_hash_words = 40, pkg_horizon = 5120, pkg_margin = 0,
    pkg_max_rejects = 3, pkg_max_emits = 8, pkg_emit_nodes = 1, pkg_static_words = 25,
    rollout = false,        -- tentative belief rollouts to the landing step of delayed commands (costly; see profile)
    cheap_landing = true,   -- bounded local lookahead for identified two-step actuator delays; false is the ablation
    public = true,          -- embed + parse + verify the public contract bytes (charged)
    prep_check = 1030, slice_reserve = 400, est_learn_read = 2900, est_learn_rec = 2900, est_learn_dec = 2100, est_tune = 2200, est_pkg = 1800,
    audit = true, audit_from = 230, audit_rounds = 5, audit_margin = 3, audit_flip = 3,
    oracle_ori = nil,       -- EXPERIMENT ONLY: table of true b_i injected as the orientation estimate
    bias = true, learn_from = 130, learn_episodes = 90,
    t_p_only = 19, t_diag = 27,    -- governor: estimated temperature limits (T_hat < 4*(limit//4)+4) for single-channel / diagonal powering
    reason = false,             -- experimental shared model induction over a coarse native macro adapter
    reason_from = 512, reason_select = true,
    reason_est_observe = 2100, reason_est_search = 4600, reason_est_select = 1600,
