function Ctrl.build(user_cfg)
  local cfg = cfg_default()
  for k, v in pairs(user_cfg or {}) do cfg[k] = v end
  if cfg.reason then
    assert(cfg.policy == "fluid" and cfg.public, "native reason profile requires fluid adapter and verified public contract")
    -- This declared experimental profile trades optional statistical tightening
    -- and equivalent-kernel tuning/compilation for resident model induction.
    -- The public-support shield, contract parser and exact risk ledger remain.
