  local THAT = P:static("THAT", 16)           -- governor temperature estimate 2*(Y - bias_lo) + 1 (heuristic, not a bound)
  local H2 = P:static("H2", 16)            -- max heat bound of the two already-requested commands that still apply
  local INC = P:static("INC", 64)          -- ring[4][16]: heat bound of the command requested for boundary b
  local HEAT = P:static("HEAT", 64)        -- ring[4][16]: heat bound applying at step b (max of last three)
