  local BH = P:static("BH", 1)             -- boundary at which UH is valid
  local LASTKP = P:static("LASTKP", 1)     -- last packet step index processed (-1 none)
  local G1 = P:static("G1", 1)             -- P(g=1) after last observed packet, scaled 2^16
  local PK = P:static("PK", 8)             -- decoded scalar fields: [0]step [1]arr [2]mode [3]energy [4]rej [5]comp [6]fail
  local LTAB = P:rodata("LTAB", {20736, 6912, 2304, 768, 256})   -- 3^(4-m)*256 : P(arrivals=m | g=0) * 2^16 (per-pattern)

  -- certified bias envelope (archive evidence, e-process); installs BLO, build_tables, learn_slice
