               reset_bounds = 7, max_U = 8, forecasts = 9}
  local function stat_inc(f, i) f:st(STAT + i, f:ld(STAT + i) + 1) end

  -- ------------------------------------------------------------------ decode
  P:func("decode", {}, function(f)
    local O = RT.OFF
    f:st(PK + 0, RT.field(f, PKT, O.physical_step.off, 32))
    f:st(PK + 1, RT.field(f, PKT, O.source_arrivals.off, 4))
    f:st(PK + 2, RT.field(f, PKT, O.mode_stop.off, 1))
    f:st(PK + 3, RT.field(f, PKT, O.energy_after_service_demand.off, 7))
    f:st(PK + 4, RT.field(f, PKT, O.energy_rejection.off, 1))
    f:st(PK + 5, RT.field(f, PKT, O.on_time_terminal_completions.off, 3))
    f:st(PK + 6, RT.field(f, PKT, O.failure_flag.off, 1))
