      f:st(YQ + i, RT.field(f, PKT, O.occupancy_measurements.off + 4 * i, 4))
      f:st(YT + i, RT.field(f, PKT, O.temperature_measurements.off + 5 * i, 5))
    end
  end)

  -- ------------------------------------------------------------------ bound propagation
  -- dst = min(63, floor((4*src_i + src_{i-1} + src_{i+1})/6) + heat_i), all neighbours OLD values
  P:func("prop", {"src", "dst", "hb"}, function(f, src, dst, hb)
    local t = f:var("t")
    for i = 0, N - 1 do
      f:set(t, (f:ld(src + i) * 4 + f:ld(src + (i - 1) % N) + f:ld(src + (i + 1) % N)) // 6 + f:ld(hb + i))
      f:iff(t:gt(63), function() f:set(t, 63) end)
      f:st(dst + i, t)
    end
  end)

  P:func("copy16", {"src", "dst"}, function(f, src, dst)
    for i = 0, N - 1 do f:st(dst + i, f:ld(src + i)) end
  end)

