      f:iff(u:lt(f:ld(UH + i)), function() f:st(UH + i, u) end)
    end
  end)

  -- commit the heat bound of the command finally requested for boundary b (triples in FIN)
  P:func("commit_heat", {"b"}, function(f, b)
    local s0, s1, s2 = f:var("s0"), f:var("s1"), f:var("s2")
    local inc = f:var("inc")
    f:set(s0, (b & 3) << 4); f:set(s1, ((b - 1) & 3) << 4); f:set(s2, ((b - 2) & 3) << 4)
