  env.stats_addr = sym.R_STATS
  local t0 = os.clock()
  local reason = vm:run(opt.max_instr)
  local vm_cpu = os.clock() - t0
  local out = env:result({oracle = opt.oracle ~= false})
  out.host_cpu = vm_cpu
  out.evaluator_cpu = os.clock() - t0 - vm_cpu
  out.reason, out.fault = reason, vm.fault
  out.work = vm.budget - vm.work_left; out.instructions = vm.instr_count
  out.image_bits, out.image_hash = bits, vm.image_hash
  out.ram_high_water = vm:peak_ram_words(); out.peak_bits = vm:peak_bits()
  out.interface_work, out.interface_ops = vm.work_iface, vm.iface_count
  out.world_trace_hash, out.vm_trace_hash = out.trace_hash, vm:trace_hash()
  out.protocol_hash = M.PROTOCOL_HASH
  out.trace_hash = U.sha256(out.image_hash .. ":" .. M.PROTOCOL_HASH .. ":" .. out.world_trace_hash .. ":" .. out.vm_trace_hash)
  out.guard = vm.ram[sym.RS_GUARD - VM.RAM_BASE]
  out.stats = {}
  local st = R.STATS.name or R.STATS.n and R.STATS.n.name
  -- Symbol naming belongs to the core; resolve its declaration rather than
  -- inspecting evaluator-private world state to construct a prediction.
  local stats_addr = st and sym[st] or sym.R_STATS
  if stats_addr then for i = 0, 31 do out.stats[i] = vm.ram[stats_addr - VM.RAM_BASE + i] end end
  return out, env, vm, {words = words, sym = sym, P = P, R = R, bits = bits, cfg = cfg, machine = machine}
end
function M.artifact(cfg)
  local words, sym, P, R, bits, c, machine = M.build(cfg)
  return {words = words, sym = sym, P = P, R = R, bits = bits, cfg = c, machine = machine}
end
return M
end

-- ======================================================================== asi.reason.core  (shared metered predictive program induction)
package.preload["asi.tests.t_reason_core"] = function(...)
