  surprise.wr("EID", 0, 3); surprise.wr("OBS", 0, 1); surprise.call("r_observe")
  T.eq(surprise.rd("OMIN"), 1, "source episode change resets the diagnostic even without a repeated reset marker")
  T.eq(surprise.rd("OMAX"), 1, "source episode change starts a fresh real range")
  local _, scale_cost = surprise.call("r_scale", 0)
