end

package.preload["asi.reason.core"] = function(...)
local GL = require("asi.gl")
local Core = {}

-- The host only emits this interpreter and its bounded searches. Candidate
-- terms, signatures, fitting, future validation and installation execute VM-1.
-- Values are integers modulo eight; predicates have a checked subtype. This
-- finite language and empirical validation are not a coverage certificate.
function Core.install(P, cfg)
  cfg = cfg or {}
  local NT, RC = cfg.term_cap or 64, cfg.ring_cap or 16
  assert(NT >= 16 and NT <= 64 and RC >= 4 and RC <= 16, "reason core bounds")
  local BASE, LIMIT = 14, cfg.max_complexity or 9
  local R = {term_cap = NT, ring_cap = RC, terminal_count = BASE}
  local function mem(name, size) local x = P:static("R_" .. name, size or 1); R[name] = x; return x end
  for _, name in ipairs({"OBS", "PREV", "LAG", "MAX", "GOAL"}) do mem(name, 4) end
  for _, name in ipairs({"NF", "NA", "SAFE", "VALID", "EID", "VER", "UNC", "ACT", "REWARD", "EVENT", "RESET", "KNOWN", "PVALID",
                         "MODELKNOWN", "ACCEPT", "COUNT", "RCNT", "RPTR", "HAVE", "LASTEVENT", "LASTEID", "NEXT", "GEN", "SOP"}) do mem(name) end
  mem("STATS", 32); mem("ROOT", 8); mem("PREVROOT", 4); mem("MEMROOT", 4); mem("PRED", 4)
  for _, name in ipairs({"CODE", "CHECKED", "TYPE", "COST", "BORN", "EPOCH", "USE", "VALS", "MAP", "MASK0", "MASK1"}) do mem(name, NT) end
  mem("SIG", NT * RC); mem("OUT", 4 * RC); mem("RID", RC); mem("REID", RC); mem("RACT", RC)
  for _, name in ipairs({"MODE", "PT", "PL", "IL", "AMASK", "PBORN", "LOSS", "FAIL", "ACOUNTS", "TRANSFER"}) do mem(name, 4) end
  mem("OPWORK", 12); mem("OPGAIN", 12); mem("OPN", 12)
  -- Real observed extrema diagnose residual scale; they never restrict valid
  -- endpoint values or certify coverage. The legacy profile emits no addition.
  if not cfg.legacy_scale then mem("OMIN", 4); mem("OMAX", 4); mem("PSCALE", 4) end
  -- STATS 0 observations,1 transitions,2 proposals,3 rejected/duplicates,
  -- 4 installs,5 anomalies,6 rollbacks,7 constructed terms,8 search work,
  -- 9 future tests,10 failed validations,11 transferred-model validations,
  -- 12 adaptive operator choices,13 forgotten terms,14 bad provenance/data,
  -- 15 maximum search work. The planner owns 16..31.
  local function inc(f, k, d) f:st(R.STATS + k, f:ld(R.STATS + k) + (d or 1)) end
  local function code(op, a, b, c) return op | ((a or 0) << 5) | ((b or 0) << 11) | ((c or 0) << 17) end

  if not cfg.legacy_scale then
    P:func("r_scale", {"field"}, function(f, field)
      f:iff(GL.or_(field:lt(0), field:ge(f:ld(R.NF))), function() f:ret(1) end)
      local cap = f:var("cap", f:ld(R.MAX + field) * f:ld(R.MAX + field))
      f:iff(cap:lt(1), function() f:set(cap, 1) end)
      f:iff(GL.or_(f:ld(R.OMIN + field):lt(0), f:ld(R.OMAX + field):lt(0)), function() f:ret(cap) end)
      local s = f:var("s", f:ld(R.OMAX + field) - f:ld(R.OMIN + field))
      f:set(s, s * s)
      f:iff(s:gt(cap), function() f:set(s, cap) end); f:iff(s:lt(1), function() f:set(s, 1) end)
      f:ret(s)
    end)
    P:func("r_range", {"field", "value"}, function(f, field, value)
      f:iff(GL.or_(field:lt(0), field:ge(f:ld(R.NF)), value:lt(0), value:gt(f:ld(R.MAX + field))), function() f:ret(0) end)
      f:iff(GL.or_(f:ld(R.OMIN + field):lt(0), value:lt(f:ld(R.OMIN + field))), function() f:st(R.OMIN + field, value) end)
      f:iff(GL.or_(f:ld(R.OMAX + field):lt(0), value:gt(f:ld(R.OMAX + field))), function() f:st(R.OMAX + field, value) end)
      f:ret(1)
    end)
  end

  P:func("r_check", {"w", "n"}, function(f, w, n)
    local op, a, b, c = f:var("op", w & 31), f:var("a", (w >> 5) & 63), f:var("b", (w >> 11) & 63), f:var("c", (w >> 17) & 63)
    f:iff(GL.or_(n:lt(0), n:ge(NT), (w >> 23):ne(0), op:gt(15)), function() f:ret(0) end)
    f:iff(op:lt(4), function()
      f:iff(GL.or_(b:ne(0), c:ne(0)), function() f:ret(0) end)
      f:iff(GL.or_(op:eq(0), op:eq(3)), function() f:iff(a:ge(4), function() f:ret(0) end); f:ret(1) end)
      f:iff(op:eq(1), function() f:iff(a:gt(7), function() f:ret(0) end); f:iff(a:le(1), function() f:ret(2) end); f:ret(1) end)
      f:iff(a:ne(0), function() f:ret(0) end); f:ret(1)
    end)
    f:iff(GL.or_(a:ge(n), b:ge(n), f:ld(R.TYPE + a):eq(0), f:ld(R.TYPE + b):eq(0)), function() f:ret(0) end)
    f:iff(op:eq(13), function()
      f:iff(GL.or_(c:ge(n), f:ld(R.TYPE + c):eq(0), f:ld(R.TYPE + a):ne(2)), function() f:ret(0) end)
      f:iff(GL.and_(f:ld(R.TYPE + b):eq(2), f:ld(R.TYPE + c):eq(2)), function() f:ret(2) end); f:ret(1)
    end)
    f:iff(c:ne(0), function() f:ret(0) end)
    f:iff(GL.or_(op:eq(8), op:eq(9)), function() f:ret(2) end)
    f:ret(1)
  end)

  P:func("r_apply", {"op", "x", "y", "z"}, function(f, op, x, y, z)
    f:iff(op:eq(13), function()
      f:iff(x:lt(0), function() f:ret(-1) end)
      f:iff(x:ne(0), function() f:ret(y) end); f:ret(z)
    end)
    f:iff(GL.or_(x:lt(0), y:lt(0)), function() f:ret(-1) end)
    f:iff(op:eq(4), function() f:ret((x + y) & 7) end)
    f:iff(op:eq(5), function() f:ret((x - y) & 7) end)
    f:iff(op:eq(6), function() f:ret(x ~ y) end)
    f:iff(op:eq(7), function() f:ret(x & y) end)
    f:iff(op:eq(8), function() f:ret(x:eq(y)) end)
    f:iff(op:eq(9), function() f:ret(x:lt(y)) end)
    f:iff(op:eq(10), function() f:iff(x:lt(y), function() f:ret(x) end); f:ret(y) end)
    f:iff(op:eq(11), function() f:iff(x:gt(y), function() f:ret(x) end); f:ret(y) end)
    f:iff(op:eq(12), function() f:ret((x + y) // 2) end)
    f:iff(op:eq(14), function() f:iff((x + y):gt(7), function() f:ret(7) end); f:ret(x + y) end)
    f:iff(op:eq(15), function() f:iff(x:lt(y), function() f:ret(0) end); f:ret(x - y) end)
    f:ret(-1)
  end)

  P:func("r_eval_mask", {"raw", "lag", "act", "mask"}, function(f, raw, lag, act, mask)
    local n, w, op, a, v = f:var("n"), f:var("w"), f:var("op"), f:var("a"), f:var("v")
    f:for_(n, 0, NT, function()
      f:iff(n:lt(f:ld(R.COUNT)), function()
        f:iff(GL.or_(mask:lt(0), f:ld(mask + n):ne(0)), function()
          f:set(w, f:ld(R.CODE + n)); f:set(op, w & 31); f:set(a, (w >> 5) & 63); f:set(v, -1)
          f:iff(w:eq(f:ld(R.CHECKED + n)), function()
            f:iff(op:eq(0), function() f:iff(a:lt(f:ld(R.NF)), function() f:set(v, f:ld(raw + a)) end) end)
            f:iff(op:eq(1), function() f:set(v, a) end)
            f:iff(op:eq(2), function() f:iff(act:ltu(f:ld(R.NA)), function() f:set(v, act) end) end)
            if not cfg.no_repr then
              f:iff(op:eq(3), function() f:iff(a:lt(f:ld(R.NF)), function() f:set(v, f:ld(lag + a)) end) end)
            end
            f:iff(op:ge(4), function()
              f:set(v, f:call("r_apply", op, f:ld(R.VALS + a), f:ld(R.VALS + ((w >> 11) & 63)), f:ld(R.VALS + ((w >> 17) & 63))))
            end)
          end)
          f:iff(GL.or_(v:lt(-1), v:gt(7)), function() f:set(v, -1) end)
          f:st(R.VALS + n, v)
        end)
      end)
    end)
  end)
  P:func("r_eval", {"raw", "lag", "act"}, function(f, raw, lag, act) f:run("r_eval_mask", raw, lag, act, -1) end)

  P:func("r_refresh", {}, function(f)
    local n, w, a = f:var("n"), f:var("w"), f:var("a")
    f:for_(n, 0, NT, function() f:st(R.MASK0 + n, 0); f:st(R.MASK1 + n, 0) end)
    for i = 0, 3 do
      f:set(a, f:ld(R.ROOT + 2 * i)); f:iff(a:ge(0), function() f:st(R.MASK0 + a, 1) end)
      f:iff(f:ld(R.ROOT + 2 * i + 1):ge(0), function() f:set(a, f:ld(R.ROOT + 2 * i + 1)) end)
      f:iff(a:ge(0), function() f:st(R.MASK1 + a, 1) end)
    end
    f:set(n, f:ld(R.COUNT) - 1)
    f:while_(n:ge(BASE), function()
      f:set(w, f:ld(R.CODE + n))
      for _, m in ipairs({R.MASK0, R.MASK1}) do
        f:iff(f:ld(m + n):ne(0), function()
          f:iff((w & 31):ge(4), function()
            f:st(m + ((w >> 5) & 63), 1); f:st(m + ((w >> 11) & 63), 1)
            f:iff((w & 31):eq(13), function() f:st(m + ((w >> 17) & 63), 1) end)
          end)
        end)
      end
      f:set(n, n - 1)
    end)
  end)

  P:func("r_predict", {"raw", "lag", "act", "branch"}, function(f, raw, lag, act, branch)
    local root, v = f:var("root"), f:var("v")
    f:iff(branch:eq(0), function() f:run("r_eval_mask", raw, lag, act, R.MASK0) end,
      function() f:run("r_eval_mask", raw, lag, act, R.MASK1) end)
    f:st(R.PVALID, 0)
    for i = 0, 3 do
      f:set(v, -1)
      f:iff(GL.lift(i):lt(f:ld(R.NF)), function()
        f:set(root, f:ld(R.ROOT + 2 * i))
        if not cfg.no_models then
          f:iff(GL.and_(branch:ne(0), f:ld(R.ROOT + 2 * i + 1):ge(0)), function() f:set(root, f:ld(R.ROOT + 2 * i + 1)) end)
          f:iff(root:ge(0), function() f:set(v, f:ld(R.VALS + root)) end, function() f:set(v, f:ld(raw + i)) end)
        else f:set(v, f:ld(raw + i)) end
        f:iff(v:ge(0), function() f:set(v, v % (f:ld(R.MAX + i) + 1)); f:st(R.PVALID, f:ld(R.PVALID) | (1 << i)) end)
      end)
      f:st(R.PRED + i, v)
    end
  end)

  P:func("r_reward", {"base"}, function(f, base)
    local s, v, d = f:var("s", 0), f:var("v"), f:var("d")
    for i = 0, 3 do
      f:iff(GL.and_(GL.lift(i):lt(f:ld(R.NF)), f:ld(R.GOAL + i):ge(0)), function()
        f:set(v, f:ld(base + i))
        f:iff(v:ge(0), function()
          f:set(d, v - f:ld(R.GOAL + i)); f:iff(d:lt(0), function() f:set(d, -d) end)
          f:iff(d:eq(0), function() f:set(s, s + 8) end, function() f:iff(d:lt(7), function() f:set(s, s + 7 - d) end) end)
        end)
      end)
    end
    f:ret(s)
  end)

  P:func("r_prospect", {"field", "term"}, function(f, field, term)
    f:st(R.ROOT + field * 2 + 1, term); f:st(R.MODE + field, 1)
    f:st(R.PT + field, 0); f:st(R.PL + field, 0); f:st(R.IL + field, 0); f:st(R.AMASK + field, 0)
    f:st(R.PBORN + field, f:ld(R.EVENT))
    if not cfg.legacy_scale then f:st(R.PSCALE + field, f:call("r_scale", field)) end
    f:run("r_refresh")
    f:st(R.TRANSFER + field, 0)
  end)

  P:func("r_init", {}, function(f)
    f:st(R.COUNT, BASE); f:st(R.LASTEVENT, -1); f:st(R.LASTEID, -1); f:st(R.UNC, 1024)
    for i = 0, 3 do
      f:st(R.CODE + i, code(0, i)); f:st(R.CODE + 4 + i, code(3, i)); f:st(R.CODE + 8 + i, code(1, i))
      f:st(R.TYPE + i, 1); f:st(R.TYPE + 4 + i, 1); f:st(R.TYPE + 8 + i, i < 2 and 2 or 1)
      f:st(R.ROOT + 2 * i, -1); f:st(R.ROOT + 2 * i + 1, -1)
      f:st(R.PREVROOT + i, -1); f:st(R.MEMROOT + i, -1); f:st(R.LAG + i, -1)
      if not cfg.legacy_scale then f:st(R.OMIN + i, -1); f:st(R.OMAX + i, -1) end
    end
    f:st(R.CODE + 12, code(2)); f:st(R.TYPE + 12, 1)
    f:st(R.CODE + 13, code(1, 7)); f:st(R.TYPE + 13, 1)
    local i = f:var("i")
    f:for_(i, 0, BASE, function() f:st(R.CHECKED + i, f:ld(R.CODE + i)); f:st(R.COST + i, 1) end)
    f:run("r_refresh")
  end)

  P:func("r_fit", {"term", "field"}, function(f, term, field)
    local i, v, y, d, loss = f:var("i"), f:var("v"), f:var("y"), f:var("d"), f:var("loss", 0)
    f:for_(i, 0, f:ld(R.RCNT), function()
      f:set(y, f:ld(R.OUT + i * 4 + field))
      f:iff(y:ge(0), function()
        f:set(v, f:ld(R.SIG + term * RC + i)); f:set(d, 8)
        f:iff(v:ge(0), function() f:set(d, (v % (f:ld(R.MAX + field) + 1)) - y) end)
        f:set(loss, loss + d * d)
      end)
    end)
    f:ret(loss)
  end)

  P:func("r_observe", {}, function(f)
    local i, a, b, x, y, d, u = f:var("i"), f:var("a"), f:var("b"), f:var("x"), f:var("y"), f:var("d"), f:var("u", 32)
    f:st(R.ACCEPT, 0)
    f:iff(GL.or_(f:ld(R.VALID):eq(0), f:ld(R.EVENT):le(f:ld(R.LASTEVENT)), f:ld(R.NF):lt(1), f:ld(R.NF):gt(4), f:ld(R.NA):lt(1), f:ld(R.NA):gt(4)),
      function() inc(f, 14); f:ret(0) end)
    for k = 0, 3 do
      f:iff(GL.lift(k):lt(f:ld(R.NF)), function()
        f:iff(GL.or_(f:ld(R.MAX + k):lt(0), f:ld(R.MAX + k):gt(7), f:ld(R.OBS + k):lt(-1), f:ld(R.OBS + k):gt(f:ld(R.MAX + k))),
          function() inc(f, 14); f:ret(0) end)
      end)
    end
    inc(f, 0); f:st(R.ACCEPT, 1)
    f:iff(GL.or_(f:ld(R.RESET):ne(0), f:ld(R.EID):ne(f:ld(R.LASTEID)), f:ld(R.HAVE):eq(0), f:ld(R.EVENT):ne(f:ld(R.LASTEVENT) + 1)), function()
      f:st(R.RCNT, 0); f:st(R.RPTR, 0); f:st(R.MODELKNOWN, 0); f:st(R.UNC, 1024)
      f:st(R.VER, f:ld(R.VER) + 1)
      if cfg.no_memory then
        inc(f, 13, f:ld(R.COUNT) - BASE); f:st(R.COUNT, BASE)
      end
      for k = 0, 3 do
        f:st(R.PREVROOT + k, -1); f:st(R.ROOT + 2 * k, -1); f:st(R.ACOUNTS + k, 0); f:st(R.FAIL + k, 0); f:st(R.LOSS + k, 0)
        if not cfg.legacy_scale then
          f:st(R.OMIN + k, -1); f:st(R.OMAX + k, -1); f:run("r_range", k, f:ld(R.OBS + k))
        end
        if cfg.no_memory then f:st(R.MEMROOT + k, -1) end
        f:set(a, f:ld(R.MEMROOT + k)); f:iff(a:lt(0), function() f:set(a, k) end)
        if not cfg.no_models then
          f:run("r_prospect", k, a)
          f:iff(f:ld(R.MEMROOT + k):ge(0), function() f:st(R.TRANSFER + k, 1) end)
        end
        f:st(R.PREV + k, f:ld(R.OBS + k)); f:st(R.LAG + k, -1)
      end
      f:st(R.HAVE, 1); f:st(R.LASTEVENT, f:ld(R.EVENT)); f:st(R.LASTEID, f:ld(R.EID)); f:run("r_refresh"); f:ret(1)
    end)
    f:iff(f:ld(R.ACT):geu(f:ld(R.NA)), function() inc(f, 14); f:st(R.HAVE, 0); f:ret(0) end)
    f:run("r_eval", R.PREV, R.LAG, f:ld(R.ACT))
    f:set(i, f:ld(R.RPTR)); f:st(R.RID + i, f:ld(R.EVENT)); f:st(R.REID + i, f:ld(R.EID)); f:st(R.RACT + i, f:ld(R.ACT))
    f:st(R.ACOUNTS + f:ld(R.ACT), f:ld(R.ACOUNTS + f:ld(R.ACT)) + 1)
    f:for_(a, 0, f:ld(R.COUNT), function() f:st(R.SIG + a * RC + i, f:ld(R.VALS + a)) end)
    for k = 0, 3 do
      f:st(R.OUT + i * 4 + k, f:ld(R.OBS + k))
      if not cfg.no_models then
        f:iff(GL.and_(GL.lift(k):lt(f:ld(R.NF)), f:ld(R.OBS + k):ge(0)), function()
          f:set(y, f:ld(R.OBS + k)); f:set(a, f:ld(R.ROOT + 2 * k))
          f:iff(a:ge(0), function()
            f:set(x, f:ld(R.VALS + a)); f:set(d, 8); f:iff(x:ge(0), function() f:set(d, (x % (f:ld(R.MAX + k) + 1)) - y) end)
            f:set(d, d * d)
            if cfg.legacy_scale then f:set(x, f:ld(R.MAX + k) * f:ld(R.MAX + k)); f:iff(x:eq(0), function() f:set(x, 1) end)
            else f:set(x, f:call("r_scale", k)) end
            f:st(R.LOSS + k, (f:ld(R.LOSS + k) * 7 + (d * 1024) // x) // 8)
            local meaningful = cfg.legacy_scale and d:gt(4) or GL.or_(d:gt(4), (d * 4):gt(x))
            f:iff(GL.or_(meaningful, GL.and_(GL.or_(f:ld(R.MAX + k):le(1), f:ld(R.TYPE + a):eq(2)), d:gt(0))), function() f:st(R.FAIL + k, f:ld(R.FAIL + k) + 1) end,
              function() f:st(R.FAIL + k, 0) end)
            f:iff(f:ld(R.FAIL + k):ge(3), function()
              inc(f, 5); f:st(R.ROOT + 2 * k, f:ld(R.PREVROOT + k)); f:st(R.PREVROOT + k, -1)
              f:st(R.VER, f:ld(R.VER) + 1); f:st(R.FAIL + k, 0); f:st(R.LOSS + k, 256)
              f:iff(f:ld(R.ROOT + 2 * k):ge(0), function() inc(f, 6) end)
              f:run("r_prospect", k, a)
            end)
          end)
          -- Score against past evidence before a surprise expands the range.
          -- The new real outcome remains valid and is then available to fitting.
          if not cfg.legacy_scale then f:run("r_range", k, y) end
          f:set(b, f:ld(R.ROOT + 2 * k + 1))
          f:iff(GL.and_(b:ge(0), f:ld(R.MODE + k):eq(1), f:ld(R.EVENT):gt(f:ld(R.PBORN + k))), function()
            f:set(a, f:ld(R.ROOT + 2 * k)); f:iff(a:lt(0), function() f:set(a, k) end)
            f:set(x, f:ld(R.VALS + a)); f:set(d, 8); f:iff(x:ge(0), function() f:set(d, (x % (f:ld(R.MAX + k) + 1)) - y) end)
            f:st(R.IL + k, f:ld(R.IL + k) + d * d)
            f:set(x, f:ld(R.VALS + b)); f:set(d, 8); f:iff(x:ge(0), function() f:set(d, (x % (f:ld(R.MAX + k) + 1)) - y) end)
            f:st(R.PL + k, f:ld(R.PL + k) + d * d); f:st(R.PT + k, f:ld(R.PT + k) + 1)
            f:st(R.AMASK + k, f:ld(R.AMASK + k) | (GL.lift(1) << f:ld(R.ACT))); inc(f, 9)
            f:set(d, f:ld(R.AMASK + k))
            f:iff(GL.and_(f:ld(R.PT + k):ge(cfg.verify_events or 4), (d & (d - 1)):ne(0)), function()
              f:set(d, f:ld(R.COST + b) - f:ld(R.COST + a)); f:iff(d:lt(0), function() f:set(d, 0) end)
              if cfg.legacy_scale then f:set(x, f:ld(R.MAX + k) * f:ld(R.MAX + k))
              else f:set(x, f:ld(R.PSCALE + k)) end
              f:iff(x:gt(4 * (cfg.max_model_error or 4)), function() f:set(x, 4 * (cfg.max_model_error or 4)) end)
              f:iff(GL.and_((f:ld(R.PL + k) * 4):le(f:ld(R.PT + k) * x),
                GL.or_(GL.and_(f:ld(R.ROOT + 2 * k):lt(0), f:ld(R.PL + k):le(f:ld(R.IL + k))),
                       ((f:ld(R.IL + k) - f:ld(R.PL + k)) * 4):gt(d),
                       GL.and_(f:ld(R.PL + k):eq(f:ld(R.IL + k)), f:ld(R.COST + b):lt(f:ld(R.COST + a))))), function()
                f:st(R.PREVROOT + k, f:ld(R.ROOT + 2 * k)); f:st(R.ROOT + 2 * k, b); f:st(R.MEMROOT + k, b)
                f:st(R.ROOT + 2 * k + 1, f:ld(R.PREVROOT + k)); f:st(R.MODE + k, 2)
                if cfg.legacy_scale then f:set(x, f:ld(R.MAX + k) * f:ld(R.MAX + k)); f:iff(x:eq(0), function() f:set(x, 1) end)
                else f:set(x, f:ld(R.PSCALE + k)) end
                f:st(R.LOSS + k, (f:ld(R.PL + k) * 1024) // (f:ld(R.PT + k) * x)); f:st(R.FAIL + k, 0)
                f:st(R.USE + b, f:ld(R.USE + b) + 1); f:st(R.VER, f:ld(R.VER) + 1); inc(f, 4)
                f:iff(f:ld(R.TRANSFER + k):ne(0), function() inc(f, 11) end)
                f:set(d, (f:ld(R.CODE + b) & 31) - 4)
                f:iff(d:ltu(12), function() f:st(R.OPGAIN + d, f:ld(R.OPGAIN + d) + 16 + f:ld(R.IL + k) - f:ld(R.PL + k)) end)
              end, function()
                f:st(R.ROOT + 2 * k + 1, -1); f:st(R.MODE + k, 0); inc(f, 10)
              end)
            end)
          end)
        end)
      end
      if not cfg.legacy_scale and cfg.no_models then f:run("r_range", k, f:ld(R.OBS + k)) end
    end
    f:st(R.RPTR, (i + 1) % RC); f:iff(f:ld(R.RCNT):lt(RC), function() f:st(R.RCNT, f:ld(R.RCNT) + 1) end); inc(f, 1)
    f:st(R.MODELKNOWN, 0)
    for k = 0, 3 do
      f:iff(GL.lift(k):lt(f:ld(R.NF)), function()
        f:iff(f:ld(R.ROOT + 2 * k):ge(0), function()
          f:st(R.MODELKNOWN, f:ld(R.MODELKNOWN) | (1 << k)); f:set(u, u + f:ld(R.LOSS + k) // f:ld(R.NF))
        end, function() f:set(u, u + 1024 // f:ld(R.NF)) end)
      end)
      f:st(R.LAG + k, f:ld(R.PREV + k)); f:st(R.PREV + k, f:ld(R.OBS + k))
    end
    f:iff(u:gt(1024), function() f:set(u, 1024) end); f:st(R.UNC, u)
    f:st(R.LASTEVENT, f:ld(R.EVENT)); f:st(R.LASTEID, f:ld(R.EID)); f:run("r_refresh"); f:ret(1)
  end)

  -- Compact only checked DAGs. Discard pending and stale rollback roots before
  -- forgetting a current model; if space is still exhausted, forget the model
  -- with the largest real residual. The immutable fallback remains available.
  P:func("r_compact", {}, function(f)
    local n, w, j, a, b, c, worst = f:var("n"), f:var("w"), f:var("j", 0), f:var("a"), f:var("b"), f:var("c"), f:var("worst", -1)
    for k = 0, 3 do f:st(R.ROOT + 2 * k + 1, -1); f:st(R.MODE + k, 0); f:st(R.PREVROOT + k, -1) end
    f:for_(n, 0, NT, function() f:st(R.MASK0 + n, 0); f:st(R.MAP + n, -1) end)
    f:for_(n, 0, BASE, function() f:st(R.MASK0 + n, 1) end)
    for k = 0, 3 do
      f:set(a, f:ld(R.ROOT + 2 * k)); f:iff(a:ge(0), function() f:st(R.MASK0 + a, 1) end)
      f:st(R.MEMROOT + k, a)
    end
    -- One recent cheap building block survives even before a model uses it.
    f:set(n, f:ld(R.COUNT) - 1)
    f:while_(n:ge(BASE), function()
      f:iff(GL.and_(worst:lt(0), f:ld(R.COST + n):le(3)), function() f:st(R.MASK0 + n, 1); f:set(worst, n) end)
      f:set(n, n - 1)
    end)
    f:set(n, f:ld(R.COUNT) - 1)
    f:while_(n:ge(BASE), function()
      f:iff(f:ld(R.MASK0 + n):ne(0), function()
        f:set(w, f:ld(R.CODE + n)); f:iff((w & 31):ge(4), function()
          f:st(R.MASK0 + ((w >> 5) & 63), 1); f:st(R.MASK0 + ((w >> 11) & 63), 1)
          f:iff((w & 31):eq(13), function() f:st(R.MASK0 + ((w >> 17) & 63), 1) end)
        end)
      end)
      f:set(n, n - 1)
    end)
    f:for_(n, 0, f:ld(R.COUNT), function()
      f:iff(f:ld(R.MASK0 + n):ne(0), function()
        f:st(R.MAP + n, j); f:set(w, f:ld(R.CODE + n)); f:set(a, w & 31)
        f:iff(a:ge(4), function()
          f:set(b, f:ld(R.MAP + ((w >> 5) & 63))); f:set(c, f:ld(R.MAP + ((w >> 11) & 63)))
          f:iff(a:eq(13), function() f:set(w, a | (b << 5) | (c << 11) | (f:ld(R.MAP + ((w >> 17) & 63)) << 17)) end,
            function() f:set(w, a | (b << 5) | (c << 11)) end)
        end)
        for _, arr in ipairs({R.TYPE, R.COST, R.BORN, R.EPOCH, R.USE}) do f:st(arr + j, f:ld(arr + n)) end
        f:st(R.CODE + j, w); f:st(R.CHECKED + j, w)
        f:for_(a, 0, RC, function() f:st(R.SIG + j * RC + a, f:ld(R.SIG + n * RC + a)) end)
        f:set(j, j + 1)
      end)
    end)
    inc(f, 13, f:ld(R.COUNT) - j); f:st(R.COUNT, j)
    for k = 0, 3 do
      f:set(a, f:ld(R.ROOT + 2 * k)); f:iff(a:ge(0), function() f:set(a, f:ld(R.MAP + a)); f:st(R.ROOT + 2 * k, a) end)
      f:st(R.MEMROOT + k, a)
    end
    -- A completely live pool cannot safely overwrite an existing dependency.
    f:iff(j:ge(NT), function()
      f:set(worst, 0); f:set(w, -1)
      for k = 0, 3 do f:iff(f:ld(R.LOSS + k):gt(w), function() f:set(w, f:ld(R.LOSS + k)); f:set(worst, k) end) end
      f:st(R.ROOT + worst * 2, -1); f:st(R.MEMROOT + worst, -1); f:st(R.VER, f:ld(R.VER) + 1)
      f:st(R.MODELKNOWN, f:ld(R.MODELKNOWN) & (~(GL.lift(1) << worst))); f:st(R.UNC, 1024)
    end)
    f:run("r_refresh")
  end)

  P:func("r_offer", {"term"}, function(f, term)
    local field, root, loss, old = f:var("field"), f:var("root"), f:var("loss"), f:var("old")
    f:for_(field, 0, f:ld(R.NF), function()
      f:iff(GL.or_(f:ld(R.MODE + field):ne(1), f:ld(R.PT + field):le(1)), function()
        f:set(root, f:ld(R.ROOT + field * 2)); f:iff(root:lt(0), function() f:set(root, field) end)
        f:iff(f:ld(R.MODE + field):eq(1), function() f:set(root, f:ld(R.ROOT + field * 2 + 1)) end)
        f:set(loss, f:call("r_fit", term, field)); f:set(old, f:call("r_fit", root, field))
        f:iff(GL.and_(term:ne(root), GL.or_(loss:lt(old),
                      GL.and_(loss:eq(old), f:ld(R.MODE + field):ne(1), f:ld(R.ROOT + field * 2):lt(0)),
                      GL.and_(loss:eq(old), f:ld(R.COST + term):lt(f:ld(R.COST + root))))), function() f:run("r_prospect", field, term) end)
      end)
    end)
  end)

  P:func("r_search_do", {}, function(f)
    if cfg.no_models then f:ret(0); return end
    local n, a, b, c, op, w, cost = f:var("n", f:ld(R.NEXT)), f:var("a"), f:var("b"), f:var("c"), f:var("op"), f:var("w"), f:var("cost")
    f:st(R.NEXT, n + 1); f:iff(f:ld(R.RCNT):lt(2), function() f:ret(0) end)
    -- Existing semantic fragments are re-fitted, never blindly installed.
    f:iff((n % 5):eq(0), function()
      f:set(a, (n // 5) % f:ld(R.COUNT)); f:run("r_offer", a); f:ret(1)
    end)
    if cfg.no_repr then
      f:run("r_offer", (n % 4)); f:run("r_offer", 8 + (n % 4)); f:run("r_offer", 12); f:ret(1); return
    end
    f:iff(f:ld(R.COUNT):ge(NT), function() f:run("r_compact"); f:ret(1) end)
    f:set(n, f:ld(R.GEN)); f:st(R.GEN, n + 1); f:set(op, n % 12)
    if not cfg.no_meta then
      f:iff((n % 4):eq(0), function() f:set(op, (n // 4) % 12) end, function()
        f:set(w, -1)
        f:for_(a, 0, 12, function()
          f:set(cost, ((f:ld(R.OPGAIN + a) + 16) * 1024) // (f:ld(R.OPWORK + a) + 1024))
          f:iff(cost:gt(w), function() f:set(w, cost); f:set(op, a) end)
        end)
        inc(f, 12)
      end)
    end
    -- Interleave action effects, relations, thresholds, current-model
    -- mutations and conditional mixtures. No stream knows the task family.
    f:set(w, n % 5); f:set(n, n // 5)
    if cfg.no_meta then f:set(op, n % 12) end
    f:set(a, (n // 12) % BASE); f:set(b, 12); f:set(c, 0)
    f:iff(w:eq(1), function() f:set(a, (n // 12) % 8); f:set(b, (a + 1 + n // 96) % 8) end)
    f:iff(w:eq(2), function() f:set(a, (n // 48) % 8); f:set(b, 8 + (n // 12) % 4) end)
    f:iff(w:eq(3), function()
      f:set(c, n % f:ld(R.NF)); f:set(a, f:ld(R.ROOT + c * 2))
      f:iff(f:ld(R.ROOT + c * 2 + 1):ge(0), function() f:set(a, f:ld(R.ROOT + c * 2 + 1)) end)
      f:iff(a:lt(0), function() f:set(a, c) end)
      f:set(b, (n // f:ld(R.NF)) % f:ld(R.COUNT)); f:set(c, 0)
    end)
    f:iff(w:eq(4), function()
      f:set(op, 9); f:set(a, (n * 7) % f:ld(R.COUNT)); f:set(c, 0)
      f:while_(GL.and_(f:ld(R.TYPE + a):ne(2), c:lt(f:ld(R.COUNT))), function() f:set(a, (a + 1) % f:ld(R.COUNT)); f:set(c, c + 1) end)
      f:set(c, n % f:ld(R.NF)); f:set(b, f:ld(R.ROOT + c * 2)); f:iff(b:lt(0), function() f:set(b, c) end)
      f:iff(f:ld(R.ROOT + c * 2 + 1):ge(0), function() f:set(c, f:ld(R.ROOT + c * 2 + 1)) end,
        function() f:set(c, (n // f:ld(R.NF)) % f:ld(R.COUNT)) end)
    end)
    f:st(R.SOP, op); f:set(op, op + 4); f:st(R.OPN + (op - 4), f:ld(R.OPN + (op - 4)) + 1); inc(f, 2)
    f:iff(op:ne(13), function() f:set(c, 0) end)
    f:set(w, op | (a << 5) | (b << 11)); f:iff(op:eq(13), function() f:set(w, w | (c << 17)) end)
    f:set(cost, f:ld(R.COST + a) + f:ld(R.COST + b) + 1); f:iff(op:eq(13), function() f:set(cost, cost + f:ld(R.COST + c)) end)
    f:iff(cost:gt(LIMIT), function() inc(f, 3); f:ret(0) end)
    f:set(c, f:call("r_check", w, f:ld(R.COUNT))); f:iff(c:eq(0), function() inc(f, 3); f:ret(0) end)
    f:for_(a, 0, f:ld(R.COUNT), function() f:iff(f:ld(R.CODE + a):eq(w), function() inc(f, 3); f:ret(0) end) end)
    f:set(n, f:ld(R.COUNT)); f:st(R.CODE + n, w); f:st(R.CHECKED + n, w); f:st(R.TYPE + n, c); f:st(R.COST + n, cost)
    f:st(R.BORN + n, f:ld(R.EVENT)); f:st(R.EPOCH + n, f:ld(R.EID)); f:st(R.USE + n, 0)
    f:for_(a, 0, f:ld(R.RCNT), function()
      f:st(R.SIG + n * RC + a, f:call("r_apply", op, f:ld(R.SIG + ((w >> 5) & 63) * RC + a),
        f:ld(R.SIG + ((w >> 11) & 63) * RC + a), f:ld(R.SIG + ((w >> 17) & 63) * RC + a)))
    end)
    -- Observationally equivalent features do not occupy the finite beam.
    f:for_(a, 0, n, function()
      f:set(cost, 1)
      f:set(b, 0)
      f:while_(GL.and_(b:lt(f:ld(R.RCNT)), cost:ne(0)), function()
        f:iff(f:ld(R.SIG + n * RC + b):ne(f:ld(R.SIG + a * RC + b)), function() f:set(cost, 0) end)
        f:set(b, b + 1)
      end)
      f:iff(GL.and_(cost:ne(0), f:ld(R.TYPE + a):eq(c)), function() inc(f, 3); f:ret(0) end)
    end)
    f:st(R.COUNT, n + 1); inc(f, 7); f:run("r_offer", n); f:ret(1)
  end)
  P:func("r_search", {}, function(f)
    local t, result, work, op = f:var("t", f:clk(4)), f:var("result"), f:var("work"), f:var("op")
    f:st(R.SOP, -1); f:set(result, f:call("r_search_do")); f:set(work, f:clk(4) - t)
    inc(f, 8, work); f:iff(work:gt(f:ld(R.STATS + 15)), function() f:st(R.STATS + 15, work) end)
    f:set(op, f:ld(R.SOP)); f:iff(op:ge(0), function() f:st(R.OPWORK + op, f:ld(R.OPWORK + op) + work) end)
    f:ret(result)
  end)
  return R
end
return Core
end

-- ======================================================================== asi.reason.hpr  (hypothesis-population reasoner, metered guest program)
package.preload["asi.reason.hpr"] = function(...)
--[============[
asi.reason.hpr -- the generation-3 reasoner: a population of competing, program-induced transition hypotheses with
prospective ranking, a world library, chance-aware search over predicted states, and self-managed compute.

EVERYTHING BELOW THE BUILDER RUNS AS METERED VM-1 INSTRUCTIONS. The host only compiles this program (GL), runs the frozen
evaluator physics and reads results. The reasoner sees exactly what every other reasoning controller sees: the 28-word sense
packet (four fields 0..7 or unknown, goal vector, safe mask, last action and reward) and the three charged interface calls.

REPRESENTATION. The world is modelled per (action, field) cell. A cell holds up to NC competing rules plus an implicit
"nothing changes" hypothesis. A rule is a small program over operands (current fields, lag fields, the action, constants and
-- for fields classified as exogenous -- their post-step values): a term is a copy, an operation with a constant, an
operation between operands, or a depth-2 term; up to two state-conditional exceptions (atom -> term) may override it.
Rules live in the word format documented below and are evaluated both as scalars (planning) and over 15 sample lanes at once
(induction, chance evaluation): one 64-bit word holds 15 four-bit lanes (0..7, 8 = unknown).

LEARNING. Real transitions enter a 15-lane window. Each transition first scores every rule of the acted cell PROSPECTIVELY
(its prediction was fixed before the outcome was seen). Only a failure of the cell's currently best hypothesis triggers
re-induction of exactly that cell (targeted revision). Induction searches simplest-first: copies and constants, operations on
the own field, operations between operands, then (for goal-relevant cells, with exponential back-off after failures) deeper
terms and depth-2 terms found by inverse peeling of an invertible outer operation. Search effort follows relevance: goal fields
and the fields their best rules read get the full search; other fields only the cheap levels. A field that no rule can predict
prospectively (and that is not a goal field) is classified exogenous; its post-step value becomes a legal operand elsewhere.
Rules are ranked by (hits*100 + 2*fit)/(tests+2): retrospective fit counts as two pseudo-observations, evidence is prospective.

MEMORY. A finished episode is stored as a world (best rules, reward table, noise flags, context fingerprint = goal vector +
first observation); three worlds are kept. A new episode is a context switch: populations are cleared; if the fingerprint
matches a stored world its rules are restored as TENTATIVE hypotheses that are removed after two failed prospective tests;
stored programs of every remembered world may also be reused by induction. Nothing synthetic is ever stored as evidence.

PLANNING. Choice is breadth-first search over distinct predicted states (cached transitions, bounded by 24 states) followed by
finite-horizon value iteration; rewards come from a learned table by goal distance (optimistic at the goal), a small progress
shaping term and an intrinsic novelty reward for rarely tried (state, action) pairs. A plan that reaches a reward is followed
while real observations keep matching it. When relevant dynamics depend on exogenous fields the reasoner evaluates their recent
empirical samples lane-parallel: one expectation level for the decided step and one chance level for the next decision.
Deliberation is allocated by value: only when one-step values show no signal and the dynamics are predictable, with
exponential back-off after failed deliberations. Where the symbolic model of the goal fields is not yet convincing, model-free
outcome statistics per (action, field value) are blended in. Exploration = untried actions, disagreement among surviving
hypotheses about goal-relevant fields, stagnation, state-action novelty. Forecast = valid fields only, unknown mass calibrated
from the measured accuracy of the controller's own earlier forecasts.

COMPUTE. The guest reads its own metered clock; when the work left per remaining step falls under an allowance it enters
economy mode (no chance evaluation, no deliberation, no deep induction, no exploration arithmetic) so the stream can be finished.

WHAT THIS IS NOT. It does not rewrite its own reasoning algorithm: the learned structures are world models (programs), a world
library, plans and effort schedules. There is no claim of recursive self-improvement. Rules are a finite grammar with
empirical validation; no coverage certificate is claimed. Terminology: "hypothesis" = a candidate transition rule.

WORD FORMATS.
  term  : op(4) | A(5)<<4 | B(5)<<9 | iop(4)<<14 | iA(5)<<18 | iB(5)<<23   (B == 31 selects the nested inner triple)
  rule  : R0 = def(0..27) | atom1(28..41) | value1(42..55) | nexc(60..61);  R1 = atom2(0..13) | value2(14..27)
  stat  : hit 0..7 | test 8..15 | streak 16..23 | fit% 24..31 | seeded 32 | seeded misses 33..35 | prior hits 36..39 | removed 40 |
          cached score 41..47
  base ids : 0..3 pre field, 4..7 lag field, 8 action, 9..12 post field (exogenous only), 16..23 constants 0..7
  ops      : 0 copy 1 add 2 sub 3 xor 4 and 5 or 6 max 7 min 8 saturating add 9 saturating sub 10 equal 11 less
]============]
local GL = require("asi.gl")
local Hpr = {}

local H8 = 0x8888888888888888
local L7 = 0x7777777777777777
local ONES = 0x1111111111111111
Hpr.H8, Hpr.L7, Hpr.ONES = H8, L7, ONES

function Hpr.install(P, cfg)
  cfg = cfg or {}
  local R = {cfg = cfg}
  local function mem(name, size)
    local x = P:static("H_" .. name, size or 1); R[name] = x; return x
  end

  -- number of flag lanes set (<= 15 lanes, flags at bit 0 of each nibble)
  P:func("h_pop", {"x"}, function(f, x) f:ret((x * ONES) >> 60) end)

  -- lane-wise equality flags between two signatures (unknown == unknown counts as equal, callers mask)
  P:func("h_eqf", {"A", "B"}, function(f, A, B)
    local x = f:var("x", A ~ B)
    f:ret((~(x | (x >> 1) | (x >> 2) | (x >> 3))) & ONES)
  end)

  -- generic lane-wise binary operation (dispatch form; hot loops use specialised inline code)
  P:func("h_sw", {"op", "A", "B"}, function(f, op, A, B)
    local U, a, b, g, r = f:var("U"), f:var("a"), f:var("b"), f:var("g"), f:var("r")
    f:set(U, (A | B) & H8); f:set(a, A & L7); f:set(b, B & L7)
    local function fin(expr)             -- force unknown lanes to the canonical nibble 8
      f:set(r, expr)
      f:ret((r & ((((U >> 3) * 15)) ~ -1)) | U)
    end
    f:iff(op:eq(1), function() fin((a + b) & L7) end)
    f:iff(op:eq(2), function() fin(((a | H8) - b) & L7) end)
    f:iff(op:eq(3), function() fin(a ~ b) end)
    f:iff(op:eq(4), function() fin(a & b) end)
    f:iff(op:eq(5), function() fin(a | b) end)
    f:set(g, ((((a | H8) - b) & H8) >> 3))
    f:iff(op:eq(6), function() fin((a & (g * 15)) | (b & ((g * 15) ~ -1) & L7)) end)
    f:iff(op:eq(7), function() fin((b & (g * 15)) | (a & ((g * 15) ~ -1) & L7)) end)
    f:iff(op:eq(8), function()
      local s, o = f:var("s"), f:var("o")
      f:set(s, a + b); f:set(o, ((s >> 3) & ONES) * 15)
      fin(((s & L7) & (o ~ -1)) | (o & L7))
    end)
    f:iff(op:eq(9), function() fin((((a | H8) - b) & L7) & (g * 15)) end)
    f:iff(op:eq(10), function()
      local x = f:var("x", a ~ b)
      fin(((x | (x >> 1) | (x >> 2)) & ONES) ~ ONES)
    end)
    fin((g ~ ONES) & ONES)           -- 11: a < b
  end)

  -- scalar twin of h_sw; unknown (-1) in -> unknown out
  P:func("h_sap", {"op", "x", "y"}, function(f, op, x, y)
    f:iff(GL.or_(x:lt(0), y:lt(0)), function() f:ret(-1) end)
    f:iff(op:eq(1), function() f:ret((x + y) & 7) end)
    f:iff(op:eq(2), function() f:ret((x - y) & 7) end)
    f:iff(op:eq(3), function() f:ret(x ~ y) end)
    f:iff(op:eq(4), function() f:ret(x & y) end)
    f:iff(op:eq(5), function() f:ret(x | y) end)
    f:iff(op:eq(6), function() f:iff(x:gt(y), function() f:ret(x) end); f:ret(y) end)
    f:iff(op:eq(7), function() f:iff(x:lt(y), function() f:ret(x) end); f:ret(y) end)
    f:iff(op:eq(8), function() f:iff((x + y):gt(7), function() f:ret(7) end); f:ret(x + y) end)
    f:iff(op:eq(9), function() f:iff(x:lt(y), function() f:ret(0) end); f:ret(x - y) end)
    f:iff(op:eq(10), function() f:iff(x:eq(y), function() f:ret(1) end); f:ret(0) end)
    f:iff(x:lt(y), function() f:ret(1) end)
    f:ret(0)
  end)


  ------------------------------------------------------------------ state
  local LW = 4 + 4 + 4 + 16 + 16 * 3                 -- library world: goal, first observation, exo flags, reward table, 16 cells x (R0, R1, stat)
  local NC = cfg.nc or 4                         -- competing rules per (action, field) cell
  assert(NC >= 1 and NC <= 6, "hypothesis population bound")
  mem("NF"); mem("NA"); mem("SAFE"); mem("EVENT"); mem("RESET"); mem("EID"); mem("LASTREW"); mem("LASTACT")
  mem("GOAL", 4); mem("MAXV", 4); mem("OBS", 4); mem("PREV", 4); mem("LAG", 4)
  mem("HAVE"); mem("STEPN"); mem("STAG")
  mem("CTX", 24); mem("SIG", 24)
  mem("WPRE", 4); mem("WLAG", 4); mem("WPOST", 4); mem("WACT"); mem("WVALID"); mem("WPOS"); mem("WCNT")
  mem("DEEPLVL")
  mem("BT"); mem("BC"); mem("BS"); mem("EVALS")
  mem("NCAND", 16); mem("CR0", 16 * NC); mem("CR1", 16 * NC); mem("CST", 16 * NC); mem("PST", 16)
  mem("TGEN"); mem("BGEN"); mem("RELN"); mem("RELL", 4); mem("CBS", 132); mem("CBN", 132); mem("CBON"); mem("REINDS"); mem("REINDM"); mem("DFAIL"); mem("DFREE"); mem("DBACK"); mem("ECON"); mem("ECOTHR"); mem("STEPG"); mem("FC", 13); mem("FOK"); mem("FTOT"); mem("UCAL"); mem("QHI"); mem("QLO"); mem("VIS", 64);  mem("VISA", 256); mem("NOVB"); mem("DELIBQ"); mem("DEEPFIT"); mem("CHON"); mem("RPOST"); mem("RNX", 16); mem("RESTORED"); mem("SIMSTRONG"); mem("CBMIN"); mem("CBSPREAD"); mem("CBW"); mem("LIB", 3 * LW); mem("LIBN"); mem("LIBAGE", 3); mem("LIBON"); mem("EXOON"); mem("RSUM"); mem("EBADAPT"); mem("CIND", 16); mem("CMISS", 16); mem("CBACK", 16); mem("CFAIL", 16); mem("EXCON"); mem("EXO", 4); mem("PTEST", 4); mem("PHIT", 4); mem("REL"); mem("STATS", 16)
  local function inc(f, k, d) f:st(R.STATS + k, f:ld(R.STATS + k) + (d or 1)) end
  -- STATS: 0 transitions, 1 inductions, 2 ladder evaluations, 3 inserted candidates, 4 surprises, 5 plans, 6 plan nodes

  ------------------------------------------------------------------ scalar term / rule evaluation
  -- scalar operation table (ROM): index op*64 + x*8 + y for known x, y in 0..7
  local function sref(op, x, y)
    if op == 1 then return (x + y) & 7 elseif op == 2 then return (x - y) & 7 elseif op == 3 then return x ~ y
    elseif op == 4 then return x & y elseif op == 5 then return x | y elseif op == 6 then return x > y and x or y
    elseif op == 7 then return x < y and x or y elseif op == 8 then return math.min(x + y, 7)
    elseif op == 9 then return x >= y and x - y or 0 elseif op == 10 then return x == y and 1 or 0
    elseif op == 11 then return x < y and 1 or 0 else return 0 end
  end
  local optab = {}
  for op = 0, 11 do for x = 0, 7 do for y = 0, 7 do optab[#optab + 1] = sref(op, x, y) end end end
  local OPTAB = P:rodata("H_OPTAB", optab)
  -- base values live in CTX[0..12]; constants 0..7 are resident at CTX[16..23]
  P:func("h_bval", {"id"}, function(f, id) f:ret(f:ld(R.CTX + id)) end)
  -- term word -> scalar (unknown inputs give -1)
  P:func("h_tev", {"T"}, function(f, T)
    local op, B, x, y, z = f:var("op"), f:var("B"), f:var("x"), f:var("y"), f:var("z")
    f:set(op, T & 15); f:set(B, (T >> 9) & 31)
    f:set(x, f:ld(R.CTX + ((T >> 4) & 31)))
    f:iff(op:eq(0), function() f:ret(x) end)
    f:iff(B:eq(31), function()
      f:set(y, f:ld(R.CTX + ((T >> 18) & 31)))
      f:iff(((T >> 14) & 15):ne(0), function()
        f:set(z, f:ld(R.CTX + ((T >> 23) & 31)))
        f:iff((y | z):lt(0), function() f:set(y, -1) end, function() f:set(y, f:ld(OPTAB + (((T >> 14) & 15) << 6) + (y << 3) + z)) end)
      end)
    end, function() f:set(y, f:ld(R.CTX + B)) end)
    f:iff((x | y):lt(0), function() f:ret(-1) end)
    f:ret(f:ld(OPTAB + (op << 6) + (x << 3) + y))
  end)
  -- rule words -> scalar. R0: def(0..27) | atom1(28..41) | val1(42..55) | nexc(60..61); R1: atom2(0..13) | val2(14..27)
  P:func("h_rev", {"R0", "R1"}, function(f, R0, R1)
    local n = f:var("n", (R0 >> 60) & 3)
    f:iff(n:ge(1), function()
      f:iff(f:call("h_tev", (R0 >> 28) & 16383):eq(1), function() f:ret(f:call("h_tev", (R0 >> 42) & 16383)) end)
    end)
    f:iff(n:ge(2), function()
      f:iff(f:call("h_tev", R1 & 16383):eq(1), function() f:ret(f:call("h_tev", (R1 >> 14) & 16383)) end)
    end)
    f:ret(f:call("h_tev", R0 & 0xFFFFFFF))
  end)

  ------------------------------------------------------------------ SWAR term / rule evaluation over the window
  P:func("h_bsig", {"id"}, function(f, id) f:ret(f:ld(R.SIG + id)) end)
  P:func("h_tsg", {"T"}, function(f, T)
    local op, B, x, y = f:var("op"), f:var("B"), f:var("x"), f:var("y")
    f:set(op, T & 15); f:set(B, (T >> 9) & 31)
    f:set(x, f:call("h_bsig", (T >> 4) & 31))
    f:iff(op:eq(0), function() f:ret(x) end)
    f:iff(B:eq(31), function()
      local iop = f:var("iop")
      f:set(iop, (T >> 14) & 15)
      f:set(y, f:call("h_bsig", (T >> 18) & 31))
      f:iff(iop:ne(0), function() f:set(y, f:call("h_sw", iop, y, f:call("h_bsig", (T >> 23) & 31))) end)
    end, function() f:set(y, f:call("h_bsig", B)) end)
    f:ret(f:call("h_sw", op, x, y))
  end)
  P:func("h_rsg", {"R0", "R1"}, function(f, R0, R1)
    local n, res, M = f:var("n", (R0 >> 60) & 3), f:var("res"), f:var("M")
    f:set(res, f:call("h_tsg", R0 & 0xFFFFFFF))
    f:iff(n:ge(2), function()
      f:set(M, f:call("h_eqf", f:call("h_tsg", R1 & 16383), ONES) * 15)
      f:set(res, (f:call("h_tsg", (R1 >> 14) & 16383) & M) | (res & (M ~ -1)))
    end)
    f:iff(n:ge(1), function()
      f:set(M, f:call("h_eqf", f:call("h_tsg", (R0 >> 28) & 16383), ONES) * 15)
      f:set(res, (f:call("h_tsg", (R0 >> 42) & 16383) & M) | (res & (M ~ -1)))
    end)
    f:ret(res)
  end)

  ------------------------------------------------------------------ window of recent real transitions
  -- Lane p holds one transition: pre, lag (pre of the previous transition), action, post. Known values 0..7, unknown 8.
  P:func("h_nib", {"v"}, function(f, v) f:iff(v:lt(0), function() f:ret(8) end); f:ret(v) end)
  P:func("h_win_clear", {}, function(f)
    local j = f:var("j")
    f:for_(j, 0, 4, function() f:st(R.WPRE + j, 0); f:st(R.WLAG + j, 0); f:st(R.WPOST + j, 0) end)
    f:st(R.WACT, 0); f:st(R.WVALID, 0); f:st(R.WPOS, 0); f:st(R.WCNT, 0)
  end)
  P:func("h_win_add", {"act"}, function(f, act)
    local p, j, sh, keep = f:var("p", f:ld(R.WPOS)), f:var("j"), f:var("sh"), f:var("keep")
    f:set(sh, p << 2); f:set(keep, (GL.lift(15) << sh) ~ -1)
    f:for_(j, 0, 4, function()
      f:st(R.WPRE + j, (f:ld(R.WPRE + j) & keep) | (f:call("h_nib", f:ld(R.PREV + j)) << sh))
      f:st(R.WLAG + j, (f:ld(R.WLAG + j) & keep) | (f:call("h_nib", f:ld(R.LAG + j)) << sh))
      f:st(R.WPOST + j, (f:ld(R.WPOST + j) & keep) | (f:call("h_nib", f:ld(R.OBS + j)) << sh))
    end)
    f:st(R.WACT, (f:ld(R.WACT) & keep) | (act << sh))
    f:st(R.WVALID, f:ld(R.WVALID) | (GL.lift(1) << sh))
    f:set(p, p + 1); f:iff(p:ge(15), function() f:set(p, 0) end); f:st(R.WPOS, p)
    f:iff(f:ld(R.WCNT):lt(15), function() f:st(R.WCNT, f:ld(R.WCNT) + 1) end)
  end)
  -- SWAR signatures of the base features over the window
  P:func("h_sigload", {}, function(f)
    local j = f:var("j")
    f:for_(j, 0, 4, function()
      f:st(R.SIG + j, f:ld(R.WPRE + j)); f:st(R.SIG + 4 + j, f:ld(R.WLAG + j)); f:st(R.SIG + 9 + j, f:ld(R.WPOST + j))
    end)
    f:st(R.SIG + 8, f:ld(R.WACT))
  end)
  -- lanes (flags) of action a with a known post value of field i
  P:func("h_cell_lanes", {"a", "i"}, function(f, a, i)
    f:ret(f:call("h_eqf", f:ld(R.WACT), a * ONES) & f:ld(R.WVALID) & ((f:ld(R.WPOST + i) >> 3) ~ -1) & ONES)
  end)

  ------------------------------------------------------------------ candidate ladder (simplest rules first)
  -- Operand lists for a rule of field i: every base except the own pre field (kept in OWNM). Values are pre-masked
  -- to 0..7 per lane; lanes where any operand is unknown are excluded once (KNOWN) instead of inside the hot loops.
  mem("LB", 13); mem("LM", 13); mem("NL"); mem("OWNM"); mem("CURI"); mem("NCUR"); mem("KNOWN")
  -- A base that is unknown on more than a quarter of the cell's lanes is not offered as an operand.
  P:func("h_mkbases", {"i", "allow_post", "Ma"}, function(f, i, allow_post, Ma)
    local j, nl, kn, kb, nm = f:var("j"), f:var("nl", 0), f:var("kn", ONES), f:var("kb"), f:var("nm", f:call("h_pop", Ma))
    local function add(idexpr)
      f:set(kb, ((f:ld(R.SIG + idexpr) >> 3) ~ -1) & ONES)
      f:iff((f:call("h_pop", kb & Ma) * 4):ge(nm * 3), function()
        f:set(kn, kn & kb)
        f:st(R.LB + nl, idexpr); f:st(R.LM + nl, f:ld(R.SIG + idexpr) & L7); f:set(nl, nl + 1)
      end)
    end
    f:set(kb, ((f:ld(R.SIG + i) >> 3) ~ -1) & ONES)
    f:set(kn, kn & kb)
    f:for_(j, 0, f:ld(R.NF), function() f:iff(j:ne(i), function() add(j) end) end)
    f:for_(j, 0, f:ld(R.NF), function() add(4 + j) end)
    add(GL.lift(8))
    f:iff(allow_post:ne(0), function()
      f:for_(j, 0, f:ld(R.NF), function()
        f:iff(GL.and_(j:ne(i), f:ld(R.EXO + j):ne(0)), function() add(9 + j) end)
      end)
    end)
    f:st(R.NL, nl); f:st(R.OWNM, f:ld(R.SIG + i) & L7); f:st(R.KNOWN, kn); f:st(R.CURI, i)
  end)

  -- lane-wise operation on pre-masked operands (no unknown lanes). Result in `r` (and `g` as scratch).
  local function swm(f, op, Am, Amh, Bm, r, g)
    if op == 1 then f:set(r, (Am + Bm) & L7)
    elseif op == 2 then f:set(r, (Amh - Bm) & L7)
    elseif op == 3 then f:set(r, Am ~ Bm)
    elseif op == 4 then f:set(r, Am & Bm)
    elseif op == 5 then f:set(r, Am | Bm)
    elseif op == 8 then
      f:set(g, ((((Am + Bm) >> 3) & ONES) * 15))
      f:set(r, (((Am + Bm) & L7) & (g ~ -1)) | (g & L7))
    else
      f:set(g, ((((Amh - Bm) & H8) >> 3) * 15))
      if op == 6 then f:set(r, (Am & g) | (Bm & (g ~ -1)))
      elseif op == 7 then f:set(r, (Bm & g) | (Am & (g ~ -1)))
      else f:set(r, ((Amh - Bm) & L7) & g) end
    end
  end

  -- `perfect` returns 1 from the enclosing function when a candidate fits every lane of the cell;
  -- `best` scores by matched lanes (noise tolerant) and keeps the best candidate in BT/BC/BS.
  local function perfect(f, sig, Tfn, Y, M)
    f:iff(((sig ~ Y) & M):eq(0), function() f:st(R.BT, Tfn()); f:ret(1) end)
  end
  local function best(f, sig, Tfn, lvl, Y, M, v)
    local x, c = v.x, v.c
    f:set(x, sig ~ Y)
    f:set(x, (((x | (x >> 1) | (x >> 2) | (x >> 3)) ~ -1) & ONES) & M)
    f:set(c, (x * ONES) >> 60)
    f:iff((c * 3 - lvl):gt(f:ld(R.BS)), function() f:st(R.BS, c * 3 - lvl); f:st(R.BC, c); f:st(R.BT, Tfn()) end)
    f:iff(c:eq(f:ld(R.NCUR)), function() f:ret(1) end)
  end
  local function gen_levels(mode)
    local pre = mode == "perfect" and "h_pl" or "h_bl"
    local function newfn(lvl, body)
      P:func(pre .. lvl, {"Y", "M"}, function(f, Yv, Mv)
        local v = {x = f:var("x"), c = f:var("c"), r = f:var("r"), g = f:var("g")}
        local function chk(sig, Tfn, l)
          if mode == "perfect" then perfect(f, sig, Tfn, Yv, Mv) else best(f, sig, Tfn, l, Yv, Mv, v) end
        end
        body(f, v, chk)
        f:ret(0)
      end)
    end
    local CI = function(f) return f:ld(R.CURI) end
    newfn(0, function(f, v, chk)
      local k = f:var("k")
      chk(f:ld(R.OWNM), function() return f:ld(R.CURI) << 4 end, 0)
      f:for_(k, 0, f:ld(R.NL), function() chk(f:ld(R.LM + k), function() return f:ld(R.LB + k) << 4 end, 1) end)
      f:for_(k, 0, 8, function() chk(k * ONES, function() return (16 + k) << 4 end, 1) end)
    end)
    newfn(1, function(f, v, chk)
      local k, Am, Amh, Bm = f:var("k"), f:var("Am", f:ld(R.OWNM)), f:var("Amh"), f:var("Bm")
      f:set(Amh, Am | H8)
      for op = 1, 9 do
        f:for_(k, 0, 8, function()
          f:set(Bm, k * ONES); swm(f, op, Am, Amh, Bm, v.r, v.g)
          chk(v.r, function() return op | (f:ld(R.CURI) << 4) | ((16 + k) << 9) end, 1)
        end)
      end
    end)
    newfn(2, function(f, v, chk)
      local k, Am, Amh, Bm = f:var("k"), f:var("Am", f:ld(R.OWNM)), f:var("Amh"), f:var("Bm")
      f:set(Amh, Am | H8)
      for op = 1, 9 do
        f:for_(k, 0, f:ld(R.NL), function()
          f:set(Bm, f:ld(R.LM + k)); swm(f, op, Am, Amh, Bm, v.r, v.g)
          chk(v.r, function() return op | (f:ld(R.CURI) << 4) | (f:ld(R.LB + k) << 9) end, 2)
        end)
      end
    end)
    if mode == "perfect" then
      newfn(4, function(f, v, chk)
        local k, Am, Amh, Bm, c = f:var("k"), f:var("Am"), f:var("Amh"), f:var("Bm"), f:var("cc")
        for op = 1, 9 do
          f:for_(k, 0, f:ld(R.NL), function()
            f:set(Am, f:ld(R.LM + k)); f:set(Amh, Am | H8)
            f:for_(c, 0, 8, function()
              f:set(Bm, c * ONES); swm(f, op, Am, Amh, Bm, v.r, v.g)
              chk(v.r, function() return op | (f:ld(R.LB + k) << 4) | ((16 + c) << 9) end, 4)
            end)
          end)
        end
      end)
      newfn(3, function(f, v, chk)
        local kx, ky, Am, Amh, Bm = f:var("kx"), f:var("ky"), f:var("Am"), f:var("Amh"), f:var("Bm")
        for op = 1, 9 do
          local ordered = (op == 2 or op == 9)
          f:for_(kx, 0, f:ld(R.NL), function()
            f:set(Am, f:ld(R.LM + kx)); f:set(Amh, Am | H8)
            f:for_(ky, ordered and 0 or (kx + 1), f:ld(R.NL), function()
              f:iff(ky:ne(kx), function()
                f:set(Bm, f:ld(R.LM + ky)); swm(f, op, Am, Amh, Bm, v.r, v.g)
                chk(v.r, function() return op | (f:ld(R.LB + kx) << 4) | (f:ld(R.LB + ky) << 9) end, 3)
              end)
            end)
          end)
        end
      end)
    end
  end
  gen_levels("perfect"); gen_levels("best")

  -- Search the ladder for a rule body of field i that explains the lanes Ma of target Y.
  -- Returns 1 for a perfect fit; BT/BC always hold the best term and its matched lanes.
  P:func("h_ladder", {"Y", "Ma", "i", "maxlvl"}, function(f, Y, Ma, i, maxlvl)
    local n, Mn = f:var("n"), f:var("Mn")
    f:set(Ma, Ma & f:ld(R.KNOWN))
    f:set(n, f:call("h_pop", Ma)); f:set(Mn, Ma * 15)
    f:st(R.NCUR, n)
    f:st(R.BS, -(1 << 30)); f:st(R.BC, 0); f:st(R.BT, i << 4)
    f:iff(n:eq(0), function() f:ret(0) end)
    for lvl = 0, 4 do
      f:iff(maxlvl:ge(lvl), function()
        f:iff(f:call("h_pl" .. lvl, Y, Mn):ne(0), function() f:st(R.BC, n); f:ret(1) end)
      end)
    end
    -- noise tolerant fallback on the cheap levels (meaningless with very few lanes)
    f:st(R.BS, -(1 << 30)); f:st(R.BC, 0)
    f:iff(n:ge(5), function()
      for lvl = 0, 2 do
        f:iff(f:call("h_bl" .. lvl, Y, Ma):ne(0), function() f:ret(1) end)
      end
    end)
    f:ret(0)
  end)
  -- depth-2 terms by inverse peeling of an invertible outer operation around the own field
  P:func("h_deep", {"Y", "Ma", "i", "n"}, function(f, Y, Ma, i, n)
    local T0, c0, X, Rt = f:var("T0", f:ld(R.BT)), f:var("c0", f:ld(R.BC)), f:var("X", f:ld(R.SIG + i)), f:var("Rt")
    local ti, cand, cc = f:var("ti"), f:var("cand"), f:var("cc")
    for _, o in ipairs({1, 3, 2}) do
      f:iff(c0:lt(n), function()
        if o == 1 then f:set(Rt, f:call("h_sw", 2, Y, X))
        elseif o == 3 then f:set(Rt, Y ~ X)
        else f:set(Rt, f:call("h_sw", 2, X, Y)) end
        f:run("h_ladder", Rt, Ma, i, f:ld(R.DEEPLVL))
        f:set(ti, f:ld(R.BT))
        f:iff(ti:ne(i << 4), function()
          f:set(cand, o | (i << 4) | (GL.lift(31) << 9) | ((ti & 15) << 14) | (((ti >> 4) & 31) << 18) | (((ti >> 9) & 31) << 23))
          f:set(cc, f:call("h_pop", f:call("h_eqf", f:call("h_tsg", cand), Y) & Ma))
          f:iff(cc:gt(c0), function() f:set(T0, cand); f:set(c0, cc) end)
        end)
      end)
    end
    f:st(R.BT, T0); f:st(R.BC, c0)
    f:ret(c0)
  end)

  ------------------------------------------------------------------ state-conditional exceptions to a rule body
  -- A rule may carry up to two exceptions: (atom -> value term). Value terms are collected from the cheap ladder levels
  -- (those that explain at least two thirds of the unexplained lanes); atoms are lane predicates built from the window.
  -- The pair with the best net gain in matched lanes wins; this tolerates observation noise.
  mem("CTW", 8); mem("CMF", 8); mem("NCOL"); mem("CRM"); mem("CMA"); mem("CNR")
  mem("AT", 96); mem("AF", 96); mem("NAT")
  mem("XR0"); mem("XR1"); mem("XC")
  do
    local function collect_fn(lvl, body)
      P:func("h_cl" .. lvl, {"Y", "M"}, function(f, Yv, Mv)
        local v = {r = f:var("r"), g = f:var("g"), x = f:var("x"), c = f:var("c")}
        local function chk(sig, Tfn)
          f:set(v.x, sig ~ Yv)
          f:set(v.x, (((v.x | (v.x >> 1) | (v.x >> 2) | (v.x >> 3)) ~ -1) & ONES) & f:ld(R.CMA))
          f:set(v.c, ((v.x & f:ld(R.CRM)) * ONES) >> 60)
          f:iff((v.c * 3):ge(f:ld(R.CNR) * 2), function()
            f:iff(GL.and_(v.c:gt(0), f:ld(R.NCOL):lt(8)), function()
              local q = f:var("q")
              f:set(q, 0)
              f:while_(GL.and_(q:lt(f:ld(R.NCOL)), f:ld(R.CMF + q):ne(v.x)), function() f:set(q, q + 1) end)
              f:iff(q:ge(f:ld(R.NCOL)), function()
                f:st(R.CTW + q, Tfn()); f:st(R.CMF + q, v.x); f:st(R.NCOL, q + 1)
              end)
            end)
          end)
        end
        body(f, v, chk)
        f:ret(0)
      end)
    end
    collect_fn(0, function(f, v, chk)
      local k = f:var("k")
      chk(f:ld(R.OWNM), function() return f:ld(R.CURI) << 4 end)
      f:for_(k, 0, f:ld(R.NL), function() chk(f:ld(R.LM + k), function() return f:ld(R.LB + k) << 4 end) end)
      f:for_(k, 0, 8, function() chk(k * ONES, function() return (16 + k) << 4 end) end)
    end)
    collect_fn(1, function(f, v, chk)
      local k, Am, Amh, Bm = f:var("k"), f:var("Am", f:ld(R.OWNM)), f:var("Amh"), f:var("Bm")
      f:set(Amh, Am | H8)
      for op = 1, 9 do
        f:for_(k, 0, 8, function()
          f:set(Bm, k * ONES); swm(f, op, Am, Amh, Bm, v.r, v.g)
          chk(v.r, function() return op | (f:ld(R.CURI) << 4) | ((16 + k) << 9) end)
        end)
      end
    end)
    collect_fn(2, function(f, v, chk)
      local k, Am, Amh, Bm = f:var("k"), f:var("Am", f:ld(R.OWNM)), f:var("Amh"), f:var("Bm")
      f:set(Amh, Am | H8)
      for op = 1, 9 do
        f:for_(k, 0, f:ld(R.NL), function()
          f:set(Bm, f:ld(R.LM + k)); swm(f, op, Am, Amh, Bm, v.r, v.g)
          chk(v.r, function() return op | (f:ld(R.CURI) << 4) | (f:ld(R.LB + k) << 9) end)
        end)
      end
    end)
  end
  -- lane predicates over the window: field == constant, and ordering / equality between pre fields
  P:func("h_atoms", {"i"}, function(f, i)
    local n, b, c, fl, x, y = f:var("n", 0), f:var("b"), f:var("c"), f:var("fl"), f:var("x"), f:var("y")
    local function add(Tword, flags)
      f:iff(GL.and_(flags:ne(0), n:lt(96)), function() f:st(R.AT + n, Tword); f:st(R.AF + n, flags); f:set(n, n + 1) end)
    end
    f:for_(b, 0, 8, function()
      f:iff(GL.or_(b:lt(f:ld(R.NF)), GL.and_(b:ge(4), b:lt(4 + f:ld(R.NF)))), function()
        f:for_(c, 0, 8, function()
          f:set(fl, f:call("h_eqf", f:ld(R.SIG + b), c * ONES) & f:ld(R.CMA))
          add(10 | (b << 4) | ((16 + c) << 9), fl)
        end)
      end)
    end)
    f:for_(x, 0, f:ld(R.NF), function()
      f:for_(y, 0, f:ld(R.NF), function()
        f:iff(x:lt(y), function()
          f:set(fl, f:call("h_eqf", f:ld(R.SIG + x), f:ld(R.SIG + y)) & f:ld(R.CMA)); add(10 | (x << 4) | (y << 9), fl)
        end)
        f:iff(x:ne(y), function()
          f:set(fl, f:call("h_sw", 11, f:ld(R.SIG + x), f:ld(R.SIG + y)) & ONES & f:ld(R.CMA)); add(11 | (x << 4) | (y << 9), fl)
        end)
      end)
    end)
    f:st(R.NAT, n)
  end)
  -- try to add up to two exceptions to the rule body T0; result in XR0/XR1 (rule words) and XC (matched lanes)
  P:func("h_exc", {"Y", "Ma", "i", "T0"}, function(f, Y, Ma, i, T0)
    local R0, R1, round, sg, M0, Rr, nR = f:var("R0", T0), f:var("R1", 0), f:var("round"), f:var("sg"), f:var("M0"), f:var("Rr"), f:var("nR")
    local k, q, g, bg, bharm, bcov, bA, bT = f:var("k"), f:var("q"), f:var("g"), f:var("bg"), f:var("bharm"), f:var("bcov"), f:var("bA"), f:var("bT")
    local m1, Lp, nex, cov, harm = f:var("m1"), f:var("Lp"), f:var("nex", 0), f:var("cov"), f:var("harm")
    f:st(R.CMA, Ma)
    f:run("h_atoms", i)
    f:for_(round, 0, 2, function()
      f:set(sg, f:call("h_rsg", R0, R1))
      f:set(M0, f:call("h_eqf", sg, Y) & Ma)
      f:set(Rr, Ma & (M0 ~ -1) & ONES)
      f:set(nR, f:call("h_pop", Rr))
      f:iff(nR:eq(0), function() f:break_() end)
      f:st(R.CRM, Rr * 15); f:st(R.CNR, nR); f:st(R.NCOL, 0)
      f:run("h_cl0", Y, 0); f:run("h_cl1", Y, 0); f:run("h_cl2", Y, 0)
      f:set(bg, 0); f:set(bharm, 0); f:set(bcov, 99); f:set(bA, -1); f:set(bT, 0)
      f:for_(k, 0, f:ld(R.NCOL), function()
        f:set(m1, f:ld(R.CMF + k) & ONES)
        f:for_(q, 0, f:ld(R.NAT), function()
          f:set(Lp, f:ld(R.AF + q))
          f:set(g, f:call("h_pop", m1 & Lp) - f:call("h_pop", M0 & Lp))
          f:iff(g:gt(0), function()
            f:set(cov, f:call("h_pop", Lp))
            f:iff(GL.or_(g:gt(bg), GL.and_(g:eq(bg), cov:lt(bcov))), function()
              f:set(bg, g); f:set(bcov, cov); f:set(bA, f:ld(R.AT + q)); f:set(bT, f:ld(R.CTW + k))
              f:set(bharm, f:call("h_pop", M0 & Lp & (m1 ~ -1)))
            end)
          end)
        end)
      end)
      f:iff(bA:lt(0), function() f:break_() end)
      f:iff(GL.or_(bg:ge(2), GL.and_(bg:ge(1), bharm:eq(0))), function()
        -- the new exception takes priority; the previous first exception becomes the second
        f:set(R1, ((R0 >> 28) & 16383) | (((R0 >> 42) & 16383) << 14))
        f:set(R0, (R0 & 0xFFFFFFF) | (bA << 28) | (bT << 42))
        f:set(nex, nex + 1)
        f:iff(nex:gt(2), function() f:set(nex, 2) end)
      end, function() f:break_() end)
    end)
    f:set(R0, (R0 & ((GL.lift(3) << 60) ~ -1)) | (nex << 60))
    f:set(sg, f:call("h_rsg", R0, R1))
    f:st(R.XR0, R0); f:st(R.XR1, R1); f:st(R.XC, f:call("h_pop", f:call("h_eqf", sg, Y) & Ma))
    f:ret(nex)
  end)

  ------------------------------------------------------------------ populations of competing rules
  -- STAT word: hit 0..7 | test 8..15 | streak 16..23 | fit% 24..31 | seeded 32 | seeded misses 33..35 | seeded prior hit 36..39
  P:func("h_stscore", {"st"}, function(f, st)
    f:ret((((st & 255) * 100) + 2 * ((st >> 24) & 255)) // (((st >> 8) & 255) + 2))
  end)
  -- the cached score lives in bits 41..47 of the stat word
  P:func("h_withscore", {"st"}, function(f, st)
    f:ret((st & ((GL.lift(127) << 41) ~ -1)) | (f:call("h_stscore", st) << 41))
  end)
  local function cs(e) return (e >> 41) & 127 end
  -- best candidate of a cell: returns index (-1 = persistence) and leaves its score in BS
  P:func("h_best", {"cell"}, function(f, cell)
    local k, bk, bs, sc = f:var("k"), f:var("bk", -1), f:var("bs", -1), f:var("sc")
    f:for_(k, 0, f:ld(R.NCAND + cell), function()
      f:set(sc, cs(f:ld(R.CST + cell * NC + k)))
      f:iff(sc:gt(bs), function() f:set(bs, sc); f:set(bk, k) end)
    end)
    -- persistence ("nothing changes") only wins when strictly better than every explicit rule
    f:set(sc, cs(f:ld(R.PST + cell)))
    f:iff(GL.or_(bk:lt(0), sc:gt(bs)), function() f:set(bs, sc); f:set(bk, -1) end)
    f:st(R.BS, bs)
    f:ret(bk)
  end)
  -- insert a rule into the cell's population unless an observationally equal one exists on the cell's lanes
  P:func("h_insert", {"cell", "R0", "R1", "fit"}, function(f, cell, R0, R1, fit)
    local n, k, sg, mask, wi, ws, sc = f:var("n"), f:var("k"), f:var("sg"), f:var("mask"), f:var("wi"), f:var("ws"), f:var("sc")
    f:set(mask, f:call("h_cell_lanes", cell >> 2, cell & 3) * 15)
    f:set(sg, f:call("h_rsg", R0, R1))
    f:set(n, f:ld(R.NCAND + cell))
    f:for_(k, 0, n, function()
      f:iff(((f:call("h_rsg", f:ld(R.CR0 + cell * NC + k), f:ld(R.CR1 + cell * NC + k)) ~ sg) & mask):eq(0), function() f:ret(0) end)
    end)
    f:iff(n:lt(NC), function()
      f:st(R.CR0 + cell * NC + n, R0); f:st(R.CR1 + cell * NC + n, R1); f:st(R.CST + cell * NC + n, (fit << 24) | (fit << 41))
      f:st(R.NCAND + cell, n + 1); inc(f, 3); f:ret(1)
    end)
    f:set(wi, 0); f:set(ws, 1 << 30)
    f:for_(k, 0, NC, function()
      f:set(sc, cs(f:ld(R.CST + cell * NC + k)))
      f:iff(sc:lt(ws), function() f:set(ws, sc); f:set(wi, k) end)
    end)
    f:st(R.CR0 + cell * NC + wi, R0); f:st(R.CR1 + cell * NC + wi, R1); f:st(R.CST + cell * NC + wi, (fit << 24) | (fit << 41))
    inc(f, 3)
    f:ret(1)
  end)
  -- induce candidate rules for cell (a, i) from the window
  P:func("h_induce", {"a", "i", "allow_post"}, function(f, a, i, allow_post)
    local Ma, n, Y, cell, k, c0 = f:var("Ma"), f:var("n"), f:var("Y"), f:var("cell"), f:var("k"), f:var("c0")
    inc(f, 1)
    f:set(Ma, f:call("h_cell_lanes", a, i)); f:set(n, f:call("h_pop", Ma))
    f:iff(n:eq(0), function() f:ret(0) end)
    f:set(Y, f:ld(R.WPOST + i)); f:set(cell, a * 4 + i)
    f:run("h_sigload")
    -- persistence fit on the window
    f:set(c0, f:call("h_pop", f:call("h_eqf", f:ld(R.WPRE + i), Y) & Ma))
    f:st(R.PST + cell, f:call("h_withscore", (f:ld(R.PST + cell) & ((GL.lift(255) << 24) ~ -1)) | ((c0 * 100 // n) << 24)))
    -- reuse: other actions' rules for the same field that already explain this action's samples
    local b2 = f:var("b2")
    f:for_(b2, 0, f:ld(R.NA), function()
      f:iff(b2:ne(a), function()
        f:for_(k, 0, f:ld(R.NCAND + b2 * 4 + i), function()
          f:set(c0, f:call("h_pop", f:call("h_eqf", f:call("h_rsg", f:ld(R.CR0 + (b2 * 4 + i) * NC + k), f:ld(R.CR1 + (b2 * 4 + i) * NC + k)), Y) & Ma))
          f:iff(c0:eq(n), function() f:run("h_insert", cell, f:ld(R.CR0 + (b2 * 4 + i) * NC + k), f:ld(R.CR1 + (b2 * 4 + i) * NC + k), 100) end)
        end)
      end)
    end)
    -- reuse: stored programs of the same field from every remembered world explain these lanes
    local w, a3 = f:var("w"), f:var("a3")
    f:iff(GL.and_(f:ld(R.LIBON):ne(0), n:ge(2)), function()
      f:for_(w, 0, f:ld(R.LIBN), function()
        f:for_(a3, 0, 4, function()
          local base = f:var("lbase")
          f:set(base, 28 + (a3 * 4 + i) * 3)
          f:iff(((f:ld(R.LIB + w * LW + base + 2) >> 62) & 1):ne(0), function()
            f:set(c0, f:call("h_pop", f:call("h_eqf", f:call("h_rsg", f:ld(R.LIB + w * LW + base), f:ld(R.LIB + w * LW + base + 1)), Y) & Ma))
            f:iff(c0:eq(n), function() f:run("h_insert", cell, f:ld(R.LIB + w * LW + base), f:ld(R.LIB + w * LW + base + 1), 100) end)
          end)
        end)
      end)
    end)
    -- exogenous post-step values are legitimate operands whenever any field has been classified as exogenous
    f:iff((f:ld(R.EXO) | f:ld(R.EXO + 1) | f:ld(R.EXO + 2) | f:ld(R.EXO + 3)):ne(0), function() f:set(allow_post, 1) end)
    f:run("h_mkbases", i, allow_post, Ma)
    local rel = f:var("rel", 0)
    f:set(rel, (f:ld(R.REL) >> i) & 1)
    f:run("h_ladder", Y, Ma, i, 2)
    f:set(c0, f:ld(R.BC)); f:set(n, f:ld(R.NCUR))
    f:iff(n:eq(0), function() f:ret(0) end)
    local T0, ec, e0, e1, nexr = f:var("T0", f:ld(R.BT)), f:var("ec", -1), f:var("e0"), f:var("e1"), f:var("nexr", 0)
    f:st(R.CIND + cell, f:ld(R.STEPN))
    local deep = f:var("deep", 0)
    f:iff(GL.and_(c0:lt(n), rel:ne(0), f:ld(R.STEPN):ge(f:ld(R.CBACK + cell)), f:ld(R.ECON):eq(0)), function() f:set(deep, 1) end)
    -- a state-conditional exception can explain what no single term does
    f:iff(GL.and_(deep:ne(0), n:ge(3), f:ld(R.EXCON):ne(0)), function()
      f:set(nexr, f:call("h_exc", Y, Ma & f:ld(R.KNOWN), i, T0))
      f:iff(nexr:gt(0), function()
        f:set(ec, f:ld(R.XC)); f:set(e0, f:ld(R.XR0)); f:set(e1, f:ld(R.XR1))
      end)
      f:st(R.BT, T0)
    end)
    -- otherwise deeper terms (goal-relevant cells only, exponential back-off after failures)
    -- terms are more parsimonious than several exceptions: search them when exceptions did not explain everything
    -- or needed two exceptions
    f:iff(GL.and_(deep:ne(0), GL.or_(ec:lt(n), nexr:ge(2)), GL.or_(n:lt(6), (c0 * 100):lt(n * f:ld(R.DEEPFIT)))), function()
      f:run("h_ladder", Y, Ma, i, 4)
      f:set(c0, f:ld(R.BC)); f:set(T0, f:ld(R.BT))
      f:iff(GL.and_(c0:lt(n), n:ge(4), f:ld(R.DEEPLVL):gt(0)), function()
        inc(f, 8); f:set(c0, f:call("h_deep", Y, Ma, i, n)); f:set(T0, f:ld(R.BT))
      end)
    end)
    f:iff(deep:ne(0), function()
      f:iff(GL.and_(c0:lt(n), ec:lt(n)), function()
        f:st(R.CFAIL + cell, f:ld(R.CFAIL + cell) + 1)
        f:iff(f:ld(R.CFAIL + cell):gt(4), function() f:st(R.CFAIL + cell, 4) end)
        f:st(R.CBACK + cell, f:ld(R.STEPN) + (GL.lift(4) << f:ld(R.CFAIL + cell)))
      end, function() f:st(R.CFAIL + cell, 0) end)
    end)
    f:iff(ec:gt(c0), function() f:run("h_insert", cell, e0, e1, ec * 100 // n - 4 * nexr) end)
    f:run("h_insert", cell, T0, 0, c0 * 100 // n)
    f:ret(1)
  end)

  ------------------------------------------------------------------ reward model, relevance, prospective learning
  mem("SHAPE"); mem("REXO"); mem("ULAG"); mem("TCK", 256); mem("TCV", 256); mem("PLNLEN"); mem("PLNPOS"); mem("PLNACT", 8); mem("PLNKEY", 9); mem("BESTS", 16); mem("RTAB", 16); mem("BESTK", 16); mem("TRIED", 4); mem("RECENT", 8); mem("RPOS"); mem("DIRTY")
  P:func("h_tc_clear", {}, function(f)
    f:st(R.TGEN, f:ld(R.TGEN) + 1)
    f:st(R.PLNLEN, 0)
  end)
  -- hash of an observation ignoring exogenous (noise) fields: the identity of a state for visit counting
  P:func("h_vkey", {"addr"}, function(f, addr)
    local k = f:var("k", 0)
    for j = 0, 3 do
      f:set(k, k * 9 + (f:ld(addr + j) + 1) * (f:ld(R.EXO + j) ~ 1))
    end
    f:ret((k * 7 + (k >> 5)) & 63)
  end)
  P:func("h_visit", {"addr"}, function(f, addr)
    local i = f:var("i", f:call("h_vkey", addr))
    f:iff(f:ld(R.VIS + i):lt(255), function() f:st(R.VIS + i, f:ld(R.VIS + i) + 1) end)
  end)
  -- a state-action pair was tried: the state is the one the action started from
  P:func("h_visit_sa", {"addr", "a"}, function(f, addr, a)
    local i = f:var("i", f:call("h_vkey", addr) * 4 + a)
    f:iff(f:ld(R.VISA + i):lt(255), function() f:st(R.VISA + i, f:ld(R.VISA + i) + 1) end)
  end)
  -- total distance of an observation array to the goal vector (-1 when no goal field or a goal field is unknown)
  P:func("h_gdist", {"addr"}, function(f, addr)
    local i, d, ng, v = f:var("i"), f:var("d", 0), f:var("ng", 0), f:var("v")
    f:for_(i, 0, f:ld(R.NF), function()
      f:iff(f:ld(R.GOAL + i):ge(0), function()
        f:set(v, f:ld(addr + i))
        f:iff(v:lt(0), function() f:ret(-1) end)
        f:set(v, v - f:ld(R.GOAL + i)); f:iff(v:lt(0), function() f:set(v, 0 - v) end)
        f:set(d, d + v); f:set(ng, ng + 1)
      end)
    end)
    f:iff(ng:eq(0), function() f:ret(-1) end)
    f:iff(d:gt(15), function() f:set(d, 15) end)           -- the reward table has 16 entries; larger distances share the last
    f:ret(d)
  end)
  -- expected reward of reaching an observation: learned table by goal distance, optimistic at the goal, interpolated
  -- between observed distances, plus a small progress shaping term
  P:func("h_rpred", {"addr"}, function(f, addr)
    local d, k, lo, hi, v = f:var("d", f:call("h_gdist", addr)), f:var("k"), f:var("lo", -1), f:var("hi", -1), f:var("v")
    f:iff(d:lt(0), function() f:ret(0) end)
    f:set(v, f:ld(R.RTAB + d))
    f:iff(v:lt(0), function()
      f:iff(d:eq(0), function() f:set(v, 256) end, function()
        f:set(k, d - 1)
        f:while_(GL.and_(k:ge(0), lo:lt(0)), function() f:iff(f:ld(R.RTAB + k):ge(0), function() f:set(lo, k) end); f:set(k, k - 1) end)
        f:set(k, d + 1)
        f:while_(GL.and_(k:lt(15), hi:lt(0)), function() f:iff(f:ld(R.RTAB + k):ge(0), function() f:set(hi, k) end); f:set(k, k + 1) end)
        f:iff(GL.and_(lo:ge(0), hi:ge(0)), function()
          f:set(v, (f:ld(R.RTAB + lo) * (hi - d) + f:ld(R.RTAB + hi) * (d - lo)) // (hi - lo))
        end, function()
          f:iff(lo:ge(0), function() f:set(v, f:ld(R.RTAB + lo)) end, function()
            f:iff(hi:ge(0), function() f:set(v, f:ld(R.RTAB + hi)) end, function() f:set(v, 0) end)
          end)
        end)
      end)
    end)
    f:ret(v + (f:ld(R.SHAPE) * (14 - d)) // 2)
  end)
  P:func("h_supd", {"st", "hit"}, function(f, st, hit)
    local h, t, s = f:var("h", st & 255), f:var("t", (st >> 8) & 255), f:var("s", (st >> 16) & 255)
    f:set(t, t + 1)
    f:iff(hit:ne(0), function() f:set(h, h + 1); f:iff(s:lt(255), function() f:set(s, s + 1) end) end, function() f:set(s, 0) end)
    f:iff(t:ge(12), function() f:set(t, t // 2); f:set(h, h // 2) end)
    f:ret(f:call("h_withscore", (st & ((GL.lift(0xFFFFFF)) ~ -1)) | h | (t << 8) | (s << 16)))
  end)

  -- refresh the cached best-candidate index of every cell
  P:func("h_refresh_best", {}, function(f)
    local c = f:var("c")
    f:for_(c, 0, 16, function() f:st(R.BESTK + c, f:call("h_best", c)) end)
  end)

  -- field mask referenced by a (simple or nested) term
  P:func("h_trefs", {"T"}, function(f, T)
    local m, b = f:var("m", 0), f:var("b")
    local function ref()
      f:iff(b:lt(8), function() f:set(m, m | (GL.lift(1) << ((b & 3) + ((b >> 2) << 2)))) end)
      f:iff(GL.and_(b:ge(9), b:le(12)), function() f:set(m, m | 256) end)         -- reads an exogenous post-step value
    end
    f:set(b, (T >> 4) & 31); ref()
    f:iff((T & 15):eq(0), function() f:ret(m) end)
    f:set(b, (T >> 9) & 31); ref()
    f:iff(b:eq(31), function()
      f:set(b, (T >> 18) & 31); ref()
      f:set(b, (T >> 23) & 31); ref()
    end)
    f:ret(m)
  end)
  -- fields that matter: goal fields and everything the current best rules of those fields read
  P:func("h_relevant", {}, function(f)
    local rel, ch, a, i, c, bk, R0, m = f:var("rel", 0), f:var("ch", 1), f:var("a"), f:var("i"), f:var("c"), f:var("bk"), f:var("R0"), f:var("m")
    local lagm, rpost = f:var("lagm", 0), f:var("rpost", 0)
    f:for_(i, 0, f:ld(R.NF), function() f:iff(f:ld(R.GOAL + i):ge(0), function() f:set(rel, rel | (GL.lift(1) << i)) end) end)
    f:while_(ch:ne(0), function()
      f:set(ch, 0)
      f:for_(i, 0, f:ld(R.NF), function()
        f:iff(((rel >> i) & 1):ne(0), function()
          f:for_(a, 0, f:ld(R.NA), function()
            f:set(c, a * 4 + i); f:set(bk, f:ld(R.BESTK + c))
            f:iff(bk:ge(0), function()
              f:set(R0, f:ld(R.CR0 + c * NC + bk))
              f:set(m, f:call("h_trefs", R0 & 0xFFFFFFF))
              f:iff(((R0 >> 60) & 3):ge(1), function()
                f:set(m, m | f:call("h_trefs", (R0 >> 28) & 16383) | f:call("h_trefs", (R0 >> 42) & 16383))
              end)
              f:iff(((R0 >> 60) & 3):ge(2), function()
                f:set(m, m | f:call("h_trefs", f:ld(R.CR1 + c * NC + bk) & 16383) | f:call("h_trefs", (f:ld(R.CR1 + c * NC + bk) >> 14) & 16383))
              end)
              f:set(lagm, lagm | ((m >> 4) & 15)); f:set(rpost, rpost | ((m >> 8) & 1)); f:set(m, m & 15)
              f:iff((m & (rel ~ -1)):ne(0), function() f:set(rel, rel | m); f:set(ch, 1) end)
            end)
          end)
        end)
      end)
    end)
    f:st(R.REL, rel); f:st(R.ULAG, lagm); f:st(R.RPOST, rpost)
    f:st(R.RELN, 0)
    f:for_(i, 0, f:ld(R.NF), function()
      f:iff(((rel >> i) & 1):ne(0), function() f:st(R.RELL + f:ld(R.RELN), i); f:st(R.RELN, f:ld(R.RELN) + 1) end)
    end)
    f:run("h_tc_clear")
    f:set(m, 0)
    f:for_(i, 0, f:ld(R.NF), function() f:iff(f:ld(R.EXO + i):ne(0), function() f:set(m, m | (GL.lift(1) << i)) end) end)
    f:st(R.REXO, rel & m)
  end)

  -- process one real transition: PREV --(LASTACT)--> OBS, with lag LAG
  P:func("h_learn", {}, function(f)
    local a, i, cell, k, bk, missed, ph, surprised, pv, hit = f:var("a", f:ld(R.LASTACT)), f:var("i"), f:var("cell"), f:var("k"), f:var("bk"), f:var("missed"), f:var("ph"), f:var("surprised", 0), f:var("pv"), f:var("hit")
    local d, nc, st, j = f:var("d"), f:var("nc"), f:var("st"), f:var("j")
    inc(f, 0)
    -- empirical reliability of the forecasts we issue: valid fields of the previous forecast against what happened
    local fi = f:var("fi")
    f:for_(fi, 0, f:ld(R.NF), function()
      f:iff(GL.and_(((f:ld(R.FC + 11) >> fi) & 1):ne(0), f:ld(R.OBS + fi):ge(0)), function()
        f:st(R.FTOT, f:ld(R.FTOT) + 1)
        f:iff(f:ld(R.FC + 2 + fi):eq(f:ld(R.OBS + fi)), function() f:st(R.FOK, f:ld(R.FOK) + 1) end)
      end)
    end)
    f:iff(f:ld(R.FTOT):ge(40), function() f:st(R.FTOT, f:ld(R.FTOT) // 2); f:st(R.FOK, f:ld(R.FOK) // 2) end)
    f:st(R.STEPN, f:ld(R.STEPN) + 1)
    f:st(R.RSUM, f:ld(R.RSUM) + f:ld(R.LASTREW))
    f:st(R.TRIED + a, f:ld(R.TRIED + a) + 1)
    f:st(R.RECENT + f:ld(R.RPOS), a); f:st(R.RPOS, (f:ld(R.RPOS) + 1) & 7)
    f:iff(f:ld(R.LASTREW):gt(0), function() f:st(R.STAG, 0) end, function() f:st(R.STAG, f:ld(R.STAG) + 1) end)
    f:set(d, f:call("h_gdist", R.OBS))
    f:iff(d:ge(0), function() f:st(R.RTAB + d, f:ld(R.LASTREW)) end)
    -- model-free evidence: outcome (reward plus goal progress) by action and by every pre-state field value
    local o, dp, b = f:var("o"), f:var("dp"), f:var("b")
    f:set(o, f:ld(R.LASTREW) // 16); f:set(dp, f:call("h_gdist", R.PREV))
    f:iff(GL.and_(dp:ge(0), d:ge(0)), function() f:set(o, o + (dp - d) * 8) end)
    f:set(b, a * 33)
    f:st(R.CBS + b + 32, f:ld(R.CBS + b + 32) + o); f:st(R.CBN + b + 32, f:ld(R.CBN + b + 32) + 1)
    f:for_(j, 0, f:ld(R.NF), function()
      f:iff(f:ld(R.PREV + j):ge(0), function()
        f:set(cell, b + j * 8 + f:ld(R.PREV + j))
        f:st(R.CBS + cell, f:ld(R.CBS + cell) + o); f:st(R.CBN + cell, f:ld(R.CBN + cell) + 1)
      end)
    end)
    f:for_(j, 0, 4, function()
      f:st(R.CTX + j, f:ld(R.PREV + j)); f:st(R.CTX + 4 + j, f:ld(R.LAG + j)); f:st(R.CTX + 9 + j, f:ld(R.OBS + j))
    end)
    f:st(R.CTX + 8, a)
    f:for_(i, 0, f:ld(R.NF), function()
      f:iff(f:ld(R.OBS + i):ge(0), function()
        f:set(cell, a * 4 + i); f:set(bk, f:ld(R.BESTK + cell)); f:set(missed, 0)
        f:set(nc, f:ld(R.NCAND + cell))
        f:for_(k, 0, nc, function()
          -- rules of fields nobody depends on are judged by their best candidate only
          f:iff(GL.or_(((f:ld(R.REL) >> i) & 1):ne(0), k:eq(bk)), function()
            f:set(pv, f:call("h_rev", f:ld(R.CR0 + cell * NC + k), f:ld(R.CR1 + cell * NC + k)))
            f:set(hit, pv:eq(f:ld(R.OBS + i)))
            f:iff(GL.and_(k:eq(bk), hit:eq(0)), function() f:set(missed, 1) end)
            f:set(st, f:call("h_supd", f:ld(R.CST + cell * NC + k), hit))
            -- library-seeded assumptions that fail their first tests are removed
            f:iff(GL.and_(((st >> 32) & 1):ne(0), hit:eq(0)), function()
              f:iff(((st >> 33) & 7):lt(7), function() f:set(st, st + (GL.lift(1) << 33)) end)
              f:iff(GL.and_(((st >> 33) & 7):ge(2), (st & 255):le((st >> 36) & 15)), function() f:set(st, st | (GL.lift(1) << 40)) end)
            end)
            f:st(R.CST + cell * NC + k, st)
          end)
        end)
        f:set(ph, f:ld(R.PREV + i):eq(f:ld(R.OBS + i)))
        f:st(R.PST + cell, f:call("h_supd", f:ld(R.PST + cell), ph))
        f:iff(GL.and_(bk:lt(0), ph:eq(0)), function() f:set(missed, 1) end)
        f:st(R.PTEST + i, f:ld(R.PTEST + i) + 1)
        f:iff(missed:eq(0), function() f:st(R.PHIT + i, f:ld(R.PHIT + i) + 1); f:st(R.CMISS + cell, 0) end, function() f:st(R.CMISS + cell, f:ld(R.CMISS + cell) + 1) end)
        f:iff(f:ld(R.PTEST + i):ge(16), function() f:st(R.PTEST + i, f:ld(R.PTEST + i) // 2); f:st(R.PHIT + i, f:ld(R.PHIT + i) // 2) end)
        f:iff(GL.or_(missed:ne(0), GL.and_(nc:eq(0), ph:eq(0))), function() f:set(surprised, surprised | (GL.lift(1) << i)); inc(f, 4) end)
      end)
    end)
    -- remove failed seeded assumptions (flag bit 40)
    f:for_(i, 0, f:ld(R.NF), function()
      f:set(cell, a * 4 + i); f:set(k, 0)
      f:while_(k:lt(f:ld(R.NCAND + cell)), function()
        f:iff(((f:ld(R.CST + cell * NC + k) >> 40) & 1):ne(0), function()
          -- a recognised world whose rules fail their first tests is not that world after all: explore again
          f:st(R.RESTORED, 0)
          f:set(nc, f:ld(R.NCAND + cell) - 1)
          f:st(R.CR0 + cell * NC + k, f:ld(R.CR0 + cell * NC + nc)); f:st(R.CR1 + cell * NC + k, f:ld(R.CR1 + cell * NC + nc))
          f:st(R.CST + cell * NC + k, f:ld(R.CST + cell * NC + nc)); f:st(R.NCAND + cell, nc)
        end, function() f:set(k, k + 1) end)
      end)
    end)
    f:run("h_win_add", a)
    f:run("h_visit", R.OBS)
    f:run("h_visit_sa", R.PREV, a)

    -- targeted re-induction of exactly the cells whose best assumption just failed
    f:for_(i, 0, f:ld(R.NF), function()
      f:iff(GL.and_(((surprised >> i) & 1):ne(0), f:ld(R.EXO + i):eq(0)), function()
        -- noisy cells are not re-induced on every miss; a miss after a hit run signals a real change
        f:set(cell, a * 4 + i)
        f:iff(GL.or_(f:ld(R.BESTK + cell):lt(0), GL.and_(GL.or_(f:ld(R.BESTS + cell):lt(f:ld(R.REINDS)), f:ld(R.CMISS + cell):ge(f:ld(R.REINDM))),
              GL.or_(f:ld(R.STEPN):ge(f:ld(R.CIND + cell) + 2), ((f:ld(R.CST + cell * NC + f:ld(R.BESTK + cell)) >> 16) & 255):ge(3)))), function()
          f:run("h_induce", a, i, 0)
        end)
      end)
    end)
    -- fields that no rule can predict prospectively are exogenous (never goal fields)
    f:set(d, 0)
    f:set(cell, 0)
    f:for_(i, 0, f:ld(R.NF), function()
      f:iff(GL.and_(f:ld(R.EXOON):ne(0), f:ld(R.GOAL + i):lt(0), f:ld(R.EXO + i):eq(0), f:ld(R.PTEST + i):ge(8), (f:ld(R.PHIT + i) * 3):lt(f:ld(R.PTEST + i))), function()
        f:st(R.EXO + i, 1); f:set(d, 1)
      end)
    end)
    f:iff(d:ne(0), function()
      f:for_(i, 0, f:ld(R.NF), function()
        f:iff(GL.and_(((surprised >> i) & 1):ne(0), f:ld(R.EXO + i):eq(0)), function() f:run("h_induce", a, i, 1) end)
      end)
    end)
    -- refresh the cached best candidates of the cells that just changed
    f:for_(i, 0, f:ld(R.NF), function()
      f:set(cell, a * 4 + i); f:set(bk, f:call("h_best", cell))
      f:iff(bk:ne(f:ld(R.BESTK + cell)), function() f:set(d, 1) end)
      f:st(R.BESTK + cell, bk); f:st(R.BESTS + cell, f:ld(R.BS))
    end)
    f:iff(d:ne(0), function() f:run("h_relevant") end)
  end)

  ------------------------------------------------------------------ initialisation, episode boundaries, world library
  mem("PLIM"); mem("OBS0", 4); mem("EPCOUNT"); mem("EB"); mem("MINTRY"); mem("PLAND"); mem("STAGW")

  P:func("h_init", {}, function(f)
    local c, j = f:var("c"), f:var("j")
    f:for_(j, 0, 16, function() f:st(R.RTAB + j, -1) end)
    f:for_(j, 0, 8, function() f:st(R.CTX + 16 + j, j); f:st(R.SIG + 16 + j, j * ONES) end)
    f:for_(c, 0, 16, function()
      f:st(R.NCAND + c, 0); f:st(R.PST + c, (GL.lift(100) << 24) | (GL.lift(100) << 41)); f:st(R.BESTK + c, -1); f:st(R.BESTS + c, 100); f:st(R.CBACK + c, 0); f:st(R.CFAIL + c, 0); f:st(R.CIND + c, -9); f:st(R.CMISS + c, 0)
    end)
    f:for_(j, 0, 4, function() f:st(R.EXO + j, 0); f:st(R.PTEST + j, 0); f:st(R.PHIT + j, 0); f:st(R.TRIED + j, 0) end)
    f:st(R.LIBN, 0); f:st(R.EPCOUNT, 0); f:st(R.HAVE, 0); f:st(R.CBON, cfg.cb == 0 and 0 or 1); f:st(R.CHON, cfg.chance == 0 and 0 or 1); f:st(R.DEEPFIT, cfg.deepfit or 60); f:st(R.REINDS, cfg.reinds or 65); f:st(R.REINDM, cfg.reindm or 2); f:st(R.DFREE, cfg.dfree or 0); f:st(R.ECOTHR, cfg.ecothr or 14000); f:st(R.UCAL, cfg.ucal == 0 and 0 or 1); f:st(R.NOVB, cfg.novelty == 0 and 0 or (cfg.novb or 32)); f:st(R.DELIBQ, cfg.delibq or 96); f:st(R.CBW, cfg.cbw or 16); f:st(R.SIMSTRONG, cfg.simstrong or 6); f:st(R.CBSPREAD, cfg.cbspread or 32); f:st(R.CBMIN, cfg.cbmin or 3)
    f:st(R.SHAPE, cfg.shape or 4); f:st(R.EB, cfg.explore == 0 and 0 or (cfg.eb or 40)); f:st(R.MINTRY, cfg.explore == 0 and 0 or (cfg.mintry or 2))
    f:st(R.EXCON, cfg.exc == 0 and 0 or 1); f:st(R.LIBON, cfg.lib == 0 and 0 or 1); f:st(R.EXOON, cfg.exo == 0 and 0 or 1); f:st(R.EBADAPT, cfg.ebadapt == 1 and 1 or 0); f:st(R.PLAND, cfg.depth or 6); f:st(R.STAGW, cfg.explore == 0 and 0 or (cfg.stagw or 16)); f:st(R.DEEPLVL, cfg.deeplvl or 4)
    f:run("h_win_clear")
  end)

  P:func("h_best_cache", {}, function(f)
    local c = f:var("c")
    f:for_(c, 0, 16, function() f:st(R.BESTK + c, f:call("h_best", c)); f:st(R.BESTS + c, f:ld(R.BS)) end)
  end)

  -- keep the best rules of the finished episode as a world in the library (most recent first, three worlds)
  P:func("h_snapshot", {}, function(f)
    local c, w, any, base, bk, j, st = f:var("c"), f:var("w"), f:var("any", 0), f:var("base"), f:var("bk"), f:var("j"), f:var("st")
    f:iff(f:ld(R.EPCOUNT):eq(0), function() f:ret(0) end)
    f:for_(w, 0, 2, function()                       -- shift worlds down: 1 <- 0, 2 <- 1 (copy in descending order)
      local src = 1 - w
      f:for_(j, 0, LW, function() f:st(R.LIB + (src + 1) * LW + j, f:ld(R.LIB + src * LW + j)) end)
      f:st(R.LIBAGE + src + 1, f:ld(R.LIBAGE + src))
    end)
    f:for_(j, 0, 4, function()
      f:st(R.LIB + j, f:ld(R.GOAL + j)); f:st(R.LIB + 4 + j, f:ld(R.OBS0 + j)); f:st(R.LIB + 8 + j, f:ld(R.EXO + j))
    end)
    f:for_(j, 0, 16, function() f:st(R.LIB + 12 + j, f:ld(R.RTAB + j)) end)
    f:for_(c, 0, 16, function()
      f:set(base, 28 + c * 3); f:set(bk, f:ld(R.BESTK + c)); f:st(R.LIB + base + 2, 0)
      f:iff(bk:ge(0), function()
        f:set(st, f:ld(R.CST + c * NC + bk))
        f:iff(GL.and_(((st >> 8) & 255):ge(2), f:ld(R.BESTS + c):ge(60)), function()
          f:st(R.LIB + base, f:ld(R.CR0 + c * NC + bk)); f:st(R.LIB + base + 1, f:ld(R.CR1 + c * NC + bk))
          f:st(R.LIB + base + 2, (st & 65535) | (GL.lift(1) << 62)); f:set(any, 1)
        end)
      end)
    end)
    f:iff(any:ne(0), function()
      f:st(R.LIBAGE, f:ld(R.EPCOUNT)); f:iff(f:ld(R.LIBN):lt(3), function() f:st(R.LIBN, f:ld(R.LIBN) + 1) end)
    end, function()
      -- nothing worth keeping: undo the shift so older worlds survive
      f:for_(w, 0, 2, function()
        f:for_(j, 0, LW, function() f:st(R.LIB + w * LW + j, f:ld(R.LIB + (w + 1) * LW + j)) end)
        f:st(R.LIBAGE + w, f:ld(R.LIBAGE + w + 1))
      end)
    end)
  end)

  -- similarity of a world's context fingerprint (goal vector + first observation) to the current episode start
  P:func("h_sim", {"w"}, function(f, w)
    local s, j = f:var("s", 0), f:var("j")
    f:for_(j, 0, 4, function()
      f:iff(f:ld(R.LIB + w * LW + j):eq(f:ld(R.GOAL + j)), function() f:set(s, s + 1) end)
      f:iff(f:ld(R.LIB + w * LW + 4 + j):eq(f:ld(R.OBS + j)), function() f:set(s, s + 1) end)
    end)
    f:ret(s)
  end)
  -- offer a stored rule to a cell as a tentative, library-seeded hypothesis
  P:func("h_offer", {"cell", "R0", "R1", "pri"}, function(f, cell, R0, R1, pri)
    local n, k, wi, ws, sc, st = f:var("n", f:ld(R.NCAND + cell)), f:var("k"), f:var("wi"), f:var("ws"), f:var("sc"), f:var("st")
    inc(f, 9)
    f:for_(k, 0, n, function()
      f:iff(GL.and_(f:ld(R.CR0 + cell * NC + k):eq(R0), f:ld(R.CR1 + cell * NC + k):eq(R1)), function() f:ret(0) end)
    end)
    -- prior: hit = pri, test = pri (or 2 when weak), seeded flag, remembered prior hits
    local test = f:var("test", 2)
    f:iff(pri:ge(4), function() f:set(test, 4) end)
    f:set(st, f:call("h_withscore", pri | (test << 8) | (GL.lift(100) << 24) | (GL.lift(1) << 32) | (pri << 36)))
    f:iff(n:lt(NC), function()
      f:st(R.CR0 + cell * NC + n, R0); f:st(R.CR1 + cell * NC + n, R1); f:st(R.CST + cell * NC + n, st); f:st(R.NCAND + cell, n + 1)
      f:ret(1)
    end)
    f:set(wi, 0); f:set(ws, 1 << 30)
    f:for_(k, 0, NC, function()
      f:set(sc, cs(f:ld(R.CST + cell * NC + k)))
      f:iff(sc:lt(ws), function() f:set(ws, sc); f:set(wi, k) end)
    end)
    f:iff(cs(st):gt(ws), function()
      f:st(R.CR0 + cell * NC + wi, R0); f:st(R.CR1 + cell * NC + wi, R1); f:st(R.CST + cell * NC + wi, st)
      f:ret(1)
    end)
    f:ret(0)
  end)
  -- start of an episode = a context switch. Transient state is reset and the rule populations are cleared. When the
  -- library recognises the context (same goal vector and first observation) that world's rules, reward table and noise
  -- flags are restored as tentative hypotheses that are dropped if they fail their first tests; otherwise the new world
  -- starts clean and may still reuse stored programs through induction.
  P:func("h_new_episode", {}, function(f)
    local c, w, j, best, bsim, sim, rank, base, pri = f:var("c"), f:var("w"), f:var("j"), f:var("best", -1), f:var("bsim", -1), f:var("sim"), f:var("rank"), f:var("base"), f:var("pri")
    f:iff(f:ld(R.LIBON):ne(0), function() f:run("h_snapshot") end)
    f:run("h_win_clear")
    f:for_(j, 0, 4, function()
      f:st(R.TRIED + j, 0); f:st(R.OBS0 + j, f:ld(R.OBS + j)); f:st(R.EXO + j, 0); f:st(R.PTEST + j, 0); f:st(R.PHIT + j, 0)
    end)
    f:st(R.STAG, 0); f:st(R.RPOS, 0); f:st(R.STEPN, 0); f:st(R.RSUM, 0); f:st(R.DFAIL, 0); f:st(R.DBACK, 0)
    f:for_(j, 0, 64, function() f:st(R.VIS + j, 0) end)
    f:for_(j, 0, 256, function() f:st(R.VISA + j, 0) end)
    f:for_(j, 0, 132, function() f:st(R.CBS + j, 0); f:st(R.CBN + j, 0) end)
    f:for_(j, 0, 16, function() f:st(R.RTAB + j, -1) end)
    f:for_(c, 0, 16, function()
      f:st(R.NCAND + c, 0); f:st(R.PST + c, (GL.lift(100) << 24) | (GL.lift(100) << 41)); f:st(R.BESTK + c, -1); f:st(R.BESTS + c, 100)
      f:st(R.CBACK + c, 0); f:st(R.CFAIL + c, 0); f:st(R.CIND + c, -9); f:st(R.CMISS + c, 0)
    end)
    f:st(R.EPCOUNT, f:ld(R.EPCOUNT) + 1); f:st(R.RESTORED, 0)
    f:iff(GL.and_(f:ld(R.LIBN):gt(0), f:ld(R.LIBON):ne(0)), function()
      f:for_(w, 0, f:ld(R.LIBN), function()
        f:set(sim, f:call("h_sim", w))
        f:iff(sim:gt(bsim), function() f:set(bsim, sim); f:set(best, w) end)
      end)
      f:iff(bsim:ge(f:ld(R.SIMSTRONG)), function()
        inc(f, 11); f:st(R.RESTORED, 1)
        f:for_(j, 0, 4, function()
          f:iff(GL.and_(f:ld(R.LIB + best * LW + 8 + j):ne(0), f:ld(R.GOAL + j):lt(0)), function() f:st(R.EXO + j, 1) end)
        end)
        f:for_(j, 0, 16, function() f:st(R.RTAB + j, f:ld(R.LIB + best * LW + 12 + j)) end)
        -- recognised worlds in rank order: the most similar first (ties: most recent)
        local used = f:var("used", 0)
        f:for_(rank, 0, f:ld(R.LIBN), function()
          f:set(w, -1); f:set(bsim, -1)
          f:for_(j, 0, f:ld(R.LIBN), function()
            f:iff(((used >> j) & 1):eq(0), function()
              f:set(sim, f:call("h_sim", j))
              f:iff(sim:gt(bsim), function() f:set(bsim, sim); f:set(w, j) end)
            end)
          end)
          f:set(used, used | (GL.lift(1) << w))
          f:iff(bsim:ge(f:ld(R.SIMSTRONG)), function()
            f:iff(rank:eq(0), function() f:set(pri, 4) end, function() f:set(pri, 1) end)
            f:for_(c, 0, 16, function()
              f:set(base, 28 + c * 3)
              f:iff(((f:ld(R.LIB + w * LW + base + 2) >> 62) & 1):ne(0), function()
                f:run("h_offer", c, f:ld(R.LIB + w * LW + base), f:ld(R.LIB + w * LW + base + 1), pri)
              end)
            end)
          end)
        end)
      end)
    end)
    f:run("h_best_cache")
    f:run("h_relevant")
    f:run("h_visit", R.OBS)
  end)

  ------------------------------------------------------------------ planning
  mem("PS", 40); mem("MK", 64); mem("MV", 64); mem("FN", 4); mem("PRT", 4); mem("NXTFULL")
  -- predicted next observation of `act` from state (pre, lag), written to dst[0..3]
  P:func("h_next", {"act", "pre", "lag", "dst"}, function(f, act, pre, lag, dst)
    local j, i, cell, bk, k, nf = f:var("j"), f:var("i"), f:var("cell"), f:var("bk"), f:var("k"), f:var("nf", f:ld(R.NF))

    f:for_(j, 0, 4, function()
      f:st(R.CTX + j, f:ld(pre + j)); f:st(R.CTX + 4 + j, f:ld(lag + j)); f:st(R.CTX + 9 + j, f:ld(pre + j))
      f:iff(j:lt(nf), function() f:st(dst + j, f:ld(pre + j)) end, function() f:st(dst + j, -1) end)
    end)
    f:st(R.CTX + 8, act)
    local function field()
      f:iff(f:ld(R.EXO + i):eq(0), function()
        f:set(cell, act * 4 + i); f:set(bk, f:ld(R.BESTK + cell))
        f:iff(bk:ge(0), function()
          f:st(dst + i, f:call("h_rev", f:ld(R.CR0 + cell * NC + bk), f:ld(R.CR1 + cell * NC + bk)))
        end)

      end)
    end
    f:iff(f:ld(R.NXTFULL):ne(0), function()
      f:for_(i, 0, nf, field)
    end, function()
      f:for_(k, 0, f:ld(R.RELN), function() f:set(i, f:ld(R.RELL + k)); field() end)
    end)
  end)
  -- exploration bonus of an action in the current state: untried actions, disagreement among surviving hypotheses
  -- about goal-relevant fields, and stagnation
  P:func("h_bonus", {"a"}, function(f, a)
    local bonus, i, k, dis, cell, bs, n0, seen, v, cnt = f:var("bonus", 0), f:var("i"), f:var("k"), f:var("dis", 0), f:var("cell"), f:var("bs"), f:var("n0"), f:var("seen"), f:var("v"), f:var("cnt")
    -- exploration is worth less the more the current behaviour already earns per step
    local eb, avg = f:var("eb", f:ld(R.EB)), f:var("avg", f:ld(R.RSUM) // (f:ld(R.STEPN) + 1))
    f:iff(avg:gt(160), function() f:set(avg, 160) end)
    f:iff(f:ld(R.EBADAPT):ne(0), function() f:set(eb, eb - (eb * avg) // 200) end)
    f:iff(GL.and_(f:ld(R.TRIED + a):lt(f:ld(R.MINTRY)), f:ld(R.RESTORED):eq(0)), function() f:set(bonus, eb) end)
    f:iff(GL.and_(f:ld(R.STAGW):gt(0), f:ld(R.STAG):ge(6)), function()
      f:set(cnt, 0)
      f:for_(k, 0, 8, function() f:iff(f:ld(R.RECENT + k):eq(a), function() f:set(cnt, cnt + 1) end) end)
      f:iff(cnt:eq(0), function()
        f:set(v, f:ld(R.STAG) // 6); f:iff(v:gt(4), function() f:set(v, 4) end)
        f:set(bonus, bonus + f:ld(R.STAGW) * v)
      end)
    end)
    f:for_(i, 0, f:ld(R.NF), function()
      f:iff(GL.and_(((f:ld(R.REL) >> i) & 1):ne(0), f:ld(R.EXO + i):eq(0)), function()
        f:set(cell, a * 4 + i); f:set(bs, f:ld(R.BESTS + cell)); f:set(seen, 0); f:set(n0, 0)
        f:st(R.CTX + 8, a)
        f:for_(k, 0, f:ld(R.NCAND + cell), function()
          f:iff((cs(f:ld(R.CST + cell * NC + k)) * 100):ge(bs * 70), function()
            f:set(v, f:call("h_rev", f:ld(R.CR0 + cell * NC + k), f:ld(R.CR1 + cell * NC + k)))
            f:iff(v:ge(0), function()
              f:iff(((seen >> v) & 1):eq(0), function() f:set(seen, seen | (GL.lift(1) << v)); f:set(n0, n0 + 1) end)
            end)
          end)
        end)
        f:iff((cs(f:ld(R.PST + cell)) * 100):ge(bs * 70), function()
          f:set(v, f:ld(R.CTX + i))
          f:iff(v:ge(0), function() f:iff(((seen >> v) & 1):eq(0), function() f:set(seen, seen | (GL.lift(1) << v)); f:set(n0, n0 + 1) end) end)
        end)
        f:iff(n0:ge(2), function() f:set(dis, dis + 1) end)
      end)
    end)
    f:iff(dis:gt(2), function() f:set(dis, 2) end)
    f:ret(bonus + dis * (eb // 2))
  end)

  ------------------------------------------------------------------ forecast
  -- forecast words: [1]=event+1 [2]=action [3..6]=branch0 [7..10]=branch1 [11]=unknown mass [12..13]=valid masks

  P:func("h_forecast", {"a"}, function(f, a)
    local i, m, sum, cnt, u, bs, v = f:var("i"), f:var("m", 0), f:var("sum", 0), f:var("cnt", 0), f:var("u"), f:var("bs"), f:var("v")
    f:st(R.NXTFULL, 1)
    f:run("h_next", a, R.OBS, R.LAG, R.FN)
    f:st(R.NXTFULL, 0)
    f:st(R.FC, f:ld(R.EVENT) + 1); f:st(R.FC + 1, a)
    f:for_(i, 0, 4, function()
      f:st(R.FC + 2 + i, -1); f:st(R.FC + 6 + i, -1)
      f:iff(i:lt(f:ld(R.NF)), function()
        f:set(bs, f:ld(R.BESTS + a * 4 + i)); f:set(v, f:ld(R.FN + i))
        f:iff(GL.and_(f:ld(R.EXO + i):eq(0), v:ge(0), bs:ge(60)), function()
          f:st(R.FC + 2 + i, v); f:st(R.FC + 6 + i, v)
          f:set(m, m | (GL.lift(1) << i)); f:set(sum, sum + bs); f:set(cnt, cnt + 1)
        end)
      end)
    end)
    f:set(u, 96)
    f:iff(cnt:gt(0), function()
      f:set(u, 264 - (sum // cnt) * 256 // 100)
      -- once enough real outcomes are in, the unknown mass follows the measured accuracy of our own forecasts
      f:iff(GL.and_(f:ld(R.UCAL):ne(0), f:ld(R.FTOT):ge(8)), function()
        f:set(u, 8 + (100 - ((f:ld(R.FOK) * 100 + 280) // (f:ld(R.FTOT) + 4))) * 2)
      end)
    end)
    f:iff(u:lt(16), function() f:set(u, 16) end)
    f:iff(u:gt(160), function() f:set(u, 160) end)
    f:st(R.FC + 10, u); f:st(R.FC + 11, m); f:st(R.FC + 12, m)
  end)

  ------------------------------------------------------------------ planning by search over distinct predicted states
  -- Breadth-first expansion of the learned model from the current state (each distinct state expanded once, bounded by
  -- MAXS), then finite-horizon value iteration over the discovered graph. The cost follows the number of distinct states,
  -- not the branching depth. Transitions are cached until the model changes, and a found multi-step plan is followed
  -- while real observations keep matching its predictions.
  local MAXS = 24
  mem("GKEY", MAXS); mem("GPRE", MAXS * 4); mem("GLAG", MAXS * 4); mem("GSUCC", MAXS * 4); mem("GREW", MAXS * 4)
  mem("GDEP", MAXS); mem("GVK", MAXS); mem("GV", MAXS); mem("GH", 64); mem("NGS"); mem("QV", 4); mem("GTMP", 4)
  local NEG = -(1 << 40)
  P:func("h_gkey", {"pre"}, function(f, pre)
    local k, j = f:var("k", 0), f:var("j")
    f:for_(j, 0, 4, function() f:set(k, k * 9 + f:ld(pre + j) + 1) end)
    f:ret(k)
  end)
  -- cached model transition (state -> predicted successor); lag-dependent rules bypass the cache
  P:func("h_tnext", {"act", "pre", "lag", "dst"}, function(f, act, pre, lag, dst)
    local key, idx, v, j = f:var("key"), f:var("idx"), f:var("v"), f:var("j")
    f:iff(f:ld(R.ULAG):ne(0), function() f:run("h_next", act, pre, lag, dst); f:ret(0) end)
    f:set(key, (f:ld(R.TGEN) << 16) | (f:call("h_gkey", pre) * 4 + act + 1))
    f:set(idx, (key * 13 + (key >> 6)) & 255)
    f:iff(f:ld(R.TCK + idx):eq(key), function()
      f:set(v, f:ld(R.TCV + idx))
      f:for_(j, 0, 4, function() f:st(dst + j, ((v >> (j << 2)) & 15) - 1) end)
      f:ret(1)
    end)
    f:run("h_next", act, pre, lag, dst)
    f:set(v, 0)
    f:for_(j, 0, 4, function() f:set(v, v | ((f:ld(dst + j) + 1) << (j << 2))) end)
    f:st(R.TCK + idx, key); f:st(R.TCV + idx, v)
    f:ret(0)
  end)
  -- state index for (pre, lag, key); adds the state when absent and capacity remains, else returns -1
  P:func("h_gstate", {"pre", "lag", "key", "dep"}, function(f, pre, lag, key, dep)
    local h, e, j, n = f:var("h", (key * 7 + (key >> 5)) & 63), f:var("e"), f:var("j"), f:var("n")
    f:set(e, f:ld(R.GH + h))
    f:while_((e >> 8):eq(f:ld(R.BGEN)), function()
      f:iff(f:ld(R.GKEY + (e & 255) - 1):eq(key), function() f:ret((e & 255) - 1) end)
      f:set(h, (h + 1) & 63); f:set(e, f:ld(R.GH + h))
    end)
    f:set(n, f:ld(R.NGS))
    f:iff(n:ge(MAXS), function() f:ret(-1) end)
    f:st(R.GH + h, (f:ld(R.BGEN) << 8) | (n + 1)); f:st(R.GKEY + n, key); f:st(R.GDEP + n, dep); f:st(R.GVK + n, f:call("h_vkey", pre))
    f:for_(j, 0, 4, function() f:st(R.GPRE + n * 4 + j, f:ld(pre + j)); f:st(R.GLAG + n * 4 + j, f:ld(lag + j)) end)
    f:st(R.NGS, n + 1)
    f:ret(n)
  end)
  -- value of every root action over a horizon of H steps; leaves QV[a] (NEG for unsafe actions)
  P:func("h_bfs", {"H"}, function(f, H)
    local s, a, idx, r, it, best, v, j, chg = f:var("s"), f:var("a"), f:var("idx"), f:var("r"), f:var("it"), f:var("best"), f:var("v"), f:var("j"), f:var("chg")
    f:st(R.BGEN, f:ld(R.BGEN) + 1)
    f:st(R.NGS, 0)
    f:run("h_gstate", R.OBS, R.LAG, f:call("h_gkey", R.OBS), 0)
    f:set(s, 0)
    f:while_(s:lt(f:ld(R.NGS)), function()
      f:for_(a, 0, f:ld(R.NA), function()
        f:st(R.GSUCC + s * 4 + a, -1); f:st(R.GREW + s * 4 + a, 0)
        f:iff(GL.and_(f:ld(R.GDEP + s):lt(H), GL.or_(s:ne(0), ((f:ld(R.SAFE) >> a) & 1):ne(0))), function()
          inc(f, 6)
          f:run("h_tnext", a, R.GPRE + s * 4, R.GLAG + s * 4, R.GTMP)
          f:iff(s:eq(0), function() f:for_(j, 0, 4, function() f:st(R.RNX + a * 4 + j, f:ld(R.GTMP + j)) end) end)
          f:st(R.GREW + s * 4 + a, f:call("h_rpred", R.GTMP))
          -- intrinsic reward for predicted transitions into rarely visited states (stronger while nothing is rewarded)
          f:iff(f:ld(R.NOVB):ne(0), function()
            -- novelty of the state-action pair being taken, plus half as much for the state it leads to
            f:set(v, f:ld(R.VISA + f:ld(R.GVK + s) * 4 + a))
            f:set(j, f:ld(R.NOVB))
            f:iff(f:ld(R.STAG):ge(6), function() f:set(j, j * 2) end)
            f:iff(v:lt(5), function() f:set(v, j >> v) end, function() f:set(v, 0) end)
            f:set(idx, f:ld(R.VIS + f:call("h_vkey", R.GTMP)))
            f:iff(idx:lt(3), function() f:set(v, v + ((j >> idx) >> 1)) end)
            f:st(R.GREW + s * 4 + a, f:ld(R.GREW + s * 4 + a) + v)
          end)
          f:iff(f:ld(R.GDEP + s):lt(H - 1), function()
            f:set(idx, f:call("h_gstate", R.GTMP, R.GPRE + s * 4, f:call("h_gkey", R.GTMP), f:ld(R.GDEP + s) + 1))
            f:st(R.GSUCC + s * 4 + a, idx)
          end)
        end)
      end)
      f:set(s, s + 1)
    end)
    -- finite-horizon value iteration (in place; values only grow, so H sweeps suffice)
    f:for_(j, 0, f:ld(R.NGS), function() f:st(R.GV + j, 0) end)
    f:set(chg, 1)
    f:for_(it, 0, H, function()
      f:iff(chg:ne(0), function()
        f:set(chg, 0)
        f:set(s, f:ld(R.NGS) - 1)
        f:while_(s:ge(0), function()
          f:iff(f:ld(R.GDEP + s):lt(H), function()
            f:set(best, NEG)
            f:for_(a, 0, f:ld(R.NA), function()
              f:iff(GL.or_(s:ne(0), ((f:ld(R.SAFE) >> a) & 1):ne(0)), function()
                f:set(v, f:ld(R.GREW + s * 4 + a))
                f:set(idx, f:ld(R.GSUCC + s * 4 + a))
                f:iff(idx:ge(0), function() f:set(v, v + (f:ld(R.GV + idx) * 9) // 10) end)
                f:iff(v:gt(best), function() f:set(best, v) end)
              end)
            end)
            f:iff(best:gt(NEG), function()
              f:iff(best:ne(f:ld(R.GV + s)), function() f:set(chg, 1); f:st(R.GV + s, best) end)
            end)
          end)
          f:set(s, s - 1)
        end)
      end)
    end)
    f:for_(a, 0, 4, function()
      f:st(R.QV + a, NEG)
      f:iff(GL.and_(a:lt(f:ld(R.NA)), ((f:ld(R.SAFE) >> a) & 1):ne(0)), function()
        f:set(v, f:ld(R.GREW + a))
        f:set(idx, f:ld(R.GSUCC + a))
        f:iff(idx:ge(0), function() f:set(v, v + (f:ld(R.GV + idx) * 9) // 10) end)
        f:st(R.QV + a, v)
      end)
    end)
  end)
  -- follow the best root action through the searched graph; remember the path when it reaches a reward
  P:func("h_extract", {"first"}, function(f, first)
    local s, step, a, ba, best, v, idx, tot, key = f:var("s", 0), f:var("step", 0), f:var("a"), f:var("ba"), f:var("best"), f:var("v"), f:var("idx"), f:var("tot", 0), f:var("key")
    f:st(R.PLNLEN, 0)
    f:while_(step:lt(8), function()
      f:set(best, NEG); f:set(ba, -1)
      f:for_(a, 0, f:ld(R.NA), function()
        f:iff(GL.or_(s:ne(0), ((f:ld(R.SAFE) >> a) & 1):ne(0)), function()
          f:set(v, f:ld(R.GREW + s * 4 + a))
          f:set(idx, f:ld(R.GSUCC + s * 4 + a))
          f:iff(idx:ge(0), function() f:set(v, v + (f:ld(R.GV + idx) * 9) // 10) end)
          f:iff(v:gt(best), function() f:set(best, v); f:set(ba, a) end)
        end)
      end)
      f:iff(ba:lt(0), function() f:break_() end)
      f:iff(step:eq(0), function() f:iff(ba:ne(first), function() f:ret(0) end) end)
      f:st(R.PLNACT + step, ba)
      f:set(tot, tot + f:ld(R.GREW + s * 4 + ba))
      f:set(idx, f:ld(R.GSUCC + s * 4 + ba))
      f:set(step, step + 1)
      f:iff(idx:lt(0), function() f:break_() end)
      f:st(R.PLNKEY + step, f:ld(R.GKEY + idx))
      f:set(s, idx)
    end)
    f:iff(GL.and_(tot:ge(128), step:ge(2)), function() f:st(R.PLNLEN, step); f:st(R.PLNPOS, 1) end)
    f:ret(0)
  end)
  -- Expected value of the NEXT decision after action a: the exogenous fields the plan depends on are sampled from their
  -- recent empirical distribution (the window lanes themselves), and the learned rules of the goal fields are evaluated
  -- for all samples at once by lane-parallel code. The result is the expected probability that some second action
  -- reaches the goal, i.e. one chance level of expectimax.
  P:func("h_chance", {"a"}, function(f, a)
    local j, a2, g, hit, acc, nl, sg, cell, bk, any = f:var("j"), f:var("a2"), f:var("g"), f:var("hit", 0), f:var("acc"), f:var("nl", f:call("h_pop", f:ld(R.WVALID))), f:var("sg"), f:var("cell"), f:var("bk"), f:var("any", 0)
    f:iff(nl:lt(4), function() f:ret(0) end)
    inc(f, 13)
    f:for_(j, 0, 4, function()
      f:iff(f:ld(R.EXO + j):ne(0), function() f:st(R.SIG + j, f:ld(R.WPOST + j)); f:st(R.SIG + 9 + j, f:ld(R.WPOST + j)) end, function()
        f:iff(f:ld(R.RNX + a * 4 + j):lt(0), function() f:st(R.SIG + j, H8) end, function() f:st(R.SIG + j, f:ld(R.RNX + a * 4 + j) * ONES) end)
        f:st(R.SIG + 9 + j, f:ld(R.SIG + j))
      end)
      f:iff(f:ld(R.OBS + j):lt(0), function() f:st(R.SIG + 4 + j, H8) end, function() f:st(R.SIG + 4 + j, f:ld(R.OBS + j) * ONES) end)
    end)
    f:for_(a2, 0, f:ld(R.NA), function()
      f:st(R.SIG + 8, a2 * ONES)
      f:set(acc, f:ld(R.WVALID))
      f:for_(g, 0, f:ld(R.NF), function()
        f:iff(f:ld(R.GOAL + g):ge(0), function()
          f:set(cell, a2 * 4 + g); f:set(bk, f:ld(R.BESTK + cell))
          f:iff(bk:ge(0), function() f:set(sg, f:call("h_rsg", f:ld(R.CR0 + cell * NC + bk), f:ld(R.CR1 + cell * NC + bk))) end,
                          function() f:set(sg, f:ld(R.SIG + g)) end)
          f:set(acc, acc & f:call("h_eqf", sg, f:ld(R.GOAL + g) * ONES)); f:set(any, 1)
        end)
      end)
      f:set(hit, hit | acc)
    end)
    f:iff(any:eq(0), function() f:ret(0) end)
    f:ret((f:call("h_pop", hit) * 256) // nl)
  end)
  -- Immediate expected reward when a goal rule reads an exogenous value of the very step being decided: the value is
  -- sampled from its recent empirical distribution and the rule evaluated for all samples at once.
  P:func("h_chance0", {"a"}, function(f, a)
    local j, g, acc, nl, sg, cell, bk, any = f:var("j"), f:var("g"), f:var("acc"), f:var("nl", f:call("h_pop", f:ld(R.WVALID))), f:var("sg"), f:var("cell"), f:var("bk"), f:var("any", 0)
    f:iff(nl:lt(4), function() f:ret(-1) end)
    f:for_(j, 0, 4, function()
      f:iff(f:ld(R.OBS + j):lt(0), function() f:st(R.SIG + j, H8) end, function() f:st(R.SIG + j, f:ld(R.OBS + j) * ONES) end)
      f:iff(f:ld(R.LAG + j):lt(0), function() f:st(R.SIG + 4 + j, H8) end, function() f:st(R.SIG + 4 + j, f:ld(R.LAG + j) * ONES) end)
      f:iff(f:ld(R.EXO + j):ne(0), function() f:st(R.SIG + 9 + j, f:ld(R.WPOST + j)) end, function() f:st(R.SIG + 9 + j, f:ld(R.SIG + j)) end)
    end)
    f:st(R.SIG + 8, a * ONES)
    f:set(acc, f:ld(R.WVALID))
    f:for_(g, 0, f:ld(R.NF), function()
      f:iff(f:ld(R.GOAL + g):ge(0), function()
        f:set(cell, a * 4 + g); f:set(bk, f:ld(R.BESTK + cell))
        f:iff(bk:ge(0), function() f:set(sg, f:call("h_rsg", f:ld(R.CR0 + cell * NC + bk), f:ld(R.CR1 + cell * NC + bk))) end,
                        function() f:set(sg, f:ld(R.SIG + g)) end)
        f:set(acc, acc & f:call("h_eqf", sg, f:ld(R.GOAL + g) * ONES)); f:set(any, 1)
      end)
    end)
    f:iff(any:eq(0), function() f:ret(-1) end)
    f:ret((f:call("h_pop", acc) * 256) // nl)
  end)
  -- model-free evidence for an action in the current state: additive shrunk estimate of reward-plus-progress
  P:func("h_cb", {"a"}, function(f, a)
    local b, base, j, est, n, v = f:var("b", a * 33), f:var("base", 0), f:var("j"), f:var("est"), f:var("n"), f:var("v")
    f:set(n, f:ld(R.CBN + b + 32))
    f:iff(n:eq(0), function() f:ret(0) end)
    f:set(base, (f:ld(R.CBS + b + 32) * 16) // n)          -- sixteenths of an outcome unit
    f:set(est, base)
    f:for_(j, 0, f:ld(R.NF), function()
      f:set(v, f:ld(R.OBS + j))
      f:iff(v:ge(0), function()
        f:set(n, f:ld(R.CBN + b + j * 8 + v))
        f:iff(n:gt(0), function()
          f:set(est, est + (((f:ld(R.CBS + b + j * 8 + v) * 16 + base) // (n + 1)) - base))
        end)
      end)
    end)
    f:ret(est)
  end)
  -- extremes of the root values over the safe actions
  P:func("h_qspread", {}, function(f)
    local a, v, lo, hi = f:var("a"), f:var("v"), f:var("lo", NEG * -1), f:var("hi", NEG)
    f:for_(a, 0, f:ld(R.NA), function()
      f:iff(((f:ld(R.SAFE) >> a) & 1):ne(0), function()
        f:set(v, f:ld(R.QV + a)); f:iff(v:gt(hi), function() f:set(hi, v) end); f:iff(v:lt(lo), function() f:set(lo, v) end)
      end)
    end)
    f:st(R.QHI, hi); f:st(R.QLO, lo)
  end)
  -- choose an action: cached plan if its premises still hold, else model-based values plus exploration bonuses
  P:func("h_plan", {}, function(f)
    local a, v, best, ba, j, tr, lo, hi = f:var("a"), f:var("v"), f:var("best", NEG), f:var("ba", 0), f:var("j"), f:var("tr"), f:var("lo"), f:var("hi")
    local cell, bk, st, acc = f:var("cell"), f:var("bk"), f:var("st"), f:var("acc")
    inc(f, 5)
    f:iff(f:ld(R.PLNLEN):gt(0), function()
      f:iff(GL.and_(f:ld(R.PLNPOS):lt(f:ld(R.PLNLEN)), f:call("h_gkey", R.OBS):eq(f:ld(R.PLNKEY + f:ld(R.PLNPOS)))), function()
        f:set(a, f:ld(R.PLNACT + f:ld(R.PLNPOS)))
        f:iff(((f:ld(R.SAFE) >> a) & 1):ne(0), function() f:st(R.PLNPOS, f:ld(R.PLNPOS) + 1); inc(f, 7); f:ret(a) end)
      end)
      f:st(R.PLNLEN, 0)
    end)
    f:st(R.NXTFULL, 0)
    f:run("h_bfs", 1)
    -- an exogenous value of the decided step itself: replace the point prediction by its expectation over samples
    f:iff(GL.and_(f:ld(R.CHON):ne(0), f:ld(R.RPOST):ne(0), f:ld(R.ECON):eq(0)), function()
      f:for_(a, 0, f:ld(R.NA), function()
        f:iff(((f:ld(R.SAFE) >> a) & 1):ne(0), function()
          f:set(v, f:call("h_chance0", a))
          f:iff(v:ge(0), function() f:st(R.QV + a, v) end)
        end)
      end)
    end)
    f:run("h_qspread"); f:set(hi, f:ld(R.QHI)); f:set(lo, f:ld(R.QLO))
    -- a sure predicted reward is simply taken
    f:iff(hi:ge(192), function()
      f:set(best, NEG)
      f:for_(a, 0, f:ld(R.NA), function()
        f:iff(((f:ld(R.SAFE) >> a) & 1):ne(0), function()
          f:set(tr, f:ld(R.TRIED + a)); f:iff(tr:gt(60), function() f:set(tr, 60) end)
          f:set(v, f:ld(R.QV + a) * 64 - tr)
          f:iff(v:gt(best), function() f:set(best, v); f:set(ba, a) end)
        end)
      end)
      f:ret(ba)
    end)
    -- chance lookahead: where the relevant dynamics depend on exogenous fields, add the expected value of the next decision
    f:iff(GL.and_(f:ld(R.CHON):ne(0), f:ld(R.REXO):ne(0), f:ld(R.PLAND):gt(1), f:ld(R.ECON):eq(0)), function()
      f:for_(a, 0, f:ld(R.NA), function()
        f:iff(((f:ld(R.SAFE) >> a) & 1):ne(0), function()
          f:st(R.QV + a, f:ld(R.QV + a) + (f:call("h_chance", a) * 9) // 10)
        end)
      end)
      f:run("h_qspread"); f:set(hi, f:ld(R.QHI)); f:set(lo, f:ld(R.QLO))
    end)
    -- deliberate further only when one step shows no signal and the relevant dynamics are predictable
    -- (the value of this computation is learned: failed deliberations back off exponentially, a found plan resets it)
    local delib = f:var("delib", 0)
    f:iff(GL.and_(f:ld(R.REXO):eq(0), f:ld(R.PLAND):gt(1), hi:lt(f:ld(R.DELIBQ)), f:ld(R.ECON):eq(0), f:ld(R.STEPN):ge(f:ld(R.DBACK))), function()
      inc(f, 10); f:set(delib, 1); f:run("h_bfs", f:ld(R.PLAND))
    end)
    f:for_(j, 0, 4, function() f:st(R.CTX + j, f:ld(R.OBS + j)); f:st(R.CTX + 4 + j, f:ld(R.LAG + j)); f:st(R.CTX + 9 + j, f:ld(R.OBS + j)) end)
    f:for_(a, 0, f:ld(R.NA), function()
      f:iff(((f:ld(R.SAFE) >> a) & 1):ne(0), function()
        f:set(v, f:ld(R.QV + a))
        f:iff(f:ld(R.ECON):eq(0), function() f:set(v, v + f:call("h_bonus", a)) end)
        -- where the symbolic model of the goal fields is not yet convincing, blend in the statistical evidence
        f:iff(GL.and_(f:ld(R.CBON):ne(0), (hi - lo):lt(f:ld(R.CBSPREAD)), f:ld(R.STEPN):ge(f:ld(R.CBMIN) * f:ld(R.NA))), function()
          -- honest confidence: prospective accuracy of the best rule of each goal field (unknown until three real tests)
          f:set(tr, 100)
          f:for_(j, 0, f:ld(R.NF), function()
            f:iff(f:ld(R.GOAL + j):ge(0), function()
              f:set(cell, a * 4 + j); f:set(bk, f:ld(R.BESTK + cell))
              f:iff(bk:ge(0), function() f:set(st, f:ld(R.CST + cell * NC + bk)) end, function() f:set(st, f:ld(R.PST + cell)) end)
              f:set(acc, 0)
              f:iff(((st >> 8) & 255):ge(3), function() f:set(acc, ((st & 255) * 100) // ((st >> 8) & 255)) end)
              f:iff(acc:lt(tr), function() f:set(tr, acc) end)
            end)
          end)
          f:iff(tr:lt(70), function() f:set(v, v + (f:call("h_cb", a) * f:ld(R.CBW) * (70 - tr)) // (16 * 70)) end)
        end)
        f:set(tr, f:ld(R.TRIED + a)); f:iff(tr:gt(60), function() f:set(tr, 60) end)
        f:set(v, v * 64 - tr)
        f:iff(v:gt(best), function() f:set(best, v); f:set(ba, a) end)
      end)
    end)
    f:iff(GL.and_(f:ld(R.NGS):gt(1), f:ld(R.REXO):eq(0)), function() f:run("h_extract", ba) end)
    f:iff(delib:ne(0), function()
      f:iff(f:ld(R.PLNLEN):gt(0), function() f:st(R.DFAIL, 0); f:st(R.DBACK, 0) end, function()
        f:st(R.DFAIL, f:ld(R.DFAIL) + 1)
        f:iff(f:ld(R.DFAIL):gt(f:ld(R.DFREE)), function()
          f:set(tr, f:ld(R.DFAIL) - f:ld(R.DFREE)); f:iff(tr:gt(4), function() f:set(tr, 4) end)
          f:st(R.DBACK, f:ld(R.STEPN) + (GL.lift(2) << tr))
        end)
      end)
    end)
    f:ret(ba)
  end)

  return R
end

------------------------------------------------------------------------ program builder and runner
-- The host only compiles this program and runs the evaluator physics. Every sensing validation, learning step,
-- hypothesis competition, memory operation, plan and forecast below executes as metered VM-1 instructions.
function Hpr.build(cfg)
  cfg = cfg or {}
  local U = require("asi.util")
  local VM = require("asi.vm")
  local Run = require("asi.run")
  local Env = require("asi.reason.env")
  local machine = Env.machine
  local P = GL.program(machine, {ram_words = 4096, stack_words = 256})
  local R = Hpr.install(P, cfg)
  local B = P:static("RS_BUFFER", 28)
  local DONE, GUARD = P:static("RS_DONE", 1), P:static("RS_GUARD", 1)
  R.DONE, R.GUARD = DONE, GUARD
  local ACT = P:static("RS_ACT", 1)
  P:main(function(f)
    local status, a, valid, i = f:var("status"), f:var("action"), f:var("valid"), f:var("i")
    f:run("h_init")
    f:while_(f:ld(DONE):eq(0), function()
      f:set(status, f:sys("RSENSE", B))
      f:set(valid, 1)
      f:iff(GL.or_(status:ne(0), f:ld(B):ne(1), f:ld(B + 1):lt(1), f:ld(B + 1):gt(4),
                    f:ld(B + 2):lt(1), f:ld(B + 2):gt(4), (f:ld(B + 11) & 1):eq(0),
                    f:ld(B + 11):lt(1), f:ld(B + 11):gt(15), f:ld(B + 12):lt(0), f:ld(B + 12):gt(15),
                    f:ld(B + 20):lt(0), f:ld(B + 20):gt(256), f:ld(B + 13):lt(0),
                    f:ld(B + 14):lt(0), f:ld(B + 14):gt(1), f:ld(B + 15):lt(0), f:ld(B + 15):gt(1),
                    (f:ld(B + 11) >> f:ld(B + 2)):ne(0), (f:ld(B + 12) >> f:ld(B + 1)):ne(0)), function() f:set(valid, 0) end)
      -- a new schema is accepted only at an explicitly marked episode reset
      f:iff(GL.and_(f:ld(R.HAVE):ne(0), f:ld(B + 14):eq(0)), function()
        f:iff(GL.or_(f:ld(B + 1):ne(f:ld(R.NF)), f:ld(B + 2):ne(f:ld(R.NA)), f:ld(B + 16):ne(f:ld(R.EID))),
          function() f:set(valid, 0) end)
        f:for_(i, 0, 4, function()
          f:iff(GL.or_(f:ld(B + 3 + i):ne(f:ld(R.MAXV + i)), f:ld(B + 7 + i):ne(f:ld(R.GOAL + i))),
            function() f:set(valid, 0) end)
        end)
      end)
      f:for_(i, 0, 4, function()
        f:iff(GL.or_(f:ld(B + 3 + i):lt(1), f:ld(B + 3 + i):gt(7),
                      f:ld(B + 7 + i):lt(-1), f:ld(B + 7 + i):gt(f:ld(B + 3 + i))), function() f:set(valid, 0) end)
        f:iff(i:lt(f:ld(B + 1)), function()
          f:iff(((f:ld(B + 12) >> i) & 1):ne(0), function()
            f:iff(GL.or_(f:ld(B + 24 + i):lt(0), f:ld(B + 24 + i):gt(f:ld(B + 3 + i))), function() f:set(valid, 0) end)
          end, function() f:iff(f:ld(B + 24 + i):ne(-1), function() f:set(valid, 0) end) end)
        end)
      end)
      f:iff(GL.and_(f:ld(B + 13):gt(0), GL.or_(f:ld(B + 23):ne(1), f:ld(B + 22):ne(f:ld(B + 13)))), function() f:set(valid, 0) end)
      f:iff(GL.and_(f:ld(B + 13):gt(0), f:ld(B + 14):eq(0), f:ld(B + 19):ne(f:ld(ACT))), function() f:set(valid, 0) end)
      -- events must advance by exactly one inside an episode
      f:iff(GL.and_(f:ld(R.HAVE):ne(0), f:ld(B + 14):eq(0), f:ld(B + 13):ne(f:ld(R.EVENT) + 1)), function() f:set(valid, 0) end)
      f:iff(valid:eq(0), function()
        f:st(GUARD, 1); f:st(DONE, 1)
      end, function()
        f:st(R.NF, f:ld(B + 1)); f:st(R.NA, f:ld(B + 2))
        f:st(R.SAFE, f:ld(B + 11)); f:st(R.EVENT, f:ld(B + 13)); f:st(R.RESET, f:ld(B + 14)); f:st(R.EID, f:ld(B + 16))
        f:st(R.LASTREW, f:ld(B + 20)); f:st(R.LASTACT, f:ld(B + 19)); f:st(DONE, f:ld(B + 15))
        f:for_(i, 0, 4, function()
          f:st(R.MAXV + i, f:ld(B + 3 + i)); f:st(R.GOAL + i, f:ld(B + 7 + i)); f:st(R.OBS + i, f:ld(B + 24 + i))
        end)
        f:iff(f:ld(B + 21):ne(0), function() f:st(GUARD, 1); f:st(DONE, 1) end)
        -- compute is a resource: when the work left per remaining step falls below the allowance, expensive reasoning stops
        f:st(R.STEPG, f:ld(B + 18))
        f:st(R.ECON, 0)
        f:iff(f:clk(3):lt((GL.lift(192) - f:ld(B + 18)) * f:ld(R.ECOTHR)), function()
          f:st(R.ECON, 1); f:st(R.STATS + 12, f:ld(R.STATS + 12) + 1)
        end)
        f:iff(f:ld(DONE):eq(0), function()
          f:iff(f:ld(R.RESET):ne(0), function()
            f:run("h_new_episode")
            f:for_(i, 0, 4, function() f:st(R.LAG + i, -1); f:st(R.PREV + i, f:ld(R.OBS + i)) end)
            f:st(R.HAVE, 1)
          end, function()
            f:run("h_learn")
            f:for_(i, 0, 4, function() f:st(R.LAG + i, f:ld(R.PREV + i)); f:st(R.PREV + i, f:ld(R.OBS + i)) end)
          end)
          f:set(a, f:call("h_plan"))
          f:iff(GL.or_(a:lt(0), a:ge(f:ld(R.NA)), ((f:ld(R.SAFE) >> a) & 1):eq(0)), function() f:set(a, 0) end)
          f:run("h_forecast", a)
          f:for_(i, 0, 13, function() f:st(R.FC + i, f:ld(R.FC + i)) end)
          f:set(status, f:sys("RPRED", R.FC))
          f:iff(status:ne(0), function() f:st(GUARD, 1); f:st(DONE, 1) end, function()
            f:set(status, f:sys("RACT", a))
            f:iff(status:ne(0), function() f:st(GUARD, 1); f:st(DONE, 1) end, function() f:st(ACT, a) end)
          end)
        end)
      end)
    end)
  end)
  local words, sym = P:build()
  local ok, bits = Run.check_image(words, machine)
  assert(ok, "hypothesis reasoner image exceeds declared cap")
  assert(P.asm.ram_top <= 4096 - 256, "hypothesis reasoner state overlaps stack")
  return words, sym, P, R, bits, cfg, machine
end

function Hpr.artifact(cfg)
  local words, sym, P, R, bits, c, machine = Hpr.build(cfg)
  return {words = words, sym = sym, P = P, R = R, bits = bits, cfg = c, machine = machine}
end

function Hpr.run(opt)
  opt = opt or {}
  local U = require("asi.util")
  local VM = require("asi.vm")
  local Run = require("asi.run")
  local Env = require("asi.reason.env")
  local words, sym, P, R, bits, cfg, machine
  if opt.artifact then
    local a = opt.artifact
    words, sym, P, R, bits, cfg, machine = a.words, a.sym, a.P, a.R, a.bits, a.cfg, a.machine
  else words, sym, P, R, bits, cfg, machine = Hpr.build(opt.cfg) end
  local image_ok, checked_bits = Run.check_image(words, machine)
  assert(image_ok and bits == checked_bits, "reasoning artifact violates declared image cap")
  local env = opt.env or Env.new(opt)
  local profile = Env.profile()
  profile.work_budget = opt.work_budget or Env.PROTOCOL.work_budget
  assert(math.type(profile.work_budget) == "integer" and profile.work_budget >= 1 and profile.work_budget <= Env.PROTOCOL.work_budget,
         "reasoning work budget outside frozen contract")
  profile.stack_words = 256
  local vm = VM.new({image = {words = words, bits = bits}, machine = machine, env = env, profile = profile,
                    coin_seed = 1, trace = opt.trace ~= false})
  env.stats_addr = sym.H_STATS
  local t0 = os.clock()
  local reason = vm:run(opt.max_instr)
  local vm_cpu = os.clock() - t0
  local out = env:result({oracle = opt.oracle ~= false})
  out.host_cpu = vm_cpu
  out.evaluator_cpu = os.clock() - t0 - vm_cpu
  out.reason, out.fault = reason, vm.fault
  out.work = vm.budget - vm.work_left; out.instructions = vm.instr_count
  out.image_bits, out.image_hash = bits, vm.image_hash
  out.ram_high_water = vm:peak_ram_words(); out.peak_bits = vm:peak_bits()
  out.interface_work, out.interface_ops = vm.work_iface, vm.iface_count
  out.world_trace_hash, out.vm_trace_hash = out.trace_hash, vm:trace_hash()
  out.protocol_hash = Env.protocol_hash
  out.trace_hash = U.sha256(out.image_hash .. ":" .. Env.protocol_hash .. ":" .. out.world_trace_hash .. ":" .. out.vm_trace_hash)
  out.guard = vm.ram[sym.RS_GUARD - VM.RAM_BASE]
  out.stats = {}
  for i = 0, 15 do out.stats[i] = vm.ram[sym.H_STATS - VM.RAM_BASE + i] end
  -- STATS: 0 transitions, 1 inductions, 3 inserted hypotheses, 4 surprises, 5 plans, 6 expanded search nodes, 7 plan steps followed,
  -- 8 deep-term searches, 9 library hypotheses offered, 10 deliberate searches, 11 recognised-world restores,
  -- 12 economy-mode steps, 13 chance evaluations
  return out, env, vm, {words = words, sym = sym, P = P, R = R, bits = bits, cfg = cfg, machine = machine}
end

return Hpr
end

-- ======================================================================== asi.reason.env3  (procedurally generated held-out worlds)
package.preload["asi.reason.env3"] = function(...)
-- asi.reason.env3: procedurally generated held-out reasoning worlds behind the SAME controller interface as asi.reason.env.
-- Nothing here is shared with the six frozen task families except the packet format, the four-stage stream structure and
-- the score definitions (asi.reason.eval is reused unchanged). Each world is drawn from a random generator; transition
-- programs include operations outside the learner's primitive set (multiplication, rotation, nested conditionals), hidden
-- variables, observation noise, gated delayed credit, structural change and a mid-stage shock. Worlds are accepted only
-- if an offline exhaustive optimum clearly beats the passive policy (no degenerate tasks), never by looking at a controller.
local U = require("asi.util")
local R = require("asi.rng")
local ISA = require("asi.isa")
local VM = require("asi.vm")
local Env = require("asi.reason.env")
local E3 = {}; E3.__index = E3
E3.ops, E3.machine = Env.ops, Env.machine

local function shuffle(r, n)
  local a = {}; for i = 1, n do a[i] = i end
  for i = n, 2, -1 do local j = r:below(i) + 1; a[i], a[j] = a[j], a[i] end
  return a
end

------------------------------------------------------------------------------------------------ class B: arithmetic puzzles
local BOPS = {"add", "sub", "xor", "and", "or", "max", "min", "mul3", "rot", "ite"}
local function rand_ast(r, depth)
  if depth == 0 or r:below(3) == 0 then
    local k = r:below(9)
    if k < 3 then return {"var", k + 1}                                          -- 1 = x, 2 = visible token, 3 = previous token
    elseif k == 3 and r:below(3) == 0 then return {"var", 4}                      -- 4 = the unobserved draw of the very step
    else return {"const", r:below(8)} end
  end
  local op = BOPS[1 + r:below(#BOPS)]
  if op == "mul3" or op == "rot" then return {op, rand_ast(r, depth - 1)} end
  if op == "ite" then return {"ite", rand_ast(r, depth - 1), rand_ast(r, depth - 1), rand_ast(r, depth - 1), rand_ast(r, depth - 1)} end
  return {op, rand_ast(r, depth - 1), rand_ast(r, depth - 1)}
end
local function ev(n, v)
  local k = n[1]
  if k == "var" then return v[n[2]] elseif k == "const" then return n[2] end
  local a = ev(n[2], v)
  if k == "mul3" then return (a * 3) & 7 elseif k == "rot" then return ((a << 1) | (a >> 2)) & 7 end
  if k == "ite" then local b = ev(n[3], v); if a == b then return ev(n[4], v) end return ev(n[5], v) end
  local b = ev(n[3], v)
  if k == "add" then return (a + b) & 7 elseif k == "sub" then return (a - b) & 7 elseif k == "xor" then return a ~ b
  elseif k == "and" then return a & b elseif k == "or" then return a | b elseif k == "max" then return math.max(a, b)
  else return math.min(a, b) end
end

------------------------------------------------------------------------------------------------ world definition
-- A world: class "A" (gated counter with bits and a hidden variable) or "B" (arithmetic with tokens). State is a small
-- integer vector; draws are fixed per step index so an offline optimum is exact.
local function new_world(seed, tag, variant)
  local r = R.new(seed, "reason-env3:" .. tag)
  local w = {tag = tag, variant = variant, class = (r:below(2) == 0) and "A" or "B"}
  w.slots = shuffle(r, 4)
  w.draws = {}
  for j = 1, 48 do w.draws[j] = {token = r:below(8), irrel = r:below(8), flip = r:bit(1, 8), noise = r:bit(1, 4), coin = r:bit(1, 2)} end
  w.target = ({3, 7})[1 + r:below(2)]
  local nprog = 4
  if w.class == "B" then
    w.target = ({7, 7, 5, 3})[1 + r:below(4)]
    w.prog, w.alt = {}, {}
    for a = 0, nprog - 1 do w.prog[a] = rand_ast(r, 2); w.alt[a] = rand_ast(r, 2) end
    w.initial = {r:below(8), r:below(8), 0, 0, 0}
  else
    -- kinds: set1, set2 (needs bit1), advance (needs condition), toggle hidden, clear, noop
    local kinds = {"set1", "gate2", "advance", "clear"}
    local perm = shuffle(r, 4)
    w.prog, w.alt = {}, {}
    local function lit() return {r:below(3), r:below(2)} end            -- variable index 0..2 (b1, b2, hidden), required value
    for a = 0, nprog - 1 do
      w.prog[a] = {kind = kinds[perm[a + 1]], cond = {lit(), (r:below(2) == 0) and lit() or nil}}
      w.alt[a] = {kind = kinds[1 + r:below(4)], cond = {lit(), (r:below(2) == 0) and lit() or nil}}
    end
    -- the first advance condition must be reachable through the gate: use bit1 (set by set1) or bit2 (set by gate2)
    for a = 0, nprog - 1 do if w.prog[a].kind == "advance" then w.prog[a].cond = {{r:below(2), 1}, nil} end end
    w.decay = r:below(2) == 0
    w.initial = {0, 0, 0, r:below(2), 0}                               -- c, b1, b2, hidden, spare
  end
  -- variants: 1 = structural novelty (actions rotated by one, first program replaced, dropout of a field), 3 = return with shock
  w.rot = (variant == 1) and 1 or 0
  return w
end
local function use_alt(w, j)
  return (w.variant == 1) or (w.variant == 3 and j > 16)
end
local function program(w, a, j)
  local idx = (a + w.rot) % 4
  if use_alt(w, j) and (a == 0 or a == 2) then return w.alt[idx] end
  return w.prog[idx]
end
local function cond_true(c, s)
  for _, l in ipairs(c) do if l then
    local v = (l[1] == 0 and s[2]) or (l[1] == 1 and s[3]) or s[4]
    if v ~= l[2] then return false end
  end end
  return true
end
local function transition(w, s, a, j)
  local d = w.draws[j]
  local n = {s[1], s[2], s[3], s[4], s[5]}
  local reward = 0
  if w.class == "B" then
    local v = {s[1], s[2], s[3], d.irrel}
    local x = ev(program(w, a, j), v)
    n[1] = x; n[3] = s[2]; n[2] = d.token
    reward = (x == w.target) and 256 or 0
  else
    local p = program(w, a, j)
    local advanced = false
    n[4] = s[4] ~ d.flip
    if p.kind == "set1" then n[2] = 1
    elseif p.kind == "gate2" then if s[2] == 1 then n[3] = 1; n[2] = 0 end
    elseif p.kind == "clear" then n[2] = 0; n[3] = 0
    elseif p.kind == "advance" then
      if cond_true(p.cond, s) then n[1] = math.min(3, s[1] + 1); advanced = true else n[1] = math.max(0, s[1] - 1) end
    end
    if not advanced and w.decay and p.kind ~= "advance" and d.coin == 1 then n[1] = math.max(0, n[1] - 1) end
    reward = (n[1] == w.target) and 256 or 0
    n[5] = d.token
  end
  return n, reward
end
local function observe(w, s, j)
  local d = w.draws[math.max(1, math.min(j, 48))]
  local raw, known
  if w.class == "B" then raw, known = {s[1], s[2], s[3], d.irrel}, 15
  else
    local b2 = 7 * s[3]
    if d.noise == 1 then b2 = 7 - b2 end                         -- the second bit is observed through noise
    raw, known = {s[1], 7 * s[2], b2, d.token}, 15
  end
  if w.variant == 1 and j % 7 == 0 then raw[2] = -1; known = known & ~2 end
  local out, km = {}, 0
  for i = 1, 4 do out[w.slots[i]] = raw[i]; if (known & (1 << (i - 1))) ~= 0 then km = km | (1 << (w.slots[i] - 1)) end end
  return out, km
end
local function goal_vector(w)
  local g = {-1, -1, -1, -1}
  g[w.slots[1]] = w.target
  return g
end
local function state_key(s) return s[1] | (s[2] << 3) | (s[3] << 6) | (s[4] << 9) | ((s[5] or 0) << 12) end

-- offline exhaustive optimum and passive return of one stage (evaluator only)
local function stage_bounds(w, count)
  local memo = {}
  local function dp(j, s)
    if j > count then return 0 end
    local k = state_key(s); local lv = memo[j]; if not lv then lv = {}; memo[j] = lv end
    if lv[k] ~= nil then return lv[k] end
    local best = -1
    for a = 0, 3 do local n, rw = transition(w, s, a, j); best = math.max(best, rw + dp(j + 1, n)) end
    lv[k] = best; return best
  end
  local oracle = dp(1, w.initial)
  local s, z = w.initial, 0
  for j = 1, count do local rw; s, rw = transition(w, s, 0, j); z = z + rw end
  return oracle, z
end

-- a world is acceptable when clairvoyant play clearly beats passive play and is not trivial
local function acceptable(seed)
  local w0 = new_world(seed, "w0", 0)
  local o, z = stage_bounds(w0, 48)
  local w1 = new_world(seed, "w0", 1)
  local o1, z1 = stage_bounds(w1, 48)
  return o >= 6 * 256 and o > z + 4 * 256 and o1 >= 4 * 256 and o1 > z1 + 2 * 256
end
function E3.accept(seed) return acceptable(seed) end
local function pick_seed(seed, salt)
  -- deterministic rejection sampling over derived world seeds
  local s = seed * 1000 + salt
  for k = 0, 400 do if acceptable(s + k * 7919) then return s + k * 7919 end end
  error("no acceptable generated world for seed " .. seed)
end
E3.pick_seed = pick_seed

------------------------------------------------------------------------------------------------ controller-facing environment
E3.PROTOCOL = {id = "GRS1-GEN1", version = 1, stages = Env.PROTOCOL.stages, fields = 4, actions = 4, value_max = 7,
  phase_steps = 48, max_steps = 192, work_budget = Env.PROTOCOL.work_budget,
  description = "procedurally generated worlds; frozen packet format, stage structure and score definitions"}
E3.protocol_hash = U.sha256(U.to_literal(E3.PROTOCOL))
function E3.profile() return Env.profile() end
local function stage_world(spec, stage)
  if stage == 0 then return new_world(spec.main, "w0", 0)
  elseif stage == 1 then return new_world(spec.main, "w0", 1)
  elseif stage == 2 then return new_world(spec.other, "w0", 0)
  else return new_world(spec.main, "w0", 3) end
end
local function class_label(w) return (w.class == "A") and "delayed" or "symbolic" end

function E3.new(opts)
  opts = opts or {}
  local seed = opts.seed or 1
  local spec = {main = pick_seed(seed, 1), other = pick_seed(seed, 2)}
  local limit = opts.steps or 192
  assert(math.type(limit) == "integer" and limit >= 1 and limit <= 192, "reasoning stream length out of range")
  local self = setmetatable({family = "generated", seed = seed, spec = spec, limit = limit, step = 0, episode = 0, epstep = 0,
    event = 0, last_action = -1, last_reward = 0, last_failure = 0, reward_total = 0, failures = 0, rejected_actions = 0,
    senses = 0, pred_calls = 0, pred_rejected = 0, forecasts = 0, known_targets = 0, point_correct = 0,
    brier_num = 0, brier_den = 0, trace = {}, records = {}, phases = {}, reset = true, done = false}, E3)
  for stage = 0, 3 do
    local n = math.min(48, math.max(0, limit - stage * 48))
    self.phases[stage + 1] = {phase = stage, label = Env.PROTOCOL.stages[stage + 1], family = class_label(stage_world(spec, stage)),
      steps = 0, total_steps = n, utility_num = 0, utility_den = 256 * n, brier_num = 0, brier_den = 0,
      prediction_correct = 0, prediction_total = 0, first_goal_event = nil}
  end
  self:_enter(0)
  return self
end
function E3:_enter(stage)
  self.episode = stage; self.epstep = 0; self.reset = true
  self.w = stage_world(self.spec, stage)
  self.state = {table.unpack(self.w.initial)}
  self.obs, self.known = observe(self.w, self.state, 1)
end
function E3:sense_words()
  local g = goal_vector(self.w)
  local w = {1, 4, 4, 7, 7, 7, 7}
  for i = 1, 4 do w[7 + i] = g[i] end
  w[12] = 15; w[13] = self.known; w[14] = self.event
  w[15] = self.reset and 1 or 0; w[16] = self.done and 1 or 0
  w[17] = self.episode; w[18] = self.epstep; w[19] = self.step; w[20] = self.last_action
  w[21] = self.last_reward; w[22] = self.last_failure; w[23] = self.event; w[24] = (self.event > 0) and 1 or 0
  for i = 1, 4 do w[24 + i] = self.obs[i] end
  return w
end
local function score_prediction(self, action, obs, known, target_event)
  local pred = self.pending_prediction
  local target = target_event or (self.event + 1)
  local present = pred and pred[1] == target and pred[2] == action
  if not present then pred = {target, action, -1, -1, -1, -1, -1, -1, -1, -1, 256, 0, 0}
  else self.forecasts = self.forecasts + 1 end
  local u = pred[11]
  local goal = goal_vector(self.w)
  local metric = {present = present and true or false, unknownmass = u, brier_num = 0, brier_den = 0,
    point_correct = 0, point_total = 0, goal_correct = 0, goal_total = 0}
  for i = 1, 4 do if (known & (1 << (i - 1))) ~= 0 then
    local v0, v1 = (pred[12] & (1 << (i - 1))) ~= 0, (pred[13] & (1 << (i - 1))) ~= 0
    local maxn, top, total = -1, 0, 0
    for v = 0, 7 do
      local hits = ((v0 and pred[2 + i] == v) and 1 or 0) + ((v1 and pred[6 + i] == v) and 1 or 0)
      local invalid = (v0 and 0 or 1) + (v1 and 0 or 1)
      local n = 8 * (256 - u) * hits + invalid * (256 - u) + 2 * u
      if n > maxn then maxn, top = n, v end
      local d = n - ((v == obs[i]) and 4096 or 0); total = total + d * d
    end
    self.brier_num = self.brier_num + total; self.brier_den = self.brier_den + 4096 * 4096
    self.known_targets = self.known_targets + 1; self.point_correct = self.point_correct + ((top == obs[i]) and 1 or 0)
    metric.brier_num = metric.brier_num + total; metric.brier_den = metric.brier_den + 4096 * 4096
    metric.point_total = metric.point_total + 1; metric.point_correct = metric.point_correct + ((top == obs[i]) and 1 or 0)
    if goal[i] >= 0 and not self.reset then
      metric.goal_total = metric.goal_total + 1; metric.goal_correct = metric.goal_correct + ((top == obs[i]) and 1 or 0)
    end
  end end
  self.pending_prediction = nil
  return metric
end
function E3:act(action)
  if self.done then return 1 end
  if math.type(action) ~= "integer" or action < 0 or action > 3 then
    self.rejected_actions = self.rejected_actions + 1; self.failures = self.failures + 1; self.last_failure = 1; return 3
  end
  local before, bknown = {table.unpack(self.obs)}, self.known
  local source_episode = self.episode
  local n, reward = transition(self.w, self.state, action, self.epstep + 1)
  local after, known = observe(self.w, n, self.epstep + 1)
  self.state = n; self.obs = after; self.known = known; self.event = self.event + 1; self.step = self.step + 1; self.epstep = self.epstep + 1
  self.reset = false; self.last_action = action; self.last_reward = reward; self.last_failure = 0; self.reward_total = self.reward_total + reward
  if self.step >= self.limit then self.done = true
  elseif self.epstep == 48 then self:_enter(self.episode + 1) end
  local metric = score_prediction(self, action, self.obs, self.known, self.event)
  local phase = self.phases[source_episode + 1]; phase.steps = phase.steps + 1; phase.utility_num = phase.utility_num + reward
  phase.brier_num = phase.brier_num + metric.brier_num; phase.brier_den = phase.brier_den + metric.brier_den
  phase.prediction_correct = phase.prediction_correct + metric.point_correct; phase.prediction_total = phase.prediction_total + metric.point_total
  if reward == 256 and not phase.first_goal_event then phase.first_goal_event = self.event end
  self.records[#self.records + 1] = {event = self.event, episode = source_episode, next_episode = self.episode, action = action,
    before = before, known_before = bknown, after = {table.unpack(self.obs)}, known_after = self.known,
    reward = reward, real = true, reset = self.reset, prediction = metric}
  self.trace[#self.trace + 1] = table.concat({self.event, self.episode, action, reward, self.known, table.concat(self.obs, ",")}, "|")
  return 0
end
function E3:submit_prediction(w)
  self.pred_calls = self.pred_calls + 1
  local ok = not self.done and w[1] == self.event + 1 and math.type(w[2]) == "integer" and w[2] >= 0 and w[2] < 4
  ok = ok and math.type(w[11]) == "integer" and w[11] >= 0 and w[11] <= 256
  for b = 0, 1 do
    local mask = w[12 + b]; ok = ok and math.type(mask) == "integer" and mask >= 0 and mask <= 15
    if ok then for i = 1, 4 do local v = w[2 + 4 * b + i]
      if (mask & (1 << (i - 1))) ~= 0 then ok = ok and math.type(v) == "integer" and v >= 0 and v <= 7
      else ok = ok and math.type(v) == "integer" and v >= -1 and v <= 7 end
    end end
  end
  if not ok then self.pred_rejected = self.pred_rejected + 1; return 3 end
  self.pending_prediction = {table.unpack(w)}; return 0
end
local function writable(vm, a, n) return math.type(a) == "integer" and a >= VM.RAM_BASE and a + n <= VM.RAM_BASE + vm.ram_words end
function E3:quote(vm, idx)
  if idx == 1 then return 128 elseif idx == 2 or idx == 3 then return 64 end
  return nil, VM.FAULT.OP
end
function E3:exec(vm, idx, rd, ra, rb, imm, t)
  local r = vm.r
  if idx == 1 then
    local dest = r[ra]; if not writable(vm, dest, 28) then return nil, VM.FAULT.ACCESS end
    local w = self:sense_words(); for i = 1, 28 do vm:mwrite(dest + i - 1, w[i]) end
    self.senses = self.senses + 1; r[rd] = 0; return 128, 128
  elseif idx == 2 then
    local before = self.event; r[rd] = self:act(r[ra])
    if self.event ~= before then
      local rec = self.records[#self.records]; rec.work = vm.budget - vm.work_left + 64
