  id = "GRS1-G3", generation = "G3",
  registration = "new controller; frozen G2 physics and scorecard; fresh heldout seeds reserved before any G3 heldout run",
  environment_protocol_hash = I.PROTOCOL.environment_protocol_hash,
  scoring_hash = I.PROTOCOL.scoring_hash,
  families = U.clone(Env.PROTOCOL.families),
  development_seeds = {1, 2, 3, 4}, holdout_seeds = {3001, 3002, 3003, 3004}, diagnostic_seeds = {2001, 2002, 2003, 2004},
  diagnostic_note = "2001..2004 are the observed G2 heldout seeds; they reproduce the frozen G2 numbers and are not fresh evidence",
  primary_reference = "g2_full",
  controllers = {full = "asi.reason.hpr: hypothesis populations, prospective ranking, world library, search over predicted states",
