G.ABLATION_CFG = {
  no_library = {lib = 0},               -- no cross-episode world library (no retention / transfer seeding)
  no_exceptions = {exc = 0},            -- rules cannot carry state-conditional exceptions
  no_deep_terms = {deeplvl = 0},        -- no depth-2 terms by inverse peeling
  no_deliberation = {depth = 1},        -- one-step model-based choice only; no search over predicted states
  no_exploration = {explore = 0},       -- no hypothesis-disagreement / untried-action / stagnation exploration
