local function mean(xs) local s = 0; for _, x in ipairs(xs) do s = s + x end return #xs > 0 and s / #xs or nil end
-- axis ratios of two groups on identical cases at one budget (equal family means, as in the frozen summary)
function G.pair_ratio(rows, num, den, budget)
  local by = {}
  for _, r in ipairs(rows) do by[r.variant .. ":" .. r.family .. ":" .. r.seed .. ":" .. r.budget_quarters] = r end
  local out = {axes = {}, utility_num = 0, utility_den = 0}
  for _, axis in ipairs(E.AXES) do
    local ns, ds = {}, {}
    for _, f in ipairs(Env.PROTOCOL.families) do
      local fn, fd = {}, {}
