          protocol = U.clone(Env.PROTOCOL), protocol_hash = Env.protocol_hash, scoring = U.clone(E.DEFINITIONS), scoring_hash = E.DEFINITIONS_HASH,
          held = opt.held and true or false, rows = rows, summary = summary, pairwise = ratios, requested_unsupported = unsupported}
end
