-- compact text rendering of a generation-3 report
function G.format(rep)
  local lines = {}
  local function put(...) lines[#lines + 1] = string.format(...) end
  put("generation %s  seeds=%s  protocol %s", rep.generation, rep.held and "heldout" or "development/diagnostic", rep.iteration_hash:sub(1, 12))
  local S = rep.summary
  local keys = {}
  for k in pairs(S.groups) do keys[#keys + 1] = k end
  table.sort(keys)
  for _, k in ipairs(keys) do
    local g = S.groups[k]
    local parts = {}
    for _, ax in ipairs(E.AXES) do parts[#parts + 1] = string.format("%s=%s", ax:sub(1, 9), g.axes[ax] and string.format("%.3f", g.axes[ax]) or "NA") end
    put("%-24s utility=%.4f work=%9.0f composite=%s", k, g.mean_utility, g.mean_work, g.composite and string.format("%.4f", g.composite) or "NA")
    put("    %s", table.concat(parts, " "))
  end
  for _, p in ipairs(rep.pairwise) do
    local parts = {}
    for _, ax in ipairs(E.AXES) do if p.axis_ratios[ax] then parts[#parts + 1] = string.format("%s=%.2f", ax:sub(1, 9), p.axis_ratios[ax]) end end
    put("full vs %-18s q%d composite %s / %s%s | %s", p.other, p.budget_quarters,
        p.full_composite and string.format("%.4f", p.full_composite) or "NA", p.other_composite and string.format("%.4f", p.other_composite) or "NA",
        (p.full_composite and p.other_composite and p.other_composite > 0) and string.format(" = %.2fx", p.full_composite / p.other_composite) or "", table.concat(parts, " "))
  end
  return table.concat(lines, "\n")
end
return G
end

