 runs",["resources"]={["bad"]=0,["image_bit_cap"]=1048576,["image_bits"]=676928,["image_words"]=10534,["max_ram_words"]=3037,["max_work"]=7446610,["over_q1_budget"]=0,["ram_static_words"]=2912,["ram_words"]=4096,["runs"]=168,["stack_words"]=256,["stress_seeds"]="100..123",["work_budget"]=33549312,},}
local E = EVIDENCE
local H, D, GN, C, RS = E.heldout, E.diagnostic, E.generated, E.compute, E.resources
local AXES = {"cross_task_transfer", "structural_ood_recovery", "normalized_utility_regret", "model_identification_efficiency",
              "proper_prediction_calibration", "delayed_planning", "knowledge_retention", "capability_per_compute"}
local function fmt(...) return string.format(...) end
local function group(S, variant, q) return S.groups[variant .. ":" .. (q or 4)] end
local function comparison(S, ref, q)
  for _, c in ipairs(S.comparisons) do if c.reference == ref and c.budget_quarters == (q or 4) then return c end end
end
local function gmean(xs)
  local s, n = 0, 0
  for _, x in ipairs(xs) do if x and x > 0 then s = s + math.log(x); n = n + 1 end end
  return n > 0 and math.exp(s / n) or nil
end
-- geometric mean of the supported per-axis ratios, optionally skipping one axis
local function axis_gm(ratios, skip)
  local xs = {}
  for _, ax in ipairs(AXES) do if ratios[ax] and ax ~= skip then xs[#xs + 1] = ratios[ax] end end
  return gmean(xs), #xs
end
local function axis_line(ratios)
  local t = {}
  for _, ax in ipairs(AXES) do if ratios[ax] then t[#t + 1] = fmt("%s %.2fx", ax, ratios[ax]) end end
  return table.concat(t, "; ")
end
local function ratio(a, b) return (a and b and b > 0) and a / b or nil end
-- hard gate violations (failures, faults, guards, resource violations) and budget-truncated streams over every variant and budget
local function gate_text(S)
  local hard, incomplete, where = 0, 0, {}
  for key, g in pairs(S.groups) do
    local gt = g.gates
    hard = hard + gt.failures + gt.faults + gt.guards + gt.resource_violations
    incomplete = incomplete + gt.incomplete
    if gt.incomplete > 0 then where[#where + 1] = fmt("%s %d", key, gt.incomplete) end
  end
  table.sort(where)
  return hard, incomplete, #where > 0 and table.concat(where, ", ") or "none"
end

-- ---------------------------------------------------------------------------------------------- headline comparisons
local hq4, dq4 = comparison(H, "g2_full", 4), comparison(D, "g2_full", 4)
local hq1, hq2 = comparison(H, "g2_full", 1), comparison(H, "g2_full", 2)
local hf, hg, hb = group(H, "full"), group(H, "g2_full"), group(H, "balanced_fixed")
local df, dg, db = group(D, "full"), group(D, "g2_full"), group(D, "balanced_fixed")
local gf, gg, gb = GN.groups.full, GN.groups.g2_full, GN.groups.balanced_fixed
local h7, hn = axis_gm(hq4.axis_ratios, "model_identification_efficiency")
local d7 = axis_gm(dq4.axis_ratios, "model_identification_efficiency")
local hb7, hbn = axis_gm(comparison(H, "balanced_fixed", 4).axis_ratios)
local db7 = axis_gm(comparison(D, "balanced_fixed", 4).axis_ratios)
local function pair(S, other) for _, p in ipairs(S.pairwise) do if p.other == other then return p end end end

-- ---------------------------------------------------------------------------------------------- ablation table
local ABL = {"no_library", "no_exceptions", "no_deep_terms", "no_deliberation", "no_exploration", "no_population", "no_noise_detection"}
local function comp_ratio(S, v) local a, b = group(S, "full"), group(S, v); return ratio(a.composite, b.composite) end
local ablation = {}
for _, v in ipairs(ABL) do
  local rh, rd = comp_ratio(H, v), comp_ratio(D, v)
  local rg = ratio(gf.composite, GN.groups[v].composite)
  local uh = ratio(hf.mean_utility, group(H, v).mean_utility)
  local wh = ratio(group(H, v).mean_work, hf.mean_work)
  local pos, neg = 0, 0
  for _, r in ipairs({rh, rd, rg}) do if r >= 1.03 then pos = pos + 1 elseif r <= 0.97 then neg = neg + 1 end end
  local verdict
  if pos == 3 then verdict = "helps the composite on all 3 evaluated sets"
  elseif pos > 0 and neg == 0 then verdict = fmt("helps the composite on %d of 3 sets (>=3%%), neutral on the rest", pos)
  elseif neg > 0 and pos == 0 then verdict = fmt("the ablation scores higher on %d of 3 sets (>=3%%): no demonstrated benefit there", neg)
  elseif pos > 0 and neg > 0 then verdict = "inconsistent: the sign of the effect changes between sets"
  else verdict = "neutral on the composite (all three sets within +-3%)" end
  ablation[#ablation + 1] = {
    name = v,
    composite_ratio_full_over_ablation = {heldout = rh, diagnostic = rd, generated = rg},
    heldout_utility_ratio = uh, heldout_work_ratio_ablation_over_full = wh,
    heldout_utility = group(H, v).mean_utility, generated_utility = GN.groups[v].utility, verdict = verdict,
  }
end

-- ---------------------------------------------------------------------------------------------- family table
local FAMS = {"causal", "symbolic", "delayed", "allocation", "latent", "regime"}
local function family_row(S, v)
  local t = {}
  for _, f in ipairs(FAMS) do local a = S.per_family[v .. ":4:" .. f]; t[#t + 1] = fmt("%s %.3f", f, a and a.util or 0) end
  return table.concat(t, ", ")
end
local function fam_mean(S, v, key)
  local t = 0
  for _, f in ipairs(FAMS) do t = t + S.per_family[v .. ":4:" .. f][key] end
  return t / #FAMS
end
local function stat(S, key, i) local s = S.stats[key]; return s and s[i] or 0 end

-- ---------------------------------------------------------------------------------------------- compute curve
local function curve(controller)
  local t = {}
  for _, r in ipairs(C.rows) do
    if r.controller == controller then t[#t + 1] = fmt("cap %.2fM: utility %.3f (truncated %d/%d, work %.2fM)", r.cap / 1e6, r.utility, r.truncated_streams, r.cases, r.work / 1e6) end
  end
  return t
end
local function crow(controller, cap_div)
  for _, r in ipairs(C.rows) do if r.controller == controller and math.abs(r.cap_fraction - 1 / cap_div) < 1e-6 then return r end end
end
local c2, c4, c8 = crow("full", 16), crow("full", 8), crow("full", 4)
local f2, f4 = crow("g2_full", 16), crow("g2_full", 8)
local b2 = crow("balanced_fixed", 16)

local hn_lib, hn_full = group(H, "no_library"), hf

return {
  title = "generation-3 reasoner: audit, mechanisms, measured evidence, limits",
  language = "Lua 5.4; every reasoning step of the controller is charged VM-1 execution (the host only compiles the image and runs the frozen task physics)",
  baseline = {
    name = "G2 full (asi.reason.core + asi.reason.plan, unchanged code path) and the unchanged paid fixed coverage reference (balanced_fixed)",
    scope = "identical cases, seeds, budgets, physics and scorecard; both references run through their original code; the two are asserted by hash before any case runs",
    pinned = "Env.protocol_hash and E.DEFINITIONS_HASH must equal the frozen G2 protocol or generation-3 evaluation refuses to run",
  },
  terminology = {
    claimed = "a hypothesis-population world-model learner with a cross-episode world library, value-allocated search, and a self-metered effort policy",
    learned_structures = "small transition programs (world models), a three-world library, cached plans, reward tables by goal distance, effort back-off schedules",
    not_claimed = {
      "recursive self-improvement: the reasoning algorithm itself is never rewritten; improvement comes from a better fixed algorithm plus learned world models",
      "general intelligence or a coverage certificate: rules come from a finite grammar and are ranked by empirical prospective accuracy only",
      "that synthetic predictions are evidence: every score is computed from real outcomes that the rule predicted before it saw them",
    },
  },
  audit_of_generation_2 = {
    mechanism = "per-field typed term DAGs from supplied operator families, a depth-3 contingent planner and a procedural macro memory",
    recorded_weaknesses = {
      "its own G2 report records: 8.77% lower reward than the paid fixed coverage reference at 2.73x the work; memory, meta and representation ablations scored higher than the full system",
      "its own G2 report records zero OOD recovery and zero early-return retention in the delayed and latent families",
      fmt("measured here on fresh generated worlds: model identification %.3f for G2 (%.3f for the fixed reference) against %.3f for generation 3", gg.axes.model_identification_efficiency, gb.axes.model_identification_efficiency, gf.axes.model_identification_efficiency),
      fmt("measured on held-out frozen seeds: G2 identification %.3f, delayed planning %.3f, retention %.3f", hg.axes.model_identification_efficiency, hg.axes.delayed_planning, hg.axes.knowledge_retention),
    },
  },
  architecture = {
    representation = "per (action, field) cell, up to four competing transition rules plus an implicit persistence hypothesis; a rule is a depth<=2 term over current fields, one-step lags, the action, constants and (for fields classified exogenous) their post-step values, with <=2 noise-tolerant state-conditional exceptions",
    induction = "bit-parallel (15 lanes x 4 bits per word) simplest-first program search over a window of recent real transitions; perfect pass then noise-tolerant pass; depth-2 terms by inverse peeling; exception terms by gain search",
    revision = "every rule is scored prospectively on each real transition (its prediction is fixed before the outcome is seen); only the failure of the best hypothesis of a cell triggers re-induction of that cell, gated by relevance and exponential back-off",
    memory = "finished episodes are stored as worlds (best rules, reward table, noise flags, context fingerprint); a new episode is a context switch that restores a recognised world as tentative hypotheses removed after two prospective misses, and lets induction reuse programs from any stored world",
    planning = "breadth-first search over distinct predicted states, finite-horizon value iteration, reward table learned by goal distance, intrinsic novelty over (state, action) pairs, plan following while observations match, lane-parallel chance lookahead over exogenous fields",
    meta = "deliberation depth is spent only where one-step values show no signal and the dynamics are predictable, with learned back-off after failed deliberations; induction effort follows goal relevance; exogenous fields are detected so that their unpredictability stops consuming search; the guest reads its own metered clock and switches to an economy mode when work left per remaining step falls below an allowance",
    forecast = "valid fields only; unknown mass calibrated from the measured accuracy of the controller's own earlier forecasts",
    resources = fmt("one task-independent image: %d words (%d of %d bits); %d static RAM words of %d (stack %d); stress audit %d runs (24 seeds x 6 frozen families + 1 generated world), %d faults/guards/failures, max work %.2fM against the 8.39M quarter budget",
