-- ======================================================================== asi.risk  (asi/risk.lua)
package.preload["asi.risk"] = function(...)
--[============[
asi/risk.lua -- OFFLINE exact verification of the controller's statistical and risk machinery.

Everything here is EVALUATOR code: it never produces controller advice and never runs inside the
metered machine. It re-derives, with arbitrary precision rationals (asi/bigint.lua), what the guest
claims, using algorithms independent of the guest's:

  * exact_counts(b)          N_b(y) of the initial-state temperature-reading law from the SPEC laws
  * log2_enclosure(n, d)     rigorous BigInt enclosure of log2(n/d) (digit extraction on exact rationals
                             truncated to 256 bits with outward rounding) -- not the guest's algorithm
  * verify_guest_tables()    guest LOGLO/LOGHI contain the true log2 for all 160 (b,y) entries
  * efactor_lemma()          exhaustive exact check of formula (T): e >= 0 and conditional mean <= 1
  * ledger()                 equation (B) in exact rationals; verify_guest_ledger() recomputes the guest's
  * stopped_ledger_dp()      exact finite-horizon check of lemma GS for a finite controlled chain
  * zero_failure_count()     ceil(ln 0.05 / ln(1 - 2^-20)) with a rigorous logarithm enclosure
  * shield_bound_lemma()     exhaustive check of the one-step worst-case heat bound used by the shield
These are checks of finite lemmas under their stated hypotheses; none of them proves that a fitted
model covers the world (that is exactly what the e-process evidence does, with its alpha).
]============]
local B = require("asi.bigint")
local Q = B.Q
local L = require("asi.laws")
local S = require("asi.spec")
local Risk = {}

-- ---------------------------------------------------------------- exact sample law of record 0
-- P_b(y) for y = clip(7 + xi + b + eps - 3F, 0, 31); (g0, xi, F, eps) from the SPEC laws; returns {[y] = Q}
function Risk.exact_pmf(b)
  local pmf = {}
  for y = 0, 31 do pmf[y] = Q.from(0) end
  local eps_p = {Q.make(1, 16), Q.make(7, 8), Q.make(1, 16)}
  for g = 0, 1 do
    local pg = (g == 1) and Q.make(1, 5) or Q.make(4, 5)
    local pxi1 = Q.make(L.thermal_noise_prob(g))
    local pf1 = Q.make(L.fault_next_prob(0, g))
    for xi = 0, 1 do
      local pxi = (xi == 1) and pxi1 or Q.sub(1, pxi1)
      for F = 0, 1 do
        local pf = (F == 1) and pf1 or Q.sub(1, pf1)
        for e = -1, 1 do
          local y = math.max(0, math.min(31, 7 + xi + b + e - 3 * F))
          pmf[y] = Q.add(pmf[y], Q.mul(Q.mul(pg, pxi), Q.mul(pf, eps_p[e + 2])))
        end
      end
    end
  end
  return pmf
end

function Risk.exact_counts(b)
  local pmf, out = Risk.exact_pmf(b), {}
  for y = 0, 31 do
    local v = Q.mul(pmf[y], 163840)
    assert(B.eq(v.d, 1), "N_b(y) must be an integer count")
    out[y] = B.to_int(v.n)
  end
  return out
end

-- ------------------------------------------------------------------ rigorous log2 enclosure
-- returns lo, hi (BigInt-rational, as Q) with lo <= log2(n/d) <= hi, hi - lo <= 2^-bits
local function sqr_round(x, prec, up)       -- x Q >= 1; square, then round to a 2^-prec grid (outward)
  local sq = Q.mul(x, x)
  local scale = B.pow(2, prec)
  local scaled = Q.mul(sq, scale)
  local f = Q.floor(scaled)
  if up and not B.eq(Q.sub(scaled, f).n, 0) then f = B.add(f, 1) end
  return Q.make(f, scale)
end
function Risk.log2_enclosure(n, d, bits)
  bits = bits or 80
  local x = Q.make(n, d)
  local e = 0
  local two = Q.from(2)
  while Q.lt(x, 1) do x = Q.mul(x, two); e = e - 1 end
  while Q.le(two, x) do x = Q.div(x, two); e = e + 1 end
  local lo_x, hi_x = x, x
  local lo_frac, step = Q.from(0), Q.make(1, 2)
  local width = Q.make(1, 1)
  local prec = bits + 40
  local half = Q.make(1, 2)
  for _ = 1, bits do
    lo_x = sqr_round(lo_x, prec, false); hi_x = sqr_round(hi_x, prec, true)
    if Q.le(two, lo_x) then
      lo_frac = Q.add(lo_frac, step); lo_x = Q.mul(lo_x, half); hi_x = Q.mul(hi_x, half)
    elseif Q.lt(hi_x, two) then
      -- digit 0
    else
      -- straddle: stop refining
      return Q.add(Q.from(e), lo_frac), Q.add(Q.add(Q.from(e), lo_frac), Q.mul(step, 2))
    end
    step = Q.mul(step, half)
  end
  return Q.add(Q.from(e), lo_frac), Q.add(Q.add(Q.from(e), lo_frac), Q.mul(step, 2))
end

-- check the guest's fixed-point (2^-16) enclosures against the independent reference
-- tables: arrays LOGLO[b*32+y], LOGHI[...] (guest integers, already read from guest RAM); BIG marks -infinity
function Risk.verify_guest_tables(LOGLO, LOGHI, BIG)
  local checked = 0
  for bi = 0, 4 do
    local counts = Risk.exact_counts(bi - 2)
    for y = 0, 31 do
      local lo, hi = LOGLO[bi * 32 + y], LOGHI[bi * 32 + y]
      if counts[y] == 0 then
        if lo ~= -BIG or hi ~= -BIG then return false, string.format("impossible reading (b=%d,y=%d) must map to -inf", bi - 2, y) end
      else
        local rlo, rhi = Risk.log2_enclosure(counts[y], 163840, 60)
        local glo, ghi = Q.make(lo, 65536), Q.make(hi, 65536)
        if Q.lt(rhi, glo) or Q.lt(ghi, rlo) then
          return false, string.format("table entry (b=%d,y=%d) [%d,%d]/2^16 does not contain log2(%d/163840)", bi - 2, y, lo, hi, counts[y])
        end
        if hi - lo > 4 then return false, "enclosure unexpectedly wide at b=" .. (bi - 2) .. " y=" .. y end
      end
      checked = checked + 1
    end
  end
  return true, checked
end

-- ------------------------------------------------------------------ formula (T): finite-factor lemma
-- exhaustive over a rational grid of enclosures and bets: nonnegative, conditional mean <= 1
function Risk.efactor_lemma(den, lamden)
  den, lamden = den or 8, lamden or 8
  local cases = 0
  for pl_n = 0, den do for ph_n = pl_n, den do
    local pl, ph = Q.make(pl_n, den), Q.make(ph_n, den)
    for lam_n = -lamden, lamden do
      local lam = Q.make(lam_n, lamden)
      for y = 0, 1 do
        local ref = Q.sign(lam) >= 0 and ph or pl                 -- formula (T)
        local e = Q.add(1, Q.mul(lam, Q.sub(y, ref)))
        if Q.sign(e) < 0 then return false, "negative e-factor" end
        cases = cases + 1
      end
      -- conditional mean for every true mean p in [pl, ph] on a grid: must be <= 1
      for p_n = pl_n * 4, ph_n * 4 do
        local p = Q.make(p_n, 4 * den)
        local ref = Q.sign(lam) >= 0 and ph or pl
        local mean = Q.add(1, Q.mul(lam, Q.sub(p, ref)))
        if Q.lt(1, mean) then return false, "conditional mean above one" end
        cases = cases + 1
      end
    end
  end end
  return true, cases
end

-- ---------------------------------------------------------------- equation (B) in exact rationals
function Risk.ledger(Delta, eta, alpha, eps)
  local reserve = Q.sub(Q.sub(Q.sub(Delta, eta), alpha), eps)
  return {reserve = reserve, feasible = Q.sign(reserve) >= 0}
end

-- recompute the guest's ledger (units of 2^-40) from its own counts; blo/bcnt = guest arrays (16 each)
function Risk.verify_guest_ledger(led, blo, bcnt, default_bias_lo)
  local n = 0
  for i = 0, 15 do
    local b = math.min(blo[i] + 3, 4)
    if bcnt[i] == 0 then b = 0 end
    n = n + b
  end
  local Delta = Q.make(1, 1048576)
  local alpha = Q.mul(Q.make(n, 1), Q.make(1, 1 << 31))
  local r = Risk.ledger(Delta, Q.from(0), alpha, Q.from(0))
  local unit = Q.make(1, 1 << 40)
  local reserve_units = Q.div(r.reserve, unit)
  if not B.eq(reserve_units.d, 1) then return false, "reserve is not a whole number of 2^-40 units" end
  if B.to_int(reserve_units.n) ~= led.reserve then return false, "guest reserve differs: " .. led.reserve .. " vs " .. B.tostring(reserve_units.n) end
  if led.n_ids ~= n then return false, "guest identifier count differs" end
  if (led.feasible == 1) ~= r.feasible then return false, "feasibility flag differs" end
  -- allocations: n identifiers of 2^-31 each, prefix-free fixed-length codes (node:4, hypothesis:3) => at most 80
  -- of 128 codes, so the sum is at most 80/128 * 2^-24 < alpha = 2^-24
  if n > 80 then return false, "more identifiers than codes" end
  return true, {n_ids = n, alpha = alpha, reserve = r.reserve}
end

-- ---------------------------------------------------------------- stopped-ledger lemma (exact DP)
-- chain description:
--   steps N; state space finite; trans(i, s) -> list of {p = Q, fail = bool, next = state, r_next = Q}
--   r[i][s]: stored risk potential before boundary i in state s; eps[i]: allowance of step i.
-- verifies (Q) at every (i,s) and returns the exact probability of eventual failure from `s0` with potential r0.
function Risk.stopped_ledger_dp(N, trans, r, eps, s0)
  local memo = {}
  local function fail_prob(i, s)
    if i == N then return Q.from(0) end
    local key = i .. ":" .. tostring(s)
    if memo[key] then return memo[key] end
    local total = Q.from(0)
    for _, t in ipairs(trans(i, s)) do
      if t.fail then total = Q.add(total, t.p)
      else total = Q.add(total, Q.mul(t.p, fail_prob(i + 1, t.next))) end
    end
    memo[key] = total
    return total
  end
  -- inequality (Q) on every reachable (i, s)
  local function check(i, s, seen)
    if i == N then return true end
    local key = i .. ":" .. tostring(s)
    if seen[key] then return true end
    seen[key] = true
    local lhs = Q.from(0)
    for _, t in ipairs(trans(i, s)) do
      if t.fail then lhs = Q.add(lhs, t.p)
      else lhs = Q.add(lhs, Q.mul(t.p, r[i + 1][t.next])) end
    end
    if Q.lt(Q.add(r[i][s], eps[i]), lhs) then return false, string.format("(Q) violated at i=%d s=%s", i, tostring(s)) end
    for _, t in ipairs(trans(i, s)) do
      if not t.fail then
        local ok, why = check(i + 1, t.next, seen); if not ok then return false, why end
      end
    end
    return true
  end
  local ok, why = check(0, s0, {})
  if not ok then return false, why end
  local bound = r[0][s0]
  for i = 0, N - 1 do bound = Q.add(bound, eps[i]) end
  local exact = fail_prob(0, s0)
  return Q.le(exact, bound), {exact = exact, bound = bound}
end

-- ---------------------------------------------------------------- RISK-TEST sample count (rigorous)
local function ln_enclosure(q, terms)       -- ln(q) for rational q > 0, as Q lo/hi
  terms = terms or 60
  local two = Q.from(2)
  local k = 0
  while Q.lt(two, q) do q = Q.div(q, two); k = k + 1 end
  while Q.lt(q, Q.make(1, 2)) do q = Q.mul(q, two); k = k - 1 end
  local function atanh_series(z)             -- 2 * atanh(z), |z| <= 1/3 ... returns lo, hi
    local sum, zp, z2 = Q.from(0), z, Q.mul(z, z)
    for i = 0, terms do
      sum = Q.add(sum, Q.div(zp, 2 * i + 1))
      zp = Q.mul(zp, z2)
    end
    -- tail bound: sum_{i>terms} |z|^(2i+1)/(2i+1) <= |z|^(2terms+3) / (1 - z^2)
    local absz = Q.sign(z) >= 0 and z or Q.neg(z)
    local tail = Q.div(Q.mul(Q.pow(absz, 2 * terms + 3), 1), Q.sub(1, z2))
    return Q.mul(Q.sub(sum, tail), 2), Q.mul(Q.add(sum, tail), 2)
  end
  local zq = Q.div(Q.sub(q, 1), Q.add(q, 1))
  local llo, lhi = atanh_series(zq)
  local ln2lo, ln2hi = atanh_series(Q.make(1, 3))
  return Q.add(llo, Q.mul(ln2lo, k)), Q.add(lhi, Q.mul(ln2hi, k))
end
Risk.ln_enclosure = ln_enclosure

function Risk.zero_failure_count(delta_den, confidence_complement_num, confidence_complement_den)
  delta_den = delta_den or 1048576
  local beta = Q.make(confidence_complement_num or 1, confidence_complement_den or 20)       -- 0.05
  -- n >= ln(beta) / ln(1 - 1/delta_den) = (-ln beta) / (-ln(1 - x)),   x = 1/delta_den
  local x = Q.make(1, delta_den)
  local nlo, nhi = ln_enclosure(Q.div(1, beta))                   -- -ln(beta) = ln(1/beta)
  -- -ln(1-x) = sum x^k/k : enclose with a tail bound
  local s, xp = Q.from(0), x
  for k = 1, 12 do s = Q.add(s, Q.div(xp, k)); xp = Q.mul(xp, x) end
  local tail = Q.mul(Q.div(xp, 1), Q.div(1, Q.sub(1, x)))
  local dlo, dhi = s, Q.add(s, tail)
  local qlo, qhi = Q.div(nlo, dhi), Q.div(nhi, dlo)             -- enclosure of the real quotient
  local nmin_lo, nmin_hi = Q.ceil(qlo), Q.ceil(qhi)
  assert(B.eq(nmin_lo, nmin_hi), "logarithm enclosure too coarse to fix the ceiling")
  return B.to_int(nmin_lo)
end

-- ---------------------------------------------------------------- shield one-step bound lemma
-- For every command pair (a1,a2), orientation, parameter in the public support, load, noise value:
--   (gamma+g)*p - eta*c - 1 + xi  <=  heat(a1,a2) where heat = (gamma_max+1)*max(a1,a2) - eta_min*min(a1,a2)
-- and the diffusion base is monotone in all three old temperatures; hence T <= U componentwise implies
-- T' <= min(63, floor((4U_i+U_l+U_r)/6) + heat), the transition the guest propagates.
function Risk.shield_bound_lemma(gamma_max, eta_min)
  local cases = 0
  for a1 = 0, 1 do for a2 = 0, 1 do
    local heat = (gamma_max + 1) * math.max(a1, a2) - eta_min * math.min(a1, a2)
    for sigma = 0, 1 do
      local p, c = L.channels(sigma, a1, a2)
      for gamma = 2, gamma_max do for eta = eta_min, 5 do for g = 0, 1 do for xi = 0, 1 do
        local actual = (gamma + g) * p - eta * c - 1 + xi
        if actual > heat then return false, string.format("heat bound violated a=(%d,%d) sigma=%d gamma=%d eta=%d g=%d xi=%d: %d > %d", a1, a2, sigma, gamma, eta, g, xi, actual, heat) end
        cases = cases + 1
      end end end end
    end
  end end
  -- monotonicity of the diffusion base in every argument
  for c = 0, 62 do for l = 0, 62 do for r = 0, 62 do
    local base = L.thermal_base(c, l, r)
    if L.thermal_base(c + 1, l, r) < base or L.thermal_base(c, l + 1, r) < base or L.thermal_base(c, l, r + 1) < base then
      return false, "diffusion base not monotone"
    end
    cases = cases + 1
  end end end
  return true, cases
end

--[[@@END@@]]
return Risk
end

-- ======================================================================== asi.proof  (asi/proof.lua)
package.preload["asi.proof"] = function(...)
--[============[
asi/proof.lua -- a FINITE, SOUND CHECKING KERNEL for a declared tractable proof language (prompt item G).

This kernel is evaluator-side. The controller has its own metered checkers inside VM-1 (guest static checker and
exhaustive equivalence in asi/guest/pkg.lua, the ledger in asi/guest/ledger.lua); this module is the independent,
declared proof language in which those obligations are stated, together with REAL PRODUCERS of certificates for the
transformations the controller actually installs, and a checker that rejects everything it cannot decide.

CERTIFICATES are Lua tables (data). Nothing in a certificate is ever executed as code (no load / loadfile / dofile).
  { rule = <name>, statement = {...}, witness = {...}, premises = { {name=, version=, kind="logical"|"empirical", text=} } }

RULES (the whole language; anything else is reported as UNSUPPORTED, never as true)
  rat_le / rat_lt / rat_eq   ground exact-rational inequality between two rational term trees
                             (terms: q, add, sub, mul, div, pow, min, max). Decided by exact evaluation.
  bv_forall                  a width-typed bit-vector predicate holds for EVERY assignment of finite-width variables
                             (and, or, xor, not, add, sub, mul, shl, shr, eq, ult, ule, ite, extract, concat).
                             Proof = bounded exhaustion (resource-capped; an over-large domain is reported, not assumed).
  int_forall                 a boolean finite-expr-1 term (the SPEC expression language, checked by asi/astx.lua) holds on
                             every point of a finite integer box.
  chain_ledger               finite transition certificate of the stopped-ledger inequality (Q): for every node
                             sum_{fail} p + sum_{ok} p r(next) <= r(node) + eps(step), probabilities nonnegative and
                             summing to exactly one; conclusion Pr(failure) <= r(start) + sum eps.
  straight_line_bound        a VM-1 program contains no backward control flow and no environment instruction, hence every
                             execution takes at most (#words) instructions: a resource trace bound for ALL inputs.
  code_equiv_ast             a VM-1 program computes the value of a finite-expr-1 term on every point of a finite box
                             (inputs stored as RAM words), with an exact instruction count per run.
  vm_equiv                   two code entries of a recorded VM state (e.g. the resident decision kernel and an emitted
                             package) produce identical outputs on every point of a finite input box.
  all_of                     conjunction of sub-certificates.

PREMISES carry VERSIONS. A certificate whose premise version differs from the current version is STALE and is rejected;
premises of kind "empirical" are never discharged by the kernel: a valid certificate with empirical premises is reported
as CONDITIONAL (syntax correctness is not the truth of an empirical premise).

COST: every primitive evaluation increments `steps`; checking stops with status "resource" at ctx.step_limit.
]============]
local U = require("asi.util")
local B = require("asi.bigint")
local Q = B.Q
local X = require("asi.astx")
local VM = require("asi.vm")
local ISA = require("asi.isa")

local Proof = {}
Proof.RULES = {"rat_le", "rat_lt", "rat_eq", "bv_forall", "int_forall", "chain_ledger", "straight_line_bound",
               "code_equiv_ast", "vm_equiv", "all_of"}
Proof.DEFAULT_STEP_LIMIT = 50000000
Proof.DEFAULT_MAX_POINTS = 1 << 22

local function result(ok, status, steps, reason, extra)
  local r = {ok = ok, status = status, steps = steps or 0, reason = reason}
  for k, v in pairs(extra or {}) do r[k] = v end
  return r
end

-- ------------------------------------------------------------------ rational terms
local function qeval(t, st)
  st.steps = st.steps + 1
  if st.steps > st.limit then error({resource = true}, 0) end
  local k = t.k
  if k == "q" then return Q.make(t.n, t.d or 1)
  elseif k == "add" then return Q.add(qeval(t.a, st), qeval(t.b, st))
  elseif k == "sub" then return Q.sub(qeval(t.a, st), qeval(t.b, st))
  elseif k == "mul" then return Q.mul(qeval(t.a, st), qeval(t.b, st))
  elseif k == "div" then
    local d = qeval(t.b, st)
    if Q.sign(d) == 0 then error({invalid = "division by zero in a rational term"}, 0) end
    return Q.div(qeval(t.a, st), d)
  elseif k == "pow" then
    if math.type(t.e) ~= "integer" or t.e < 0 or t.e > 4096 then error({invalid = "exponent must be an integer in 0..4096"}, 0) end
    st.steps = st.steps + t.e
    return Q.pow(qeval(t.a, st), t.e)
  elseif k == "min" then return Q.min(qeval(t.a, st), qeval(t.b, st))
  elseif k == "max" then return Q.max(qeval(t.a, st), qeval(t.b, st)) end
  error({invalid = "unknown rational term " .. tostring(k)}, 0)
end

-- ------------------------------------------------------------------ bit-vector language
local function bv_type(n, vars)
  local op = n.op
  if op == "var" then
    local w = vars[n.name]
    if not w then error({invalid = "unknown bit-vector variable " .. tostring(n.name)}, 0) end
    return w
  elseif op == "const" then
    if math.type(n.w) ~= "integer" or n.w < 1 or n.w > 62 or math.type(n.v) ~= "integer" or n.v < 0 or n.v >= (1 << n.w) then
      error({invalid = "malformed bit-vector constant"}, 0)
    end
    return n.w
  elseif op == "not" then return bv_type(n.a, vars)
  elseif op == "and" or op == "or" or op == "xor" or op == "add" or op == "sub" or op == "mul" then
    local wa, wb = bv_type(n.a, vars), bv_type(n.b, vars)
    if wa ~= wb then error({invalid = "width mismatch in " .. op}, 0) end
    return wa
  elseif op == "shl" or op == "shr" then
    if math.type(n.k) ~= "integer" or n.k < 0 then error({invalid = "shift amount must be a nonnegative integer constant"}, 0) end
    return bv_type(n.a, vars)
  elseif op == "eq" or op == "ult" or op == "ule" then
    local wa, wb = bv_type(n.a, vars), bv_type(n.b, vars)
    if wa ~= wb then error({invalid = "width mismatch in " .. op}, 0) end
    return 1
  elseif op == "ite" then
    if bv_type(n.c, vars) ~= 1 then error({invalid = "ite condition must have width 1"}, 0) end
    local wa, wb = bv_type(n.a, vars), bv_type(n.b, vars)
    if wa ~= wb then error({invalid = "ite branch width mismatch"}, 0) end
    return wa
  elseif op == "extract" then
    local w = bv_type(n.a, vars)
    if not (math.type(n.hi) == "integer" and math.type(n.lo) == "integer" and n.lo >= 0 and n.hi >= n.lo and n.hi < w) then
      error({invalid = "bad extract range"}, 0)
    end
    return n.hi - n.lo + 1
  elseif op == "concat" then
    local w = bv_type(n.a, vars) + bv_type(n.b, vars)
    if w > 62 then error({invalid = "concat wider than 62 bits"}, 0) end
    return w
  end
  error({invalid = "unknown bit-vector operator " .. tostring(op)}, 0)
end

local function bv_eval(n, env, vars, st)
  st.steps = st.steps + 1
  local op = n.op
  if op == "var" then return env[n.name]
  elseif op == "const" then return n.v end
  local function mask(w) return (1 << w) - 1 end
  if op == "not" then local w = bv_type(n.a, vars); return (~bv_eval(n.a, env, vars, st)) & mask(w)
  elseif op == "and" then return bv_eval(n.a, env, vars, st) & bv_eval(n.b, env, vars, st)
  elseif op == "or" then return bv_eval(n.a, env, vars, st) | bv_eval(n.b, env, vars, st)
  elseif op == "xor" then return bv_eval(n.a, env, vars, st) ~ bv_eval(n.b, env, vars, st)
  elseif op == "add" then local w = bv_type(n.a, vars); return (bv_eval(n.a, env, vars, st) + bv_eval(n.b, env, vars, st)) & mask(w)
  elseif op == "sub" then local w = bv_type(n.a, vars); return (bv_eval(n.a, env, vars, st) - bv_eval(n.b, env, vars, st)) & mask(w)
  elseif op == "mul" then local w = bv_type(n.a, vars); return (bv_eval(n.a, env, vars, st) * bv_eval(n.b, env, vars, st)) & mask(w)
  elseif op == "shl" then local w = bv_type(n.a, vars); local v = bv_eval(n.a, env, vars, st); if n.k >= w then return 0 end; return (v << n.k) & mask(w)
  elseif op == "shr" then local v = bv_eval(n.a, env, vars, st); if n.k >= 62 then return 0 end; return v >> n.k
  elseif op == "eq" then return bv_eval(n.a, env, vars, st) == bv_eval(n.b, env, vars, st) and 1 or 0
  elseif op == "ult" then return bv_eval(n.a, env, vars, st) < bv_eval(n.b, env, vars, st) and 1 or 0
  elseif op == "ule" then return bv_eval(n.a, env, vars, st) <= bv_eval(n.b, env, vars, st) and 1 or 0
  elseif op == "ite" then if bv_eval(n.c, env, vars, st) == 1 then return bv_eval(n.a, env, vars, st) end; return bv_eval(n.b, env, vars, st)
  elseif op == "extract" then return (bv_eval(n.a, env, vars, st) >> n.lo) & mask(n.hi - n.lo + 1)
  elseif op == "concat" then local wb = bv_type(n.b, vars); return (bv_eval(n.a, env, vars, st) << wb) | bv_eval(n.b, env, vars, st) end
  error({invalid = "unknown bit-vector operator"}, 0)
end
Proof.bv_type, Proof.bv_eval = bv_type, bv_eval

-- ------------------------------------------------------------------ VM helpers (replay of recorded machine states)
local function run_vm(vm, entry, ret, args, limit)
  vm.halted, vm.reason, vm.fault = false, nil, nil
  vm.pc = entry
  vm.r[15] = ret
  for i, a in ipairs(args or {}) do vm.r[i] = a end
  vm:run(limit)
  return vm.reason
end

local function vm_from_snapshot(snap, machine)
  local prof = {inst_work = 1, inst_dur = 1, ram_words = snap.ram_words, horizon = 1 << 60, watchdog_period = nil,
                step_ticks = 1, work_budget = 1 << 60, stack_words = snap.stack_words or 0}
  local vm = VM.new({image = {words = snap.image, entry = 0, bits = #snap.image * 64}, machine = machine, profile = prof})
  for i = 0, snap.ram_words - 1 do vm.ram[i] = snap.ram[i + 1] or 0 end          -- snapshots are 1-based arrays (canonical form)
  for i = 0, 15 do vm.r[i] = snap.regs[i + 1] or 0 end
  return vm
end

-- capture the RAM and registers of a (halted) machine so that kernel entries can be replayed later
function Proof.snapshot_vm(vm, image_words)
  local ram = {}
  for i = 0, vm.ram_words - 1 do ram[i + 1] = vm.ram[i] end
  local regs = {}
  for i = 0, 15 do regs[i + 1] = vm.r[i] end
  return {image = image_words, ram = ram, ram_words = vm.ram_words, regs = regs, stack_words = vm.stack_words}
end

-- ------------------------------------------------------------------ the checker
local check

local function box_points(vars)
  local n = 1
  for _, v in ipairs(vars) do
    local span = v.hi - v.lo + 1
    if span < 1 then error({invalid = "empty variable range"}, 0) end
    n = n * span
    if n > (1 << 40) then return n end
  end
  return n
end

local function each_point(vars, fn)
  local env = {}
  local idx = {}
  for i, v in ipairs(vars) do idx[i] = v.lo; env[v.name] = v.lo end
  local k = #vars
  while true do
    local r = fn(env)
    if r ~= nil then return r end
    local i = k
    while i >= 1 do
      idx[i] = idx[i] + 1
      if idx[i] <= vars[i].hi then env[vars[i].name] = idx[i]; break end
      idx[i] = vars[i].lo; env[vars[i].name] = vars[i].lo
      i = i - 1
    end
    if i < 1 then return nil end
  end
end

local RULE = {}

RULE.rat_le = function(c, ctx, st)
  local s = c.statement
  local a, b = qeval(s.lhs, st), qeval(s.rhs, st)
  return Q.le(a, b), "lhs=" .. Q.tostring(a) .. " rhs=" .. Q.tostring(b)
end
RULE.rat_lt = function(c, ctx, st)
  local s = c.statement
  local a, b = qeval(s.lhs, st), qeval(s.rhs, st)
  return Q.lt(a, b), "lhs=" .. Q.tostring(a) .. " rhs=" .. Q.tostring(b)
end
RULE.rat_eq = function(c, ctx, st)
  local s = c.statement
  local a, b = qeval(s.lhs, st), qeval(s.rhs, st)
  return Q.eq(a, b), "lhs=" .. Q.tostring(a) .. " rhs=" .. Q.tostring(b)
end

RULE.bv_forall = function(c, ctx, st)
  local s = c.statement
  local vars, widths, total = {}, {}, 1
  for _, v in ipairs(s.vars) do
    if math.type(v.w) ~= "integer" or v.w < 1 or v.w > 62 then error({invalid = "variable width must be in 1..62"}, 0) end
    widths[v.name] = v.w
    vars[#vars + 1] = {name = v.name, lo = 0, hi = (1 << v.w) - 1}
    total = total * (1 << v.w)
    if total > (ctx.max_points or Proof.DEFAULT_MAX_POINTS) then
      error({resource = true, reason = "domain of " .. total .. "+ points exceeds the exhaustion cap"}, 0)
    end
  end
  if bv_type(s.pred, widths) ~= 1 then error({invalid = "a bit-vector fact must be a width-1 predicate"}, 0) end
  local cex = each_point(vars, function(env)
    st.steps = st.steps + 1
    if st.steps > st.limit then error({resource = true}, 0) end
    if bv_eval(s.pred, env, widths, st) ~= 1 then
      local t = {}
      for k, v in pairs(env) do t[#t + 1] = k .. "=" .. v end
      table.sort(t)
      return table.concat(t, ",")
    end
  end)
  if cex then return false, "counterexample " .. cex end
  return true, "all " .. total .. " assignments satisfy the predicate"
end

RULE.int_forall = function(c, ctx, st)
  local s = c.statement
  local types = {}
  for _, v in ipairs(s.vars) do types[v.name] = {type = "integer"} end
  local ok_t, ty = pcall(X.infer, s.pred, types)
  if not ok_t then error({invalid = "ill-typed term: " .. tostring(ty)}, 0) end
  if ty ~= "boolean" then error({invalid = "an int_forall fact must be boolean"}, 0) end
  if box_points(s.vars) > (ctx.max_points or Proof.DEFAULT_MAX_POINTS) then
    error({resource = true, reason = "box exceeds the exhaustion cap"}, 0)
  end
  local cex = each_point(s.vars, function(env)
    st.steps = st.steps + 1
    if st.steps > st.limit then error({resource = true}, 0) end
    local v = X.eval(s.pred, env)
    if v ~= true then
      local t = {}
      for k, x in pairs(env) do t[#t + 1] = k .. "=" .. x end
      table.sort(t)
      return table.concat(t, ",")
    end
  end)
  if cex then return false, "counterexample " .. cex end
  return true, "holds on the whole box"
end

RULE.chain_ledger = function(c, ctx, st)
  local s, w = c.statement, c.witness
  local nodes = w.nodes
  local sum_eps = Q.from(0)
  for i = 1, s.N do sum_eps = Q.add(sum_eps, Q.make(w.eps[i] and w.eps[i][1] or 0, w.eps[i] and w.eps[i][2] or 1)) end
  for id, nd in pairs(nodes) do
    st.steps = st.steps + 1
    if nd.step < 0 or nd.step > s.N then return false, "node " .. id .. " has a step outside 0..N" end
    local r = Q.make(nd.r[1], nd.r[2])
    if Q.sign(r) < 0 then return false, "negative potential at " .. id end
    if nd.step < s.N then
      local total, lhs = Q.from(0), Q.from(0)
      for _, t in ipairs(nd.trans) do
        local p = Q.make(t.p[1], t.p[2])
        if Q.sign(p) < 0 then return false, "negative probability at " .. id end
        total = Q.add(total, p)
        if t.fail then lhs = Q.add(lhs, p)
        else
          local nx = nodes[t.next]
          if not nx then return false, "missing successor " .. tostring(t.next) end
          if nx.step ~= nd.step + 1 then return false, "successor of " .. id .. " is not at the next step" end
          lhs = Q.add(lhs, Q.mul(p, Q.make(nx.r[1], nx.r[2])))
        end
      end
      if not Q.eq(total, Q.from(1)) then return false, "probabilities at " .. id .. " do not sum to one" end
      local eps = w.eps[nd.step + 1] and Q.make(w.eps[nd.step + 1][1], w.eps[nd.step + 1][2]) or Q.from(0)
      if Q.lt(Q.add(r, eps), lhs) then return false, "stopped-ledger inequality (Q) violated at " .. id end
    end
  end
  local start = nodes[s.start]
  if not start or start.step ~= 0 then return false, "missing start node" end
  local bound = Q.add(Q.make(start.r[1], start.r[2]), sum_eps)
  local claim = Q.make(s.bound[1], s.bound[2])
  if Q.lt(claim, bound) then return false, "claimed bound " .. Q.tostring(claim) .. " is below r0 + sum eps = " .. Q.tostring(bound) end
  return true, "Pr(failure) <= " .. Q.tostring(bound)
end

-- machines a certificate may name; the two published machines are resolved on first use
local MACHINES = setmetatable({}, {__index = function(t, k)
  if k == "parity" then t[k] = require("asi.parity").machine; return t[k] end
  if k == "net" then t[k] = require("asi.run").MACHINE; return t[k] end
end})
function Proof.register_machine(name, machine) MACHINES[name] = machine end

local function num(v)
  if v == true then return 1 elseif v == false then return 0 elseif B.is(v) then return B.to_int(v) end
  return v
end

RULE.straight_line_bound = function(c, ctx, st)
  local s = c.statement
  local m = MACHINES[s.machine]
  if not m then error({invalid = "unknown machine " .. tostring(s.machine)}, 0) end
  local words = s.program
  for i = 1, #words do
    st.steps = st.steps + 1
    local op, rd, ra, rb, imm = ISA.decode(words[i])
    local e = m.by_code[op]
    if not e then return false, "undecodable word at " .. (i - 1) end
    if e.env then return false, "environment instruction " .. e.name .. " at " .. (i - 1) .. " is not straight-line" end
    local fmt = e.fmt
    if fmt == "b2" or fmt == "b1" or fmt == "j" or fmt == "jal" then
      if imm <= 0 then return false, "backward or self branch at " .. (i - 1) end
      if i - 1 + imm > #words then return false, "branch leaves the program at " .. (i - 1) end
    end
    if e.name == "IDLE" or e.name == "JALR" then return false, e.name .. " is not allowed in a straight-line program" end
    if e.name == "JR" and i ~= #words then return false, "an indirect jump is only allowed as the final return" end
  end
  if #words > s.bound then return false, "program has " .. #words .. " words, above the bound " .. s.bound end
  return true, "every execution takes at most " .. #words .. " instructions (<= " .. s.bound .. ")"
end

local function flat_prof(ram_words)
  return {inst_work = 1, inst_dur = 1, ram_words = ram_words, horizon = 1 << 50, watchdog_period = nil, step_ticks = 1,
          work_budget = 1 << 50, stack_words = 0}
end

RULE.code_equiv_ast = function(c, ctx, st)
  local s = c.statement
  local m = MACHINES[s.machine]
  if not m then error({invalid = "unknown machine " .. tostring(s.machine)}, 0) end
  local types = {}
  for _, v in ipairs(s.vars) do types[v.name] = {type = "integer"} end
  local ok_t, ty = pcall(X.infer, s.reference, types)
  if not ok_t or ty ~= "integer" then error({invalid = "reference term must be an integer-valued finite-expr-1 term"}, 0) end
  if box_points(s.vars) > (ctx.max_points or Proof.DEFAULT_MAX_POINTS) then error({resource = true, reason = "box exceeds the cap"}, 0) end
  local img = {}
  for i, w in ipairs(s.program) do img[i] = w end
  img[#img + 1] = ISA.encode(m.by_name.HALT, 0, 0, 0, 0)
  local ram_words = s.ram_words or 256
  local counts = {}
  local cex = each_point(s.vars, function(env)
    local vm = VM.new({image = {words = img, entry = 0, bits = #img * 64}, machine = m, profile = flat_prof(ram_words)})
    for _, v in ipairs(s.vars) do vm.ram[v.addr - VM.RAM_BASE] = env[v.name] end
    vm.r[15] = #s.program
    vm:run(s.max_instr or 100000)
    st.steps = st.steps + vm.instr_count
    if st.steps > st.limit then error({resource = true}, 0) end
    local expected = num(X.eval(s.reference, env))
    if vm.reason ~= "halt" then return "program did not halt cleanly" end
    if vm.r[s.out_reg] ~= expected then return string.format("value %s != reference %s", tostring(vm.r[s.out_reg]), tostring(expected)) end
    local n = vm.instr_count - 1
    counts[n] = true
    if s.instr_bound and n > s.instr_bound then return "executed " .. n .. " instructions, above the bound " .. s.instr_bound end
  end)
  if cex then return false, cex end
  return true, "program agrees with the reference on the whole box"
end

RULE.vm_equiv = function(c, ctx, st)
  local s, w = c.statement, c.witness
  local m = MACHINES[s.machine]
  if not m then error({invalid = "unknown machine " .. tostring(s.machine)}, 0) end
  if box_points(s.vars) > (ctx.max_points or Proof.DEFAULT_MAX_POINTS) then error({resource = true, reason = "box exceeds the cap"}, 0) end
  local snap = w.snapshot
  local cex = each_point(s.vars, function(env)
    local outs = {}
    for k, entry in ipairs({s.entry_a, s.entry_b}) do
      local vm = vm_from_snapshot(snap, m)
      for _, put in ipairs(s.inputs) do
        for i = 0, put.n - 1 do vm.ram[put.addr + i - VM.RAM_BASE] = env[put.var] end
      end
      for _, cl in ipairs(s.clobber or {}) do
        for i = 0, cl.n - 1 do vm.ram[cl.addr + i - VM.RAM_BASE] = cl.value end
      end
      local reason = run_vm(vm, entry.addr, s.ret, entry.args, s.max_instr or 200000)
      st.steps = st.steps + vm.instr_count
      if st.steps > st.limit then error({resource = true}, 0) end
      if reason ~= "halt" then return "entry " .. k .. " did not halt cleanly (" .. tostring(reason) .. ")" end
      local o = {}
      for i = 0, s.out.n - 1 do o[i] = vm.ram[s.out.addr + i - VM.RAM_BASE] end
      outs[k] = o
    end
    for i = 0, s.out.n - 1 do
      if outs[1][i] ~= outs[2][i] then
        local t = {}
        for k, x in pairs(env) do t[#t + 1] = k .. "=" .. x end
        table.sort(t)
        return string.format("outputs differ at word %d (%s vs %s) for %s", i, tostring(outs[1][i]), tostring(outs[2][i]), table.concat(t, ","))
      end
    end
  end)
  if cex then return false, cex end
  return true, "both entries agree on the whole input box"
end

RULE.all_of = function(c, ctx, st)
  for i, sub in ipairs(c.witness.parts) do
    local r = check(sub, ctx, st)
    if not r.ok then return false, "part " .. i .. " failed: " .. tostring(r.reason) end
  end
  return true, "all " .. #c.witness.parts .. " parts hold"
end

-- ctx: { versions = {name -> current version}, step_limit, max_points }
check = function(cert, ctx, st)
  st = st or {steps = 0, limit = (ctx and ctx.step_limit) or Proof.DEFAULT_STEP_LIMIT}
  ctx = ctx or {}
  if type(cert) ~= "table" or type(cert.rule) ~= "string" then
    return result(false, "invalid", st.steps, "a certificate must be a table with a rule name")
  end
  local rule = RULE[cert.rule]
  if not rule then return result(false, "unsupported", st.steps, "no checking rule named '" .. cert.rule .. "' is declared in this kernel") end
  -- premise currency first: a stale proof is never examined further
  local conditional, hyps = false, {}
  for _, p in ipairs(cert.premises or {}) do
    if p.version ~= nil then
      local cur = (ctx.versions or {})[p.name]
      if cur ~= p.version then
        return result(false, "stale", st.steps, string.format("premise '%s' was proved for version %s but the current version is %s", tostring(p.name), tostring(p.version), tostring(cur)))
      end
    end
    if p.kind == "empirical" then conditional = true; hyps[#hyps + 1] = p.name .. ": " .. tostring(p.text) end
  end
  local ok, a, b = pcall(rule, cert, ctx, st)
  if not ok then
    if type(a) == "table" and a.resource then return result(false, "resource", st.steps, a.reason or "step limit exceeded") end
    if type(a) == "table" and a.invalid then return result(false, "invalid", st.steps, a.invalid) end
    return result(false, "invalid", st.steps, "malformed certificate: " .. tostring(a))
  end
  if a then
    return result(true, conditional and "conditional" or "valid", st.steps, b, {conditional = conditional, hypotheses = hyps, hash = U.sha256(U.canonical(cert))})
  end
  return result(false, "refuted", st.steps, b)
end

function Proof.check(cert, ctx) return check(cert, ctx, nil) end

-- the kernel never says "true" for what it cannot decide
function Proof.check_statement_text(text)
  return result(false, "unsupported", 0, "free-text statements are not part of the proof language: " .. tostring(text):sub(1, 60))
end

-- ------------------------------------------------------------------ producers
local function qpair(q) return {B.to_int(q.n), B.to_int(q.d)} end

-- ledger identity r0 <= Delta - eta - alpha - eps  as a rational certificate
function Proof.produce_reserve(delta, eta, alpha, eps, r0, versions_premises)
  local function k(x) return {k = "q", n = x[1], d = x[2]} end
  local rhs = {k = "sub", a = {k = "sub", a = {k = "sub", a = k(delta), b = k(eta)}, b = k(alpha)}, b = k(eps)}
  return {rule = "rat_le", statement = {lhs = k(r0), rhs = rhs}, premises = versions_premises or {}}
end

-- one-step worst-case heat bound used by the shield (public support of gamma, eta; shared load and noise)
function Proof.produce_shield_bound(gamma_max, eta_min)
  local function var(n) return {ref = n} end
  local function op(o, ...) return {op = o, args = {...}} end
  local p = op("if", op("eq", var("sigma"), 0), var("a1"), var("a2"))
  local cc = op("if", op("eq", var("sigma"), 0), var("a2"), var("a1"))
  local actual = op("add", op("sub", op("sub", op("mul", op("add", var("gamma"), var("g")), p), op("mul", var("eta"), cc)), 1), var("xi"))
  local heat = op("sub", op("mul", gamma_max + 1, op("max", var("a1"), var("a2"))), op("mul", eta_min, op("min", var("a1"), var("a2"))))
  return {rule = "int_forall", statement = {
    vars = {{name = "gamma", lo = 2, hi = gamma_max}, {name = "eta", lo = eta_min, hi = 5}, {name = "g", lo = 0, hi = 1}, {name = "xi", lo = 0, hi = 1},
            {name = "sigma", lo = 0, hi = 1}, {name = "a1", lo = 0, hi = 1}, {name = "a2", lo = 0, hi = 1}},
    pred = op("le", actual, heat)},
    premises = {{name = "public_support", kind = "empirical", text = "gamma in [2,gamma_max], eta in [eta_min,5] (published support)"}}}
end

-- finite chain certificate from a transition function; r(i, s) is the exact failure probability (tight potential)
function Proof.produce_chain(N, trans, s0, eps)
  local nodes, memo = {}, {}
  local function key(i, s) return i .. ":" .. tostring(s) end
  local function build(i, s)
    local k = key(i, s)
    if memo[k] then return memo[k] end
    local nd = {step = i, trans = {}}
    memo[k] = nd
    nodes[k] = nd
    if i == N then nd.r = {0, 1}; return nd end
    local r = Q.from(0)
    for _, t in ipairs(trans(i, s)) do
      local entry = {p = qpair(t.p), fail = t.fail or false}
      if t.fail then r = Q.add(r, t.p)
      else
        local nx = build(i + 1, t.next)
        entry.next = key(i + 1, t.next)
        r = Q.add(r, Q.mul(t.p, Q.make(nx.r[1], nx.r[2])))
      end
      nd.trans[#nd.trans + 1] = entry
    end
    nd.r = qpair(r)
    return nd
  end
  local start = build(0, s0)
  local epsw, sum = {}, Q.from(0)
  for i = 0, N - 1 do
    local e = eps and eps[i] or Q.from(0)
    epsw[i + 1] = qpair(e); sum = Q.add(sum, e)             -- allowance of step i is epsw[i + 1]
  end
  local bound = Q.add(Q.make(start.r[1], start.r[2]), sum)
  return {rule = "chain_ledger", statement = {N = N, start = key(0, s0), bound = qpair(bound)}, witness = {nodes = nodes, eps = epsw}}
end

-- certificate that a VM-1 straight-line program (the parity specialiser output) respects its resource bound
function Proof.produce_straight_line(machine_name, words, bound)
  return {rule = "straight_line_bound", statement = {machine = machine_name, program = words, bound = bound}}
end

-- certificate that specialiser output computes d_{s,kappa} (reference built from s, kappa as a finite-expr-1 term)
function Proof.produce_specialization(prof, s, kappa, words, vb_addr)
  local n = prof.n
  local function var(i) return {ref = "b" .. i} end
  local par
  for i = 0, n - 1 do
    if (s >> i) & 1 == 1 then par = par and {op = "xor", args = {par, var(i)}} or var(i) end
  end
  par = par or 0
  local eqt
  for i = 0, n - 1 do
    local term = {op = "eq", args = {var(i), (kappa >> i) & 1}}
    eqt = eqt and {op = "and", args = {eqt, term}} or term
  end
  local ref = {op = "xor", args = {par, {op = "indicator", args = {eqt}}}}
  local vars = {}
  for i = 0, n - 1 do vars[i + 1] = {name = "b" .. i, lo = 0, hi = 1, addr = vb_addr + i} end
  return {rule = "code_equiv_ast", statement = {machine = "parity", program = words, vars = vars, reference = ref, out_reg = 1,
                                                 instr_bound = #words, ram_words = prof.ram_words}}
end

-- certificate that the emitted decision-kernel package equals the resident kernel on the whole (QB,TB) box
-- ep supplies the finished machine and the symbols of the controller image
function Proof.produce_package_equivalence(snapshot, sym, nodes, par_version)
  local entry_pkg = snapshot.ram[sym.PKGE - VM.RAM_BASE + 1]
  return {rule = "vm_equiv", statement = {
    machine = "net", ret = sym["main.ret"],
    vars = {{name = "qb", lo = 0, hi = 31}, {name = "tb", lo = 0, hi = 9}},
    inputs = {{var = "qb", addr = sym.QB, n = nodes}, {var = "tb", addr = sym.TB, n = nodes}},
    clobber = {{addr = sym.DS, n = nodes, value = 255}},
    entry_a = {addr = sym.kernel_generic, args = {sym.PAR}}, entry_b = {addr = entry_pkg, args = {}},
    out = {addr = sym.DS, n = nodes}, max_instr = 200000},
    witness = {snapshot = snapshot},
    premises = {{name = "params", version = par_version, kind = "logical", text = "package emitted for this parameter version"}}}
end

--[[@@END@@]]
return Proof
end

-- ======================================================================== asi.parity  (asi/parity.lua)
package.preload["asi.parity"] = function(...)
--[============[
asi/parity.lua -- the parity-exception LOWER-BOUND SUBFAMILY (spec sections 8 and IX; prompt item I).

THIS IS NOT THE DYNAMICAL NETWORK and never stands in for it. It is a finite coupled instance that
supports access / retention / verification tests with REAL costs:

  hidden s, kappa ~ Unif({0,1}^n)           d(v) = <s,v>_F2  xor  1{v = kappa}                    (L1)
  physical mechanism, context v:            d(v)=0: P=U, Q=P      d(v)=1: Q=U, P=Q       U ~ Ber(1/2)
  action a=0 : do(P=1)  a=1 : do(Q=1)       correct orientation => both variables one;
                                            wrong orientation   => both one w.p. 1/2, else FAILURE (absorbing)
  archive    : R = n+24 independent historical do(P=1) outcomes Y_{v,j} (= value of Q) per context.
               d(v)=0 => Y == 1 always; d(v)=1 => Y ~ Ber(1/2). Observations, never labels.
  auditor    : Z_j(v) = <s,v> xor (1-H) 1{v=kappa} xor E_j,  H ~ Ber(1/8) persistent blind spot,
               E_j ~ Ber(1/16) fresh                                                                (L2)
  instruction width W = 4 + 3 ceil(log2(8n)); an instruction costs W work AND W ticks;
  archive page (512+R)W, diagnostic 32W, auditor call 4W, input / deployment / feedback W each.
  preparation T0 = 2^23 ticks, then K windows of D0 = 80W ticks. In each window an independent opportunity
  process closes at every tick with probability 1/(64 D0). A late, closed or absent deployment yields zero
  utility and NO failure. An active failure sets all later utility to zero (absorbing). The diagnostic is a
  declared physical separation from the scored target: charged, informative, cannot cause failure.
  Generic evaluator (10n+4)W; specialised straight-line evaluator J(s,kappa) W, J = 3n+wt(s)-wt(kappa)+4. (L3)
  Cost contract only: the specialiser below emits REAL VM-1 bytecode and a checker proves it; producing it
  is paid work inside the controller.

CONVENTIONS fixed here (the text leaves them open; all are documented, none favours a controller):
  * windows: window j occupies ticks [T0 + j D0, T0 + (j+1) D0). INPUT at start tick t returns V_j for the window
    containing t. A deployment actuates the context of the window whose input was read last (never the context of a
    later window: no late-command aliasing); it occupies ticks [t, t+W) and completes at tau = t+W-(T0+jD0); it is
    LATE if tau > D0, otherwise CLOSED iff the window's closure process fired at some tick in 1..tau.
    A deployment without a preceding input, or a second deployment for the same window, is INVALID (no effect).
  * randomness: theta / archive / contexts / noise / closure use independent streams; the closure of window j is
    drawn tick by tick from its own stream ("parity-close-j"), so it is identical for every controller.
  * accepted deployments always report OK: the opportunity state is revealed only by feedback (which arrives
    after deployment). Feedback codes: 1 no actuation (closed), 2 both variables one, 3 failure.
  * touched contexts q (access lemma L4): contexts of archive pages, diagnostics and OPEN-deployment feedback.
]============]
local U = require("asi.util")
local B = require("asi.bigint")
local Q = B.Q
local R = require("asi.rng")
local ISA = require("asi.isa")
local VM = require("asi.vm")

local Parity = {}

Parity.ops = {{"PINPUT", "rr"}, {"PPAGE", "rrr"}, {"PDIAG", "rrr"}, {"PAUD", "rrr"}, {"PDEPLOY", "rr"}, {"PFB", "rr"}}
Parity.machine = ISA.build(Parity.ops)
Parity.OK, Parity.LATE, Parity.NOT_READY, Parity.INVALID, Parity.EMPTY = 0, 1, 2, 3, 5

local function ceil_log2(x) local k = 0 while (1 << k) < x do k = k + 1 end return k end
local function popcount(x) local c = 0 while x ~= 0 do c = c + (x & 1); x = x >> 1 end return c end
local function parity_bit(x) return popcount(x) & 1 end
Parity.popcount, Parity.parity_bit = popcount, parity_bit

-- ------------------------------------------------------------------ profile (all derived constants)
function Parity.profile(o)
  o = o or {}
  local n = o.n or 12
  assert(n >= 3 and n <= 16, "n must be in 3..16")
  local K = o.K or 256
  local W = 4 + 3 * ceil_log2(8 * n)
  local p = {n = n, N = 1 << n, R = o.R or (n + 24), K = K, W = W}
  p.D0 = 80 * W
  p.T0 = o.T0 or (1 << 23)
  p.beta_den = o.beta_den or (64 * p.D0)                  -- closure probability per tick = 1 / beta_den (o.beta_den: TESTS ONLY)
  p.page_cost, p.diag_cost, p.aud_cost = (512 + p.R) * W, 32 * W, 4 * W
  p.input_cost, p.deploy_cost, p.feedback_cost, p.instr_cost = W, W, W, W
  p.generic_instr = 10 * n + 4
  p.Jmin, p.Jmax = 2 * n + 4, 4 * n + 4
  p.delta_den = 1 << 16                                   -- global risk 2^-16
  p.horizon = p.T0 + K * p.D0
  p.ram_words = o.ram_words or 256
  p.s0_bits = p.ram_words * 64                             -- declared variable writable allowance
  p.archive_bits = p.N * 64                                -- one 64-bit page word per context (outcomes + provenance)
  p.page_bits_payload = p.R
  assert(p.R <= 48, "page word holds at most 48 outcome bits")
  return p
end

function Parity.J(prof, s, kappa) return 3 * prof.n + popcount(s) - popcount(kappa) + 4 end
function Parity.J_parity_only(prof, s) return 2 * popcount(s) + 3 end

-- total memory M = l_arc + L0 + 16 W + s0 (the actual archive encoding includes provenance)
function Parity.memory_bound(prof, l0_bits) return prof.archive_bits + l0_bits + 16 * prof.W + prof.s0_bits end

function Parity.d(inst, v) return parity_bit(inst.s & v) ~ ((v == inst.kappa) and 1 or 0) end

-- ------------------------------------------------------------------ instance (hidden state, evaluator side)
-- ov (optional) overrides the hidden parameters for TESTS ONLY: {s=, kappa=, H=}
function Parity.instance(prof, seed, ov)
  local rt = R.new(seed, "parity-theta")
  local inst = {seed = seed, prof = prof}
  inst.s = rt:below(prof.N)
  inst.kappa = rt:below(prof.N)
  inst.H = rt:bit(1, 8)                                    -- 1: auditor blind to the exception
  if ov then
    if ov.s ~= nil then inst.s = ov.s end
    if ov.kappa ~= nil then inst.kappa = ov.kappa end
    if ov.H ~= nil then inst.H = ov.H end
  end
  local ra = R.new(seed, "parity-archive")
  inst.arch = {}
  for v = 0, prof.N - 1 do
    local d = Parity.d(inst, v)
    local u = ra:bits(prof.R)                            -- R fresh fair bits for EVERY context (stream alignment never depends on d)
    inst.arch[v] = (d == 0) and ((1 << prof.R) - 1) or u
  end
  local rc = R.new(seed, "parity-ctx")
  inst.ctx = {}
  for j = 0, prof.K - 1 do inst.ctx[j] = rc:below(prof.N) end
  return inst
end

-- ------------------------------------------------------------------ the charged world
local World = {}
World.__index = World
Parity.World = World

function World.new(prof, inst)
  local w = setmetatable({p = prof, inst = inst, events = {}, nev = 0}, World)
  w.phys = R.new(inst.seed, "parity-phys")
  w.aud = R.new(inst.seed, "parity-aud")
  w.touched, w.touched_n = {}, 0
  w.deployed = {}                                          -- window -> record
  w.G = 0
  w.failed, w.failed_window = false, nil
  w.counts = {pages = 0, diags = 0, audits = 0, inputs = 0, deploys = 0, open_deploys = 0, late = 0, closed = 0, feedbacks = 0}
  w.pending = nil
  return w
end

local function ev(w, kind, t, a, b, r)
  w.nev = w.nev + 1
  w.events[w.nev] = string.format("%d,%s,%d,%s,%s,%s", w.nev, kind, t, tostring(a), tostring(b), tostring(r))
  return w.nev
end

function World:window_of(t)
  if t < self.p.T0 then return nil end
  return (t - self.p.T0) // self.p.D0
end

local function touch(w, v)
  if not w.touched[v] then w.touched[v] = true; w.touched_n = w.touched_n + 1 end
end

-- INPUT: bit words [0..n-1] of V_j, then j, then v. Returns status, words
function World:input(t)
  local j = self:window_of(t)
  if j == nil then ev(self, "input", t, "-", "-", "not_ready"); return Parity.NOT_READY end
  if j >= self.p.K then ev(self, "input", t, "-", "-", "empty"); return Parity.EMPTY end
  local v = self.inst.ctx[j]
  local words = {}
  for i = 0, self.p.n - 1 do words[i + 1] = (v >> i) & 1 end
  words[self.p.n + 1], words[self.p.n + 2] = j, v
  self.counts.inputs = self.counts.inputs + 1
  self.input_window = j                                    -- a deployment actuates the context of the window whose input was read
  ev(self, "input", t, j, v, "ok")
  return Parity.OK, words
end

function World:page(t, v)
  if v < 0 or v >= self.p.N then ev(self, "page", t, v, "-", "invalid"); return Parity.INVALID end
  touch(self, v)
  self.counts.pages = self.counts.pages + 1
  ev(self, "page", t, v, "-", "ok")
  return Parity.OK, (v << 48) | self.inst.arch[v]
end

function World:diag(t, v, a)
  if v < 0 or v >= self.p.N or (a ~= 0 and a ~= 1) then ev(self, "diag", t, v, a, "invalid"); return Parity.INVALID end
  touch(self, v)
  self.counts.diags = self.counts.diags + 1
  local out = (Parity.d(self.inst, v) == a) and 1 or self.phys:bits(1)     -- correct orientation: both variables one
  ev(self, "diag", t, v, a, out)
  return Parity.OK, out
end

function World:audit(t, v)
  if v < 0 or v >= self.p.N then ev(self, "audit", t, v, "-", "invalid"); return Parity.INVALID end
  local z = parity_bit(self.inst.s & v)
  if self.inst.H == 0 and v == self.inst.kappa then z = z ~ 1 end
  z = z ~ self.aud:bit(1, 16)
  self.counts.audits = self.counts.audits + 1
  ev(self, "audit", t, v, "-", z)
  return Parity.OK, z
end

-- DEPLOY at start tick t, completing at tend. One deployment per window; late/closed deployments never fail.
function World:deploy(t, tend, a)
  local p = self.p
  local j = self.input_window
  if j == nil or (a ~= 0 and a ~= 1) or self.deployed[j] then
    ev(self, "deploy", t, a, "-", "invalid"); return Parity.INVALID
  end
  local tau = tend - (p.T0 + j * p.D0)
  local rec = {window = j, a = a, tau = tau, v = self.inst.ctx[j]}
  self.deployed[j] = rec
  self.counts.deploys = self.counts.deploys + 1
  if tau > p.D0 then
    rec.outcome = "late"; self.counts.late = self.counts.late + 1
    ev(self, "deploy", t, a, tau, "late"); return Parity.LATE
  end
  local rcl = R.new(self.inst.seed, "parity-close-" .. j)           -- the opportunity process of this window
  local closed = false
  for _ = 1, tau do if rcl:bernoulli(1, p.beta_den) then closed = true; break end end
  if closed then
    rec.outcome = "closed"; self.counts.closed = self.counts.closed + 1
    self.pending = {code = 1, v = rec.v, open = false}
  else
    self.counts.open_deploys = self.counts.open_deploys + 1
    if self.failed then
      rec.outcome = "absorbed"; self.pending = {code = 2, v = rec.v, open = true}      -- utility is already zero
    else
      local correct = (a == Parity.d(self.inst, rec.v))
      local rd = R.new(self.inst.seed, "parity-deploy-" .. j)
      if correct or rd:bernoulli(1, 2) then
        rec.outcome = "success"; self.G = self.G + 1; self.pending = {code = 2, v = rec.v, open = true}
      else
        rec.outcome = "failure"; self.failed, self.failed_window = true, j
        self.pending = {code = 3, v = rec.v, open = true}
      end
    end
  end
  ev(self, "deploy", t, a, tau, "accepted")
  return Parity.OK
end

function World:feedback(t)
  local pf = self.pending
  if not pf then ev(self, "feedback", t, "-", "-", "not_ready"); return Parity.NOT_READY end
  self.pending = nil
  if pf.open then touch(self, pf.v) end                              -- informative deployment feedback touches the context
  self.counts.feedbacks = self.counts.feedbacks + 1
  ev(self, "feedback", t, pf.v, "-", pf.code)
  return Parity.OK, pf.code
end

function World:finish() self.finished = true end

-- result: utility = G / K (exact rational), failure indicator D, access accounting
function World:result()
  local c = self.counts
  return {utility_num = self.G, utility_den = self.p.K, failed = self.failed, failed_window = self.failed_window,
          touched = self.touched_n, counts = c, abstained = self.p.K - c.deploys,
          found_kappa_touched = self.touched[self.inst.kappa] == true, transcript_hash = self:transcript_hash()}
end

function World:transcript_hash() return U.sha256(table.concat(self.events, "\n")) end

-- ------------------------------------------------------------------ exact analysis (rational arithmetic)
-- All probabilities below are RIGOROUS ENCLOSURES {lo, hi} (exact rationals on a 2^-bits grid, every operation
-- rounded outward): (1-1/128000)^1450 raised to the K-th power has millions of exact bits, so exact rationals are
-- replaced by intervals whose width is below 2^-bits. Nothing is a floating-point estimate.
local IVBITS = 160
local function rdown(x) local sc = B.pow(2, IVBITS); return Q.make(Q.floor(Q.mul(x, sc)), sc) end
local function rup(x)
  local sc = B.pow(2, IVBITS)
  local f = Q.floor(Q.mul(x, sc))
  if not Q.eq(Q.mul(x, sc), Q.make(f, 1)) then f = B.add(f, 1) end
  return Q.make(f, sc)
end
local function iv(lo, hi) return {lo = lo, hi = hi} end
local function iv_mul(a, b) return iv(rdown(Q.mul(a.lo, b.lo)), rup(Q.mul(a.hi, b.hi))) end    -- nonnegative operands
local function iv_pow(a, e)
  local result, base = iv(Q.from(1), Q.from(1)), a
  while e > 0 do
    if e & 1 == 1 then result = iv_mul(result, base) end
    e = e >> 1
    if e > 0 then base = iv_mul(base, base) end
  end
  return result
end
local function iv_one_minus(a) return iv(Q.sub(1, a.hi), Q.sub(1, a.lo)) end
local function iv_div(a, b) return iv(rdown(Q.div(a.lo, b.hi)), rup(Q.div(a.hi, b.lo))) end
local function iv_const(x) return iv(x, x) end
Parity.iv = {mul = iv_mul, pow = iv_pow, one_minus = iv_one_minus, div = iv_div, const = iv_const}

function Parity.beta(prof) return Q.make(1, prof.beta_den) end
-- P(opportunity still open after tau ticks) = (1 - beta)^tau
function Parity.open_prob(prof, tau) return iv_pow(iv_const(Q.sub(1, Parity.beta(prof))), tau) end

-- per-window failure probability of the parity-only policy deploying every window with completion tick tau
function Parity.ignore_window_failure(prof, tau)
  return iv_mul(Parity.open_prob(prof, tau), iv_const(Q.make(1, 2 * prof.N)))
end

-- risk of the parity-only policy over K windows with the absorbing rule: 1 - (1-q)^K
function Parity.ignore_risk(prof, tau)
  local q = Parity.ignore_window_failure(prof, tau)
  return iv_one_minus(iv_pow(iv_one_minus(q), prof.K))
end

-- expected utility of the parity-only policy, absorbing failure: (succ/K) * (1-(1-q)^K)/q
function Parity.ignore_utility(prof, tau)
  local rho = Parity.open_prob(prof, tau)
  local q = iv_mul(rho, iv_const(Q.make(1, 2 * prof.N)))
  local succ = iv_mul(rho, iv_const(Q.sub(1, Q.make(1, 2 * prof.N))))
  local geo = iv_div(iv_one_minus(iv_pow(iv_one_minus(q), prof.K)), q)
  return iv_mul(iv_div(succ, iv_const(Q.from(prof.K))), geo)
end

-- policy that knows (s, kappa): never fails, utility = P(open at tau)
function Parity.known_utility(prof, tau) return Parity.open_prob(prof, tau) end

-- the same risk written the (wrong) independent way, to show the difference: K * q
function Parity.union_bound_risk(prof, tau) return iv_mul(Parity.ignore_window_failure(prof, tau), iv_const(Q.from(prof.K))) end

-- repeated-auditor error at the exceptional context: majority of m (odd) calls vs the true orientation
function Parity.auditor_majority_error(m)
  assert(m % 2 == 1, "odd number of calls")
  local e = Q.from(0)                                       -- P(flip noise makes the majority wrong about the stated bit)
  for k = (m + 1) // 2, m do
    local c = B.from(1)
    for i = 1, k do c = c * (m - k + i) end
    for i = 1, k do c = B.divmod(c, i) end
    e = Q.add(e, Q.mul(Q.make(c, 1), Q.mul(Q.pow(Q.make(1, 16), k), Q.pow(Q.make(15, 16), m - k))))
  end
  local H = Q.make(1, 8)
  return Q.add(Q.mul(H, Q.sub(1, e)), Q.mul(Q.sub(1, H), e)), e
end

-- access lemma: Pr(kappa_hat = kappa) <= min(1, (q+1)/N)  (L4);  <= min(1, (r+1)/N + Pr(Q > r)) (L5)
function Parity.L4_bound(q, N) return Q.min(Q.from(1), Q.make(q + 1, N)) end
function Parity.L5_bound(r, N, p_exceed) return Q.min(Q.from(1), Q.add(Q.make(r + 1, N), p_exceed)) end

-- exhaustive optimum over ALL deterministic strategies of the strengthened (noiseless-disclosure) experiment:
-- a strategy is a sequence of q distinct tested points followed by a guess; kappa is uniform on N points.
-- Returns the maximal exact success probability and the number of strategies enumerated.
function Parity.exhaustive_discovery(N, q)
  -- Answers off the all-negative path are fully determined (a positive answer names kappa), so a deterministic
  -- strategy is its all-negative query sequence plus the final guess; its success is counted over every kappa.
  local best, count = Q.from(0), 0
  local tested = {}
  local function score(g)
    local hits = 0
    for kappa = 0, N - 1 do
      if tested[kappa] or kappa == g then hits = hits + 1 end
    end
    return hits
  end
  local function rec(depth)
    if depth == q then
      local any = false
      for g = 0, N - 1 do
        if not tested[g] then
          any = true; count = count + 1
          local pr = Q.make(score(g), N)
          if Q.lt(best, pr) then best = pr end
        end
      end
      if not any then count = count + 1; best = Q.max(best, Q.make(score(-1), N)) end
      return
    end
    for x = 0, N - 1 do
      if not tested[x] then tested[x] = true; rec(depth + 1); tested[x] = nil end
    end
  end
  rec(0)
  return best, count
end

-- retention lemma: all 2^(2n) functions d_{s,kappa} are pairwise distinct; returns count and the support facts used
function Parity.retention_check(n)
  local N = 1 << n
  local seen, count = {}, 0
  for s = 0, N - 1 do
    for k = 0, N - 1 do
      local bits = {}
      for v = 0, N - 1 do bits[v + 1] = parity_bit(s & v) ~ ((v == k) and 1 or 0) end
      local key = table.concat(bits)
      if seen[key] then return false, string.format("(s=%d,k=%d) equals (s=%d,k=%d)", s, k, seen[key][1], seen[key][2]) end
      seen[key] = {s, k}
      count = count + 1
    end
  end
  -- the proof's two support facts, checked exhaustively: parity differences have support N/2; singleton differences <= 2
  for s = 1, N - 1 do
    local supp = 0
    for v = 0, N - 1 do if parity_bit(s & v) == 1 then supp = supp + 1 end end
    if supp ~= N // 2 then return false, "parity difference support is not N/2" end
  end
  return true, count
end

-- ------------------------------------------------------------------ specialiser (REAL VM-1 bytecode) and evaluators
local M = Parity.machine
local function enc(mn, rd, ra, rb, imm) return ISA.encode(M.by_name[mn], rd, ra, rb, imm) end
Parity.enc = enc
Parity.LINK = 15

-- register convention of every evaluator: argument/result r1, temporaries r3 (parity) r4 (equality) r12 (bit); r15 = link
-- Specialised straight-line evaluator of d(v) = <s,v> xor 1{v=kappa}; v's bits are the words at vb_addr .. vb_addr+n-1.
-- Instruction count = 3n + wt(s) - wt(kappa) + 4 = J(s,kappa).
function Parity.specialize(prof, s, kappa, vb_addr)
  local code = {}
  local function push(w) code[#code + 1] = w end
  push(enc("MOVI", 3, 0, 0, 0))                              -- par = 0
  push(enc("MOVI", 4, 0, 0, 1))                              -- eq = 1
  for i = 0, prof.n - 1 do
    push(enc("LD", 12, 0, 0, vb_addr + i))                   -- t = bit i of v
    if (s >> i) & 1 == 1 then push(enc("XOR", 3, 3, 12, 0)) end                  -- par ^= t
    if (kappa >> i) & 1 == 0 then push(enc("XORI", 12, 12, 0, 1)) end            -- xnor with kappa_i = 0 is NOT
    push(enc("AND", 4, 4, 12, 0))                             -- eq &= (t xnor kappa_i)
  end
  push(enc("XOR", 1, 3, 4, 0))                                -- d = par xor eq
  push(enc("JR", 0, Parity.LINK, 0, 0))
  assert(#code == Parity.J(prof, s, kappa), "specialiser instruction count differs from J(s,kappa)")
  return code
end

-- the same emitter for the parity-only model (the active code that cannot express the exception): 2 wt(s) + 3 instructions
function Parity.specialize_parity_only(prof, s, vb_addr)
  local code = {enc("MOVI", 3, 0, 0, 0)}
  for i = 0, prof.n - 1 do
    if (s >> i) & 1 == 1 then
      code[#code + 1] = enc("LD", 12, 0, 0, vb_addr + i)
      code[#code + 1] = enc("XOR", 3, 3, 12, 0)
    end
  end
  code[#code + 1] = enc("MOV", 1, 3, 0, 0)
  code[#code + 1] = enc("JR", 0, Parity.LINK, 0, 0)
  assert(#code == Parity.J_parity_only(prof, s))
  return code
end

-- the declared generic evaluator: v bits at [r1 ..), s bits at [r1+n+2 ..), kappa bits at [r1+2n+2 ..); r2 = r1 + n
-- (3 loads, 5 Boolean instructions, an increment and a conditional branch per coordinate; 4 further instructions)
function Parity.generic_words(prof)
  local n = prof.n
  return {
    enc("MOVI", 3, 0, 0, 0), enc("MOVI", 4, 0, 0, 1),
    enc("LD", 12, 1, 0, 0), enc("LD", 13, 1, 0, n + 2), enc("AND", 13, 13, 12, 0), enc("XOR", 3, 3, 13, 0),
    enc("LD", 13, 1, 0, 2 * n + 2), enc("XOR", 13, 13, 12, 0), enc("XORI", 13, 13, 0, 1), enc("AND", 4, 4, 13, 0),
    enc("ADDI", 1, 1, 0, 1), enc("BNE", 0, 1, 2, -9),
    enc("XOR", 1, 3, 4, 0), enc("JR", 0, Parity.LINK, 0, 0),
  }
end

-- execute an evaluator on VM-1 under the flat W-per-instruction profile; returns result, instructions, ticks
function Parity.exec(prof, words, ram_init, regs)
  local img = {}
  for i, w in ipairs(words) do img[i] = w end
  img[#img + 1] = enc("HALT", 0, 0, 0, 0)
  local pr = {inst_work = prof.W, inst_dur = prof.W, ram_words = prof.ram_words, horizon = 1 << 50, work_budget = 1 << 50, stack_words = 0}
  local vm = VM.new({image = {words = img, entry = 0, bits = #img * 64}, machine = M, profile = pr})
  for a, val in pairs(ram_init or {}) do vm.ram[a - VM.RAM_BASE] = val end
  for r, val in pairs(regs or {}) do vm.r[r] = val end
  vm.r[Parity.LINK] = #words
  vm:run(100000)
  return vm.r[1], vm.instr_count - 1, vm.t
end

-- exhaustive proof obligation for the specialiser: for ALL v the emitted code returns d_{s,kappa}(v) and costs exactly J W
function Parity.prove_specialization(prof, s, kappa)
  local vb = VM.RAM_BASE + 8
  local code = Parity.specialize(prof, s, kappa, vb)
  local inst = {s = s, kappa = kappa}
  for v = 0, prof.N - 1 do
    local ram = {}
    for i = 0, prof.n - 1 do ram[vb + i] = (v >> i) & 1 end
    local out, cnt, ticks = Parity.exec(prof, code, ram, {})
    if out ~= Parity.d(inst, v) then return false, string.format("wrong value at v=%d", v) end
    if cnt ~= #code or ticks ~= #code * prof.W + prof.W then return false, "cost differs from J(s,kappa) W" end
  end
  return true, #code
end

--[[@@END@@]]
return Parity
end

-- ======================================================================== asi.parityenv  (asi/parityenv.lua)
package.preload["asi.parityenv"] = function(...)
--[============[
asi/parityenv.lua -- environment adapter binding VM-1 to the parity-exception subfamily (asi/parity.lua).

Paid interface instructions (cost = work = ticks, invoking instruction included; arguments are snapshotted at
the START tick; the processor stalls, the world does not pause). rd always receives a status (0 OK, 1 LATE,
2 NOT_READY, 3 INVALID, 5 EMPTY).

  PINPUT   rd, ra      write the n bits of V_j (word i = bit i), then j, then v, to mem[r[ra] .. +n+1]   W
  PPAGE    rd, ra, rb  archive page of context r[ra] -> one word at mem[r[rb]]: (v<<48)|outcomes       (512+R) W
  PDIAG    rd, ra, rb  physical diagnostic, desc r[ra] = v | (a << 32); outcome word at mem[r[rb]]    32 W
  PAUD     rd, ra, rb  auditor call for context r[ra]; answer bit at mem[r[rb]]                       4 W
  PDEPLOY  rd, ra      deploy action r[ra] (0: do(P=1), 1: do(Q=1)) for the current window            W
  PFB      rd, ra      post-deployment feedback code -> mem[r[ra]] (1 no actuation, 2 both one, 3 failure)  W

A destination that is not writable RAM is an ACCESS FAULT (nothing is revealed). The invalid-request cost is
charged in full (the controller pays for what it asks).
]============]
local U = require("asi.util")
local S = require("asi.spec")
local ISA = require("asi.isa")
local VM = require("asi.vm")
local Parity = require("asi.parity")

local PE = {}
PE.__index = PE
PE.machine = Parity.machine
PE.index = {PINPUT = 1, PPAGE = 2, PDIAG = 3, PAUD = 4, PDEPLOY = 5, PFB = 6}
local I = PE.index

function PE.profile(prof)
  return {inst_work = prof.W, inst_dur = prof.W, ram_words = prof.ram_words, horizon = prof.horizon,
          watchdog_period = nil, step_ticks = prof.D0, work_budget = prof.horizon}
end

function PE.new(prof, world) return setmetatable({p = prof, world = world}, PE) end

local function writable(vm, a, n)
  return a >= VM.RAM_BASE and a + n <= VM.RAM_BASE + vm.ram_words
end

function PE:quote(vm, idx, rd, ra, rb, imm, t)
  local p = self.p
  if idx == I.PINPUT then return p.input_cost
  elseif idx == I.PPAGE then return p.page_cost
  elseif idx == I.PDIAG then return p.diag_cost
  elseif idx == I.PAUD then return p.aud_cost
  elseif idx == I.PDEPLOY then return p.deploy_cost
  elseif idx == I.PFB then return p.feedback_cost end
  return nil, VM.FAULT.OP
end

function PE:exec(vm, idx, rd, ra, rb, imm, t)
  local w, r, p = self.world, vm.r, self.p
  local cost = self:quote(vm, idx)
  if idx == I.PINPUT then
    local dest = r[ra]
    if not writable(vm, dest, p.n + 2) then return nil, VM.FAULT.ACCESS end
    local st, words = w:input(t)
    if st == 0 then for i = 1, p.n + 2 do vm:mwrite(dest + i - 1, words[i]) end end
    r[rd] = st
  elseif idx == I.PPAGE then
    local dest = r[rb]
    if not writable(vm, dest, 1) then return nil, VM.FAULT.ACCESS end
    local st, word = w:page(t, r[ra])
    if st == 0 then vm:mwrite(dest, word) end
    r[rd] = st
  elseif idx == I.PDIAG then
    local dest = r[rb]
    if not writable(vm, dest, 1) then return nil, VM.FAULT.ACCESS end
    local desc = r[ra]
    local st, out = w:diag(t, desc & 0xffffffff, desc >> 32)
    if st == 0 then vm:mwrite(dest, out) end
    r[rd] = st
  elseif idx == I.PAUD then
    local dest = r[rb]
    if not writable(vm, dest, 1) then return nil, VM.FAULT.ACCESS end
    local st, z = w:audit(t, r[ra])
    if st == 0 then vm:mwrite(dest, z) end
    r[rd] = st
  elseif idx == I.PDEPLOY then
    r[rd] = w:deploy(t, t + cost, r[ra])
  elseif idx == I.PFB then
    local dest = r[ra]
    if not writable(vm, dest, 1) then return nil, VM.FAULT.ACCESS end
    local st, code = w:feedback(t)
    if st == 0 then vm:mwrite(dest, code) end
    r[rd] = st
  else
    return nil, VM.FAULT.OP
  end
  return cost, cost
end

-- run one controller image on one instance. opts: seed (instance), inst, max_instr, coin_seed, trace
function PE.episode(prof, words, opts)
  opts = opts or {}
  local inst = opts.inst or Parity.instance(prof, opts.seed or 1)
  local world = Parity.World.new(prof, inst)
  local env = PE.new(prof, world)
  local l0 = #words * 64 + ISA.decoder_bits(PE.machine) + 1024
  local pr = PE.profile(prof)
  pr.stack_words = opts.stack_words or 0
  local vm = VM.new({image = {words = words, entry = 0, bits = l0}, machine = PE.machine, env = env, profile = pr,
                     coin_seed = opts.coin_seed or 1, trace = opts.trace})
  local why = vm:run(opts.max_instr)
  world:finish()
  local res = world:result()
  local M = Parity.memory_bound(prof, l0)
  res.controller = {reason = why, fault = vm.fault, instructions = vm.instr_count, interface_ops = vm.iface_count,
                    work_used = vm.budget - vm.work_left, final_tick = vm.t, l0_bits = l0, ram_high_water_words = vm:peak_ram_words(),
                    image_hash = vm.image_hash, memory_bound = M,
                    peak_total_bits = prof.archive_bits + l0 + 16 * prof.W + vm:peak_ram_words() * 64}
  res.controller.within_memory = res.controller.peak_total_bits <= M
  res.inst = inst
  return res, world, vm
end

--[[@@END@@]]
return PE
end

