--[============[
asi/tests/t_math.lua -- tests for util (u64, checked ints, bit streams, sha256, canonical)
and bigint/rational. Expected values come from independent facts (known vectors, algebraic
identities, small-integer cross checks), not from calling the implementation twice.
]============]
local U = require("asi.util")
local B = require("asi.bigint")
local Q = B.Q
local T = U.T
local S = {}

function S.run()
  -- ---- unsigned helpers
  local q, r = U.udivmod(-1, 10)            -- 2^64-1 = 18446744073709551615
  T.eq(U.u64str(-1), "18446744073709551615", "u64str(-1)")
  T.eq(q, 1844674407370955161, "udivmod quotient"); T.eq(r, 5, "udivmod remainder")
  T.eq(select(1, U.udivmod(math.mininteger, 3)), 3074457345618258602, "udivmod 2^63/3")
  T.eq(U.u64str(math.mininteger), "9223372036854775808", "u64str 2^63")
  local a, b = U.udivmod(-1, -2); T.check(a == 1 and b == 1, "udivmod big divisor (2^64-1)/(2^64-2)")
  a, b = U.udivmod(5, -2); T.check(a == 0 and b == 5, "udivmod divisor above 2^63")
  a, b = U.udivmod(-1, -1); T.check(a == 1 and b == 0, "udivmod equal")
  T.rejects(function() U.udivmod(1, 0) end, "division by zero")

  -- ---- checked arithmetic
  T.rejects(function() U.cadd(math.maxinteger, 1) end, "overflow")
  T.rejects(function() U.csub(math.mininteger, 1) end, "overflow")
  T.rejects(function() U.cmul(math.maxinteger, 2) end, "overflow")
  T.rejects(function() U.cmul(math.mininteger, -1) end, "overflow")
  T.rejects(function() U.cmul(-1, math.mininteger) end, "overflow")
  T.eq(U.cmul(math.mininteger, 1), math.mininteger, "cmul min*1")
  T.eq(U.cmul(-3, -4), 12, "cmul signs")
  T.eq(U.cadd(5, -7), -2, "cadd")
  T.rejects(function() U.cadd(1.5, 2) end, "integers required")

  -- ---- bit streams (MSB first)
  local w = U.BitWriter(); w:put(0xA, 4); w:put(0x1234, 16); w:put(1, 1); w:put(-1 & U.lowmask(64), 64)
  local words = w:pad_to(128)
  T.eq(words[1] >> 60, 0xA, "bitstream top nibble")
  local rd = U.BitReader(words)
  T.eq(rd:get(4), 0xA, "read nibble"); T.eq(rd:get(16), 0x1234, "read 16"); T.eq(rd:get(1), 1, "read 1")
  T.eq(rd:get(64), -1, "read straddling full word")
  T.rejects(function() local x = U.BitWriter(); x:put(16, 4) end, "does not fit")

  -- ---- bytes <-> words
  local ws = U.bytes_to_words("ABCDEFGHI")
  T.eq(#ws, 2, "9 bytes -> 2 words"); T.eq(ws[1], 0x4142434445464748, "first word big-endian")
  T.eq(ws[2], 0x4900000000000000, "last word zero padded")
  T.eq(U.words_to_bytes(ws, 9), "ABCDEFGHI", "roundtrip bytes")

  -- ---- SHA-256 (NIST vectors)
  T.eq(U.sha256(""), "e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855", "sha256 empty")
  T.eq(U.sha256("abc"), "ba7816bf8f01cfea414140de5dae2223b00361a396177a9cb410ff61f20015ad", "sha256 abc")
  T.eq(U.sha256("abcdbcdecdefdefgefghfghighijhijkijkljklmklmnlmnomnopnopq"),
    "248d6a61d20638b8e5c026930c3e6039a33ce45964ff2167f6ecedd419db06c1", "sha256 two blocks")
  T.eq(U.sha256(string.rep("a", 1000000)),
    "cdc76e5c9914fb9281a1c7e284d73e67f1809a48a497200e046d39ccc7112cd0", "sha256 million a")

  -- ---- canonical serializer
  T.eq(U.canonical({1, 2, {b = true, a = "x\"y\n"}}), '{1,2,{["a"]="x\\"y\\010",["b"]=true}}', "canonical shape")
  T.rejects(function() U.canonical({x = 0.5}) end, "exact integers")
  T.rejects(function() U.canonical(print) end, "forbids functions")

  -- ---- bigint
  local function big(s) return B.from_string(s) end
  T.eq(B.tostring(big("123456789012345678901234567890")), "123456789012345678901234567890", "decimal roundtrip")
  T.eq(B.tostring(B.from(math.mininteger)), "-9223372036854775808", "from(minint)")
  T.eq(B.tostring(B.from(math.maxinteger) + B.from(1)), "9223372036854775808", "maxint+1")
  T.eq(B.to_int(B.from(math.mininteger)), math.mininteger, "to_int minint")
  T.rejects(function() B.to_int(B.from(math.maxinteger) + 1) end, "exceeds")
  local x = big("340282366920938463463374607431768211456")      -- 2^128
  T.check(B.eq(x, B.pow(2, 128)), "2^128 literal vs pow")
  T.eq(B.bit_length(x), 129, "bit_length 2^128")
  T.eq(B.tostring(B.pow(3, 100)), "515377520732011331036461129765621272702107522001", "3^100")
  -- division identity on pseudo-random operands (a = q*b + r, 0<=r<b), several limb sizes
  local seed = 12345
  local function rnd() seed = (seed * 6364136223846793005 + 1442695040888963407); return seed end
  for trial = 1, 400 do
    local la, lb = 1 + (rnd() >> 1) % 9, 1 + (rnd() >> 1) % 6
    local av, bv = B.from(0), B.from(0)
    for _ = 1, la do av = av * B.from(1 << 24) + B.from((rnd() >> 8) & 0xffffff) end
    for _ = 1, lb do bv = bv * B.from(1 << 24) + B.from((rnd() >> 8) & 0xffffff) end
    if bv.s == 0 then bv = B.from(7) end
    local qq, rr = B.divmod(av, bv)
    T.check(B.eq(qq * bv + rr, av) and rr.s >= 0 and B.cmp(rr, bv) < 0, "divmod identity trial " .. trial)
  end
  -- small cross-check against native ints incl. negatives (floor semantics)
  for _, p in ipairs({{7, 2}, {-7, 2}, {7, -2}, {-7, -2}, {0, 5}, {123456789, 1000}}) do
    local qq, rr = B.divmod(p[1], p[2])
    T.check(B.to_int(qq) == p[1] // p[2] and B.to_int(rr) == p[1] % p[2], "floor divmod " .. p[1] .. "/" .. p[2])
  end
  local tq, tr = B.divmod_trunc(-7, 2)
  T.check(B.to_int(tq) == -3 and B.to_int(tr) == -1, "trunc divmod -7/2")
  T.eq(B.tostring(B.gcd(big("123456789012345678901234567890"), big("9876543210"))), "90", "gcd")
  T.check(B.cmp(-5, 3) < 0 and B.cmp(5, -3) > 0 and B.cmp(4, 4) == 0, "cmp signs")
  T.eq(B.tostring(B.mul(big("99999999999999999999"), big("99999999999999999999"))),
    "9999999999999999999800000000000000000001", "mul (10^20-1)^2")

