  T.eq(Q.tostring(h), "3/4", "reduce"); T.eq(Q.tostring(Q.make(-6, -8)), "3/4", "double negative")
  T.eq(Q.tostring(Q.make(3, -9)), "-1/3", "sign to numerator")
  T.eq(Q.tostring(Q.add(Q.make(1, 3), Q.make(1, 6))), "1/2", "1/3+1/6")
  T.eq(Q.tostring(Q.sub(Q.make(1, 3), Q.make(1, 2))), "-1/6", "1/3-1/2")
  T.eq(Q.tostring(Q.mul(Q.make(math.maxinteger, 2), Q.make(2, math.maxinteger))), "1/1", "cross cancellation exact")
  T.eq(Q.tostring(Q.pow(Q.make(1, 2), 70)), "1/1180591620717411303424", "(1/2)^70")
  T.check(Q.lt(Q.make(1, 3), Q.make(1, 2)) and Q.le(Q.make(1, 2), Q.make(2, 4)), "rational order")
  T.eq(B.tostring(Q.floor(Q.make(-7, 2))), "-4", "floor negative"); T.eq(B.tostring(Q.ceil(Q.make(-7, 2))), "-3", "ceil negative")
  T.rejects(function() Q.make(1, 0) end, "zero denominator")
