  T.eq(Q.tostring(Q.pow(Q.sub(1, Q.make(1, 8)), 3)), "343/512", "(7/8)^3")
  T.check(math.abs(Q.tofloat(Q.make(1, 3)) - 1 / 3) < 1e-15, "tofloat display")
end

return S
end

