--[============[
asi/tests/t_rng.lua -- replay generator and exact samplers.
Exactness of rejection sampling is tested against ADVERSARIAL word sequences (not the
PRNG): the boundary words 2^64 mod n - 1 and 2^64 mod n must be rejected / accepted.
]============]
local U = require("asi.util")
local R = require("asi.rng")
local T = U.T
local S = {}

local function scripted(words)
  local i = 0
  return R.from_words(function() i = i + 1; assert(words[i] ~= nil, "script exhausted"); return words[i] end)
end

function S.run()
  -- determinism and stream separation
  local a, b = R.new(1, "world"), R.new(1, "world")
  local c, d = R.new(1, "coins"), R.new(2, "world")
  local same, diffc, diffd = true, false, false
  for _ = 1, 100 do
    local x, y = a:next_word(), b:next_word()
    if x ~= y then same = false end
    if c:next_word() ~= x then diffc = true end
    if d:next_word() ~= x then diffd = true end
  end
  T.check(same, "same (seed,label) replays exactly"); T.check(diffc and diffd, "different label/seed differ")

  -- known xoshiro256** reference output for state (1,2,3,4): first outputs 11520, 0, 1509978240, 1215971899390074240
  local r0 = R.new(0, "x"); r0.s0, r0.s1, r0.s2, r0.s3 = 1, 2, 3, 4
  T.eq(r0:next_word(), 11520, "xoshiro256** reference output 1")
  T.eq(r0:next_word(), 0, "xoshiro256** reference output 2")
  T.eq(r0:next_word(), 1509978240, "xoshiro256** reference output 3")
  T.eq(r0:next_word(), 1215971899390074240, "xoshiro256** reference output 4")

