  -- n = 10: 2^64 mod 10 = 6 => words 0..5 rejected, 6 accepted -> 6 % 10 = 6
  s = scripted({5, 6})
  T.eq(s:below(10), 6, "n=10 rejects 0..5"); T.eq(s.rejections, 1, "n=10 one rejection")
  -- unsigned words above 2^63 must be treated as large positive numbers
  s = scripted({-1})   -- 2^64-1 ; n=10 -> (2^64-1) % 10 = 5
  T.eq(s:below(10), 5, "unsigned word modulo")
  T.eq(R.new(3, "x"):below(1), 0, "below(1) needs no word")
  T.rejects(function() R.new(3, "x"):below(0) end, "positive integer")

  -- exact distribution test over ALL words of an 8-bit toy: emulate below(n) on the 2^8 word
  -- interface to confirm that rejection yields exact uniformity (counts equal)
  for _, n in ipairs({3, 5, 7, 10, 100, 200}) do
    local t = (256 - n) % n
    local counts = {}
    for w = 0, 255 do if w >= t then counts[w % n] = (counts[w % n] or 0) + 1 end end
    local first = counts[0]; local uniform = true
    for k = 0, n - 1 do if counts[k] ~= first then uniform = false end end
    T.check(uniform, "toy-width rejection is exactly uniform for n=" .. n)
  end

