  T.rejects(function() g:bernoulli(6, 5) end, "outside [0,1]")
  local hits, trials = 0, 40000
  for _ = 1, trials do if g:bernoulli(1, 8) then hits = hits + 1 end end
  local mean, sd = trials / 8, math.sqrt(trials * (1 / 8) * (7 / 8))
  T.check(math.abs(hits - mean) < 4 * sd, "bernoulli(1/8) frequency within 4 sigma: " .. hits)

  -- categorical probabilities (1/16, 7/8, 1/16) used by sensor noise
  local cnt = {0, 0, 0}
  for _ = 1, trials do local k = g:categorical({1, 14, 1}); cnt[k] = cnt[k] + 1 end
  T.check(math.abs(cnt[1] - trials / 16) < 4 * math.sqrt(trials / 16), "categorical low mass")
  T.check(math.abs(cnt[2] - trials * 7 / 8) < 4 * math.sqrt(trials * 7 / 64), "categorical middle mass")

  -- subset: exactly k distinct sorted elements in range; each element near-uniform inclusion k/n
  local incl = {}
  for _ = 1, 4000 do
    local sub = g:subset(12, 32)
    T.check(#sub == 12, "subset size")
    for i = 1, #sub do
      T.check(sub[i] >= 0 and sub[i] < 32 and (i == 1 or sub[i] > sub[i - 1]), "subset sorted distinct in range")
      incl[sub[i]] = (incl[sub[i]] or 0) + 1
    end
