    {"archive bits", "archive bits", function(s) s.record_layout.history.bits = 33554431 end},
    {"page cost", "page cost", function(s) s.interfaces.page_read.full_page_work_duration = 2559 end},
    {"watchdog reserve", "watchdog reserve", function(s) s.interfaces.watchdog.work_reserved_before_controller_allocation = 5119 end},
    {"unknown reference", "unknown reference", function(s) s.algebraic_laws.source_arrival_probability.expression = {ref = "hidden_answer_oracle"} end},
    {"bad arity", "arity violation", function(s) s.algebraic_laws.completion_boundary.expression = {op = "add", args = {{ref = "k"}}} end},
    {"float literal", "not an integer, boolean or table", function(s) s.algebraic_laws.completion_boundary.expression = {op = "add", args = {{ref = "k"}, 0.5}} end},
    {"prose as code", "prose is not code", function(s) s.algebraic_laws.completion_boundary.expression = {op = "add", args = {{ref = "k"}, "1"}} end},
    {"zero denominator", "positive literal denominator", function(s) s.algebraic_laws.source_arrival_probability.expression = {op = "rational", args = {1, 0}} end},
    {"illegal probability", "outside declared bounds", function(s) s.algebraic_laws.thermal_noise_probability.expression = {op = "rational", args = {3, 2}} end},
    {"stale thermal neighbours", "thermal base differs from native law", function(s)
