["control_reproduction_lua"]="local f=assert(io.open('C:/Users/Gabri/Downloads/execute.lua','rb'))\nlocal s=f:read('a');f:close()\nassert(load(s:match('^(.-)%-%- =+ entry point'),'@execute.lua'))()\nlocal R,E,U=require('asi.reason'),require('asi.reason.eval'),require('asi.util')\nlocal Env=require('asi.reason.env')\nlocal variants={\n {'g1',{legacy_scale=true,always_deep=true}},\n {'gate_only',{legacy_scale=true,always_deep=false}},\n {'scale_only',{legacy_scale=false,always_deep=true}}}\nlocal rows={}\nfor _,v in ipairs(variants) do\n local a=R.artifact(v[2])\n for _,family in ipairs(Env.PROTOCOL.families) do\n  for seed=2001,2004 do\n   local r,env,vm=R.run{artifact=a,family=family,seed=seed,\n    steps=192,work_budget=33549312,trace=true,oracle=true}\n   r.variant=v[1];r.budget_quarters=4;r.allowed_work=33549312\n   r.held=false;r.generation='observed_control'\n   E.score(r,env,33549312)\n   if a.sym.RP_GATE_SKIP then\n    r.gate_skip=vm:mread(a.sym.RP_GATE_SKIP)\n    r.gate_deep=vm:mread(a.sym.RP_GATE_DEEP)\n   end\n   r.host_cpu=nil;r.evaluator_cpu=nil;rows[#rows+1]=r\n  end\n end\nend\nprint(U.sha256(U.to_literal(rows)))\n",
