-- ======================================================================== asi.tests.t_reason_env  (paid endpoint and scorecard regressions)
package.preload["asi.tests.t_reason_env"] = function(...)
local U, Env = require("asi.util"), require("asi.reason.env")
local VM, ISA, GL = require("asi.vm"), require("asi.isa"), require("asi.gl")
local T, M = U.T, {}
local function uniform(e,a)
  return {e.event+1,a,-1,-1,-1,-1,-1,-1,-1,-1,256,0,0}
end
local function one_sys(op,budget,arg,setup,env)
  env=env or Env.new{family="symbolic",seed=1,steps=4}
  local words={ISA.encode(Env.machine.by_name[op],0,1),ISA.encode(Env.machine.by_name.HALT)}
  local p=Env.profile();p.work_budget=budget
  local vm=VM.new{image={words=words,entry=0,bits=#words*64+ISA.decoder_bits(Env.machine)},machine=Env.machine,env=env,profile=p}
  vm.r[1]=arg or 0;if setup then setup(vm,env) end
  vm:run(1);return vm,env
end
local function passive_image()
  local P=GL.program(Env.machine,{ram_words=4096,stack_words=256})
  local B=P:static("ENV_PACKET",28);local Q=P:static("ENV_FORECAST",13)
  P:main(function(f)
    f:do_(f:sys("RSENSE",B))
    f:while_(f:ld(B+Env.O.DONE):eq(0),function()
      f:st(Q,f:ld(B+Env.O.EVENT)+1);f:st(Q+1,0)
      for j=2,9 do f:st(Q+j,-1) end
      f:st(Q+10,256);f:st(Q+11,0);f:st(Q+12,0)
      f:do_(f:sys("RPRED",Q));f:do_(f:sys("RACT",0));f:do_(f:sys("RSENSE",B))
    end)
  end)
  return P:build()
end
local function brute_upper(family,seed,n)
  local best=0
  local function walk(seq)
    local e=Env.new{family=family,seed=seed,steps=n}
    for _,a in ipairs(seq) do if e:act(a)~=0 then return end end
    if #seq==n then best=math.max(best,e.reward_total);return end
    local mask=e:sense_words()[Env.O.SAFE+1]
    for a=0,3 do if (mask & (1<<a))~=0 then seq[#seq+1]=a;walk(seq);seq[#seq]=nil end end
  end
  walk({});return best
end
function M.run()
  T.eq(Env.WORDS,28,"fixed endpoint packet has no extra family/rule slots")
  T.eq(Env.PRED_WORDS,13,"fixed forecast packet")
  T.eq(Env.protocol_hash,U.sha256(U.to_literal(Env.PROTOCOL)),"frozen dynamics provenance")
  T.rejects(function() Env.new{family="lookup_answer"} end,"unknown","unknown task family rejected")
  T.rejects(function() Env.new{steps=193} end,"out of range","finite task clock bounded")
  local profile=Env.profile()
  T.eq(profile.work_budget,33549312,"same discretionary work ceiling as retained benchmark")
  T.eq(profile.ram_words,4096,"public RAM bound");T.eq(profile.stack_words,256,"public stack bound")
  T.eq(profile.watchdog_period,nil,"task clock advances only through paid actions")
  -- A syscall is atomic: the full advertised cost must fit before physics,
  -- forecasts or observations change. No short payment buys a partial event.
  for _,c in ipairs({{"RSENSE",128,VM.RAM_BASE},{"RACT",64,0},{"RPRED",64,VM.RAM_BASE}}) do
    local function prep(vm,e) if c[1]=="RPRED" then for i,v in ipairs(uniform(e,0)) do vm.ram[i-1]=v end end end
    local denied,e=one_sys(c[1],c[2]-1,c[3],prep)
    T.eq(denied.reason,"budget",c[1].." whole invocation refused below price")
    T.eq(denied.work_iface,0,c[1].." refusal charges no partial interface")
    T.eq(e.event,0,c[1].." refused call cannot advance real task")
    T.eq(e.senses+e.pred_calls,0,c[1].." refused call has no delivery/submission")
    local paid,ep=one_sys(c[1],c[2],c[3],prep)
    T.eq(paid.work_iface,c[2],c[1].." exact price is metered")
    T.eq(paid.t,c[2],c[1].." interface time includes invocation")
    T.eq(paid.iface_count,1,c[1].." one paid operation")
    T.eq(ep.event,c[1]=="RACT" and 1 or 0,c[1].." only ACT changes event")
    T.eq(paid.r[0],0,c[1].." valid call returns status only")
    if c[1]=="RACT" then T.eq(ep.records[1].work,64,"actual evidence records total paid work at action") end
  end
  for _,dst in ipairs({0,VM.RAM_BASE+4096-27}) do
    local vm,e=one_sys("RSENSE",128,dst)
    T.eq(vm.fault and vm.fault.code,VM.FAULT.ACCESS,"sense cannot overwrite image or cross RAM boundary")
    T.eq(e.senses,0,"invalid destination cannot deliver a partial packet")
  end
  do
    local vm,e=one_sys("RACT",64,4)
    T.eq(vm.r[0],3,"illegal action returns refusal status")
    T.eq(vm.work_iface,64,"illegal action still pays interface price")
    T.eq(e.event,0,"illegal action cannot change real event")
    T.eq(e.failures,1,"illegal action is retained as a contract failure")
  end
  -- One compiled image is executed unchanged across all families. The code
  -- knows only the schema and the safe passive action, never the host family.
  local words=passive_image();local image_hash=U.sha256_words(words)
  for _,family in ipairs(Env.PROTOCOL.families) do
    local e=Env.new{family=family,seed=1};local vm=VM.new{
      image={words=words,entry=0,bits=#words*64+ISA.decoder_bits(Env.machine)},machine=Env.machine,env=e,profile=Env.profile()}
    T.eq(vm:run(),"halt",family.." immutable image terminates")
    T.eq(vm.image_hash,image_hash,family.." uses byte-identical image")
    T.eq(e.event,192,family.." exact paid real horizon")
    T.eq(e.senses,193,family.." initial and subsequent observations paid")
    T.eq(e.pred_calls,192,family.." every forecast paid")
    T.eq(e.forecasts,192,family.." no valid forecast silently omitted")
    T.eq(e.failures+e.pred_rejected,0,family.." packet and safety guards")
    T.eq(vm.work_iface,193*128+192*(64+64),family.." all interface work counted")
    T.eq(e.brier_num*8,e.brier_den*7,family.." uniform multiclass Brier exactly7/8")
    local total=0
    for i,p in ipairs(e.phases) do
      T.eq(p.steps,48,family.." finite phase length")
      T.eq(p.phase,i-1,family.." phase order is evaluator metadata")
      total=total+p.utility_num
    end
    T.eq(total,e.reward_total,family.." phase returns sum to full real return")
    for _,r in ipairs(e.records) do
      T.eq(r.event,(r.episode*48)+((r.event-1)%48)+1,"real provenance monotonic across resets")
      T.check(r.real and r.work~=nil,"only actual paid events become records")
      T.eq(r.reset,(r.event%48==0 and r.event<192),"forecast outcome names next published reset packet")
      for i=1,4 do
        local known=(r.known_after & (1<<(i-1)))~=0
        T.check((known and r.after[i]>=0 and r.after[i]<=7) or (not known and r.after[i]==-1),"missing values agree with public known mask")
      end
    end
    local result=e:result{oracle=false}
    T.eq(result.oracle_num,nil,"offline optimum never required by endpoint")
    T.eq(#e:sense_words(),28,"schema never grows with hidden family")
    T.eq(Env.oracle(family,1,4),brute_upper(family,1,4),family.." finite DP agrees with independent exhaustive action histories")
  end
  do
    local e=Env.new{family="delayed",seed=1,steps=12};local action={}
    for a=1,3 do action[e.p.actions[a]]=a end
    for cycle=1,2 do for _,op in ipairs({1,2,3,3,3}) do T.eq(e:act(action[op]),0,"real composed key/door/travel action") end end
    T.eq(e.reward_total,512,"delayed goals require repeated successful action composition")
  end
  do
    local e=Env.new{family="symbolic",seed=3}
    local a=U.to_literal(e:sense_words());T.eq(U.to_literal(e:sense_words()),a,"repeated sensing cannot resample hidden noise")
    e:act(0);T.eq(e.reset,false,"real action consumes initial reset")
    T.eq(e:sense_words()[Env.O.PROV_EVENT+1],1,"public provenance equals real event")
    T.eq(e:sense_words()[Env.O.PROV_REAL+1],1,"public provenance distinguishes initial packet")
    local w=uniform(e,0);w[1]=e.event
    T.eq(e:submit_prediction(w),3,"past forecast timestamp rejected")
    w=uniform(e,0);w[3]=8;w[12]=1
    T.eq(e:submit_prediction(w),3,"out of range active prediction rejected")
    w=uniform(e,0);w[11]=257
    T.eq(e:submit_prediction(w),3,"invalid unknown mass rejected")
    T.eq(e.event,1,"rejected forecasts are not synthetic observations")
    local before=e.brier_num;local denom=e.brier_den
    T.eq(e:submit_prediction(uniform(e,1)),0,"legal mismatched action forecast accepted as a submission")
    e:act(0)
    T.eq((e.brier_num-before)*8,(e.brier_den-denom)*7,"mismatched action forecast scores uniform rather than disappearing")
    T.eq(e.forecasts,0,"mismatched action is not a valid matched forecast")
  end
  do
    -- Test-only replay supplies exact next observations to check the scorer,
    -- including a reset. This privileged fixture is never a guest input.
    local e=Env.new{family="symbolic",seed=3};local twin=Env.new{family="symbolic",seed=3}
    for i=1,47 do e:act(0);twin:act(0) end
    twin:act(0);local w=uniform(e,0);w[11]=0;w[12]=twin.known;w[13]=twin.known
    for i=1,4 do w[2+i]=twin.obs[i];w[6+i]=twin.obs[i] end
    local before=e.brier_num
    T.eq(e:submit_prediction(w),0,"exact fixture forecast submitted before real event")
    e:act(0);T.eq(e.brier_num,before,"reset forecast scores published next observation, not discarded private state")
    T.eq(e.records[48].next_episode,1,"record attributes the next published episode")
    T.eq(U.to_literal(e.records[48].after),U.to_literal(twin.obs),"record and forecast truth use the same published observation")
  end
  -- Scorecard checks use declared synthetic row arithmetic only. No measured
  -- controller outcome selects a formula, reference or ablation after freezing.
  local E=require("asi.reason.eval")
  T.eq(E.DEFINITIONS_HASH,U.sha256(U.to_literal(E.DEFINITIONS)),"score formula provenance")
  local cfg=E.config("fixed_representation")
  T.check(cfg.no_repr and cfg.no_plan and cfg.no_epistemic and cfg.no_memory and cfg.no_meta and cfg.plan_depth==1,"fixed representation reference gates frozen")
  T.eq(cfg.no_models,nil,"fixed representation reference retains primitive model selection")
  cfg.no_models=true;T.eq(E.config("fixed_representation").no_models,nil,"configuration copies cannot mutate frozen reference")
  local absent,why=E.config("no_synthesis");T.eq(absent,nil,"unsupported independent synthesis ablation stays NA")
  T.check(type(why)=="string","unsupported mechanism has an explicit reason")
  T.rejects(function() E.config("invented") end,"unknown","unknown configuration rejected")
  local function row(v,f,s,q)
    return {variant=v,family=f,seed=s,budget_quarters=4,axes=q,utility_num=0,utility_den=1,work=1,allowed_work=10,complete=true}
  end
