              row("fixed_representation","causal",1,{[axis]=0.5}),row("fixed_representation","causal",2,{})}
  local summary=E.summarize(rows);local comparison=summary.comparisons[1]
  T.eq(comparison.axis_ratios[axis],2,"ratios use identical supported family/seed pairs")
  T.eq(comparison.axis_support[axis].cases,1,"paired support excludes unmatched NA case")
  T.eq(comparison.primary,true,"stronger predeclared reference is primary")
  T.eq(comparison.full9_axis_2x_demonstrated,false,"partial evidence cannot claim full nine-axis doubling")
  rows[1].axes[axis]=0;summary=E.summarize(rows)
  T.eq(summary.comparisons[1].axis_ratios[axis],0,"supported zero numerator is not dropped or floored")
  rows[3].axes[axis]=0;summary=E.summarize(rows)
  T.eq(summary.comparisons[1].axis_ratios[axis],nil,"zero reference denominator never manufactures an infinite gain")
  T.check(summary.comparisons[1].axis_na[axis]~=nil,"undefined ratio records its reason")
  local env=Env.new{family="symbolic",seed=1};local z=env:result();z.work=1;z.stats={[20]=3,[21]=7,[22]=2}
  E.score(z,env,33549312)
