  T.eq(z.axes[E.AXES[4]],0,"no prospective identification witness scores zero")
  T.eq(z.axes[E.AXES[8]],nil,"no fabricated strategy-utility witness")
  T.check(z.axis_na[E.AXES[8]]~=nil,"unimplemented strategic improvement marked NA")
  T.eq(z.diagnostics.stored_macros,3,"stored procedures are labeled separately from action execution")
  T.eq(z.diagnostics.executed_macro_actions,7,"macro-action counter is not called a proposal")
  T.eq(z.diagnostics.real_macro_positive_outcomes,2,"positive real macro outcomes retain their own counter")
  local Iter=require("asi.reason.iteration")
  T.eq(Iter.PROTOCOL_HASH,U.sha256(U.to_literal(Iter.PROTOCOL)),"G2 preregistration provenance")
  T.eq(Iter.PROTOCOL.environment_protocol_hash,Env.protocol_hash,"generation change cannot replace frozen task physics")
  T.eq(Iter.PROTOCOL.scoring_hash,E.DEFINITIONS_HASH,"generation change cannot replace frozen scoring")
  T.eq(table.concat(Iter.PROTOCOL.holdout_seeds,","),"2001,2002,2003,2004","G2 reserved generic heldout before implementation")
  T.eq(table.concat(Iter.PROTOCOL.previous_generation.heldout_seeds,","),"1001,1002,1003,1004","observed G1 data remain labeled separately")
  local old,new,balanced=Iter.config("g1"),Iter.config("full"),Iter.config("balanced_fixed")
