  T.eq(new.legacy_scale,false,"G2 observed-range diagnostics enabled")
  T.eq(new.always_deep,false,"G2 dependency compute gate enabled")
  T.check(balanced.no_models and balanced.no_plan and balanced.no_memory and balanced.no_meta,"balanced reference contains no model discovery or deep planner")
  T.eq(balanced.no_epistemic,nil,"balanced reference retains declared safe-action coverage policy")
