  T.eq(E.DEFINITIONS.primary_reference,"fixed_representation","G1 primary reference is not overwritten by G2")
  T.rejects(function() Iter.run{held=true,seed=1001} end,"reserved","G1 observed seed cannot be relabeled G2 heldout")
