  T.eq(gs.comparisons[1].axis_ratios[axis],2,"G2 reuses identical paired component arithmetic")
  T.eq(gs.comparisons[1].full9_axis_2x_demonstrated,false,"G2 partial improvement cannot become full9-axis doubling")
