  local vm = VM.new({image = {words = words, bits = Run.image_bits(words)}, machine = Run.MACHINE,
    profile = {ram_words = 4096, stack_words = 256, step_ticks = 8192, horizon = 1 << 50, work_budget = 1 << 50}})
  local function rd(n, i) return vm.ram[sym["H_" .. n] - VM.RAM_BASE + (i or 0)] end
  local function wr(n, i, v) vm.ram[sym["H_" .. n] - VM.RAM_BASE + (i or 0)] = v end
  local function call(n, ...)
    vm.halted, vm.reason, vm.fault, vm.pc = false, nil, nil, sym[n]
    vm.r[14], vm.r[15] = VM.RAM_BASE + 4096, sym["main.ret"]
    for i, v in ipairs({...}) do vm.r[i] = v end
    local before = vm.instr_count
    vm:run(50000000)
    assert(vm.reason == "halt" and not vm.fault, "hpr helper " .. n .. ": " .. tostring(vm.reason) .. "/" .. (vm.fault and vm.fault.name or "none"))
    return vm.r[1], vm.instr_count - before
  end
  return {P = P, R = R, sym = sym, words = words, vm = vm, rd = rd, wr = wr, call = call}
end

local function lane(w, k) return (w >> (4 * k)) & 15 end
local function sref(op, x, y)
  if x == 8 or y == 8 then return 8 end
  if op == 1 then return (x + y) & 7 elseif op == 2 then return (x - y) & 7 elseif op == 3 then return x ~ y
  elseif op == 4 then return x & y elseif op == 5 then return x | y elseif op == 6 then return math.max(x, y)
  elseif op == 7 then return math.min(x, y) elseif op == 8 then return math.min(x + y, 7)
  elseif op == 9 then return math.max(x - y, 0) elseif op == 10 then return x == y and 1 or 0 end
  return x < y and 1 or 0
end

function M.run()
  local Hpr, Env, Reason = require("asi.reason.hpr"), require("asi.reason.env"), require("asi.reason")
  local q = fixture()
  T.check(Run.image_bits(q.words) <= (1 << 20) and q.P.asm.ram_top <= 3840, "hypothesis reasoner helpers obey the immutable image/RAM bounds")

  -- 1. bit-parallel lane operations agree with an independent scalar reference, including unknown lanes
  local seed = 12345
  local function rnd(n) seed = (seed * 1103515245 + 12345) & 0x7fffffff; return (seed >> 8) % n end
  local bad = 0
  for _ = 1, 40 do
    local A, B = 0, 0
    for k = 0, 14 do
      local a, b = rnd(8), rnd(8)
      if rnd(6) == 0 then a = 8 end
      if rnd(6) == 0 then b = 8 end
      A = A | (a << (4 * k)); B = B | (b << (4 * k))
    end
    for op = 1, 11 do
      local r = q.call("h_sw", op, A, B)
      for k = 0, 14 do if lane(r, k) ~= sref(op, lane(A, k), lane(B, k)) then bad = bad + 1 end end
      local x, y = rnd(9) - 1, rnd(9) - 1
      local want = (x < 0 or y < 0) and -1 or sref(op, x, y)
      if q.call("h_sap", op, x, y) ~= want then bad = bad + 1 end
    end
  end
  T.eq(bad, 0, "15-lane SWAR operations match the scalar reference for every operation and unknown-lane pattern")

  -- 2. induction recovers known transition programs from fourteen real-looking samples and generalises to unseen states
  local truth = {
    {"add of two fields", function(s) return (s[0] + s[1]) & 7 end},
    {"xor with a constant", function(s) return s[0] ~ 5 end},
    {"max of two fields", function(s) return math.max(s[1], s[2]) end},
    {"copy of another field", function(s) return s[3] end},
    {"depth-2 term", function(s) return (s[0] + (s[1] & 1)) & 7 end},
  }
  for _, t in ipairs(truth) do
    for k = 0, 15 do q.wr("NCAND", k, 0); q.wr("PST", k, 0) end
    q.wr("NF", 0, 4); q.wr("NA", 0, 4); q.wr("DEEPLVL", 0, 4); q.wr("DEEPFIT", 0, 60); q.wr("EXCON", 0, 1); q.wr("REL", 0, 1); for c = 0, 7 do q.wr("SIG", 16 + c, c * ONES) end
    for j = 0, 3 do q.wr("EXO", j, 0) end
    q.call("h_win_clear")
    for _ = 1, 14 do
      local pre = {}
      for j = 0, 3 do pre[j] = rnd(8); q.wr("PREV", j, pre[j]); q.wr("LAG", j, rnd(8)) end
      local post = {}
      for j = 0, 3 do post[j] = rnd(8) end
      post[0] = t[2](pre)
      for j = 0, 3 do q.wr("OBS", j, post[j]) end
      q.call("h_win_add", 0)
    end
    local _, cost = q.call("h_induce", 0, 0, 0)
    local bk = q.call("h_best", 0)
    local R0, R1 = q.rd("CR0", 0 * 4 + bk), q.rd("CR1", 0 * 4 + bk)
    local good = 0
    for _ = 1, 48 do
      local pre = {}
      for j = 0, 3 do pre[j] = rnd(8); q.wr("CTX", j, pre[j]); q.wr("CTX", 4 + j, rnd(8)) end
      q.wr("CTX", 8, 0)
      for c = 0, 7 do q.wr("CTX", 16 + c, c) end
      if q.call("h_rev", R0, R1) == t[2](pre) then good = good + 1 end
    end
    T.eq(good, 48, "induced rule generalises exactly: " .. t[1])
    T.check(cost > 0 and cost < 400000, "induction is paid VM work with a bounded cost: " .. t[1])
  end

  -- 3. end-to-end safety and metering on every family
  local art = Hpr.artifact()
  T.eq(art.sym.RS_GUARD ~= nil, true, "reasoner exposes its schema guard")
  T.check(art.bits <= Env.PROTOCOL.image_cap_bits, "hypothesis reasoner image meets the L0 cap")
  T.check(art.P.asm.ram_top <= 3840, "hypothesis reasoner state reserves the full declared stack")
  for _, family in ipairs(Env.PROTOCOL.families) do
    local row = Hpr.run({family = family, seed = 3, steps = 12, artifact = art, oracle = false})
    T.eq(row.reason, "halt", family .. " reaches a finite endpoint")
    T.eq(row.steps, 12, family .. " executes paid actions")
    T.eq(row.guard, 0, family .. " obeys schema/provenance")
    T.eq(row.failures, 0, family .. " respects the safety contract")
    T.eq(row.pred_rejected, 0, family .. " submits valid forecasts")
    T.eq(row.forecast_count, 12, family .. " forecasts every action")
    T.check(row.work > 0 and row.work <= Env.PROTOCOL.work_budget, family .. " pays for all reasoning")
    T.check(row.ram_high_water <= 4096, family .. " bounded guest memory")
    T.eq(row.oracle_num, nil, family .. " receives no offline oracle")
  end

  -- 4. deterministic replay and exact accounting
  local opt = {family = "regime", seed = 7, steps = 30, artifact = art, oracle = false}
  local x, y = Hpr.run(opt), Hpr.run(opt)
  T.eq(x.trace_hash, y.trace_hash, "same observations and paid reasoning replay exactly")
  T.eq(x.work, y.work, "replay preserves all reasoning costs")
  T.eq(x.utility_num, y.utility_num, "replay preserves decisions and reward")

  -- 5. corrupted schema fields without an episode reset stop the controller before a second action
  for _, change in ipairs({"MAX", "GOAL", "EID"}) do
    local env = Env.new({family = "causal", seed = 2, steps = 4})
    local sense = env.sense_words
    env.sense_words = function(self)
      local w = sense(self)
      if self.event > 0 and w[15] == 0 then
        if change == "MAX" then w[4] = 6
        elseif change == "EID" then w[17] = w[17] + 1
        else for j = 8, 11 do if w[j] >= 0 then w[j] = -1; break end end end
      end
      return w
    end
    local vm = VM.new({image = {words = art.words, bits = art.bits}, machine = art.machine, env = env, profile = Env.profile(), coin_seed = 1})
    T.eq(vm:run(), "halt", "corrupted " .. change .. " stops normally")
    T.eq(env.step, 1, "changing " .. change .. " without RESET cannot cause a second action")
    T.eq(vm.ram[art.sym.RS_GUARD - VM.RAM_BASE], 1, "schema provenance guard rejects " .. change)
  end
  local exhausted = Hpr.run({family = "symbolic", seed = 1, steps = 192, artifact = art, work_budget = 64, oracle = false})
  T.eq(exhausted.steps, 0, "exhaustion cannot produce an uncharged action")
  T.check(exhausted.work <= 64, "exhaustion stays inside the hard work bound")
  T.rejects(function() Hpr.run({artifact = art, work_budget = Env.PROTOCOL.work_budget + 1}) end,
            "outside frozen contract", "caller cannot widen the declared compute cap")

  -- 6. the new mechanisms are behaviourally present and removable (counters are written by the guest itself)
  local full = Hpr.run({family = "symbolic", seed = 1, steps = 120, artifact = art, oracle = false})
  local nolib = Hpr.run({family = "symbolic", seed = 1, steps = 120, artifact = Hpr.artifact({lib = 0}), oracle = false})
  local noexc = Hpr.run({family = "delayed", seed = 1, steps = 60, artifact = Hpr.artifact({exc = 0}), oracle = false})
  local withexc = Hpr.run({family = "delayed", seed = 1, steps = 60, artifact = art, oracle = false})
  T.check(full.stats[1] > 0 and full.stats[3] > 0, "hypotheses are induced and inserted by VM instructions")
  T.check(full.stats[9] > 0, "a second episode seeds hypotheses from the retained world library")
  T.eq(nolib.stats[9], 0, "the library ablation really disables seeding")
  T.check(full.trace_hash ~= nolib.trace_hash, "disabling the library changes the metered behaviour")
  T.check(withexc.trace_hash ~= noexc.trace_hash, "disabling exceptions changes the metered behaviour")
  T.check(withexc.stats[7] > 0 or withexc.stats[10] > 0, "plans are searched or followed on a delayed-credit task")
  -- the controller gets nothing the generation-2 controller did not get: identical packet, identical interface ops
  T.eq(art.machine, Env.machine, "same charged interface as every other reasoning controller")
  T.check(art.sym.RS_BUFFER ~= nil and art.sym.H_STATS ~= nil, "the guest sees only its sensing buffer and declares its own state")

  -- 7. compute is a managed resource: the guest watches its own metered clock and drops expensive reasoning when the
  -- work left per remaining step falls below its allowance; it must still finish the stream
  local rich = Hpr.run({family = "symbolic", seed = 2, steps = 96, artifact = art, oracle = false})
  local poor = Hpr.run({family = "symbolic", seed = 2, steps = 96, artifact = art, oracle = false, work_budget = 1500000})
  T.eq(rich.stats[12], 0, "with ample budget no step is run in economy mode")
  T.check(poor.stats[12] > 0, "a tight budget switches the guest into economy mode")
  T.check(poor.work <= 1500000 and poor.steps >= 90, "economy mode completes (nearly) the whole stream inside the hard bound")
  T.check(poor.work < rich.work, "economy mode actually spends less work")

  -- 8. every new mechanism is a removable, behaviour-changing part of the metered program (not decoration)
  local base = Hpr.run({family = "symbolic", seed = 3, steps = 72, artifact = art, oracle = false})
  T.check(base.stats[13] > 0, "chance lookahead over exogenous samples runs on a task with a noise field")
  for name, c in pairs({no_chance = {chance = 0}, no_novelty = {novelty = 0}, no_cb = {cb = 0}, no_noise_detection = {exo = 0},
                        no_exploration = {explore = 0}, one_hypothesis = {nc = 1}}) do
    local r = Hpr.run({family = "latent", seed = 2, steps = 72, artifact = Hpr.artifact(c), oracle = false})
    local ref = Hpr.run({family = "latent", seed = 2, steps = 72, artifact = art, oracle = false})
    T.check(r.trace_hash ~= ref.trace_hash, "ablation " .. name .. " changes the metered behaviour")
    T.eq(r.guard, 0, "ablation " .. name .. " still obeys the schema contract")
  end
  local nochance = Hpr.run({family = "symbolic", seed = 3, steps = 72, artifact = Hpr.artifact({chance = 0}), oracle = false})
  T.eq(nochance.stats[13], 0, "the chance ablation really disables the evaluation")

  -- 9. generated held-out worlds: same interface and scorecard, worlds accepted only by an offline optimum test
  local E3 = require("asi.reason.env3")
  local E, G = require("asi.reason.eval"), require("asi.reason.generation3")
  T.eq(G.PROTOCOL.environment_protocol_hash, Env.protocol_hash, "G3 uses the frozen task physics")
  T.eq(G.PROTOCOL.scoring_hash, E.DEFINITIONS_HASH, "G3 uses the frozen scorecard")
  for _, seed in ipairs({6, 7, 8}) do
    local env = E3.new({seed = seed, steps = 192})
    local best, abstain, phases = E3.oracle(seed, 192)
    T.check(best > abstain + 2 * 256 and #phases == 4, "generated world " .. seed .. " has an optimum clearly above passive play")
    local row = Hpr.run({artifact = art, env = env, steps = 192, oracle = false})
    T.eq(row.guard, 0, "generated world " .. seed .. " obeys the schema/provenance contract")
    T.eq(row.steps, 192, "generated world " .. seed .. " is completed")
    T.eq(row.pred_rejected, 0, "generated world " .. seed .. " receives only valid forecasts")
  end
  -- 10. schemas smaller than the frozen 4 fields x 4 actions are accepted and handled (field / action counts are data)
  for _, schema in ipairs({{nf = 3, na = 3}, {nf = 2, na = 4}, {nf = 4, na = 2}}) do
    local env = E3.new({seed = 2, steps = 40})
    local sw, act = env.sense_words, env.act
    env.sense_words = function(self)
      local w = sw(self)
      w[2], w[3] = schema.nf, schema.na
      w[12] = (1 << schema.na) - 1
      for i = schema.nf + 1, 4 do w[7 + i] = -1; w[24 + i] = -1 end
      w[13] = w[13] & ((1 << schema.nf) - 1)
      for i = 1, schema.nf do if (w[13] & (1 << (i - 1))) == 0 then w[24 + i] = -1 end end
      return w
    end
    env.act = function(self, a) if a >= schema.na then self.failures = self.failures + 1; return 3 end return act(self, a) end
    local row = Hpr.run({artifact = art, env = env, steps = 40, oracle = false})
    T.eq(row.guard, 0, "schema nf=" .. schema.nf .. " na=" .. schema.na .. " is accepted")
    T.eq(row.failures, 0, "schema nf=" .. schema.nf .. " na=" .. schema.na .. " never picks an unavailable action")
    T.eq(row.steps, 40, "schema nf=" .. schema.nf .. " na=" .. schema.na .. " completes")
  end
  -- 11. a goal on every field gives goal distances up to 28; the bounded reward table must absorb them without corruption
  do
    local env = E3.new({seed = 3, steps = 60})
    local sw = env.sense_words
    env.sense_words = function(self) local w = sw(self); for i = 8, 11 do w[i] = 3 end return w end
    local row = Hpr.run({artifact = art, env = env, steps = 60, oracle = false})
    T.eq(row.guard, 0, "goals on all four fields are accepted")
    T.eq(row.steps, 60, "goals on all four fields do not derail the controller")
    T.check(row.ram_high_water <= 4096, "goal-distance clamping keeps the guest inside its memory")
  end
  local ga, gb = E3.new({seed = 6}), E3.new({seed = 6})
  local ra = Hpr.run({artifact = art, env = ga, oracle = false, steps = 60})
  local rb = Hpr.run({artifact = art, env = gb, oracle = false, steps = 60})
  T.eq(ra.trace_hash, rb.trace_hash, "generated worlds replay exactly")
end
return M
end

