Separate groups (they test different things and must not be confused):
  conformance            : math, rng, validate (local finite laws), world (simulator vs an independent oracle), vm, gl
  finite certificate soundness : risk (exact verifier of the statistical/risk machinery), proof (the declared proof kernel)
  resource-correct controller execution : parity (cost-contract world + guest controllers), twin (noninterference)
  failure detection      : mutation (each required failure class is detected)
  performance evidence / reports : harness (protocol, bounds, report round trip, CLI exit codes) -- the large evidence run
                           itself is `lua asi.lua compare`, not a unit test
]============]
local U = require("asi.util")
local T = U.T

local All = {}

All.suites = {
  {name = "math", module = "asi.tests.t_math", group = "conformance"},
  {name = "rng", module = "asi.tests.t_rng", group = "conformance"},
  {name = "validate", module = "asi.tests.t_validate", group = "conformance"},
  {name = "world", module = "asi.tests.t_world", group = "conformance"},
  {name = "vm", module = "asi.tests.t_vm", group = "conformance"},
  {name = "gl", module = "asi.tests.t_gl", group = "conformance"},
  {name = "risk", module = "asi.tests.t_risk", group = "certificate"},
  {name = "proof", module = "asi.tests.t_proof", group = "certificate"},
  {name = "parity", module = "asi.tests.t_parity", group = "execution"},
  {name = "twin", module = "asi.tests.t_twin", group = "execution"},
  {name = "mutation", module = "asi.tests.t_mutation", group = "failure-detection"},
  {name = "harness", module = "asi.tests.t_harness", group = "reports"},
  {name = "reason", module = "asi.tests.t_reason", group = "reasoning"},
}

function All.find(name)
  for _, s in ipairs(All.suites) do if s.name == name then return s end end
end

-- run one suite; returns {name=, passed=, failed=, failures=, error=, seconds=}
function All.run_suite(s, verbose)
  T.reset()
  local t0 = os.clock()
  local ok, err = pcall(function() require(s.module).run() end)
  local r = {name = s.name, group = s.group, passed = T.passed, failed = T.failed, failures = T.failures, seconds = os.clock() - t0}
  if not ok then r.error = tostring(err) end
  return r
end

--[[@@END@@]]
return All
end

