-- ============================================================================ entry point
-- DEFAULT_ARGS: what the Run button does when no command-line arguments are given. nil = the quick-start below.
local DEFAULT_ARGS = nil

local Cli = require("asi.cli")

local function quickstart()
  local steps = {
    {"help"},
    {"risk"},
    {"parity", "--mode", "full", "--seed", "2001"},
    {"reason", "--family", "delayed", "--seed", "1", "--steps", "24"},
    {"selftest", "math", "rng", "gl", "vm", "world"},
  }
  local worst = 0
  for _, a in ipairs(steps) do
    io.stdout:write("\n$ lua main.lua ", table.concat(a, " "), "\n")
    local code = Cli.main(a)
    io.stdout:write("(exit status ", tostring(code), ")\n")
    if code > worst then worst = code end
  end
  io.stdout:write("\nQuick-start finished with status ", tostring(worst), ". Next: `lua main.lua selftest` runs all registered suites; ",
                  "`lua main.lua reason-report` prints the redesign audit and evidence.\n")
  return worst
end

local args = {}
for i = 1, #(arg or {}) do args[i] = arg[i] end
local code
if #args == 0 and DEFAULT_ARGS == nil then code = quickstart()
else code = Cli.main(#args > 0 and args or DEFAULT_ARGS) end
os.exit(code)
